export interface User {
  username: string;
  name: string;
  role: 'admin' | 'user';
}

export interface Printer {
  id: string;
  serialNumber: string;
  model: string;
  location: string; // e.g., "Hemşire Bankosu"
  floor: string;    // e.g., "2. Kat"
  lastCounter: number;
  lastTonerDate: string; // ISO Date string
  compatibleToner: string; // e.g., "505A"
}

export interface TonerStock {
  modelName: string; // e.g., "505A"
  quantity: number;
}

export interface StockLog {
  id: string;
  date: string;
  type: 'IN' | 'OUT';
  tonerModel: string;
  quantity: number;
  description: string;
  printerId?: string; // If type is OUT and assigned to a printer
  user: string;
}

import { Printer, TonerStock, StockLog } from '../types';

const STORAGE_KEYS = {
  PRINTERS: 'app_printers',
  STOCKS: 'app_stocks',
  LOGS: 'app_logs',
};

// Initial Mock Data
const INITIAL_PRINTERS: Printer[] = [
  {
    id: '1',
    serialNumber: 'CN123456',
    model: 'HP LaserJet P2035',
    location: 'Hemşire Bankosu',
    floor: '2. Kat',
    lastCounter: 15420,
    lastTonerDate: new Date().toISOString(),
    compatibleToner: '05A'
  },
  {
    id: '2',
    serialNumber: 'CN987654',
    model: 'Canon LBP 6030',
    location: 'Başhekim Sekreterya',
    floor: '1. Kat',
    lastCounter: 8500,
    lastTonerDate: '2023-10-01T10:00:00.000Z',
    compatibleToner: '85A'
  }
];

const INITIAL_STOCKS: TonerStock[] = [
  { modelName: '05A', quantity: 10 },
  { modelName: '85A', quantity: 5 },
  { modelName: '12A', quantity: 2 },
];

export const StorageService = {
  getPrinters: (): Printer[] => {
    const data = localStorage.getItem(STORAGE_KEYS.PRINTERS);
    return data ? JSON.parse(data) : INITIAL_PRINTERS;
  },

  savePrinters: (printers: Printer[]) => {
    localStorage.setItem(STORAGE_KEYS.PRINTERS, JSON.stringify(printers));
  },

  getStocks: (): TonerStock[] => {
    const data = localStorage.getItem(STORAGE_KEYS.STOCKS);
    return data ? JSON.parse(data) : INITIAL_STOCKS;
  },

  saveStocks: (stocks: TonerStock[]) => {
    localStorage.setItem(STORAGE_KEYS.STOCKS, JSON.stringify(stocks));
  },

  getLogs: (): StockLog[] => {
    const data = localStorage.getItem(STORAGE_KEYS.LOGS);
    return data ? JSON.parse(data) : [];
  },

  addLog: (log: StockLog) => {
    const logs = StorageService.getLogs();
    const newLogs = [log, ...logs];
    localStorage.setItem(STORAGE_KEYS.LOGS, JSON.stringify(newLogs));
  }
};

import React, { useState } from 'react';
import { Menu, X, Printer, Package, LogOut, LayoutDashboard, History } from 'lucide-react';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onLogout: () => void;
  user: { name: string };
}

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, onLogout, user }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { id: 'dashboard', label: 'Özet', icon: LayoutDashboard },
    { id: 'printers', label: 'Yazıcılar', icon: Printer },
    { id: 'stock', label: 'Stok Yönetimi', icon: Package },
    { id: 'history', label: 'Geçmiş', icon: History },
  ];

  const handleNavClick = (id: string) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Mobile Header */}
      <div className="md:hidden bg-blue-700 text-white p-4 flex justify-between items-center shadow-md sticky top-0 z-50">
        <h1 className="text-xl font-bold">Toner Takip</h1>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Sidebar (Desktop) / Drawer (Mobile) */}
      <aside className={`
        fixed md:static inset-y-0 left-0 z-40 w-64 bg-slate-900 text-slate-100 transform transition-transform duration-200 ease-in-out
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
        md:translate-x-0 flex flex-col
      `}>
        <div className="p-6 hidden md:block">
          <h1 className="text-2xl font-bold text-blue-400">Toner Takip</h1>
          <p className="text-xs text-slate-400 mt-1">v1.0.0</p>
        </div>

        <div className="p-4 bg-slate-800 md:hidden">
          <p className="text-sm text-slate-400">Hoşgeldin,</p>
          <p className="font-semibold">{user.name}</p>
        </div>

        <nav className="flex-1 px-2 py-4 space-y-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNavClick(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
                activeTab === item.id 
                  ? 'bg-blue-600 text-white shadow-lg' 
                  : 'text-slate-300 hover:bg-slate-800'
              }`}
            >
              <item.icon size={20} />
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-700">
           <div className="hidden md:block mb-4 px-2">
            <p className="text-xs text-slate-400">Kullanıcı</p>
            <p className="font-medium text-sm truncate">{user.name}</p>
          </div>
          <button
            onClick={onLogout}
            className="w-full flex items-center space-x-3 px-4 py-2 text-red-400 hover:bg-red-400/10 rounded-lg transition-colors"
          >
            <LogOut size={20} />
            <span>Çıkış Yap</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto h-[calc(100vh-64px)] md:h-screen">
        <div className="max-w-5xl mx-auto">
          {children}
        </div>
      </main>

      {/* Mobile Overlay */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-30 md:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2 } from 'lucide-react';
import { Printer } from '../types';
import { StorageService } from '../services/storage';

interface PrinterListProps {
  onSelectPrinter?: (printer: Printer) => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ onSelectPrinter }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<Printer | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Printer>>({
    model: '',
    serialNumber: '',
    location: '',
    floor: '',
    lastCounter: 0,
    compatibleToner: ''
  });

  useEffect(() => {
    loadPrinters();
  }, []);

  const loadPrinters = () => {
    setPrinters(StorageService.getPrinters());
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    let updatedList = [...printers];

    if (editingPrinter) {
      updatedList = updatedList.map(p => 
        p.id === editingPrinter.id ? { ...p, ...formData } as Printer : p
      );
    } else {
      const newPrinter: Printer = {
        id: Date.now().toString(),
        lastTonerDate: new Date().toISOString(),
        ...formData as Printer
      };
      updatedList.push(newPrinter);
    }

    StorageService.savePrinters(updatedList);
    setPrinters(updatedList);
    closeModal();
  };

  const openModal = (printer?: Printer) => {
    if (printer) {
      setEditingPrinter(printer);
      setFormData(printer);
    } else {
      setEditingPrinter(null);
      setFormData({
        model: '',
        serialNumber: '',
        location: '',
        floor: '',
        lastCounter: 0,
        compatibleToner: ''
      });
    }
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingPrinter(null);
  };

  const filteredPrinters = printers.filter(p => 
    p.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.serialNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Yazıcı Listesi</h2>
        <button 
          onClick={() => openModal()}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-all active:scale-95"
        >
          <Plus size={18} />
          <span>Yeni Yazıcı Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
        <input
          type="text"
          placeholder="Yazıcı ara (Model, Konum, Seri No)..."
          className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredPrinters.map(printer => (
          <div key={printer.id} className="bg-white p-5 rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
            <div className="flex justify-between items-start mb-3">
              <div className="flex items-center gap-2 text-blue-600 font-medium">
                <PrinterIcon size={18} />
                <span>{printer.model}</span>
              </div>
              <button onClick={() => openModal(printer)} className="text-slate-400 hover:text-blue-600 p-1">
                <Edit2 size={16} />
              </button>
            </div>

            <div className="space-y-2 text-sm text-slate-600">
              <div className="flex items-center gap-2">
                <Hash size={14} className="text-slate-400" />
                <span className="font-mono bg-slate-100 px-1 rounded text-xs">{printer.serialNumber}</span>
              </div>
              <div className="flex items-center gap-2">
                <MapPin size={14} className="text-slate-400" />
                <span>{printer.floor} - {printer.location}</span>
              </div>
              <div className="flex justify-between border-t border-slate-50 pt-2 mt-2">
                <div>
                  <p className="text-xs text-slate-400">Sayaç</p>
                  <p className="font-semibold">{printer.lastCounter.toLocaleString()}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs text-slate-400">Son Değişim</p>
                  <p className="font-semibold">{new Date(printer.lastTonerDate).toLocaleDateString('tr-TR')}</p>
                </div>
              </div>
              <div className="mt-2 pt-2 border-t border-dashed border-slate-200">
                 <p className="text-xs text-slate-400">Uyumlu Toner</p>
                 <span className="inline-block bg-orange-100 text-orange-700 px-2 py-0.5 rounded text-xs font-medium">
                   {printer.compatibleToner || 'Belirtilmedi'}
                 </span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden">
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
              <h3 className="font-bold text-lg text-slate-800">
                {editingPrinter ? 'Yazıcı Düzenle' : 'Yeni Yazıcı Ekle'}
              </h3>
              <button onClick={closeModal}><X size={20} className="text-slate-400" /></button>
            </div>

            <form onSubmit={handleSave} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Marka/Model</label>
                  <input required className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} placeholder="Örn: HP M1234" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Seri No</label>
                  <input required className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} placeholder="Örn: CNC123" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Kat</label>
                  <input required className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} placeholder="Örn: 2. Kat" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Birim/Oda</label>
                  <input required className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} placeholder="Örn: Hemşire Bankosu" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Son Sayaç</label>
                  <input type="number" required className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    value={formData.lastCounter} onChange={e => setFormData({...formData, lastCounter: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Uyumlu Toner</label>
                  <input className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    value={formData.compatibleToner} onChange={e => setFormData({...formData, compatibleToner: e.target.value})} placeholder="Örn: 505A" />
                </div>
              </div>

              <div className="pt-4 flex gap-3">
                <button type="button" onClick={closeModal} className="flex-1 py-3 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors">İptal</button>
                <button type="submit" className="flex-1 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium">Kaydet</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ArrowDown, ArrowUp, CheckCircle, AlertTriangle, Search } from 'lucide-react';
import { TonerStock, Printer, StockLog } from '../types';
import { StorageService } from '../services/storage';

interface StockManagementProps {
  user: { name: string };
}

export const StockManagement: React.FC<StockManagementProps> = ({ user }) => {
  const [stocks, setStocks] = useState<TonerStock[]>([]);
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [activeTab, setActiveTab] = useState<'LIST' | 'IN' | 'OUT'>('LIST');

  // Transaction States
  const [selectedPrinterId, setSelectedPrinterId] = useState('');
  const [selectedTonerModel, setSelectedTonerModel] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [newStockModel, setNewStockModel] = useState(''); // For adding new model type
  const [description, setDescription] = useState('');

  // Notification
  const [message, setMessage] = useState<{type: 'success' | 'error', text: string} | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setStocks(StorageService.getStocks());
    setPrinters(StorageService.getPrinters());
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 3000);
  };

  const handleStockIn = (e: React.FormEvent) => {
    e.preventDefault();
    const model = newStockModel.trim().toUpperCase();
    if (!model) return;

    const updatedStocks = [...stocks];
    const existingIndex = updatedStocks.findIndex(s => s.modelName === model);

    if (existingIndex >= 0) {
      updatedStocks[existingIndex].quantity += quantity;
    } else {
      updatedStocks.push({ modelName: model, quantity: quantity });
    }

    StorageService.saveStocks(updatedStocks);

    // Log
    const log: StockLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      type: 'IN',
      tonerModel: model,
      quantity: quantity,
      description: 'Stok Girişi (Manuel)',
      user: user.name
    };
    StorageService.addLog(log);

    refreshData();
    showMessage('success', `${quantity} adet ${model} stoğa eklendi.`);
    setNewStockModel('');
    setQuantity(1);
    setActiveTab('LIST');
  };

  const handleStockOut = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTonerModel) {
      showMessage('error', 'Lütfen toner seçiniz.');
      return;
    }

    // Check stock
    const updatedStocks = [...stocks];
    const stockIndex = updatedStocks.findIndex(s => s.modelName === selectedTonerModel);

    if (stockIndex === -1 || updatedStocks[stockIndex].quantity < 1) {
      showMessage('error', 'Yetersiz stok!');
      return;
    }

    // Decrement Stock
    updatedStocks[stockIndex].quantity -= 1; // Assuming 1 per usage usually
    StorageService.saveStocks(updatedStocks);

    // Update Printer
    let printerDesc = "";
    if (selectedPrinterId) {
      const updatedPrinters = printers.map(p => {
        if (p.id === selectedPrinterId) {
          printerDesc = `${p.location} (${p.floor})`;
          return {
            ...p,
            lastTonerDate: new Date().toISOString(),
            lastCounter: p.lastCounter // Ideally we'd ask for new counter here too, but keep simple
          };
        }
        return p;
      });
      StorageService.savePrinters(updatedPrinters);
    }

    // Log
    const log: StockLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      type: 'OUT',
      tonerModel: selectedTonerModel,
      quantity: 1,
      printerId: selectedPrinterId,
      description: selectedPrinterId ? `Yazıcıya Takıldı: ${printerDesc}` : `Stok Çıkışı: ${description}`,
      user: user.name
    };
    StorageService.addLog(log);

    refreshData();
    showMessage('success', `${selectedTonerModel} stoktan düşüldü.`);
    setSelectedPrinterId('');
    setSelectedTonerModel('');
    setActiveTab('LIST');
  };

  // Helper to auto-select toner when printer is selected
  const onPrinterSelect = (printerId: string) => {
    setSelectedPrinterId(printerId);
    const printer = printers.find(p => p.id === printerId);
    if (printer && printer.compatibleToner) {
      setSelectedTonerModel(printer.compatibleToner);
    }
  };

  return (
    <div className="space-y-6">
      {message && (
        <div className={`fixed top-4 right-4 p-4 rounded-lg shadow-xl text-white z-50 animate-bounce ${message.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
          {message.text}
        </div>
      )}

      <div className="flex space-x-2 bg-white p-1 rounded-xl shadow-sm border border-slate-100 w-fit">
        <button 
          onClick={() => setActiveTab('LIST')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'LIST' ? 'bg-slate-800 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
        >
          Stok Listesi
        </button>
        <button 
          onClick={() => setActiveTab('IN')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'IN' ? 'bg-green-600 text-white' : 'text-green-700 hover:bg-green-50'}`}
        >
          <ArrowDown size={16} /> Stok Giriş
        </button>
        <button 
          onClick={() => setActiveTab('OUT')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'OUT' ? 'bg-orange-600 text-white' : 'text-orange-700 hover:bg-orange-50'}`}
        >
          <ArrowUp size={16} /> Toner Çıkış
        </button>
      </div>

      {activeTab === 'LIST' && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {stocks.map(stock => (
            <div key={stock.modelName} className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center justify-center text-center">
              <h3 className="text-3xl font-bold text-slate-800 mb-1">{stock.quantity}</h3>
              <p className="text-slate-500 font-medium">Model: {stock.modelName}</p>
              {stock.quantity < 3 && (
                <span className="mt-2 text-xs bg-red-100 text-red-700 px-2 py-1 rounded-full flex items-center gap-1">
                  <AlertTriangle size={12} /> Kritik
                </span>
              )}
            </div>
          ))}
          {stocks.length === 0 && (
            <div className="col-span-full p-8 text-center text-slate-400">Henüz stok kaydı yok.</div>
          )}
        </div>
      )}

      {activeTab === 'IN' && (
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 max-w-lg">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <div className="p-2 bg-green-100 rounded-lg text-green-700"><ArrowDown size={20}/></div>
            Stok Girişi Yap
          </h3>
          <form onSubmit={handleStockIn} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Toner Modeli</label>
              <input 
                list="toner-models"
                required
                className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                placeholder="Örn: 505A, 85A..."
                value={newStockModel}
                onChange={e => setNewStockModel(e.target.value)}
              />
              <datalist id="toner-models">
                {stocks.map(s => <option key={s.modelName} value={s.modelName} />)}
              </datalist>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Adet</label>
              <div className="flex items-center gap-4">
                <button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="p-3 bg-slate-100 rounded-lg font-bold">-</button>
                <input 
                  type="number" 
                  min="1"
                  required
                  className="w-full text-center p-3 border rounded-xl focus:ring-2 focus:ring-green-500 outline-none font-bold text-lg"
                  value={quantity}
                  onChange={e => setQuantity(parseInt(e.target.value) || 1)}
                />
                <button type="button" onClick={() => setQuantity(quantity + 1)} className="p-3 bg-slate-100 rounded-lg font-bold">+</button>
              </div>
            </div>
