import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Tag, Box } from 'lucide-react';
import { StorageService } from '../services/storage';
import { SystemConfig } from '../types';

export const Settings: React.FC = () => {
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [] });
  const [newBrand, setNewBrand] = useState('');
  const [newModel, setNewModel] = useState('');

  useEffect(() => {
    setConfig(StorageService.getConfig());
  }, []);

  const handleAddBrand = (e: React.FormEvent) => {
    e.preventDefault();
    if (newBrand.trim() && !config.brands.includes(newBrand.trim())) {
      const updatedConfig = { ...config, brands: [...config.brands, newBrand.trim()] };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
      setNewBrand('');
    }
  };

  const handleDeleteBrand = (brand: string) => {
    if (confirm(`${brand} markasını silmek istediğinize emin misiniz?`)) {
      const updatedConfig = { ...config, brands: config.brands.filter(b => b !== brand) };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
    }
  };

  const handleAddModel = (e: React.FormEvent) => {
    e.preventDefault();
    if (newModel.trim() && !config.models.includes(newModel.trim())) {
      const updatedConfig = { ...config, models: [...config.models, newModel.trim()] };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
      setNewModel('');
    }
  };

  const handleDeleteModel = (model: string) => {
    if (confirm(`${model} modelini silmek istediğinize emin misiniz?`)) {
      const updatedConfig = { ...config, models: config.models.filter(m => m !== model) };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
    }
  };

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
        <Save size={24} className="text-blue-600" />
        Sistem Ayarları
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Brand Management */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-700 mb-4 flex items-center gap-2">
            <Tag size={20} /> Yazıcı Markaları
          </h3>

          <form onSubmit={handleAddBrand} className="flex gap-2 mb-4">
            <input 
              type="text" 
              placeholder="Yeni marka (örn: Brother)"
              className="flex-1 p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              value={newBrand}
              onChange={(e) => setNewBrand(e.target.value)}
            />
            <button type="submit" className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700">
              <Plus size={20} />
            </button>
          </form>

          <div className="space-y-2 max-h-64 overflow-y-auto">
            {config.brands.map(brand => (
              <div key={brand} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg group">
                <span className="font-medium">{brand}</span>
                <button onClick={() => handleDeleteBrand(brand)} className="text-slate-400 hover:text-red-500 transition-colors">
                  <Trash2 size={18} />
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* Model Management */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-700 mb-4 flex items-center gap-2">
            <Box size={20} /> Yazıcı Modelleri
          </h3>

          <form onSubmit={handleAddModel} className="flex gap-2 mb-4">
            <input 
              type="text" 
              placeholder="Yeni model (örn: MF416dw)"
              className="flex-1 p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              value={newModel}
              onChange={(e) => setNewModel(e.target.value)}
            />
            <button type="submit" className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700">
              <Plus size={20} />
            </button>
          </form>

          <div className="space-y-2 max-h-64 overflow-y-auto">
            {config.models.map(model => (
              <div key={model} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg group">
                <span className="font-medium">{model}</span>
                <button onClick={() => handleDeleteModel(model)} className="text-slate-400 hover:text-red-500 transition-colors">
                  <Trash2 size={18} />
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

