import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Globe } from 'lucide-react';
import { Printer, SystemConfig } from '../types';
import { StorageService } from '../services/storage';

interface PrinterListProps {
  onSelectPrinter?: (printer: Printer) => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ onSelectPrinter }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [] });
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<Printer | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Printer>>({
    brand: '',
    model: '',
    serialNumber: '',
    location: '',
    floor: '',
    lastCounter: 0,
    compatibleToner: '',
    connectionType: 'USB',
    ipAddress: ''
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    setPrinters(StorageService.getPrinters());
    setConfig(StorageService.getConfig());
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    let updatedList = [...printers];

    if (editingPrinter) {
      updatedList = updatedList.map(p => 
        p.id === editingPrinter.id ? { ...p, ...formData } as Printer : p
      );
    } else {
      const newPrinter: Printer = {
        id: Date.now().toString(),
        lastTonerDate: new Date().toISOString(),
        ...formData as Printer
      };
      updatedList.push(newPrinter);
    }

    StorageService.savePrinters(updatedList);
    setPrinters(updatedList);
    closeModal();
  };

  const openModal = (printer?: Printer) => {
    if (printer) {
      setEditingPrinter(printer);
      setFormData(printer);
    } else {
      setEditingPrinter(null);
      setFormData({
        brand: config.brands[0] || '',
        model: config.models[0] || '',
        serialNumber: '',
        location: '',
        floor: '',
        lastCounter: 0,
        compatibleToner: '',
        connectionType: 'USB',
        ipAddress: ''
      });
    }
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingPrinter(null);
  };

  const filteredPrinters = printers.filter(p => 
    p.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.serialNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Yazıcı Listesi</h2>
        <button 
          onClick={() => openModal()}
          className="bg-primary-700 hover:bg-primary-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-all active:scale-95"
        >
          <Plus size={18} />
          <span>Yeni Yazıcı Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
        <input
          type="text"
          placeholder="Yazıcı ara (Marka, Model, IP, Konum)..."
          className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 outline-none transition-all"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredPrinters.map(printer => (
          <div key={printer.id} className="bg-white dark:bg-slate-800 p-5 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow">
            <div className="flex justify-between items-start mb-3">
              <div className="flex items-center gap-2 text-primary-700 dark:text-primary-400 font-bold">
                <PrinterIcon size={18} />
                <span>{printer.brand} {printer.model}</span>
              </div>
              <button onClick={() => openModal(printer)} className="text-slate-400 hover:text-primary-600 p-1">
                <Edit2 size={16} />
              </button>
            </div>

            <div className="space-y-2 text-sm text-slate-600 dark:text-slate-300">
               {/* Connection Info Badge */}
               <div className="flex gap-2 mb-2">
                <div className={`flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium border ${
                  printer.connectionType === 'Network' 
