                             {record.status === 'COMPLETED' ? 'TAMAMLANDI' : record.status === 'PENDING' ? 'BEKLİYOR' : 'HURDA/DEĞİŞİM'}
                          </span>
                          <span className="text-xs text-slate-400">{new Date(record.date).toLocaleDateString('tr-TR')}</span>
