import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Globe, Trash2, History, Wrench, Truck } from 'lucide-react';
import { Printer, SystemConfig, StockLog, ServiceRecord } from '../types';
import { StorageService } from '../services/storage';

interface PrinterListProps {
  onSelectPrinter?: (printer: Printer) => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ onSelectPrinter }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [] });
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<Printer | null>(null);
  const [selectedPrinterHistory, setSelectedPrinterHistory] = useState<{printer: Printer, tonerLogs: StockLog[], serviceLogs: ServiceRecord[]} | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Printer>>({
    brand: '',
    model: '',
    serialNumber: '',
    location: '',
    floor: '',
    lastCounter: 0,
    compatibleToner: '',
    connectionType: 'USB',
    ipAddress: '',
    supplier: ''
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    setPrinters(StorageService.getPrinters());
    setConfig(StorageService.getConfig());
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm('Bu yazıcıyı silmek istediğinize emin misiniz? Bu işlem geri alınamaz.')) {
      StorageService.deletePrinter(id);
      // Update state directly to reflect changes immediately
      setPrinters(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleEditClick = (e: React.MouseEvent, printer: Printer) => {
    e.stopPropagation();
    openFormModal(printer);
  };

  const handleHistoryClick = (e: React.MouseEvent, printer: Printer) => {
    e.stopPropagation();
    openHistoryModal(printer);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    let updatedList = [...printers];

    if (editingPrinter) {
      updatedList = updatedList.map(p => 
        p.id === editingPrinter.id ? { ...p, ...formData } as Printer : p
      );
    } else {
      const newPrinter: Printer = {
        id: Date.now().toString(),
        lastTonerDate: new Date().toISOString(),
        ...formData as Printer
      };
      updatedList.push(newPrinter);
    }

    StorageService.savePrinters(updatedList);
    setPrinters(updatedList);
    closeFormModal();
  };

  const openFormModal = (printer?: Printer) => {
    if (printer) {
      setEditingPrinter(printer);
      setFormData(printer);
    } else {
      setEditingPrinter(null);
      setFormData({
        brand: config.brands[0] || '',
        model: config.models[0] || '',
        serialNumber: '',
        location: '',
        floor: '',
        lastCounter: 0,
        compatibleToner: '',
        connectionType: 'USB',
        ipAddress: '',
        supplier: config.suppliers[0] || ''
      });
    }
    setIsFormModalOpen(true);
  };

  const closeFormModal = () => {
    setIsFormModalOpen(false);
    setEditingPrinter(null);
  };

  const openHistoryModal = (printer: Printer) => {
    const allLogs = StorageService.getLogs();
    const allServices = StorageService.getServiceRecords();

    // Filter logs for this printer
    const printerLogs = allLogs.filter(log => log.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const printerServices = allServices.filter(srv => srv.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    setSelectedPrinterHistory({
      printer,
      tonerLogs: printerLogs,
      serviceLogs: printerServices
    });
    setIsHistoryModalOpen(true);
  };

  const filteredPrinters = printers.filter(p => 
    p.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.serialNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Yazıcı Listesi ({printers.length})</h2>
        <button 
          onClick={() => openFormModal()}
          className="bg-primary-700 hover:bg-primary-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-all active:scale-95"
        >
          <Plus size={18} />
          <span>Yeni Yazıcı Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
        <input
          type="text"
          placeholder="Yazıcı ara (Marka, Model, IP, Konum)..."
          className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 outline-none transition-all"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredPrinters.map(printer => (
          <div key={printer.id} className="bg-white dark:bg-slate-800 p-5 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow relative group">
            <div className="flex justify-between items-start mb-3">
              <div className="flex items-center gap-2 text-primary-700 dark:text-primary-400 font-bold">
                <PrinterIcon size={18} />
                <span>{printer.brand} {printer.model}</span>
              </div>
              <div className="flex gap-1">
                 <button 
                   type="button"
                   onClick={(e) => handleHistoryClick(e, printer)} 
                   className="p-1.5 text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors" 
                   title="Detay ve Geçmiş"
                 >
                  <History size={16} />
                </button>
                <button 
                   type="button"
                   onClick={(e) => handleEditClick(e, printer)} 
                   className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20 rounded transition-colors" 
                   title="Düzenle"
                >
                  <Edit2 size={16} />
                </button>
                <button 
                  type="button"
                  onClick={(e) => handleDelete(e, printer.id)} 
                  className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors" 
                  title="Sil"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>

            <div className="space-y-2 text-sm text-slate-600 dark:text-slate-300">
               {/* Connection Info Badge */}
               <div className="flex gap-2 mb-2 flex-wrap">
                <div className={`flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium border ${
                  printer.connectionType === 'Network' 
                    ? 'bg-purple-50 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300 border-purple-100 dark:border-purple-800' 
                    : 'bg-gray-100 dark:bg-slate-700 text-gray-700 dark:text-gray-300 border-gray-200 dark:border-slate-600'
                }`}>
                  {printer.connectionType === 'Network' ? <Wifi size={12}/> : <Usb size={12}/>}
                  {printer.connectionType === 'Network' ? printer.ipAddress : 'USB Bağlantı'}
                </div>
                {printer.supplier && (
                  <div className="flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium border bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 border-blue-100 dark:border-blue-800">
                    <Truck size={12} />
                    {printer.supplier}
                  </div>
                )}
              </div>

              <div className="flex items-center gap-2">
                <Hash size={14} className="text-slate-400" />
                <span className="font-mono bg-slate-100 dark:bg-slate-700 px-1 rounded text-xs">{printer.serialNumber}</span>
              </div>
              <div className="flex items-center gap-2">
                <MapPin size={14} className="text-slate-400" />
                <span>{printer.floor} - {printer.location}</span>
              </div>

