export const StorageService = {
  getPrinters: (): Printer[] => {
    const data = localStorage.getItem(STORAGE_KEYS.PRINTERS);
    return data ? JSON.parse(data) : INITIAL_PRINTERS;
  },

  savePrinters: (printers: Printer[]) => {
    localStorage.setItem(STORAGE_KEYS.PRINTERS, JSON.stringify(printers));
  },

  // New: Delete Printer
  deletePrinter: (printerId: string) => {
    const printers = StorageService.getPrinters();
    const updated = printers.filter(p => String(p.id) !== String(printerId));
    localStorage.setItem(STORAGE_KEYS.PRINTERS, JSON.stringify(updated));
  },

  getStocks: (): TonerStock[] => {
    const data = localStorage.getItem(STORAGE_KEYS.STOCKS);
    return data ? JSON.parse(data) : INITIAL_STOCKS;
  },

  saveStocks: (stocks: TonerStock[]) => {
    localStorage.setItem(STORAGE_KEYS.STOCKS, JSON.stringify(stocks));
  },

  getLogs: (): StockLog[] => {
    const data = localStorage.getItem(STORAGE_KEYS.LOGS);
    return data ? JSON.parse(data) : [];
  },

  addLog: (log: StockLog) => {
    const logs = StorageService.getLogs();
    const newLogs = [log, ...logs];
    localStorage.setItem(STORAGE_KEYS.LOGS, JSON.stringify(newLogs));
  },

  // New: Service Records
  getServiceRecords: (): ServiceRecord[] => {
    const data = localStorage.getItem(STORAGE_KEYS.SERVICES);
    return data ? JSON.parse(data) : [];
  },

  saveServiceRecords: (records: ServiceRecord[]) => {
    localStorage.setItem(STORAGE_KEYS.SERVICES, JSON.stringify(records));
  },

  addServiceRecord: (record: ServiceRecord) => {
    const records = StorageService.getServiceRecords();
    const newRecords = [record, ...records];
    localStorage.setItem(STORAGE_KEYS.SERVICES, JSON.stringify(newRecords));
  },

  getConfig: (): SystemConfig => {
    const data = localStorage.getItem(STORAGE_KEYS.CONFIG);
    return data ? JSON.parse(data) : INITIAL_CONFIG;
  },

  saveConfig: (config: SystemConfig) => {
    localStorage.setItem(STORAGE_KEYS.CONFIG, JSON.stringify(config));
  }
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Globe, Trash2, History, Wrench, Truck } from 'lucide-react';
import { Printer, SystemConfig, StockLog, ServiceRecord } from '../types';
import { StorageService } from '../services/storage';

interface PrinterListProps {
  onSelectPrinter?: (printer: Printer) => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ onSelectPrinter }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [] });
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<Printer | null>(null);
  const [selectedPrinterHistory, setSelectedPrinterHistory] = useState<{printer: Printer, tonerLogs: StockLog[], serviceLogs: ServiceRecord[]} | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Printer>>({
    brand: '',
    model: '',
    serialNumber: '',
    location: '',
    floor: '',
    lastCounter: 0,
    compatibleToner: '',
    connectionType: 'USB',
    ipAddress: '',
    supplier: ''
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    setPrinters(StorageService.getPrinters());
    setConfig(StorageService.getConfig());
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // Kart tıklamasını engelle
    // window.confirm kullanarak tarayıcı uyumluluğunu artırıyoruz
    if (window.confirm('Bu yazıcıyı silmek istediğinize emin misiniz? Bu işlem geri alınamaz.')) {
      // Önce veritabanından/storage'dan sil
      StorageService.deletePrinter(id);

      // Sonra ekranı anlık güncelle (ID'leri string'e çevirerek karşılaştırıyoruz)
      setPrinters(prev => prev.filter(p => String(p.id) !== String(id)));
    }
  };

  const handleEditClick = (e: React.MouseEvent, printer: Printer) => {
    e.stopPropagation();
    openFormModal(printer);
  };

  const handleHistoryClick = (e: React.MouseEvent, printer: Printer) => {
    e.stopPropagation();
    openHistoryModal(printer);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    let updatedList = [...printers];

    if (editingPrinter) {
      updatedList = updatedList.map(p => 
        p.id === editingPrinter.id ? { ...p, ...formData } as Printer : p
      );
    } else {
      const newPrinter: Printer = {
        id: Date.now().toString(),
        lastTonerDate: new Date().toISOString(),
        ...formData as Printer
      };
      updatedList.push(newPrinter);
    }

    StorageService.savePrinters(updatedList);
    setPrinters(updatedList);
    closeFormModal();
  };

  const openFormModal = (printer?: Printer) => {
    if (printer) {
      setEditingPrinter(printer);
      setFormData(printer);
    } else {
      setEditingPrinter(null);
      setFormData({
        brand: config.brands[0] || '',
        model: config.models[0] || '',
        serialNumber: '',
        location: '',
        floor: '',
        lastCounter: 0,
        compatibleToner: '',
        connectionType: 'USB',
        ipAddress: '',
        supplier: config.suppliers[0] || ''
      });
    }
    setIsFormModalOpen(true);
  };

  const closeFormModal = () => {
    setIsFormModalOpen(false);
    setEditingPrinter(null);
  };

  const openHistoryModal = (printer: Printer) => {
    const allLogs = StorageService.getLogs();
    const allServices = StorageService.getServiceRecords();

    // Filter logs for this printer
    const printerLogs = allLogs.filter(log => String(log.printerId) === String(printer.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const printerServices = allServices.filter(srv => String(srv.printerId) === String(printer.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    setSelectedPrinterHistory({
      printer,
      tonerLogs: printerLogs,
      serviceLogs: printerServices
    });
    setIsHistoryModalOpen(true);
  };

  const filteredPrinters = printers.filter(p => 
    p.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.serialNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Yazıcı Listesi ({printers.length})</h2>
        <button 
          onClick={() => openFormModal()}
          className="bg-primary-700 hover:bg-primary-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-all active:scale-95"
        >
          <Plus size={18} />
          <span>Yeni Yazıcı Ekle</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
        <input
          type="text"
          placeholder="Yazıcı ara (Marka, Model, IP, Konum)..."
          className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 outline-none transition-all"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredPrinters.map(printer => (
          <div key={printer.id} className="bg-white dark:bg-slate-800 p-5 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow relative group">
            <div className="flex justify-between items-start mb-3">
              <div className="flex items-center gap-2 text-primary-700 dark:text-primary-400 font-bold">
                <PrinterIcon size={18} />
                <span>{printer.brand} {printer.model}</span>
              </div>
              <div className="flex gap-1">
                 <button 
                   type="button"
                   onClick={(e) => handleHistoryClick(e, printer)} 
                   className="p-1.5 text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors" 
                   title="Detay ve Geçmiş"
                 >
                  <History size={16} />
                </button>
                <button 
                   type="button"
                   onClick={(e) => handleEditClick(e, printer)} 
                   className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20 rounded transition-colors" 
                   title="Düzenle"
                >
                  <Edit2 size={16} />
                </button>
                <button 
                  type="button"
                  onClick={(e) => handleDelete(e, printer.id)} 
                  className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors" 
                  title="Sil"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>

            <div className="space-y-2 text-sm text-slate-600 dark:text-slate-300">
               {/* Connection Info Badge */}
               <div className="flex gap-2 mb-2 flex-wrap">
                <div className={`flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium border ${
                  printer.connectionType === 'Network' 
                    ? 'bg-purple-50 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300 border-purple-100 dark:border-purple-800' 
                    : 'bg-gray-100 dark:bg-slate-700 text-gray-700 dark:text-gray-300 border-gray-200 dark:border-slate-600'
                }`}>
                  {printer.connectionType === 'Network' ? <Wifi size={12}/> : <Usb size={12}/>}
                  {printer.connectionType === 'Network' ? printer.ipAddress : 'USB Bağlantı'}
                </div>
                {printer.supplier && (
                  <div className="flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium border bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 border-blue-100 dark:border-blue-800">
                    <Truck size={12} />
                    {printer.supplier}
                  </div>
                )}
              </div>

              <div className="flex items-center gap-2">
                <Hash size={14} className="text-slate-400" />
                <span className="font-mono bg-slate-100 dark:bg-slate-700 px-1 rounded text-xs">{printer.serialNumber}</span>
              </div>
              <div className="flex items-center gap-2">
                <MapPin size={14} className="text-slate-400" />
                <span>{printer.floor} - {printer.location}</span>
              </div>

              <div className="flex justify-between border-t border-slate-50 dark:border-slate-700 pt-2 mt-2">
                <div>
                  <p className="text-xs text-slate-400">Sayaç</p>
                  <p className="font-semibold text-slate-700 dark:text-slate-200">{printer.lastCounter.toLocaleString()}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs text-slate-400">Son Değişim</p>
                  <p className="font-semibold text-slate-700 dark:text-slate-200">{new Date(printer.lastTonerDate).toLocaleDateString('tr-TR')}</p>
                </div>
              </div>
              <div className="mt-2 pt-2 border-t border-dashed border-slate-200 dark:border-slate-700 flex justify-between items-center">
                 <p className="text-xs text-slate-400">Uyumlu Toner</p>
                 <span className="inline-block bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300 px-2 py-0.5 rounded text-xs font-medium">
                   {printer.compatibleToner || 'Belirtilmedi'}
                 </span>
              </div>

               <button 
                type="button"
                onClick={(e) => handleHistoryClick(e, printer)} 
                className="w-full mt-2 py-1.5 text-xs text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-900/30 hover:bg-primary-100 dark:hover:bg-primary-900/50 rounded transition-colors flex items-center justify-center gap-1"
               >
                 <History size={12} />
                 Detay & Geçmişi Gör
               </button>
            </div>
          </div>
        ))}
      </div>

      {/* Add/Edit Modal */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-y-auto max-h-[90vh]">
            <div className="bg-slate-50 dark:bg-slate-700 px-6 py-4 border-b border-slate-100 dark:border-slate-600 flex justify-between items-center sticky top-0">
              <h3 className="font-bold text-lg text-slate-800 dark:text-white">
                {editingPrinter ? 'Yazıcı Düzenle' : 'Yeni Yazıcı Ekle'}
              </h3>
              <button onClick={closeFormModal}><X size={20} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200" /></button>
            </div>

            <form onSubmit={handleSave} className="p-6 space-y-4">
              {/* Brand & Model Select */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Marka</label>
                  <select 
                    required 
                    className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.brand} 
                    onChange={e => setFormData({...formData, brand: e.target.value})}
                  >
                    <option value="">Seçiniz</option>
                    {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Model</label>
                  <select 
                    required 
                    className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.model} 
                    onChange={e => setFormData({...formData, model: e.target.value})}
                  >
                    <option value="">Seçiniz</option>
                    {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>

              {/* Supplier Selection */}
              <div>
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Tedarikçi Firma</label>
                 <select 
                    className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.supplier} 
                    onChange={e => setFormData({...formData, supplier: e.target.value})}
                  >
                    <option value="">Seçiniz</option>
                    {config.suppliers.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
              </div>

              {/* Connection Type */}
              <div className="bg-slate-50 dark:bg-slate-700 p-3 rounded-lg border border-slate-200 dark:border-slate-600">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-200 mb-2">Bağlantı Türü</label>
                <div className="flex gap-4">
                  <label className="flex items-center gap-2 cursor-pointer p-2 rounded hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors">
                    <input 
                      type="radio" 
                      name="connType" 
                      checked={formData.connectionType === 'USB'} 
                      onChange={() => setFormData({...formData, connectionType: 'USB', ipAddress: ''})} 
                      className="accent-primary-600"
                    />
                    <span className="flex items-center gap-1 text-sm text-slate-900 dark:text-white"><Usb size={16}/> USB</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer p-2 rounded hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors">
                    <input 
                      type="radio" 
                      name="connType" 
                      checked={formData.connectionType === 'Network'} 
                      onChange={() => setFormData({...formData, connectionType: 'Network'})} 
                      className="accent-primary-600"
                    />
                    <span className="flex items-center gap-1 text-sm text-slate-900 dark:text-white"><Wifi size={16}/> Network (IP)</span>
                  </label>
                </div>

                {formData.connectionType === 'Network' && (
                  <div className="mt-3">
                    <label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">IP Adresi</label>
                    <div className="relative">
                      <Globe size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                      <input 
                        type="text" 
                        required 
                        className="w-full pl-9 p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-600 text-slate-900 dark:text-white"
                        value={formData.ipAddress} 
                        onChange={e => setFormData({...formData, ipAddress: e.target.value})} 
                        placeholder="Örn: 192.168.1.236" 
                      />
                    </div>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Seri No</label>
                  <input required className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} placeholder="Örn: CNC123" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Kat</label>
                  <input required className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} placeholder="Örn: 4. Kat" />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Birim/Oda</label>
                <input required className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} placeholder="Örn: Medikal Muhasebe" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Son Sayaç</label>
                  <input type="number" required className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.lastCounter} onChange={e => setFormData({...formData, lastCounter: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Uyumlu Toner</label>
                  <input className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.compatibleToner} onChange={e => setFormData({...formData, compatibleToner: e.target.value})} placeholder="Örn: C-EXV 49" />
                </div>
              </div>

              <div className="pt-4 flex gap-3">
                <button type="button" onClick={closeFormModal} className="flex-1 py-3 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors">İptal</button>
                <button type="submit" className="flex-1 py-3 bg-primary-700 text-white rounded-lg hover:bg-primary-800 transition-colors font-medium">Kaydet</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* History Modal */}
      {isHistoryModalOpen && selectedPrinterHistory && (
         <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-y-auto max-h-[90vh]">
            <div className="bg-slate-50 dark:bg-slate-700 px-6 py-4 border-b border-slate-100 dark:border-slate-600 flex justify-between items-center sticky top-0">
               <div>
                  <h3 className="font-bold text-lg text-slate-800 dark:text-white">
                    {selectedPrinterHistory.printer.brand} {selectedPrinterHistory.printer.model}
                  </h3>
                  <div className="flex gap-2 items-center">
                    <p className="text-xs text-slate-500 dark:text-slate-400">{selectedPrinterHistory.printer.location} - {selectedPrinterHistory.printer.floor}</p>
                    {selectedPrinterHistory.printer.supplier && (
                       <span className="text-[10px] bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-1.5 py-0.5 rounded border border-blue-200 dark:border-blue-800">
                         {selectedPrinterHistory.printer.supplier}
                       </span>
                    )}
                  </div>
               </div>
              <button onClick={() => setIsHistoryModalOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200" /></button>
            </div>

            <div className="p-6">
              <h4 className="font-semibold text-primary-700 dark:text-primary-400 mb-3 flex items-center gap-2"><History size={16}/> Toner Değişim Geçmişi</h4>
              <div className="space-y-4 mb-8">
                {selectedPrinterHistory.tonerLogs.length === 0 && <p className="text-sm text-slate-400">Henüz kayıt yok.</p>}
                {selectedPrinterHistory.tonerLogs.map((log, index) => {
                   const prevLog = selectedPrinterHistory.tonerLogs[index + 1];
                   return (
                     <div key={log.id} className="relative pl-6 border-l-2 border-slate-200 dark:border-slate-700 pb-2 last:pb-0">
                       <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-primary-500 border-2 border-white dark:border-slate-800"></div>
                       <div className="bg-slate-50 dark:bg-slate-700/50 p-3 rounded-lg">
                          <div className="flex justify-between items-start">
                             <span className="font-bold text-slate-800 dark:text-white text-sm">{new Date(log.date).toLocaleDateString('tr-TR')}</span>
                             <span className="text-xs text-slate-500">{new Date(log.date).toLocaleTimeString('tr-TR')}</span>
                          </div>
                          <p className="text-sm text-slate-600 dark:text-slate-300 mt-1">
                            {log.tonerModel} toner takıldı. <span className="text-xs text-slate-400">({log.user})</span>
                          </p>
                          {prevLog && (
                            <p className="text-xs text-slate-400 mt-1">
                              Önceki değişim: {new Date(prevLog.date).toLocaleDateString('tr-TR')}
                            </p>
                          )}
                       </div>
                     </div>
                   );
                })}
              </div>

              <h4 className="font-semibold text-orange-700 dark:text-orange-400 mb-3 flex items-center gap-2 pt-4 border-t dark:border-slate-700"><Wrench size={16}/> Servis & Bakım Geçmişi</h4>
              <div className="space-y-2">
                 {selectedPrinterHistory.serviceLogs.length === 0 && <p className="text-sm text-slate-400">Servis kaydı yok.</p>}
                 {selectedPrinterHistory.serviceLogs.map(srv => (
                    <div key={srv.id} className="bg-orange-50 dark:bg-orange-900/10 border border-orange-100 dark:border-orange-900/30 p-3 rounded-lg text-sm">
                       <div className="flex justify-between font-medium text-slate-800 dark:text-slate-200">
                         <span>{srv.issue}</span>
                         <span>{new Date(srv.date).toLocaleDateString('tr-TR')}</span>
                       </div>
                       <p className="text-slate-600 dark:text-slate-400 mt-1">{srv.actionTaken}</p>
                       <div className="mt-2 flex justify-between text-xs text-slate-500">
                          <span>{srv.provider}</span>
                          <span className="font-semibold">{srv.cost > 0 ? `${srv.cost} ₺` : 'Ücretsiz'}</span>
                       </div>
                    </div>
                 ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Tag, Box, MessageCircle, Truck } from 'lucide-react';
import { StorageService } from '../services/storage';
import { SystemConfig } from '../types';

export const Settings: React.FC = () => {
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [] });
  const [newBrand, setNewBrand] = useState('');
  const [newModel, setNewModel] = useState('');
  const [newSupplier, setNewSupplier] = useState('');
  const [whatsappNumber, setWhatsappNumber] = useState('');

  useEffect(() => {
    const currentConfig = StorageService.getConfig();
    setConfig(currentConfig);
    if (currentConfig.whatsappNumber) {
      setWhatsappNumber(currentConfig.whatsappNumber);
    }
  }, []);

  const handleAddBrand = (e: React.FormEvent) => {
    e.preventDefault();
    if (newBrand.trim() && !config.brands.includes(newBrand.trim())) {
      const updatedConfig = { ...config, brands: [...config.brands, newBrand.trim()] };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
      setNewBrand('');
    }
  };

  const handleDeleteBrand = (brandToRemove: string) => {
    if (window.confirm(`${brandToRemove} markasını silmek istediğinize emin misiniz?`)) {
      const newBrands = config.brands.filter(b => b !== brandToRemove);
      const updatedConfig = { ...config, brands: newBrands };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
    }
  };

  const handleAddModel = (e: React.FormEvent) => {
    e.preventDefault();
    if (newModel.trim() && !config.models.includes(newModel.trim())) {
      const updatedConfig = { ...config, models: [...config.models, newModel.trim()] };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
      setNewModel('');
    }
  };

  const handleDeleteModel = (modelToRemove: string) => {
    if (window.confirm(`${modelToRemove} modelini silmek istediğinize emin misiniz?`)) {
      const newModels = config.models.filter(m => m !== modelToRemove);
      const updatedConfig = { ...config, models: newModels };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
    }
  };

  const handleAddSupplier = (e: React.FormEvent) => {
    e.preventDefault();
    if (newSupplier.trim() && !config.suppliers.includes(newSupplier.trim())) {
      const updatedConfig = { ...config, suppliers: [...config.suppliers, newSupplier.trim()] };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
      setNewSupplier('');
    }
  };

  const handleDeleteSupplier = (supplierToRemove: string) => {
    if (window.confirm(`${supplierToRemove} firmasını silmek istediğinize emin misiniz?`)) {
      const newSuppliers = config.suppliers.filter(s => s !== supplierToRemove);
      const updatedConfig = { ...config, suppliers: newSuppliers };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
    }
  };

  const handleSaveWhatsapp = () => {
    const updatedConfig = { ...config, whatsappNumber: whatsappNumber };
    StorageService.saveConfig(updatedConfig);
    setConfig(updatedConfig);
    alert('Bildirim numarası kaydedildi.');
  };

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800 dark:text-white flex items-center gap-2">
        <Save size={24} className="text-primary-600 dark:text-primary-400" />
        Sistem Ayarları
      </h2>

      {/* WhatsApp Notification Settings */}
      <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
        <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200 mb-4 flex items-center gap-2">
          <MessageCircle size={20} className="text-green-600" /> WhatsApp Bildirim Ayarları
        </h3>
        <p className="text-sm text-slate-500 dark:text-slate-400 mb-4">
          Stok sayısı kritik seviyeye (1 adet) düştüğünde bu numaraya otomatik bildirim gönderilecektir.
        </p>
        <div className="flex gap-2">
           <input 
              type="tel" 
              placeholder="905xxxxxxxxx"
              className="flex-1 p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              value={whatsappNumber}
              onChange={(e) => setWhatsappNumber(e.target.value)}
            />
             <button onClick={handleSaveWhatsapp} className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700">
              Kaydet
            </button>
        </div>
      </div>

      {/* Grid for Data Management */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Supplier Management */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 md:col-span-2">
          <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200 mb-4 flex items-center gap-2">
            <Truck size={20} /> Tedarikçi / Servis Firmaları
          </h3>
          <p className="text-xs text-slate-400 mb-3">Yazıcıların temin edildiği ve servise gittiği firmalar (Örn: Anahtar Bilgisayar, Enes Bilişim)</p>

          <form onSubmit={handleAddSupplier} className="flex gap-2 mb-4">
            <input 
              type="text" 
              placeholder="Yeni firma (örn: Anahtar Bilgisayar)"
              className="flex-1 p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              value={newSupplier}
              onChange={(e) => setNewSupplier(e.target.value)}
            />
            <button type="submit" className="bg-primary-700 text-white p-2 rounded-lg hover:bg-primary-800">
              <Plus size={20} />
            </button>
          </form>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 max-h-48 overflow-y-auto">
            {config.suppliers.map(supplier => (
              <div key={supplier} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700 rounded-lg group">
                <span className="font-medium text-slate-700 dark:text-slate-200">{supplier}</span>
                <button 
                  type="button"
                  onClick={() => handleDeleteSupplier(supplier)} 
                  className="text-slate-400 hover:text-red-500 dark:hover:text-red-400 transition-colors"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            ))}
          </div>
