        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Tag, Box, MessageCircle, Truck } from 'lucide-react';
import { StorageService } from '../services/storage';
import { SystemConfig } from '../types';

export const Settings: React.FC = () => {
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [] });
  const [newBrand, setNewBrand] = useState('');
  const [newModel, setNewModel] = useState('');
  const [newSupplier, setNewSupplier] = useState('');
  const [whatsappNumber, setWhatsappNumber] = useState('');

  useEffect(() => {
    loadConfig();
  }, []);

  const loadConfig = () => {
    const currentConfig = StorageService.getConfig();
    setConfig(currentConfig);
    if (currentConfig.whatsappNumber) {
      setWhatsappNumber(currentConfig.whatsappNumber);
    }
  };

  // --- Handlers for Brands ---
  const handleAddBrand = (e: React.FormEvent) => {
    e.preventDefault();
    const val = newBrand.trim();
    if (val && !config.brands.includes(val)) {
      const updated = { ...config, brands: [...config.brands, val] };
      StorageService.saveConfig(updated);
      setConfig(updated);
      setNewBrand('');
    }
  };

  const handleDeleteBrand = (e: React.MouseEvent, item: string) => {
    e.preventDefault();
    if (window.confirm(`"${item}" markasını silmek istediğinize emin misiniz?`)) {
      // Use exact string matching after trimming just in case
      const updatedList = config.brands.filter(b => b.trim() !== item.trim());
      const updatedConfig = { ...config, brands: updatedList };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
    }
  };

  // --- Handlers for Models ---
  const handleAddModel = (e: React.FormEvent) => {
    e.preventDefault();
    const val = newModel.trim();
    if (val && !config.models.includes(val)) {
      const updated = { ...config, models: [...config.models, val] };
      StorageService.saveConfig(updated);
      setConfig(updated);
      setNewModel('');
    }
  };

  const handleDeleteModel = (e: React.MouseEvent, item: string) => {
    e.preventDefault();
    if (window.confirm(`"${item}" modelini silmek istediğinize emin misiniz?`)) {
      const updatedList = config.models.filter(m => m.trim() !== item.trim());
      const updatedConfig = { ...config, models: updatedList };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
    }
  };

  // --- Handlers for Suppliers ---
  const handleAddSupplier = (e: React.FormEvent) => {
    e.preventDefault();
    const val = newSupplier.trim();
    if (val && !config.suppliers.includes(val)) {
      const updated = { ...config, suppliers: [...config.suppliers, val] };
      StorageService.saveConfig(updated);
      setConfig(updated);
      setNewSupplier('');
    }
  };

  const handleDeleteSupplier = (e: React.MouseEvent, item: string) => {
    e.preventDefault();
    if (window.confirm(`"${item}" firmasını silmek istediğinize emin misiniz?`)) {
      const updatedList = config.suppliers.filter(s => s.trim() !== item.trim());
      const updatedConfig = { ...config, suppliers: updatedList };
      StorageService.saveConfig(updatedConfig);
      setConfig(updatedConfig);
    }
  };

  const handleSaveWhatsapp = () => {
    const updatedConfig = { ...config, whatsappNumber: whatsappNumber };
    StorageService.saveConfig(updatedConfig);
    setConfig(updatedConfig);
    alert('Bildirim numarası kaydedildi.');
  };

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800 dark:text-white flex items-center gap-2">
        <Save size={24} className="text-primary-600 dark:text-primary-400" />
        Sistem Ayarları
      </h2>

      {/* WhatsApp Section */}
      <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
        <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200 mb-4 flex items-center gap-2">
          <MessageCircle size={20} className="text-green-600" /> WhatsApp Bildirim Ayarları
        </h3>
        <div className="flex gap-2">
           <input 
              type="tel" 
              placeholder="905xxxxxxxxx"
              className="flex-1 p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              value={whatsappNumber}
              onChange={(e) => setWhatsappNumber(e.target.value)}
            />
             <button onClick={handleSaveWhatsapp} className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700">
              Kaydet
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* SUPPLIERS */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 md:col-span-2">
          <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200 mb-4 flex items-center gap-2">
            <Truck size={20} /> Tedarikçi / Servis Firmaları
          </h3>
          <form onSubmit={handleAddSupplier} className="flex gap-2 mb-4">
            <input 
              type="text" 
              placeholder="Yeni firma ekle..."
              className="flex-1 p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              value={newSupplier}
              onChange={(e) => setNewSupplier(e.target.value)}
            />
            <button type="submit" className="bg-primary-700 text-white p-2 rounded-lg hover:bg-primary-800">
              <Plus size={20} />
            </button>
          </form>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 max-h-48 overflow-y-auto">
            {config.suppliers.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700 rounded-lg group">
                <span className="font-medium text-slate-700 dark:text-slate-200">{item}</span>
                <button 
                  type="button"
                  onClick={(e) => handleDeleteSupplier(e, item)} 
                  className="bg-white dark:bg-slate-600 p-2 rounded text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 transition-all border border-slate-200 dark:border-slate-500"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* BRANDS */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
          <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200 mb-4 flex items-center gap-2">
            <Tag size={20} /> Yazıcı Markaları
          </h3>
          <form onSubmit={handleAddBrand} className="flex gap-2 mb-4">
            <input 
              type="text" 
              placeholder="Yeni marka ekle..."
              className="flex-1 p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              value={newBrand}
              onChange={(e) => setNewBrand(e.target.value)}
            />
            <button type="submit" className="bg-primary-700 text-white p-2 rounded-lg hover:bg-primary-800">
              <Plus size={20} />
            </button>
          </form>
          <div className="space-y-2 max-h-64 overflow-y-auto">
            {config.brands.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700 rounded-lg group">
                <span className="font-medium text-slate-700 dark:text-slate-200">{item}</span>
                <button 
                  type="button"
                  onClick={(e) => handleDeleteBrand(e, item)} 
                  className="bg-white dark:bg-slate-600 p-2 rounded text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 transition-all border border-slate-200 dark:border-slate-500"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* MODELS */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
          <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200 mb-4 flex items-center gap-2">
            <Box size={20} /> Yazıcı Modelleri
          </h3>
          <form onSubmit={handleAddModel} className="flex gap-2 mb-4">
            <input 
              type="text" 
              placeholder="Yeni model ekle..."
              className="flex-1 p-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              value={newModel}
              onChange={(e) => setNewModel(e.target.value)}
            />
            <button type="submit" className="bg-primary-700 text-white p-2 rounded-lg hover:bg-primary-800">
              <Plus size={20} />
            </button>
          </form>
          <div className="space-y-2 max-h-64 overflow-y-auto">
            {config.models.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700 rounded-lg group">
                <span className="font-medium text-slate-700 dark:text-slate-200">{item}</span>
                <button 
                  type="button"
                  onClick={(e) => handleDeleteModel(e, item)} 
                  className="bg-white dark:bg-slate-600 p-2 rounded text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 transition-all border border-slate-200 dark:border-slate-500"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

