  const [cost, setCost] = useState(0); 
  const [newStockModel, setNewStockModel] = useState(''); 
  const [description, setDescription] = useState('');

  // Notification
  const [message, setMessage] = useState<{type: 'success' | 'error', text: string} | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setStocks(StorageService.getStocks());
    setPrinters(StorageService.getPrinters());
    setLogs(StorageService.getLogs()); // Fetch Logs
    setConfig(StorageService.getConfig());
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 3000);
  };

  const checkLowStockAndNotify = (model: string, newQty: number) => {
    if (newQty <= 1) {
       const config = StorageService.getConfig();
       if (config.whatsappNumber) {
         setTimeout(() => {
            alert(`⚠️ SİSTEM UYARISI: ${model} toneri kritik seviyeye (${newQty}) düştü! WhatsApp bildirimi ${config.whatsappNumber} numarasına gönderildi.`);
         }, 500);
       }
    }
  };

  const handleStockIn = (e: React.FormEvent) => {
    e.preventDefault();
    const model = newStockModel.trim(); // No uppercase forcing, keeping original format
    if (!model) {
      showMessage('error', 'Lütfen bir model seçiniz.');
      return;
    }

    const updatedStocks = [...stocks];
    const existingIndex = updatedStocks.findIndex(s => s.modelName === model);

    if (existingIndex >= 0) {
      updatedStocks[existingIndex].quantity += quantity;
    } else {
      updatedStocks.push({ modelName: model, quantity: quantity });
    }

    StorageService.saveStocks(updatedStocks);

    // Log
    const log: StockLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      type: 'IN',
      tonerModel: model,
      quantity: quantity,
      description: 'Stok Girişi (Manuel)',
      user: user.name,
      cost: cost 
    };
    StorageService.addLog(log);

    refreshData();
    showMessage('success', `${quantity} adet ${model} stoğa eklendi.`);
    setNewStockModel('');
    setQuantity(1);
    setCost(0);
    setActiveTab('LIST');
  };

  const handleStockOut = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTonerModel) {
      showMessage('error', 'Lütfen toner seçiniz.');
      return;
    }

    // Check stock
    const updatedStocks = [...stocks];
    const stockIndex = updatedStocks.findIndex(s => s.modelName === selectedTonerModel);

    if (stockIndex === -1 || updatedStocks[stockIndex].quantity < 1) {
      showMessage('error', 'Yetersiz stok!');
      return;
    }

    // Decrement Stock
    updatedStocks[stockIndex].quantity -= 1; 
    const newQuantity = updatedStocks[stockIndex].quantity;
    StorageService.saveStocks(updatedStocks);

    // Check Notification
    checkLowStockAndNotify(selectedTonerModel, newQuantity);

    // Update Printer
    let printerDesc = "";
    if (selectedPrinterId && selectedPrinterId !== 'MANUAL') {
      const updatedPrinters = printers.map(p => {
        if (p.id === selectedPrinterId) {
          printerDesc = `${p.location} (${p.floor})`;
          return {
            ...p,
            lastTonerDate: new Date().toISOString(),
            lastCounter: p.lastCounter 
          };
        }
        return p;
      });
      StorageService.savePrinters(updatedPrinters);
    }

    // Log
    const log: StockLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      type: 'OUT',
      tonerModel: selectedTonerModel,
      quantity: 1,
      printerId: selectedPrinterId === 'MANUAL' ? undefined : selectedPrinterId,
      description: (selectedPrinterId && selectedPrinterId !== 'MANUAL') ? `Yazıcıya Takıldı: ${printerDesc}` : `Stok Çıkışı: ${description}`,
      user: user.name
    };
    StorageService.addLog(log);

    refreshData();
    showMessage('success', `${selectedTonerModel} stoktan düşüldü.`);
    setSelectedPrinterId('');
    setSelectedTonerModel('');
    setActiveTab('LIST');
  };

  // Helper to auto-select toner when printer is selected
  const onPrinterSelect = (printerId: string) => {
    setSelectedPrinterId(printerId);
    const printer = printers.find(p => p.id === printerId);
    if (printer && printer.compatibleToner) {
      setSelectedTonerModel(printer.compatibleToner);
    }
  };

  // Filter only OUT logs for the table
  const outputLogs = logs.filter(l => l.type === 'OUT');

  return (
    <div className="space-y-6">
      {message && (
        <div className={`fixed top-4 right-4 p-4 rounded-lg shadow-xl text-white z-50 animate-bounce ${message.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
          {message.text}
        </div>
      )}

      <div className="flex space-x-2 bg-white dark:bg-slate-800 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 w-fit">
        <button 
          onClick={() => setActiveTab('LIST')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'LIST' ? 'bg-primary-900 text-white' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
        >
          Stok Listesi
        </button>
        <button 
          onClick={() => setActiveTab('IN')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'IN' ? 'bg-green-600 text-white' : 'text-green-700 dark:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20'}`}
        >
          <ArrowDown size={16} /> Stok Giriş
        </button>
        <button 
          onClick={() => setActiveTab('OUT')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'OUT' ? 'bg-orange-600 text-white' : 'text-orange-700 dark:text-orange-400 hover:bg-orange-50 dark:hover:bg-orange-900/20'}`}
        >
          <ArrowUp size={16} /> Toner Çıkış
        </button>
      </div>

      {activeTab === 'LIST' && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {stocks.map(stock => (
            <div key={stock.modelName} className="bg-white dark:bg-slate-800 p-6 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col items-center justify-center text-center">
              <h3 className="text-3xl font-bold text-slate-800 dark:text-white mb-1">{stock.quantity}</h3>
              <p className="text-slate-500 dark:text-slate-400 font-medium">Model: {stock.modelName}</p>
              {stock.quantity < 3 && (
                <span className="mt-2 text-xs bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 px-2 py-1 rounded-full flex items-center gap-1">
                  <AlertTriangle size={12} /> Kritik
                </span>
              )}
            </div>
          ))}
          {stocks.length === 0 && (
            <div className="col-span-full p-8 text-center text-slate-400">Henüz stok kaydı yok.</div>
          )}
        </div>
      )}

      {activeTab === 'IN' && (
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 max-w-lg">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
            <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg text-green-700 dark:text-green-400"><ArrowDown size={20}/></div>
            Stok Girişi Yap
          </h3>
          <form onSubmit={handleStockIn} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Toner/Mürekkep Modeli</label>
              <div className="relative">
                 <select 
                    required
                    className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white appearance-none"
                    value={newStockModel}
                    onChange={e => setNewStockModel(e.target.value)}
                 >
                    <option value="">Listeden Seçiniz</option>
                    {config.tonerModels?.map(s => <option key={s} value={s}>{s}</option>)}
                 </select>
                 <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
              </div>
              <p className="text-xs text-slate-400 mt-2 flex items-center gap-1">
                <SettingsIcon size={12} /> Listede olmayan modelleri "Ayarlar" sayfasından ekleyebilirsiniz.
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Adet</label>
              <div className="flex items-center gap-4">
                <button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">-</button>
                <input 
                  type="number" 
                  min="1"
                  required
                  className="w-full text-center p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none font-bold text-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={quantity}
                  onChange={e => setQuantity(parseInt(e.target.value) || 1)}
                />
                <button type="button" onClick={() => setQuantity(quantity + 1)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">+</button>
              </div>
            </div>

             <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                 Toplam Maliyet (TL) 
                 <span className="text-xs font-normal text-slate-400 ml-1">(Ücretsizse 0 giriniz)</span>
              </label>
              <div className="relative">
                 <Banknote className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input 
                   type="number" 
                   min="0"
                   className="w-full pl-10 p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   value={cost}
                   onChange={e => setCost(parseFloat(e.target.value) || 0)}
                 />
              </div>
            </div>

            <button type="submit" className="w-full py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200 dark:shadow-none">
              Stok Ekle
            </button>
          </form>
        </div>
      )}

      {activeTab === 'OUT' && (
        <div className="flex flex-col lg:flex-row gap-6">
          <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 w-full lg:w-1/2">
             <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
              <div className="p-2 bg-orange-100 dark:bg-orange-900/30 rounded-lg text-orange-700 dark:text-orange-400"><ArrowUp size={20}/></div>
              Toner Çıkışı (Değişim)
            </h3>
            <form onSubmit={handleStockOut} className="space-y-5">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Hangi Yazıcıya?</label>
                <select 
                  className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={selectedPrinterId}
                  onChange={(e) => onPrinterSelect(e.target.value)}
                >
                  <option value="">-- Yazıcı Seçiniz --</option>
                  {printers.map(p => (
                    <option key={p.id} value={p.id}>
                      {p.location} ({p.model})
                    </option>
                  ))}
                  <option value="MANUAL">Listede Yok / Manuel Çıkış</option>
                </select>
              </div>

              {selectedPrinterId === 'MANUAL' && (
                 <div>
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Açıklama / Yer</label>
                 <input 
                   className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   placeholder="Örn: 3. Kat Depo"
                   value={description}
                   onChange={e => setDescription(e.target.value)}
                   required
                 />
               </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Verilen Toner Modeli</label>
                <select 
                  required
                  className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={selectedTonerModel}
                  onChange={e => setSelectedTonerModel(e.target.value)}
                >
                  <option value="">-- Model Seçiniz --</option>
                  {stocks.map(s => (
                    <option key={s.modelName} value={s.modelName} disabled={s.quantity <= 0}>
                      {s.modelName} (Stok: {s.quantity})
                    </option>
                  ))}
                </select>
              </div>

              <div className="p-4 bg-orange-50 dark:bg-orange-900/20 rounded-xl text-sm text-orange-800 dark:text-orange-200 border border-orange-100 dark:border-orange-800/30">
                <p>Onayladığınızda stoktan <strong>1 adet</strong> düşülecektir.</p>
                {selectedPrinterId && selectedPrinterId !== 'MANUAL' && (
                  <p className="mt-1">Seçilen yazıcının <strong>son değişim tarihi</strong> güncellenecektir.</p>
                )}
              </div>

              <button type="submit" className="w-full py-4 bg-orange-600 text-white rounded-xl font-bold hover:bg-orange-700 transition-colors shadow-lg shadow-orange-200 dark:shadow-none">
                Çıkış Yap & Onayla
              </button>
            </form>
          </div>

          {/* Recent Outputs Table - NEW FEATURE */}
          <div className="w-full lg:w-1/2">
             <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 h-full max-h-[600px] overflow-hidden flex flex-col">
                <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
                   <Calendar size={20} className="text-slate-500"/> Son Toner Çıkış Hareketleri
                </h3>
                <div className="overflow-y-auto flex-1">
                   <table className="w-full text-left text-sm">
                      <thead className="bg-slate-50 dark:bg-slate-700 sticky top-0">
                         <tr>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium">Toner</th>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium">Açıklama</th>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium text-right">Tarih</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                         {outputLogs.slice(0, 15).map(log => (
                            <tr key={log.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50">
                               <td className="p-3 font-medium text-slate-800 dark:text-white">{log.tonerModel}</td>
                               <td className="p-3 text-slate-600 dark:text-slate-300 max-w-[150px] truncate" title={log.description}>{log.description}</td>
                               <td className="p-3 text-right text-slate-400 text-xs">
                                  {new Date(log.date).toLocaleDateString('tr-TR')} <br/>
                                  {new Date(log.date).toLocaleTimeString('tr-TR', {hour: '2-digit', minute:'2-digit'})}
                               </td>
                            </tr>
                         ))}
                         {outputLogs.length === 0 && (
                            <tr><td colSpan={3} className="p-4 text-center text-slate-400">Henüz çıkış kaydı yok.</td></tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export interface User {
  username: string;
  name: string;
  role: 'admin' | 'user';
  password?: string; // Added for internal DB storage
}

export type ConnectionType = 'USB' | 'Network';

export type PrinterStatus = 'ACTIVE' | 'MAINTENANCE' | 'BROKEN' | 'SCRAPPED';

export interface Printer {
  id: string;
  serialNumber: string;
  brand: string;   // e.g. "Canon", "HP"
  model: string;   // e.g. "3325i"
  location: string;
  floor: string;
  lastCounter: number;
  lastTonerDate: string;
  compatibleToner: string;
  connectionType: ConnectionType;
  ipAddress?: string; // Only if Network
  supplier: string; // e.g. "Anahtar Bilgisayar", "Enes Bilişim"
  status: PrinterStatus; // New Visual Status
}

export interface TonerStock {
  modelName: string;
  quantity: number;
}

export interface StockLog {
  id: string;
  date: string;
  type: 'IN' | 'OUT';
  tonerModel: string;
  quantity: number;
  description: string;
  printerId?: string;
  user: string;
  cost?: number; // Added for tracking Ink/Toner costs
  pageYield?: number; // New: How many pages printed with the previous toner?
}

export interface ServiceRecord {
  id: string;
  printerId: string;
  printerName: string; // Cache name for easier display
  date: string;
  issue: string; // Arıza tanımı
  actionTaken: string; // Yapılan işlem
  cost: number;
  provider: string; // Servis firması
  status: 'PENDING' | 'COMPLETED' | 'SCRAPPED'; // Bekliyor, Tamamlandı, Hurda
}

export interface SystemConfig {
  brands: string[];
  models: string[];
  suppliers: string[]; // List of vendors
  tonerModels: string[]; // New: List of toner types
  whatsappNumber?: string; // For notifications
}

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Globe, Trash2, History, Truck, AlertTriangle, QrCode, FileSpreadsheet, Download, CheckCircle2, XCircle, AlertCircle } from 'lucide-react';
import { Printer, SystemConfig, StockLog, ServiceRecord, PrinterStatus } from '../types';
import { StorageService } from '../services/storage';

interface PrinterListProps {
  onSelectPrinter?: (printer: Printer) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ onSelectPrinter, targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [] });
  const [searchTerm, setSearchTerm] = useState('');

  // Modals State
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  // QR Code Modal
  const [qrPrinter, setQrPrinter] = useState<Printer | null>(null);

  const [editingPrinter, setEditingPrinter] = useState<Printer | null>(null);
  const [selectedPrinterHistory, setSelectedPrinterHistory] = useState<{printer: Printer, tonerLogs: StockLog[], serviceLogs: ServiceRecord[]} | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Printer>>({
    brand: '',
    model: '',
    serialNumber: '',
    location: '',
    floor: '',
    lastCounter: 0,
    compatibleToner: '',
    connectionType: 'USB',
    ipAddress: '',
    supplier: '',
    status: 'ACTIVE'
  });

  useEffect(() => {
    StorageService.runMaintenance();
    loadData();
  }, []);

  // Deep Linking Logic
  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const target = printers.find(p => p.id === targetPrinterId);
      if (target) {
        openHistoryModal(target);
      }
      // Clear the target so it doesn't reopen if closed
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  const loadData = () => {
    setPrinters(StorageService.getPrinters());
    setConfig(StorageService.getConfig());
  };

  // --- ACTIONS ---

  const confirmDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    setDeleteId(id);
  };

  const performDelete = () => {
    if (deleteId) {
      const updatedList = StorageService.deletePrinter(deleteId);
      setPrinters([...updatedList]);
      setDeleteId(null);
    }
  };

  const handleEditClick = (e: React.MouseEvent, printer: Printer) => {
    e.preventDefault();
    e.stopPropagation();
    openFormModal(printer);
  };

  // QR Button Click
  const handleQrClick = (e: React.MouseEvent, printer: Printer) => {
    e.preventDefault();
    e.stopPropagation();
    setQrPrinter(printer);
  };

  const handleHistoryClick = (printer: Printer) => {
    openHistoryModal(printer);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    let updatedList = [...printers];

    if (editingPrinter) {
      updatedList = updatedList.map(p => 
        p.id === editingPrinter.id ? { ...p, ...formData } as Printer : p
      );
    } else {
      const newPrinter: Printer = {
        id: Date.now().toString(),
        lastTonerDate: new Date().toISOString(),
        ...formData as Printer,
        status: formData.status || 'ACTIVE'
      };
      updatedList.push(newPrinter);
    }

    StorageService.savePrinters(updatedList);
    setPrinters(updatedList);
    closeFormModal();
  };

  // --- EXPORT TO EXCEL ---
  const downloadInventoryCSV = () => {
    if (printers.length === 0) {
      alert('Listelenecek cihaz yok.');
      return;
    }
    const headers = ["Durum", "Marka", "Model", "Seri No", "Konum", "Kat", "Baglanti", "IP", "Son Sayac", "Toner Modeli", "Tedarikci"];
    const rows = printers.map(p => [
      p.status,
      p.brand,
      p.model,
      p.serialNumber,
      `"${p.location}"`,
      p.floor,
      p.connectionType,
      p.ipAddress || '-',
      p.lastCounter,
      p.compatibleToner,
      `"${p.supplier}"`
    ].join(","));

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers.join(",") + "\n" + rows.join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Envanter_Listesi_${new Date().toLocaleDateString()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // --- MODAL HELPERS ---

  const openFormModal = (printer?: Printer) => {
    if (printer) {
      setEditingPrinter(printer);
      setFormData(printer);
    } else {
      setEditingPrinter(null);
      setFormData({
        brand: config.brands[0] || '',
        model: config.models[0] || '',
        serialNumber: '',
        location: '',
        floor: '',
        lastCounter: 0,
        compatibleToner: '',
        connectionType: 'USB',
        ipAddress: '',
        supplier: config.suppliers[0] || '',
        status: 'ACTIVE'
      });
    }
    setIsFormModalOpen(true);
  };

  const closeFormModal = () => {
    setIsFormModalOpen(false);
    setEditingPrinter(null);
  };

  const openHistoryModal = (printer: Printer) => {
    const allLogs = StorageService.getLogs();
    const allServices = StorageService.getServiceRecords();

    const printerLogs = allLogs.filter(log => String(log.printerId) === String(printer.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const printerServices = allServices.filter(srv => String(srv.printerId) === String(printer.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    setSelectedPrinterHistory({
      printer,
      tonerLogs: printerLogs,
      serviceLogs: printerServices
    });
    setIsHistoryModalOpen(true);
  };

  const filteredPrinters = printers.filter(p => 
    p.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.serialNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Helper for Status UI
  const getStatusColor = (status: PrinterStatus) => {
    switch (status) {
      case 'ACTIVE': return 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/10 dark:border-emerald-500/50';
      case 'MAINTENANCE': return 'border-orange-500 bg-orange-50 dark:bg-orange-900/10 dark:border-orange-500/50';
      case 'BROKEN': return 'border-red-500 bg-red-50 dark:bg-red-900/10 dark:border-red-500/50';
      case 'SCRAPPED': return 'border-slate-500 bg-slate-100 dark:bg-slate-800 dark:border-slate-500 opacity-75';
      default: return 'border-slate-200';
    }
  };

  const getStatusLabel = (status: PrinterStatus) => {
    switch (status) {
      case 'ACTIVE': return { text: 'AKTİF', icon: <CheckCircle2 size={12} /> };
      case 'MAINTENANCE': return { text: 'SERVİSTE', icon: <Truck size={12} /> };
      case 'BROKEN': return { text: 'ARIZALI', icon: <AlertTriangle size={12} /> };
      case 'SCRAPPED': return { text: 'HURDA', icon: <XCircle size={12} /> };
      default: return { text: 'BİLİNMİYOR', icon: null };
    }
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Header Section */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Cihaz Yönetimi</h2>
          <p className="text-sm text-slate-500 dark:text-slate-400">Toplam {printers.length} yazıcı listeleniyor</p>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
            <button 
            onClick={downloadInventoryCSV}
            className="flex-1 sm:flex-none bg-green-600 hover:bg-green-700 text-white px-4 py-3 rounded-xl flex items-center justify-center gap-2 font-semibold shadow-sm transition-all"
            >
            <FileSpreadsheet size={20} /> Excel
            </button>
            <button 
            onClick={() => openFormModal()}
            className="flex-[2] sm:flex-none bg-primary-600 hover:bg-primary-700 text-white px-5 py-3 rounded-xl flex items-center justify-center gap-2 font-semibold shadow-lg shadow-primary-200 dark:shadow-none transition-all active:scale-95"
            >
            <Plus size={20} />
            Yeni Cihaz
            </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative group">
        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
          <Search className="text-slate-400 group-focus-within:text-primary-500 transition-colors" size={20} />
        </div>
        <input
          type="text"
          placeholder="Marka, Model, Seri No veya Konum ara..."
          className="w-full pl-11 pr-4 py-4 rounded-2xl border-2 border-transparent bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm focus:border-primary-500 focus:ring-0 outline-none transition-all placeholder:text-slate-400"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* CARD GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {filteredPrinters.map(printer => {
          const statusInfo = getStatusLabel(printer.status || 'ACTIVE');
          const cardStyle = getStatusColor(printer.status || 'ACTIVE');

          return (
            <div 
              key={printer.id} 
              className={`group bg-white dark:bg-slate-800 rounded-2xl shadow-sm hover:shadow-xl border-2 overflow-hidden transition-all duration-300 flex flex-col relative ${cardStyle}`}
            >
              {/* QR CODE BUTTON - ABSOLUTE TOP RIGHT */}
              <button 
                  onClick={(e) => handleQrClick(e, printer)}
                  className="absolute top-4 right-4 p-2 bg-white/80 dark:bg-slate-700/80 backdrop-blur-sm text-slate-600 dark:text-slate-300 rounded-lg shadow-sm hover:text-primary-600 dark:hover:text-primary-400 z-10"
                  title="QR Kod Göster"
              >
                  <QrCode size={20} />
              </button>

              {/* CARD BODY */}
              <div 
                className="p-5 flex-1 cursor-pointer relative"
                onClick={() => handleHistoryClick(printer)}
              >
                {/* Brand & Status Badge */}
                <div className="flex justify-between items-start mb-4 pr-10">
                    <div className="flex flex-col gap-2">
                        <span className="bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider w-fit">
                          {printer.brand}
                        </span>
                        <span className={`flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase w-fit tracking-wide
                          ${printer.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-300' : ''}
                          ${printer.status === 'MAINTENANCE' ? 'bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-300' : ''}
                          ${printer.status === 'BROKEN' ? 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300' : ''}
                          ${printer.status === 'SCRAPPED' ? 'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-400' : ''}
                        `}>
                           {statusInfo.icon} {statusInfo.text}
                        </span>
                    </div>
                </div>

                {/* Model Name */}
                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-1 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">
                  {printer.model}
                </h3>

                {/* Location & Serial */}
                <div className="space-y-2 mt-4">
                    <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400 text-sm">
                      <MapPin size={16} className="text-slate-400" />
                      <span className="line-clamp-1">{printer.location} <span className="text-slate-400">({printer.floor})</span></span>
                    </div>
                    <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400 text-sm">
                      <Hash size={16} className="text-slate-400" />
                      <span className="font-mono">{printer.serialNumber}</span>
                    </div>
                    <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400 text-sm">
                      {printer.connectionType === 'Network' ? <Globe size={16} className="text-emerald-500"/> : <Usb size={16} className="text-slate-400"/>}
                      <span className="font-mono text-xs">{printer.connectionType === 'Network' ? printer.ipAddress : 'USB Bağlantı'}</span>
                    </div>
                </div>
              </div>

              {/* ACTION FOOTER */}
              <div className="grid grid-cols-2 border-t border-slate-200 dark:border-slate-700 divide-x divide-slate-200 dark:divide-slate-700">
                <button 
                    onClick={(e) => handleEditClick(e, printer)}
                    className="py-4 flex items-center justify-center gap-2 text-blue-600 dark:text-blue-400 font-semibold hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors active:bg-blue-100"
                >
                    <Edit2 size={18} /> Düzenle
                </button>
                <button 
                    onClick={(e) => confirmDelete(e, printer.id)}
                    className="py-4 flex items-center justify-center gap-2 text-red-600 dark:text-red-400 font-semibold hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors active:bg-red-100"
                >
                    <Trash2 size={18} /> Sil
                </button>
              </div>
            </div>
          );
        })}

        {printers.length === 0 && (
           <div className="col-span-full flex flex-col items-center justify-center py-20 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-700">
              <PrinterIcon size={48} className="text-slate-300 mb-4" />
              <p className="text-slate-500 font-medium">Kayıtlı yazıcı bulunamadı</p>
              <p className="text-slate-400 text-sm">Yeni eklemek için butonu kullanın</p>
           </div>
        )}
      </div>

      {/* --- QR CODE MODAL --- */}
      {qrPrinter && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[70] flex items-center justify-center p-4 animate-in fade-in duration-200" onClick={() => setQrPrinter(null)}>
            <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl max-w-sm w-full text-center relative" onClick={e => e.stopPropagation()}>
                <button onClick={() => setQrPrinter(null)} className="absolute top-4 right-4 p-2 bg-slate-100 dark:bg-slate-700 rounded-full text-slate-500"><X size={20}/></button>

                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-1">{qrPrinter.brand} {qrPrinter.model}</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{qrPrinter.location}</p>

                <div className="bg-white p-4 rounded-xl border-2 border-slate-100 inline-block mb-4">
                    <img 
                        src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(window.location.origin + window.location.pathname + '?pid=' + qrPrinter.id)}`} 
                        alt="QR Code" 
                        className="w-48 h-48"
                    />
                </div>

                <p className="text-xs text-slate-400 max-w-[250px] mx-auto">
                    Bu kodu yazıcının üzerine yapıştırın. Telefondan okutulduğunda direkt bu sayfa açılacaktır.
                </p>
            </div>
        </div>
      )}

      {/* --- DELETE MODAL --- */}
      {deleteId && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
           <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-sm w-full p-6 text-center scale-100 animate-in zoom-in-95 duration-200">
              <div className="w-16 h-16 bg-red-100 dark:bg-red-900/30 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Trash2 size={32} />
              </div>
              <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-2">Yazıcı Siliniyor</h3>
              <p className="text-slate-500 dark:text-slate-400 text-sm mb-6">
                 Bu cihazı ve geçmiş tüm kayıtlarını kalıcı olarak silmek istediğinize emin misiniz? Bu işlem geri alınamaz.
              </p>
              <div className="grid grid-cols-2 gap-3">
                 <button 
                    onClick={() => setDeleteId(null)}
                    className="py-3 px-4 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl font-semibold hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors"
                 >
                    Vazgeç
                 </button>
                 <button 
                    onClick={performDelete}
                    className="py-3 px-4 bg-red-600 text-white rounded-xl font-semibold hover:bg-red-700 shadow-lg shadow-red-200 dark:shadow-none transition-colors"
                 >
                    Evet, Sil
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* Add/Edit Modal */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-y-auto max-h-[90vh] animate-in slide-in-from-bottom-4 duration-300">
            <div className="bg-white dark:bg-slate-800 px-6 py-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center sticky top-0 z-10">
              <h3 className="font-bold text-lg text-slate-800 dark:text-white">
                {editingPrinter ? 'Cihazı Düzenle' : 'Yeni Cihaz Ekle'}
              </h3>
              <button type="button" onClick={closeFormModal} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full hover:bg-slate-200 transition-colors"><X size={20} className="text-slate-500 dark:text-slate-300" /></button>
            </div>

            <form onSubmit={handleSave} className="p-6 space-y-5">

              {/* STATUS SELECTION (NEW) */}
              <div className="bg-slate-50 dark:bg-slate-700/50 p-4 rounded-xl border border-slate-100 dark:border-slate-700">
                 <label className="block text-sm font-semibold text-slate-700 dark:text-slate-200 mb-3">Cihaz Durumu</label>
                 <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                    {[
                      { val: 'ACTIVE', label: 'Aktif', color: 'bg-emerald-100 text-emerald-700 border-emerald-300' },
                      { val: 'MAINTENANCE', label: 'Serviste', color: 'bg-orange-100 text-orange-700 border-orange-300' },
                      { val: 'BROKEN', label: 'Arızalı', color: 'bg-red-100 text-red-700 border-red-300' },
                      { val: 'SCRAPPED', label: 'Hurda', color: 'bg-slate-200 text-slate-700 border-slate-300' }
                    ].map(opt => (
                       <label key={opt.val} className={`cursor-pointer border-2 rounded-lg p-2 text-center text-xs font-bold transition-all ${
                          formData.status === opt.val ? opt.color : 'border-slate-200 text-slate-500 bg-white dark:bg-slate-800 dark:border-slate-600'
                       }`}>
                          <input type="radio" className="hidden" name="status" checked={formData.status === opt.val} onChange={() => setFormData({...formData, status: opt.val as PrinterStatus})} />
                          {opt.label}
                       </label>
                    ))}
                 </div>
              </div>

              {/* Brand & Model Select */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Marka</label>
                  <div className="relative">
                     <select 
                        required 
                        className="w-full appearance-none p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white transition-all"
                        value={formData.brand} 
                        onChange={e => setFormData({...formData, brand: e.target.value})}
                     >
                        <option value="">Seçiniz</option>
                        {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                     </select>
                     <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Model</label>
                  <div className="relative">
                     <select 
                        required 
                        className="w-full appearance-none p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white transition-all"
                        value={formData.model} 
                        onChange={e => setFormData({...formData, model: e.target.value})}
                     >
                        <option value="">Seçiniz</option>
                        {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                     </select>
                     <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
                  </div>
                </div>
              </div>

              {/* Supplier Selection */}
              <div>
                 <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Tedarikçi / Servis</label>
                 <div className="relative">
                     <select 
                        className="w-full appearance-none p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white transition-all"
                        value={formData.supplier} 
                        onChange={e => setFormData({...formData, supplier: e.target.value})}
                     >
                        <option value="">Seçiniz</option>
                        {config.suppliers.map(s => <option key={s} value={s}>{s}</option>)}
                     </select>
                     <Truck size={18} className="absolute right-10 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                     <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
                  </div>
              </div>

              {/* Connection Type */}
              <div className="bg-slate-50 dark:bg-slate-700/50 p-4 rounded-xl border border-slate-100 dark:border-slate-700">
                <label className="block text-sm font-semibold text-slate-700 dark:text-slate-200 mb-3">Bağlantı Türü</label>
                <div className="flex gap-4 mb-4">
                  <label className={`flex-1 flex items-center justify-center gap-2 cursor-pointer p-3 rounded-lg border transition-all ${formData.connectionType === 'USB' ? 'bg-white dark:bg-slate-600 border-primary-500 shadow-sm text-primary-700 dark:text-primary-300' : 'border-transparent hover:bg-slate-200 dark:hover:bg-slate-600 text-slate-500'}`}>
                    <input 
                      type="radio" 
                      name="connType" 
                      className="hidden"
                      checked={formData.connectionType === 'USB'} 
                      onChange={() => setFormData({...formData, connectionType: 'USB', ipAddress: ''})} 
                    />
                    <Usb size={18}/> USB
                  </label>
                  <label className={`flex-1 flex items-center justify-center gap-2 cursor-pointer p-3 rounded-lg border transition-all ${formData.connectionType === 'Network' ? 'bg-white dark:bg-slate-600 border-primary-500 shadow-sm text-primary-700 dark:text-primary-300' : 'border-transparent hover:bg-slate-200 dark:hover:bg-slate-600 text-slate-500'}`}>
                    <input 
                      type="radio" 
                      name="connType" 
                      className="hidden"
                      checked={formData.connectionType === 'Network'} 
                      onChange={() => setFormData({...formData, connectionType: 'Network'})} 
                    />
                    <Wifi size={18}/> Network
                  </label>
                </div>

                {formData.connectionType === 'Network' && (
                  <div>
                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1 uppercase tracking-wider">IP Adresi</label>
                    <div className="relative">
                      <Globe size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                      <input 
                        type="text" 
                        required 
                        className="w-full pl-10 p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-600 text-slate-900 dark:text-white font-mono"
                        value={formData.ipAddress} 
                        onChange={e => setFormData({...formData, ipAddress: e.target.value})} 
                        placeholder="192.168.1.xxx" 
                      />
                    </div>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Seri No</label>
                  <input required className="w-full p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} placeholder="CNC..." />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Kat</label>
                  <input required className="w-full p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} placeholder="4. Kat" />
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Konum / Birim</label>
                <div className="relative">
                   <MapPin size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                   <input required className="w-full pl-10 p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                     value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} placeholder="Örn: Muhasebe Ofisi" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Son Sayaç</label>
                  <input type="number" required className="w-full p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.lastCounter} onChange={e => setFormData({...formData, lastCounter: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Uyumlu Toner</label>
                  <input 
                    list="toner-models-list" 
                    className="w-full p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.compatibleToner} 
                    onChange={e => setFormData({...formData, compatibleToner: e.target.value})} 
                    placeholder="Örn: 85A" 
                  />
                  <datalist id="toner-models-list">
                    {config.tonerModels?.map(tm => <option key={tm} value={tm} />)}
                  </datalist>
                </div>
              </div>

              <div className="pt-4 flex gap-3">
                <button type="button" onClick={closeFormModal} className="flex-1 py-4 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors font-semibold">İptal</button>
                <button type="submit" className="flex-1 py-4 bg-primary-600 text-white rounded-xl hover:bg-primary-700 transition-colors font-bold shadow-lg shadow-primary-200 dark:shadow-none">
                  {editingPrinter ? 'Değişiklikleri Kaydet' : 'Cihazı Kaydet'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* History Modal */}
      {isHistoryModalOpen && selectedPrinterHistory && (
         <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-y-auto max-h-[90vh] animate-in slide-in-from-bottom-4 duration-300">
            <div className="bg-white dark:bg-slate-800 px-6 py-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center sticky top-0 z-10">
               <div>
                  <h3 className="font-bold text-xl text-slate-800 dark:text-white">
                    {selectedPrinterHistory.printer.brand} {selectedPrinterHistory.printer.model}
                  </h3>
                  <div className="flex gap-2 items-center mt-1">
                     <span className="bg-primary-50 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 text-xs px-2 py-0.5 rounded font-medium">
                        {selectedPrinterHistory.printer.location}
                     </span>
                     <span className="text-slate-400 text-xs">•</span>
                     <span className="text-slate-500 dark:text-slate-400 text-xs">{selectedPrinterHistory.printer.serialNumber}</span>
                  </div>
               </div>
              <button type="button" onClick={() => setIsHistoryModalOpen(false)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full hover:bg-slate-200 transition-colors"><X size={20} className="text-slate-500 dark:text-slate-300" /></button>
            </div>

            <div className="p-6">
              <h4 className="font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
                 <div className="p-2 bg-blue-100 dark:bg-blue-900/30 text-blue-600 rounded-lg"><History size={18}/></div>
                 Toner Değişim Geçmişi
              </h4>
              <div className="space-y-4 mb-8">
                {selectedPrinterHistory.tonerLogs.length === 0 && (
                   <div className="text-center py-6 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-dashed border-slate-200 dark:border-slate-700">
                      <p className="text-slate-400">Henüz kayıt yok.</p>
                   </div>
                )}
                {selectedPrinterHistory.tonerLogs.map((log) => (
                    <div key={log.id} className="relative pl-6 border-l-2 border-slate-200 dark:border-slate-700 pb-4 last:pb-0">
                       <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-white dark:bg-slate-800 border-2 border-blue-500"></div>
                       <div className="bg-slate-50 dark:bg-slate-700/50 p-4 rounded-xl border border-slate-100 dark:border-slate-700 hover:shadow-sm transition-shadow">
                          <div className="flex justify-between items-start mb-1">
                             <span className="font-bold text-slate-700 dark:text-slate-200">{log.tonerModel}</span>
                             <span className="text-xs text-slate-400 bg-white dark:bg-slate-800 px-2 py-1 rounded border dark:border-slate-600 shadow-sm">{new Date(log.date).toLocaleDateString('tr-TR')}</span>
                          </div>

                          {/* YIELD DATA - NEW DISPLAY */}
                          {log.pageYield !== undefined && log.pageYield > 0 && (
                             <div className="my-2 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 text-xs px-2 py-1 rounded w-fit font-medium flex items-center gap-1">
                                <History size={10} />
                                Önceki toner verimi: {log.pageYield.toLocaleString()} sayfa
                             </div>
                          )}

                          <p className="text-sm text-slate-500 dark:text-slate-400 mb-2">
                             İşlemi Yapan: <span className="font-medium text-slate-700 dark:text-slate-300">{log.user}</span>
                          </p>
                          {log.description && <p className="text-xs text-slate-400 italic bg-white dark:bg-slate-800 p-2 rounded">{log.description}</p>}
                       </div>
                    </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ArrowDown, ArrowUp, CheckCircle, AlertTriangle, Search, Banknote, Calendar, Settings as SettingsIcon, MessageCircle, Printer as PrinterIcon } from 'lucide-react';
import { TonerStock, Printer, StockLog, SystemConfig } from '../types';
import { StorageService } from '../services/storage';

interface StockManagementProps {
  user: { name: string };
}

export const StockManagement: React.FC<StockManagementProps> = ({ user }) => {
  const [stocks, setStocks] = useState<TonerStock[]>([]);
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [logs, setLogs] = useState<StockLog[]>([]); // New State for History
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [] });
  const [activeTab, setActiveTab] = useState<'LIST' | 'IN' | 'OUT'>('LIST');

  // Transaction States
  const [selectedPrinterId, setSelectedPrinterId] = useState('');
  const [selectedTonerModel, setSelectedTonerModel] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [cost, setCost] = useState(0); 
  const [newStockModel, setNewStockModel] = useState(''); 
  const [description, setDescription] = useState('');

  // Page Yield Logic
  const [currentCounter, setCurrentCounter] = useState<number>(0);
  const [lastPrinterCounter, setLastPrinterCounter] = useState<number>(0);

  // Notification
  const [message, setMessage] = useState<{type: 'success' | 'error', text: string} | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setStocks(StorageService.getStocks());
    setPrinters(StorageService.getPrinters());
    setLogs(StorageService.getLogs()); // Fetch Logs
    setConfig(StorageService.getConfig());
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 3000);
  };

  const checkLowStockAndNotify = (model: string, newQty: number) => {
    if (newQty <= 1) {
       const config = StorageService.getConfig();
       if (config.whatsappNumber) {
         setTimeout(() => {
            alert(`⚠️ SİSTEM UYARISI: ${model} toneri kritik seviyeye (${newQty}) düştü! WhatsApp bildirimi ${config.whatsappNumber} numarasına gönderildi.`);
         }, 500);
       }
    }
  };

  const handleStockIn = (e: React.FormEvent) => {
    e.preventDefault();
    const model = newStockModel.trim(); // No uppercase forcing, keeping original format
    if (!model) {
      showMessage('error', 'Lütfen bir model seçiniz.');
      return;
    }

    const updatedStocks = [...stocks];
    const existingIndex = updatedStocks.findIndex(s => s.modelName === model);

    if (existingIndex >= 0) {
      updatedStocks[existingIndex].quantity += quantity;
    } else {
      updatedStocks.push({ modelName: model, quantity: quantity });
    }

    StorageService.saveStocks(updatedStocks);

    // Log
    const log: StockLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      type: 'IN',
      tonerModel: model,
      quantity: quantity,
      description: 'Stok Girişi (Manuel)',
      user: user.name,
      cost: cost 
    };
    StorageService.addLog(log);

    refreshData();
    showMessage('success', `${quantity} adet ${model} stoğa eklendi.`);
    setNewStockModel('');
    setQuantity(1);
    setCost(0);
    setActiveTab('LIST');
  };

  const handleStockOut = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTonerModel) {
      showMessage('error', 'Lütfen toner seçiniz.');
      return;
    }

    // Check stock
    const updatedStocks = [...stocks];
    const stockIndex = updatedStocks.findIndex(s => s.modelName === selectedTonerModel);

    if (stockIndex === -1 || updatedStocks[stockIndex].quantity < 1) {
      showMessage('error', 'Yetersiz stok!');
      return;
    }

    // Decrement Stock
    updatedStocks[stockIndex].quantity -= 1; 
    const newQuantity = updatedStocks[stockIndex].quantity;
    StorageService.saveStocks(updatedStocks);

    // Check Notification
    checkLowStockAndNotify(selectedTonerModel, newQuantity);

    // Update Printer & Calculate Yield
    let printerDesc = "";
    let calculatedYield = 0;

    if (selectedPrinterId && selectedPrinterId !== 'MANUAL') {
      const updatedPrinters = printers.map(p => {
        if (p.id === selectedPrinterId) {
          printerDesc = `${p.location} (${p.floor})`;

          // Yield Calculation
          if (currentCounter > p.lastCounter) {
             calculatedYield = currentCounter - p.lastCounter;
          }

          return {
            ...p,
            lastTonerDate: new Date().toISOString(),
            lastCounter: currentCounter || p.lastCounter // Update to new counter
          };
        }
        return p;
      });
      StorageService.savePrinters(updatedPrinters);
    }

    // Log
    const log: StockLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      type: 'OUT',
      tonerModel: selectedTonerModel,
      quantity: 1,
      printerId: selectedPrinterId === 'MANUAL' ? undefined : selectedPrinterId,
      description: (selectedPrinterId && selectedPrinterId !== 'MANUAL') ? `Yazıcıya Takıldı: ${printerDesc}` : `Stok Çıkışı: ${description}`,
      user: user.name,
      pageYield: calculatedYield > 0 ? calculatedYield : undefined
    };
    StorageService.addLog(log);

    refreshData();
    showMessage('success', `${selectedTonerModel} stoktan düşüldü. ${calculatedYield > 0 ? `(Önceki toner: ${calculatedYield} sayfa)` : ''}`);
    setSelectedPrinterId('');
    setSelectedTonerModel('');
    setCurrentCounter(0);
    setActiveTab('LIST');
  };

  // Helper to auto-select toner when printer is selected
  const onPrinterSelect = (printerId: string) => {
    setSelectedPrinterId(printerId);
    const printer = printers.find(p => p.id === printerId);
    if (printer) {
      if (printer.compatibleToner) setSelectedTonerModel(printer.compatibleToner);
      setLastPrinterCounter(printer.lastCounter);
      setCurrentCounter(printer.lastCounter); // Set default to current to avoid confusion
    } else {
       setLastPrinterCounter(0);
       setCurrentCounter(0);
    }
  };

  // WhatsApp Order Generator
  const sendWhatsappOrder = (model: string) => {
     const supplier = config.suppliers[0] || '';
     const text = `Merhaba, ${model} model toner stoğumuz kritik seviyenin altına düştü. Sipariş vermek istiyoruz.`;
     const url = `https://wa.me/${config.whatsappNumber}?text=${encodeURIComponent(text)}`;
     window.open(url, '_blank');
  };

  // Filter only OUT logs for the table
  const outputLogs = logs.filter(l => l.type === 'OUT');

  return (
    <div className="space-y-6">
      {message && (
        <div className={`fixed top-4 right-4 p-4 rounded-lg shadow-xl text-white z-50 animate-bounce ${message.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
          {message.text}
        </div>
      )}

      <div className="flex space-x-2 bg-white dark:bg-slate-800 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 w-fit">
        <button 
          onClick={() => setActiveTab('LIST')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'LIST' ? 'bg-primary-900 text-white' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
        >
          Stok Listesi
        </button>
        <button 
          onClick={() => setActiveTab('IN')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'IN' ? 'bg-green-600 text-white' : 'text-green-700 dark:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20'}`}
        >
          <ArrowDown size={16} /> Stok Giriş
        </button>
        <button 
          onClick={() => setActiveTab('OUT')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'OUT' ? 'bg-orange-600 text-white' : 'text-orange-700 dark:text-orange-400 hover:bg-orange-50 dark:hover:bg-orange-900/20'}`}
        >
          <ArrowUp size={16} /> Toner Çıkış
        </button>
      </div>

      {activeTab === 'LIST' && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {stocks.map(stock => (
            <div key={stock.modelName} className="bg-white dark:bg-slate-800 p-6 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col items-center justify-center text-center relative group hover:border-primary-300 transition-colors">
              <h3 className="text-3xl font-bold text-slate-800 dark:text-white mb-1">{stock.quantity}</h3>
              <p className="text-slate-500 dark:text-slate-400 font-medium">Model: {stock.modelName}</p>

              {stock.quantity < 3 && (
                 <div className="mt-2 flex flex-col gap-2 w-full">
                    <span className="text-xs bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 px-2 py-1 rounded-full flex items-center justify-center gap-1 mx-auto">
                      <AlertTriangle size={12} /> Kritik
                    </span>
                    {config.whatsappNumber && (
                        <button 
                          onClick={() => sendWhatsappOrder(stock.modelName)}
                          className="text-xs bg-green-500 text-white px-2 py-1.5 rounded-lg flex items-center justify-center gap-1 hover:bg-green-600"
                        >
                            <MessageCircle size={12} /> Sipariş Ver
                        </button>
                    )}
                 </div>
              )}
            </div>
          ))}
          {stocks.length === 0 && (
            <div className="col-span-full p-8 text-center text-slate-400">Henüz stok kaydı yok.</div>
          )}
        </div>
      )}

      {activeTab === 'IN' && (
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 max-w-lg">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
            <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg text-green-700 dark:text-green-400"><ArrowDown size={20}/></div>
            Stok Girişi Yap
          </h3>
          <form onSubmit={handleStockIn} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Toner/Mürekkep Modeli</label>
              <div className="relative">
                 <select 
                    required
                    className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white appearance-none"
                    value={newStockModel}
                    onChange={e => setNewStockModel(e.target.value)}
                 >
                    <option value="">Listeden Seçiniz</option>
                    {config.tonerModels?.map(s => <option key={s} value={s}>{s}</option>)}
                 </select>
                 <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
              </div>
              <p className="text-xs text-slate-400 mt-2 flex items-center gap-1">
                <SettingsIcon size={12} /> Listede olmayan modelleri "Ayarlar" sayfasından ekleyebilirsiniz.
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Adet</label>
              <div className="flex items-center gap-4">
                <button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">-</button>
                <input 
                  type="number" 
                  min="1"
                  required
                  className="w-full text-center p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none font-bold text-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={quantity}
                  onChange={e => setQuantity(parseInt(e.target.value) || 1)}
                />
                <button type="button" onClick={() => setQuantity(quantity + 1)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">+</button>
              </div>
            </div>

             <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                 Toplam Maliyet (TL) 
                 <span className="text-xs font-normal text-slate-400 ml-1">(Ücretsizse 0 giriniz)</span>
              </label>
              <div className="relative">
                 <Banknote className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input 
                   type="number" 
                   min="0"
                   className="w-full pl-10 p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   value={cost}
                   onChange={e => setCost(parseFloat(e.target.value) || 0)}
                 />
              </div>
            </div>

            <button type="submit" className="w-full py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200 dark:shadow-none">
              Stok Ekle
            </button>
          </form>
        </div>
      )}

      {activeTab === 'OUT' && (
        <div className="flex flex-col lg:flex-row gap-6">
          <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 w-full lg:w-1/2">
             <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
              <div className="p-2 bg-orange-100 dark:bg-orange-900/30 rounded-lg text-orange-700 dark:text-orange-400"><ArrowUp size={20}/></div>
              Toner Çıkışı (Değişim)
            </h3>
            <form onSubmit={handleStockOut} className="space-y-5">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Hangi Yazıcıya?</label>
                <select 
                  className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={selectedPrinterId}
                  onChange={(e) => onPrinterSelect(e.target.value)}
                >
                  <option value="">-- Yazıcı Seçiniz --</option>
                  {printers.map(p => (
                    <option key={p.id} value={p.id}>
                      {p.location} ({p.model}) - {p.status === 'ACTIVE' ? 'Aktif' : 'Serviste/Arızalı'}
                    </option>
                  ))}
                  <option value="MANUAL">Listede Yok / Manuel Çıkış</option>
                </select>
              </div>

              {selectedPrinterId && selectedPrinterId !== 'MANUAL' && (
                 <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-100 dark:border-blue-800/50">
                     <label className="block text-sm font-bold text-blue-800 dark:text-blue-300 mb-2 flex items-center gap-2">
                        <PrinterIcon size={16} /> GÜNCEL SAYAÇ (ZORUNLU)
                     </label>
                     <p className="text-xs text-blue-600 dark:text-blue-400 mb-2">Eski sayaç: {lastPrinterCounter}</p>
                     <input 
                        type="number" 
                        required
                        min={lastPrinterCounter}
                        className="w-full p-3 border border-blue-300 dark:border-blue-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none font-mono text-lg"
                        placeholder="Örn: 10500"
                        value={currentCounter}
                        onChange={e => setCurrentCounter(parseInt(e.target.value))}
                     />
                     {currentCounter > lastPrinterCounter && (
                         <p className="text-xs text-green-600 dark:text-green-400 mt-2 font-bold">
                            Bu toner ile basılan sayfa: {currentCounter - lastPrinterCounter}
                         </p>
                     )}
                 </div>
              )}

              {selectedPrinterId === 'MANUAL' && (
                 <div>
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Açıklama / Yer</label>
                 <input 
                   className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   placeholder="Örn: 3. Kat Depo"
                   value={description}
                   onChange={e => setDescription(e.target.value)}
                   required
                 />
               </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Verilen Toner Modeli</label>
                <select 
                  required
                  className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={selectedTonerModel}
                  onChange={e => setSelectedTonerModel(e.target.value)}
                >
                  <option value="">-- Model Seçiniz --</option>
                  {stocks.map(s => (
                    <option key={s.modelName} value={s.modelName} disabled={s.quantity <= 0}>
                      {s.modelName} (Stok: {s.quantity})
                    </option>
                  ))}
                </select>
              </div>

              <div className="p-4 bg-orange-50 dark:bg-orange-900/20 rounded-xl text-sm text-orange-800 dark:text-orange-200 border border-orange-100 dark:border-orange-800/30">
                <p>Onayladığınızda stoktan <strong>1 adet</strong> düşülecektir.</p>
                {selectedPrinterId && selectedPrinterId !== 'MANUAL' && (
                  <p className="mt-1">Sayaç güncellenecek ve <strong>verimlilik analizi</strong> kaydedilecektir.</p>
                )}
              </div>

              <button type="submit" className="w-full py-4 bg-orange-600 text-white rounded-xl font-bold hover:bg-orange-700 transition-colors shadow-lg shadow-orange-200 dark:shadow-none">
                Çıkış Yap & Onayla
              </button>
            </form>
          </div>

          {/* Recent Outputs Table - NEW FEATURE */}
          <div className="w-full lg:w-1/2">
             <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 h-full max-h-[600px] overflow-hidden flex flex-col">
                <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
                   <Calendar size={20} className="text-slate-500"/> Son Toner Çıkış Hareketleri
                </h3>
                <div className="overflow-y-auto flex-1">
                   <table className="w-full text-left text-sm">
                      <thead className="bg-slate-50 dark:bg-slate-700 sticky top-0">
                         <tr>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium">Toner</th>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium">Açıklama</th>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium text-right">Verim</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                         {outputLogs.slice(0, 15).map(log => (
                            <tr key={log.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50">
                               <td className="p-3 font-medium text-slate-800 dark:text-white">{log.tonerModel}</td>
                               <td className="p-3 text-slate-600 dark:text-slate-300 max-w-[150px] truncate" title={log.description}>{log.description}</td>
                               <td className="p-3 text-right text-xs">
                                  {log.pageYield ? <span className="text-green-600 font-bold">{log.pageYield} sf</span> : <span className="text-slate-400">-</span>}
                               </td>
                            </tr>
                         ))}
                         {outputLogs.length === 0 && (
                            <tr><td colSpan={3} className="p-4 text-center text-slate-400">Henüz çıkış kaydı yok.</td></tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export interface User {
  username: string;
  name: string;
  role: 'admin' | 'user';
  password?: string; // Added for internal DB storage
}

export type ConnectionType = 'USB' | 'Network';

export type PrinterStatus = 'ACTIVE' | 'MAINTENANCE' | 'BROKEN' | 'SCRAPPED' | 'SPARE';

export interface Printer {
  id: string;
  serialNumber: string;
  brand: string;   // e.g. "Canon", "HP"
  model: string;   // e.g. "3325i"
  location: string;
  floor: string;
  lastCounter: number;
  lastTonerDate: string;
  compatibleToner: string;
  connectionType: ConnectionType;
  ipAddress?: string; // Only if Network
  supplier: string; // e.g. "Anahtar Bilgisayar", "Enes Bilişim"
  status: PrinterStatus; // New Visual Status
}

export interface TonerStock {
  modelName: string;
  quantity: number;
}

export interface StockLog {
  id: string;
  date: string;
  type: 'IN' | 'OUT';
  tonerModel: string;
  quantity: number;
  description: string;
  printerId?: string;
  user: string;
  cost?: number; // Added for tracking Ink/Toner costs
  pageYield?: number; // New: How many pages printed with the previous toner?
}

export interface ServiceRecord {
  id: string;
  printerId: string;
  printerName: string; // Cache name for easier display
  date: string;
  issue: string; // Arıza tanımı
  actionTaken: string; // Yapılan işlem
  cost: number;
  provider: string; // Servis firması
  status: 'PENDING' | 'COMPLETED' | 'SCRAPPED'; // Bekliyor, Tamamlandı, Hurda
}

export interface SystemConfig {
  brands: string[];
  models: string[];
  suppliers: string[]; // List of vendors
  tonerModels: string[]; // New: List of toner types
  whatsappNumber?: string; // For notifications
}

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Globe, Trash2, History, Truck, AlertTriangle, QrCode, FileSpreadsheet, Download, CheckCircle2, XCircle, AlertCircle, Archive } from 'lucide-react';
import { Printer, SystemConfig, StockLog, ServiceRecord, PrinterStatus } from '../types';
import { StorageService } from '../services/storage';

interface PrinterListProps {
  onSelectPrinter?: (printer: Printer) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ onSelectPrinter, targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [] });
  const [searchTerm, setSearchTerm] = useState('');

  // Modals State
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  // QR Code Modal
  const [qrPrinter, setQrPrinter] = useState<Printer | null>(null);

  const [editingPrinter, setEditingPrinter] = useState<Printer | null>(null);
  const [selectedPrinterHistory, setSelectedPrinterHistory] = useState<{printer: Printer, tonerLogs: StockLog[], serviceLogs: ServiceRecord[]} | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Printer>>({
    brand: '',
    model: '',
    serialNumber: '',
    location: '',
    floor: '',
    lastCounter: 0,
    compatibleToner: '',
    connectionType: 'USB',
    ipAddress: '',
    supplier: '',
    status: 'ACTIVE'
  });

  useEffect(() => {
    StorageService.runMaintenance();
    loadData();
  }, []);

  // Deep Linking Logic
  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const target = printers.find(p => p.id === targetPrinterId);
      if (target) {
        openHistoryModal(target);
      }
      // Clear the target so it doesn't reopen if closed
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  const loadData = () => {
    setPrinters(StorageService.getPrinters());
    setConfig(StorageService.getConfig());
  };

  // --- ACTIONS ---

  const confirmDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    setDeleteId(id);
  };

  const performDelete = () => {
    if (deleteId) {
      const updatedList = StorageService.deletePrinter(deleteId);
      setPrinters([...updatedList]);
      setDeleteId(null);
    }
  };

  const handleEditClick = (e: React.MouseEvent, printer: Printer) => {
    e.preventDefault();
    e.stopPropagation();
    openFormModal(printer);
  };

  // QR Button Click
  const handleQrClick = (e: React.MouseEvent, printer: Printer) => {
    e.preventDefault();
    e.stopPropagation();
    setQrPrinter(printer);
  };

  const handleHistoryClick = (printer: Printer) => {
    openHistoryModal(printer);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    let updatedList = [...printers];

    if (editingPrinter) {
      updatedList = updatedList.map(p => 
        p.id === editingPrinter.id ? { ...p, ...formData } as Printer : p
      );
    } else {
      const newPrinter: Printer = {
        id: Date.now().toString(),
        lastTonerDate: new Date().toISOString(),
        ...formData as Printer,
        status: formData.status || 'ACTIVE'
      };
      updatedList.push(newPrinter);
    }

    StorageService.savePrinters(updatedList);
    setPrinters(updatedList);
    closeFormModal();
  };

  // --- EXPORT TO EXCEL ---
  const downloadInventoryCSV = () => {
    if (printers.length === 0) {
      alert('Listelenecek cihaz yok.');
      return;
    }
    const headers = ["Durum", "Marka", "Model", "Seri No", "Konum", "Kat", "Baglanti", "IP", "Son Sayac", "Toner Modeli", "Tedarikci"];
    const rows = printers.map(p => [
      p.status,
      p.brand,
      p.model,
      p.serialNumber,
      `"${p.location}"`,
      p.floor,
      p.connectionType,
      p.ipAddress || '-',
      p.lastCounter,
      p.compatibleToner,
      `"${p.supplier}"`
    ].join(","));

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers.join(",") + "\n" + rows.join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Envanter_Listesi_${new Date().toLocaleDateString()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // --- MODAL HELPERS ---

  const openFormModal = (printer?: Printer) => {
    if (printer) {
      setEditingPrinter(printer);
      setFormData(printer);
    } else {
      setEditingPrinter(null);
      setFormData({
        brand: config.brands[0] || '',
        model: config.models[0] || '',
        serialNumber: '',
        location: '',
        floor: '',
        lastCounter: 0,
        compatibleToner: '',
        connectionType: 'USB',
        ipAddress: '',
        supplier: config.suppliers[0] || '',
        status: 'ACTIVE'
      });
    }
    setIsFormModalOpen(true);
  };

  const closeFormModal = () => {
    setIsFormModalOpen(false);
    setEditingPrinter(null);
  };

  const openHistoryModal = (printer: Printer) => {
    const allLogs = StorageService.getLogs();
    const allServices = StorageService.getServiceRecords();

    const printerLogs = allLogs.filter(log => String(log.printerId) === String(printer.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const printerServices = allServices.filter(srv => String(srv.printerId) === String(printer.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    setSelectedPrinterHistory({
      printer,
      tonerLogs: printerLogs,
      serviceLogs: printerServices
    });
    setIsHistoryModalOpen(true);
  };

  const filteredPrinters = printers.filter(p => 
    p.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.serialNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Helper for Status UI
  const getStatusColor = (status: PrinterStatus) => {
    switch (status) {
      case 'ACTIVE': return 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/10 dark:border-emerald-500/50';
      case 'SPARE': return 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/10 dark:border-indigo-500/50';
      case 'MAINTENANCE': return 'border-orange-500 bg-orange-50 dark:bg-orange-900/10 dark:border-orange-500/50';
      case 'BROKEN': return 'border-red-500 bg-red-50 dark:bg-red-900/10 dark:border-red-500/50';
      case 'SCRAPPED': return 'border-slate-500 bg-slate-100 dark:bg-slate-800 dark:border-slate-500 opacity-75';
      default: return 'border-slate-200';
    }
  };

  const getStatusLabel = (status: PrinterStatus) => {
    switch (status) {
      case 'ACTIVE': return { text: 'AKTİF', icon: <CheckCircle2 size={12} /> };
      case 'SPARE': return { text: 'YEDEKTE', icon: <Archive size={12} /> };
      case 'MAINTENANCE': return { text: 'SERVİSTE', icon: <Truck size={12} /> };
      case 'BROKEN': return { text: 'ARIZALI', icon: <AlertTriangle size={12} /> };
      case 'SCRAPPED': return { text: 'HURDA', icon: <XCircle size={12} /> };
      default: return { text: 'BİLİNMİYOR', icon: null };
    }
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Header Section */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Cihaz Yönetimi</h2>
          <p className="text-sm text-slate-500 dark:text-slate-400">Toplam {printers.length} yazıcı listeleniyor</p>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
            <button 
            onClick={downloadInventoryCSV}
            className="flex-1 sm:flex-none bg-green-600 hover:bg-green-700 text-white px-4 py-3 rounded-xl flex items-center justify-center gap-2 font-semibold shadow-sm transition-all"
            >
            <FileSpreadsheet size={20} /> Excel
            </button>
            <button 
            onClick={() => openFormModal()}
            className="flex-[2] sm:flex-none bg-primary-600 hover:bg-primary-700 text-white px-5 py-3 rounded-xl flex items-center justify-center gap-2 font-semibold shadow-lg shadow-primary-200 dark:shadow-none transition-all active:scale-95"
            >
            <Plus size={20} />
            Yeni Cihaz
            </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative group">
        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
          <Search className="text-slate-400 group-focus-within:text-primary-500 transition-colors" size={20} />
        </div>
        <input
          type="text"
          placeholder="Marka, Model, Seri No veya Konum ara..."
          className="w-full pl-11 pr-4 py-4 rounded-2xl border-2 border-transparent bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm focus:border-primary-500 focus:ring-0 outline-none transition-all placeholder:text-slate-400"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* CARD GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {filteredPrinters.map(printer => {
          const statusInfo = getStatusLabel(printer.status || 'ACTIVE');
          const cardStyle = getStatusColor(printer.status || 'ACTIVE');

          return (
            <div 
              key={printer.id} 
              className={`group bg-white dark:bg-slate-800 rounded-2xl shadow-sm hover:shadow-xl border-2 overflow-hidden transition-all duration-300 flex flex-col relative ${cardStyle}`}
            >
              {/* QR CODE BUTTON - ABSOLUTE TOP RIGHT */}
              <button 
                  onClick={(e) => handleQrClick(e, printer)}
                  className="absolute top-4 right-4 p-2 bg-white/80 dark:bg-slate-700/80 backdrop-blur-sm text-slate-600 dark:text-slate-300 rounded-lg shadow-sm hover:text-primary-600 dark:hover:text-primary-400 z-10"
                  title="QR Kod Göster"
              >
                  <QrCode size={20} />
              </button>

              {/* CARD BODY */}
              <div 
                className="p-5 flex-1 cursor-pointer relative"
                onClick={() => handleHistoryClick(printer)}
              >
                {/* Brand & Status Badge */}
                <div className="flex justify-between items-start mb-4 pr-10">
                    <div className="flex flex-col gap-2">
                        <span className="bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider w-fit">
                          {printer.brand}
                        </span>
                        <span className={`flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase w-fit tracking-wide
                          ${printer.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-300' : ''}
                          ${printer.status === 'SPARE' ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900 dark:text-indigo-300' : ''}
                          ${printer.status === 'MAINTENANCE' ? 'bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-300' : ''}
                          ${printer.status === 'BROKEN' ? 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300' : ''}
                          ${printer.status === 'SCRAPPED' ? 'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-400' : ''}
                        `}>
                           {statusInfo.icon} {statusInfo.text}
                        </span>
                    </div>
                </div>

                {/* Model Name */}
                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-1 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">
                  {printer.model}
                </h3>

                {/* Location & Serial */}
                <div className="space-y-2 mt-4">
                    <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400 text-sm">
                      <MapPin size={16} className="text-slate-400" />
                      <span className="line-clamp-1">{printer.location} <span className="text-slate-400">({printer.floor})</span></span>
                    </div>
                    <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400 text-sm">
                      <Hash size={16} className="text-slate-400" />
                      <span className="font-mono">{printer.serialNumber}</span>
                    </div>
                    <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400 text-sm">
                      {printer.connectionType === 'Network' ? <Globe size={16} className="text-emerald-500"/> : <Usb size={16} className="text-slate-400"/>}
                      <span className="font-mono text-xs">{printer.connectionType === 'Network' ? printer.ipAddress : 'USB Bağlantı'}</span>
                    </div>
                </div>
              </div>

              {/* ACTION FOOTER */}
              <div className="grid grid-cols-2 border-t border-slate-200 dark:border-slate-700 divide-x divide-slate-200 dark:divide-slate-700">
                <button 
                    onClick={(e) => handleEditClick(e, printer)}
                    className="py-4 flex items-center justify-center gap-2 text-blue-600 dark:text-blue-400 font-semibold hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors active:bg-blue-100"
                >
                    <Edit2 size={18} /> Düzenle
                </button>
                <button 
                    onClick={(e) => confirmDelete(e, printer.id)}
                    className="py-4 flex items-center justify-center gap-2 text-red-600 dark:text-red-400 font-semibold hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors active:bg-red-100"
                >
                    <Trash2 size={18} /> Sil
                </button>
              </div>
            </div>
          );
        })}

        {printers.length === 0 && (
           <div className="col-span-full flex flex-col items-center justify-center py-20 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-700">
              <PrinterIcon size={48} className="text-slate-300 mb-4" />
              <p className="text-slate-500 font-medium">Kayıtlı yazıcı bulunamadı</p>
              <p className="text-slate-400 text-sm">Yeni eklemek için butonu kullanın</p>
           </div>
        )}
      </div>

      {/* --- QR CODE MODAL --- */}
      {qrPrinter && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[70] flex items-center justify-center p-4 animate-in fade-in duration-200" onClick={() => setQrPrinter(null)}>
            <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl max-w-sm w-full text-center relative" onClick={e => e.stopPropagation()}>
                <button onClick={() => setQrPrinter(null)} className="absolute top-4 right-4 p-2 bg-slate-100 dark:bg-slate-700 rounded-full text-slate-500"><X size={20}/></button>

                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-1">{qrPrinter.brand} {qrPrinter.model}</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{qrPrinter.location}</p>

                <div className="bg-white p-4 rounded-xl border-2 border-slate-100 inline-block mb-4">
                    <img 
                        src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(window.location.origin + window.location.pathname + '?pid=' + qrPrinter.id)}`} 
                        alt="QR Code" 
                        className="w-48 h-48"
                    />
                </div>

                <p className="text-xs text-slate-400 max-w-[250px] mx-auto">
                    Bu kodu yazıcının üzerine yapıştırın. Telefondan okutulduğunda direkt bu sayfa açılacaktır.
                </p>
            </div>
        </div>
      )}

      {/* --- DELETE MODAL --- */}
      {deleteId && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
           <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-sm w-full p-6 text-center scale-100 animate-in zoom-in-95 duration-200">
              <div className="w-16 h-16 bg-red-100 dark:bg-red-900/30 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Trash2 size={32} />
              </div>
              <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-2">Yazıcı Siliniyor</h3>
              <p className="text-slate-500 dark:text-slate-400 text-sm mb-6">
                 Bu cihazı ve geçmiş tüm kayıtlarını kalıcı olarak silmek istediğinize emin misiniz? Bu işlem geri alınamaz.
              </p>
              <div className="grid grid-cols-2 gap-3">
                 <button 
                    onClick={() => setDeleteId(null)}
                    className="py-3 px-4 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl font-semibold hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors"
                 >
                    Vazgeç
                 </button>
                 <button 
                    onClick={performDelete}
                    className="py-3 px-4 bg-red-600 text-white rounded-xl font-semibold hover:bg-red-700 shadow-lg shadow-red-200 dark:shadow-none transition-colors"
                 >
                    Evet, Sil
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* Add/Edit Modal */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-y-auto max-h-[90vh] animate-in slide-in-from-bottom-4 duration-300">
            <div className="bg-white dark:bg-slate-800 px-6 py-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center sticky top-0 z-10">
              <h3 className="font-bold text-lg text-slate-800 dark:text-white">
                {editingPrinter ? 'Cihazı Düzenle' : 'Yeni Cihaz Ekle'}
              </h3>
              <button type="button" onClick={closeFormModal} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full hover:bg-slate-200 transition-colors"><X size={20} className="text-slate-500 dark:text-slate-300" /></button>
            </div>

            <form onSubmit={handleSave} className="p-6 space-y-5">

              {/* STATUS SELECTION (NEW) */}
              <div className="bg-slate-50 dark:bg-slate-700/50 p-4 rounded-xl border border-slate-100 dark:border-slate-700">
                 <label className="block text-sm font-semibold text-slate-700 dark:text-slate-200 mb-3">Cihaz Durumu</label>
                 <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                    {[
                      { val: 'ACTIVE', label: 'Aktif', color: 'bg-emerald-100 text-emerald-700 border-emerald-300' },
                      { val: 'SPARE', label: 'Yedek', color: 'bg-indigo-100 text-indigo-700 border-indigo-300' },
                      { val: 'MAINTENANCE', label: 'Serviste', color: 'bg-orange-100 text-orange-700 border-orange-300' },
                      { val: 'BROKEN', label: 'Arızalı', color: 'bg-red-100 text-red-700 border-red-300' },
                      { val: 'SCRAPPED', label: 'Hurda', color: 'bg-slate-200 text-slate-700 border-slate-300' }
                    ].map(opt => (
                       <label key={opt.val} className={`cursor-pointer border-2 rounded-lg p-2 text-center text-xs font-bold transition-all ${
                          formData.status === opt.val ? opt.color : 'border-slate-200 text-slate-500 bg-white dark:bg-slate-800 dark:border-slate-600'
                       }`}>
                          <input type="radio" className="hidden" name="status" checked={formData.status === opt.val} onChange={() => setFormData({...formData, status: opt.val as PrinterStatus})} />
                          {opt.label}
                       </label>
                    ))}
                 </div>
              </div>

              {/* Brand & Model Select */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Marka</label>
                  <div className="relative">
                     <select 
                        required 
                        className="w-full appearance-none p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white transition-all"
                        value={formData.brand} 
                        onChange={e => setFormData({...formData, brand: e.target.value})}
                     >
                        <option value="">Seçiniz</option>
                        {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                     </select>
                     <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Model</label>
                  <div className="relative">
                     <select 
                        required 
                        className="w-full appearance-none p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white transition-all"
                        value={formData.model} 
                        onChange={e => setFormData({...formData, model: e.target.value})}
                     >
                        <option value="">Seçiniz</option>
                        {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                     </select>
                     <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
                  </div>
                </div>
              </div>

              {/* Supplier Selection */}
              <div>
                 <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Tedarikçi / Servis</label>
                 <div className="relative">
                     <select 
                        className="w-full appearance-none p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white transition-all"
                        value={formData.supplier} 
                        onChange={e => setFormData({...formData, supplier: e.target.value})}
                     >
                        <option value="">Seçiniz</option>
                        {config.suppliers.map(s => <option key={s} value={s}>{s}</option>)}
                     </select>
                     <Truck size={18} className="absolute right-10 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                     <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
