                <div className="flex gap-4 mb-4">
                  <label className={`flex-1 flex items-center justify-center gap-2 cursor-pointer p-3 rounded-lg border transition-all ${formData.connectionType === 'USB' ? 'bg-white dark:bg-slate-600 border-primary-500 shadow-sm text-primary-700 dark:text-primary-300' : 'border-transparent hover:bg-slate-200 dark:hover:bg-slate-600 text-slate-500'}`}>
                    <input 
                      type="radio" 
                      name="connType" 
                      className="hidden"
                      checked={formData.connectionType === 'USB'} 
                      onChange={() => setFormData({...formData, connectionType: 'USB', ipAddress: ''})} 
                    />
                    <Usb size={18}/> USB
                  </label>
                  <label className={`flex-1 flex items-center justify-center gap-2 cursor-pointer p-3 rounded-lg border transition-all ${formData.connectionType === 'Network' ? 'bg-white dark:bg-slate-600 border-primary-500 shadow-sm text-primary-700 dark:text-primary-300' : 'border-transparent hover:bg-slate-200 dark:hover:bg-slate-600 text-slate-500'}`}>
                    <input 
                      type="radio" 
                      name="connType" 
                      className="hidden"
                      checked={formData.connectionType === 'Network'} 
                      onChange={() => setFormData({...formData, connectionType: 'Network'})} 
                    />
                    <Wifi size={18}/> Network
                  </label>
                </div>

                {formData.connectionType === 'Network' && (
                  <div>
                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1 uppercase tracking-wider">IP Adresi</label>
                    <div className="relative">
                      <Globe size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                      <input 
                        type="text" 
                        required 
                        className="w-full pl-10 p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-white dark:bg-slate-600 text-slate-900 dark:text-white font-mono"
                        value={formData.ipAddress} 
                        onChange={e => setFormData({...formData, ipAddress: e.target.value})} 
                        placeholder="192.168.1.xxx" 
                      />
                    </div>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Seri No</label>
                  <input required className="w-full p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} placeholder="CNC..." />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Kat</label>
                  <input required className="w-full p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} placeholder="4. Kat" />
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Konum / Birim</label>
                <div className="relative">
                   <MapPin size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                   <input required className="w-full pl-10 p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                     value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} placeholder="Örn: Muhasebe Ofisi" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Son Sayaç</label>
                  <input type="number" required className="w-full p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.lastCounter} onChange={e => setFormData({...formData, lastCounter: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Uyumlu Toner</label>
                  <input 
                    list="toner-models-list" 
                    className="w-full p-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-white"
                    value={formData.compatibleToner} 
                    onChange={e => setFormData({...formData, compatibleToner: e.target.value})} 
                    placeholder="Örn: 85A" 
                  />
                  <datalist id="toner-models-list">
                    {config.tonerModels?.map(tm => <option key={tm} value={tm} />)}
                  </datalist>
                </div>
              </div>

              <div className="pt-4 flex gap-3">
                <button type="button" onClick={closeFormModal} className="flex-1 py-4 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors font-semibold">İptal</button>
                <button type="submit" className="flex-1 py-4 bg-primary-600 text-white rounded-xl hover:bg-primary-700 transition-colors font-bold shadow-lg shadow-primary-200 dark:shadow-none">
                  {editingPrinter ? 'Değişiklikleri Kaydet' : 'Cihazı Kaydet'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* History Modal */}
      {isHistoryModalOpen && selectedPrinterHistory && (
         <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-y-auto max-h-[90vh] animate-in slide-in-from-bottom-4 duration-300">
            <div className="bg-white dark:bg-slate-800 px-6 py-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center sticky top-0 z-10">
               <div>
                  <h3 className="font-bold text-xl text-slate-800 dark:text-white">
                    {selectedPrinterHistory.printer.brand} {selectedPrinterHistory.printer.model}
                  </h3>
                  <div className="flex gap-2 items-center mt-1">
                     <span className="bg-primary-50 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 text-xs px-2 py-0.5 rounded font-medium">
                        {selectedPrinterHistory.printer.location}
                     </span>
                     <span className="text-slate-400 text-xs">•</span>
                     <span className="text-slate-500 dark:text-slate-400 text-xs">{selectedPrinterHistory.printer.serialNumber}</span>
                  </div>
               </div>
              <button type="button" onClick={() => setIsHistoryModalOpen(false)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full hover:bg-slate-200 transition-colors"><X size={20} className="text-slate-500 dark:text-slate-300" /></button>
            </div>

            <div className="p-6">
              <h4 className="font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
                 <div className="p-2 bg-blue-100 dark:bg-blue-900/30 text-blue-600 rounded-lg"><History size={18}/></div>
                 Toner Değişim Geçmişi
              </h4>
              <div className="space-y-4 mb-8">
                {selectedPrinterHistory.tonerLogs.length === 0 && (
                   <div className="text-center py-6 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-dashed border-slate-200 dark:border-slate-700">
                      <p className="text-slate-400">Henüz kayıt yok.</p>
                   </div>
                )}
                {selectedPrinterHistory.tonerLogs.map((log) => (
                    <div key={log.id} className="relative pl-6 border-l-2 border-slate-200 dark:border-slate-700 pb-4 last:pb-0">
                       <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-white dark:bg-slate-800 border-2 border-blue-500"></div>
                       <div className="bg-slate-50 dark:bg-slate-700/50 p-4 rounded-xl border border-slate-100 dark:border-slate-700 hover:shadow-sm transition-shadow">
                          <div className="flex justify-between items-start mb-1">
                             <span className="font-bold text-slate-700 dark:text-slate-200">{log.tonerModel}</span>
                             <span className="text-xs text-slate-400 bg-white dark:bg-slate-800 px-2 py-1 rounded border dark:border-slate-600 shadow-sm">{new Date(log.date).toLocaleDateString('tr-TR')}</span>
                          </div>

                          {/* YIELD DATA - NEW DISPLAY */}
                          {log.pageYield !== undefined && log.pageYield > 0 && (
                             <div className="my-2 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 text-xs px-2 py-1 rounded w-fit font-medium flex items-center gap-1">
                                <History size={10} />
                                Önceki toner verimi: {log.pageYield.toLocaleString()} sayfa
                             </div>
                          )}

                          <p className="text-sm text-slate-500 dark:text-slate-400 mb-2">
                             İşlemi Yapan: <span className="font-medium text-slate-700 dark:text-slate-300">{log.user}</span>
                          </p>
                          {log.description && <p className="text-xs text-slate-400 italic bg-white dark:bg-slate-800 p-2 rounded">{log.description}</p>}
                       </div>
                    </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ArrowDown, ArrowUp, CheckCircle, AlertTriangle, Search, Banknote, Calendar, Settings as SettingsIcon, MessageCircle, Printer as PrinterIcon } from 'lucide-react';
import { TonerStock, Printer, StockLog, SystemConfig } from '../types';
import { StorageService } from '../services/storage';

interface StockManagementProps {
  user: { name: string };
}

export const StockManagement: React.FC<StockManagementProps> = ({ user }) => {
  const [stocks, setStocks] = useState<TonerStock[]>([]);
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [logs, setLogs] = useState<StockLog[]>([]); // New State for History
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [] });
  const [activeTab, setActiveTab] = useState<'LIST' | 'IN' | 'OUT'>('LIST');

  // Transaction States
  const [selectedPrinterId, setSelectedPrinterId] = useState('');
  const [selectedTonerModel, setSelectedTonerModel] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [cost, setCost] = useState(0); 
  const [newStockModel, setNewStockModel] = useState(''); 
  const [description, setDescription] = useState('');

  // Page Yield Logic
  const [currentCounter, setCurrentCounter] = useState<number>(0);
  const [lastPrinterCounter, setLastPrinterCounter] = useState<number>(0);

  // Notification
  const [message, setMessage] = useState<{type: 'success' | 'error', text: string} | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setStocks(StorageService.getStocks());
    setPrinters(StorageService.getPrinters());
    setLogs(StorageService.getLogs()); // Fetch Logs
    setConfig(StorageService.getConfig());
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 3000);
  };

  const checkLowStockAndNotify = (model: string, newQty: number) => {
    if (newQty <= 1) {
       const config = StorageService.getConfig();
       if (config.whatsappNumber) {
         setTimeout(() => {
            alert(`⚠️ SİSTEM UYARISI: ${model} toneri kritik seviyeye (${newQty}) düştü! WhatsApp bildirimi ${config.whatsappNumber} numarasına gönderildi.`);
         }, 500);
       }
    }
  };

  const handleStockIn = (e: React.FormEvent) => {
    e.preventDefault();
    const model = newStockModel.trim(); // No uppercase forcing, keeping original format
    if (!model) {
      showMessage('error', 'Lütfen bir model seçiniz.');
      return;
    }

    const updatedStocks = [...stocks];
    const existingIndex = updatedStocks.findIndex(s => s.modelName === model);

    if (existingIndex >= 0) {
      updatedStocks[existingIndex].quantity += quantity;
    } else {
      updatedStocks.push({ modelName: model, quantity: quantity });
    }

    StorageService.saveStocks(updatedStocks);

    // Log
    const log: StockLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      type: 'IN',
      tonerModel: model,
      quantity: quantity,
      description: 'Stok Girişi (Manuel)',
      user: user.name,
      cost: cost 
    };
    StorageService.addLog(log);

    refreshData();
    showMessage('success', `${quantity} adet ${model} stoğa eklendi.`);
    setNewStockModel('');
    setQuantity(1);
    setCost(0);
    setActiveTab('LIST');
  };

  const handleStockOut = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTonerModel) {
      showMessage('error', 'Lütfen toner seçiniz.');
      return;
    }

    // Check stock
    const updatedStocks = [...stocks];
    const stockIndex = updatedStocks.findIndex(s => s.modelName === selectedTonerModel);

    if (stockIndex === -1 || updatedStocks[stockIndex].quantity < 1) {
      showMessage('error', 'Yetersiz stok!');
      return;
    }

    // Decrement Stock
    updatedStocks[stockIndex].quantity -= 1; 
    const newQuantity = updatedStocks[stockIndex].quantity;
    StorageService.saveStocks(updatedStocks);

    // Check Notification
    checkLowStockAndNotify(selectedTonerModel, newQuantity);

    // Update Printer & Calculate Yield
    let printerDesc = "";
    let calculatedYield = 0;

    if (selectedPrinterId && selectedPrinterId !== 'MANUAL') {
      const updatedPrinters = printers.map(p => {
        if (p.id === selectedPrinterId) {
          printerDesc = `${p.location} (${p.floor})`;

          // Yield Calculation
          if (currentCounter > p.lastCounter) {
             calculatedYield = currentCounter - p.lastCounter;
          }

          return {
            ...p,
            lastTonerDate: new Date().toISOString(),
            lastCounter: currentCounter || p.lastCounter // Update to new counter
          };
        }
        return p;
      });
      StorageService.savePrinters(updatedPrinters);
    }

    // Log
    const log: StockLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      type: 'OUT',
      tonerModel: selectedTonerModel,
      quantity: 1,
      printerId: selectedPrinterId === 'MANUAL' ? undefined : selectedPrinterId,
      description: (selectedPrinterId && selectedPrinterId !== 'MANUAL') ? `Yazıcıya Takıldı: ${printerDesc}` : `Stok Çıkışı: ${description}`,
      user: user.name,
      pageYield: calculatedYield > 0 ? calculatedYield : undefined
    };
    StorageService.addLog(log);

    refreshData();
    showMessage('success', `${selectedTonerModel} stoktan düşüldü. ${calculatedYield > 0 ? `(Önceki toner: ${calculatedYield} sayfa)` : ''}`);
    setSelectedPrinterId('');
    setSelectedTonerModel('');
    setCurrentCounter(0);
    setActiveTab('LIST');
  };

  // Helper to auto-select toner when printer is selected
  const onPrinterSelect = (printerId: string) => {
    setSelectedPrinterId(printerId);
    const printer = printers.find(p => p.id === printerId);
    if (printer) {
      if (printer.compatibleToner) setSelectedTonerModel(printer.compatibleToner);
      setLastPrinterCounter(printer.lastCounter);
      setCurrentCounter(printer.lastCounter); // Set default to current to avoid confusion
    } else {
       setLastPrinterCounter(0);
       setCurrentCounter(0);
    }
  };

  // WhatsApp Order Generator
  const sendWhatsappOrder = (model: string) => {
     const supplier = config.suppliers[0] || '';
     const text = `Merhaba, ${model} model toner stoğumuz kritik seviyenin altına düştü. Sipariş vermek istiyoruz.`;
     const url = `https://wa.me/${config.whatsappNumber}?text=${encodeURIComponent(text)}`;
     window.open(url, '_blank');
  };

  // Filter only OUT logs for the table
  const outputLogs = logs.filter(l => l.type === 'OUT');

  // Printer Status Helper
  const getPrinterStatusText = (status: string) => {
    switch(status) {
      case 'ACTIVE': return 'Aktif';
      case 'SPARE': return 'Yedekte';
      case 'MAINTENANCE': return 'Serviste';
      case 'BROKEN': return 'Arızalı';
      case 'SCRAPPED': return 'Hurda';
      default: return '';
    }
  };

  return (
    <div className="space-y-6">
      {message && (
        <div className={`fixed top-4 right-4 p-4 rounded-lg shadow-xl text-white z-50 animate-bounce ${message.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
          {message.text}
        </div>
      )}

      <div className="flex space-x-2 bg-white dark:bg-slate-800 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 w-fit">
        <button 
          onClick={() => setActiveTab('LIST')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'LIST' ? 'bg-primary-900 text-white' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
        >
          Stok Listesi
        </button>
        <button 
          onClick={() => setActiveTab('IN')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'IN' ? 'bg-green-600 text-white' : 'text-green-700 dark:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20'}`}
        >
          <ArrowDown size={16} /> Stok Giriş
        </button>
        <button 
          onClick={() => setActiveTab('OUT')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'OUT' ? 'bg-orange-600 text-white' : 'text-orange-700 dark:text-orange-400 hover:bg-orange-50 dark:hover:bg-orange-900/20'}`}
        >
          <ArrowUp size={16} /> Toner Çıkış
        </button>
      </div>

      {activeTab === 'LIST' && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {stocks.map(stock => (
            <div key={stock.modelName} className="bg-white dark:bg-slate-800 p-6 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col items-center justify-center text-center relative group hover:border-primary-300 transition-colors">
              <h3 className="text-3xl font-bold text-slate-800 dark:text-white mb-1">{stock.quantity}</h3>
              <p className="text-slate-500 dark:text-slate-400 font-medium">Model: {stock.modelName}</p>

              {stock.quantity < 3 && (
                 <div className="mt-2 flex flex-col gap-2 w-full">
                    <span className="text-xs bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 px-2 py-1 rounded-full flex items-center justify-center gap-1 mx-auto">
                      <AlertTriangle size={12} /> Kritik
                    </span>
                    {config.whatsappNumber && (
                        <button 
                          onClick={() => sendWhatsappOrder(stock.modelName)}
                          className="text-xs bg-green-500 text-white px-2 py-1.5 rounded-lg flex items-center justify-center gap-1 hover:bg-green-600"
                        >
                            <MessageCircle size={12} /> Sipariş Ver
                        </button>
                    )}
                 </div>
              )}
            </div>
          ))}
          {stocks.length === 0 && (
            <div className="col-span-full p-8 text-center text-slate-400">Henüz stok kaydı yok.</div>
          )}
        </div>
      )}

      {activeTab === 'IN' && (
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 max-w-lg">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
            <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg text-green-700 dark:text-green-400"><ArrowDown size={20}/></div>
            Stok Girişi Yap
          </h3>
          <form onSubmit={handleStockIn} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Toner/Mürekkep Modeli</label>
              <div className="relative">
                 <select 
                    required
                    className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white appearance-none"
                    value={newStockModel}
                    onChange={e => setNewStockModel(e.target.value)}
                 >
                    <option value="">Listeden Seçiniz</option>
                    {config.tonerModels?.map(s => <option key={s} value={s}>{s}</option>)}
                 </select>
                 <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
              </div>
              <p className="text-xs text-slate-400 mt-2 flex items-center gap-1">
                <SettingsIcon size={12} /> Listede olmayan modelleri "Ayarlar" sayfasından ekleyebilirsiniz.
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Adet</label>
              <div className="flex items-center gap-4">
                <button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">-</button>
                <input 
                  type="number" 
                  min="1"
                  required
                  className="w-full text-center p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none font-bold text-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={quantity}
                  onChange={e => setQuantity(parseInt(e.target.value) || 1)}
                />
                <button type="button" onClick={() => setQuantity(quantity + 1)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">+</button>
              </div>
            </div>

             <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                 Toplam Maliyet (TL) 
                 <span className="text-xs font-normal text-slate-400 ml-1">(Ücretsizse 0 giriniz)</span>
              </label>
              <div className="relative">
                 <Banknote className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input 
                   type="number" 
                   min="0"
                   className="w-full pl-10 p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   value={cost}
                   onChange={e => setCost(parseFloat(e.target.value) || 0)}
                 />
              </div>
            </div>

            <button type="submit" className="w-full py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200 dark:shadow-none">
              Stok Ekle
            </button>
          </form>
        </div>
      )}

