import React, { useState, useEffect } from 'react';
import { ArrowDown, ArrowUp, CheckCircle, AlertTriangle, Search, Banknote, Calendar, Settings as SettingsIcon, MessageCircle, Printer as PrinterIcon } from 'lucide-react';
import { TonerStock, Printer, StockLog, SystemConfig } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface StockManagementProps {
  user: { name: string };
}

export const StockManagement: React.FC<StockManagementProps> = ({ user }) => {
  const [stocks, setStocks] = useState<TonerStock[]>([]);
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [logs, setLogs] = useState<StockLog[]>([]); // New State for History
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [] });
  const [activeTab, setActiveTab] = useState<'LIST' | 'IN' | 'OUT'>('LIST');
  const [loading, setLoading] = useState(true);

  // Transaction States
  const [selectedPrinterId, setSelectedPrinterId] = useState('');
  const [selectedTonerModel, setSelectedTonerModel] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [cost, setCost] = useState(0); 
  const [newStockModel, setNewStockModel] = useState(''); 
  const [description, setDescription] = useState('');
  const [customDate, setCustomDate] = useState(new Date().toISOString().split('T')[0]); // Default today YYYY-MM-DD

  // Notification
  const [message, setMessage] = useState<{type: 'success' | 'error', text: string} | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    setLoading(true);
    const [s, p, l, c] = await Promise.all([
      StorageService.getStocks(),
      StorageService.getPrinters(),
      StorageService.getLogs(),
      StorageService.getConfig()
    ]);
    setStocks(s);
    setPrinters(p);
    setLogs(l);
    setConfig(c);
    setLoading(false);
    // Reset date to today on refresh just in case
    setCustomDate(new Date().toISOString().split('T')[0]);
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 3000);
  };

  const checkLowStockAndNotify = (model: string, newQty: number) => {
    if (newQty <= 1) {
       // Config is already loaded in state, no need to fetch again for this
       if (config.whatsappNumber) {
         setTimeout(() => {
            alert(`⚠️ SİSTEM UYARISI: ${model} toneri kritik seviyeye (${newQty}) düştü! WhatsApp bildirimi ${config.whatsappNumber} numarasına gönderildi.`);
         }, 500);
       }
    }
  };

  const handleStockIn = async (e: React.FormEvent) => {
    e.preventDefault();
    const model = newStockModel.trim();
    if (!model) {
      showMessage('error', 'Lütfen bir model seçiniz.');
      return;
    }

    // Calc new quantity
    const existingStock = stocks.find(s => s.modelName === model);
    const newQty = (existingStock ? existingStock.quantity : 0) + quantity;

    // Save Stock (Async)
    await StorageService.saveStock({ modelName: model, quantity: newQty });

    // Log
    const log: StockLog = {
      id: Date.now().toString(), // Will be overwritten by DB ID but kept for type safety
      date: new Date().toISOString(),
      type: 'IN',
      tonerModel: model,
      quantity: quantity,
      description: 'Stok Girişi (Manuel)',
      user: user.name,
      cost: cost 
    };
    await StorageService.addLog(log);

    await refreshData();
    showMessage('success', `${quantity} adet ${model} stoğa eklendi.`);
    setNewStockModel('');
    setQuantity(1);
    setCost(0);
    setActiveTab('LIST');
  };

  const handleStockOut = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTonerModel) {
      showMessage('error', 'Lütfen toner seçiniz.');
      return;
    }

    // Check stock locally first
    const stock = stocks.find(s => s.modelName === selectedTonerModel);

    if (!stock || stock.quantity < 1) {
      showMessage('error', 'Yetersiz stok!');
      return;
    }

    // Prepare Date
    // Combine selected date with current time to preserve order for logs on the same day
    const now = new Date();
    const logDate = new Date(customDate);
    logDate.setHours(now.getHours(), now.getMinutes(), now.getSeconds());
    const isoLogDate = logDate.toISOString();

    // Decrement Stock
    const newQuantity = stock.quantity - 1;
    await StorageService.saveStock({ modelName: selectedTonerModel, quantity: newQuantity });

    // Check Notification
    checkLowStockAndNotify(selectedTonerModel, newQuantity);

    // Update Printer
    let printerDesc = "";

    if (selectedPrinterId && selectedPrinterId !== 'MANUAL') {
      const printer = printers.find(p => p.id === selectedPrinterId);
      if (printer) {
         printerDesc = `${printer.location} (${printer.floor})`;

         // Logic: Only update the printer's "Last Toner Date" if the entered date is NEWER than what is stored.
         // This allows backdating (entering past records) without messing up the current status.
         const isNewerDate = isoLogDate > printer.lastTonerDate;

         const updatedPrinter = {
            ...printer,
            lastTonerDate: isNewerDate ? isoLogDate : printer.lastTonerDate
         };
         await StorageService.updatePrinter(updatedPrinter);
      }
    }

    // Log
    const log: StockLog = {
      id: '',
      date: isoLogDate,
      type: 'OUT',
      tonerModel: selectedTonerModel,
      quantity: 1,
      printerId: selectedPrinterId === 'MANUAL' ? undefined : selectedPrinterId,
      description: (selectedPrinterId && selectedPrinterId !== 'MANUAL') ? `Yazıcıya Takıldı: ${printerDesc}` : `Stok Çıkışı: ${description}`,
      user: user.name
    };
    await StorageService.addLog(log);

    await refreshData();
    showMessage('success', `${selectedTonerModel} stoktan düşüldü.`);
    setSelectedPrinterId('');
    setSelectedTonerModel('');
    setActiveTab('LIST');
  };

  // Helper to auto-select toner when printer is selected
  const onPrinterSelect = (printerId: string) => {
    setSelectedPrinterId(printerId);
    const printer = printers.find(p => p.id === printerId);
    if (printer) {
      if (printer.compatibleToner) setSelectedTonerModel(printer.compatibleToner);
    }
  };

  // WhatsApp Order Generator
  const sendWhatsappOrder = (model: string) => {
     const text = `Merhaba, ${model} model toner stoğumuz kritik seviyenin altına düştü. Sipariş vermek istiyoruz.`;
     const url = `https://wa.me/${config.whatsappNumber}?text=${encodeURIComponent(text)}`;
     window.open(url, '_blank');
  };

  // Filter only OUT logs for the table
  const outputLogs = logs.filter(l => l.type === 'OUT');

  // Printer Status Helper
  const getPrinterStatusText = (status: string) => {
    switch(status) {
      case 'ACTIVE': return 'Aktif';
      case 'SPARE': return 'Yedekte';
      case 'MAINTENANCE': return 'Serviste';
      case 'BROKEN': return 'Arızalı';
      case 'SCRAPPED': return 'Hurda';
      default: return '';
    }
  };

  if (loading) {
    return <LoadingScreen message="Stok verileri güncelleniyor..." />;
  }

  return (
    <div className="space-y-6">
      {message && (
        <div className={`fixed top-4 right-4 p-4 rounded-lg shadow-xl text-white z-50 animate-bounce ${message.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
          {message.text}
        </div>
      )}

      <div className="flex space-x-2 bg-white dark:bg-slate-800 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 w-fit">
        <button 
          onClick={() => setActiveTab('LIST')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'LIST' ? 'bg-primary-900 text-white' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
        >
          Stok Listesi
        </button>
        <button 
          onClick={() => setActiveTab('IN')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'IN' ? 'bg-green-600 text-white' : 'text-green-700 dark:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20'}`}
        >
          <ArrowDown size={16} /> Stok Giriş
        </button>
        <button 
          onClick={() => setActiveTab('OUT')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'OUT' ? 'bg-orange-600 text-white' : 'text-orange-700 dark:text-orange-400 hover:bg-orange-50 dark:hover:bg-orange-900/20'}`}
        >
          <ArrowUp size={16} /> Toner Çıkış
        </button>
      </div>

      {activeTab === 'LIST' && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {stocks.map(stock => (
            <div key={stock.modelName} className="bg-white dark:bg-slate-800 p-6 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col items-center justify-center text-center relative group hover:border-primary-300 transition-colors">
              <h3 className="text-3xl font-bold text-slate-800 dark:text-white mb-1">{stock.quantity}</h3>
              <p className="text-slate-500 dark:text-slate-400 font-medium">Model: {stock.modelName}</p>

              {stock.quantity < 3 && (
                 <div className="mt-2 flex flex-col gap-2 w-full">
                    <span className="text-xs bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 px-2 py-1 rounded-full flex items-center justify-center gap-1 mx-auto">
                      <AlertTriangle size={12} /> Kritik
                    </span>
                    {config.whatsappNumber && (
                        <button 
                          onClick={() => sendWhatsappOrder(stock.modelName)}
                          className="text-xs bg-green-500 text-white px-2 py-1.5 rounded-lg flex items-center justify-center gap-1 hover:bg-green-600"
                        >
                            <MessageCircle size={12} /> Sipariş Ver
                        </button>
                    )}
                 </div>
              )}
            </div>
          ))}
          {stocks.length === 0 && (
            <div className="col-span-full p-8 text-center text-slate-400">Henüz stok kaydı yok.</div>
          )}
        </div>
      )}

      {activeTab === 'IN' && (
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 max-w-lg">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
            <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg text-green-700 dark:text-green-400"><ArrowDown size={20}/></div>
            Stok Girişi Yap
          </h3>
          <form onSubmit={handleStockIn} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Toner/Mürekkep Modeli</label>
              <div className="relative">
                 <select 
                    required
                    className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white appearance-none"
                    value={newStockModel}
                    onChange={e => setNewStockModel(e.target.value)}
                 >
                    <option value="">Listeden Seçiniz</option>
                    {config.tonerModels?.map(s => <option key={s} value={s}>{s}</option>)}
                 </select>
                 <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
              </div>
              <p className="text-xs text-slate-400 mt-2 flex items-center gap-1">
                <SettingsIcon size={12} /> Listede olmayan modelleri "Ayarlar" sayfasından ekleyebilirsiniz.
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Adet</label>
              <div className="flex items-center gap-4">
                <button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">-</button>
                <input 
                  type="number" 
                  min="1"
                  required
                  className="w-full text-center p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none font-bold text-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={quantity}
                  onChange={e => setQuantity(parseInt(e.target.value) || 1)}
                />
                <button type="button" onClick={() => setQuantity(quantity + 1)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">+</button>
              </div>
            </div>

             <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                 Toplam Maliyet (TL) 
                 <span className="text-xs font-normal text-slate-400 ml-1">(Ücretsizse 0 giriniz)</span>
              </label>
              <div className="relative">
                 <Banknote className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input 
                   type="number" 
                   min="0"
                   className="w-full pl-10 p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   value={cost}
                   onChange={e => setCost(parseFloat(e.target.value) || 0)}
                 />
              </div>
            </div>

            <button type="submit" className="w-full py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200 dark:shadow-none">
              Stok Ekle
            </button>
          </form>
        </div>
      )}

      {activeTab === 'OUT' && (
        <div className="flex flex-col lg:flex-row gap-6">
          <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 w-full lg:w-1/2">
             <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
              <div className="p-2 bg-orange-100 dark:bg-orange-900/30 rounded-lg text-orange-700 dark:text-orange-400"><ArrowUp size={20}/></div>
              Toner Çıkışı (Değişim)
            </h3>
            <form onSubmit={handleStockOut} className="space-y-5">

              {/* DATE SELECTOR */}
              <div>
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">İşlem Tarihi</label>
                 <div className="relative cursor-pointer" onClick={() => document.getElementById('date-picker')?.showPicker()}>
                     <Calendar size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                     <input 
                        id="date-picker"
                        type="date" 
                        required
                        className="w-full pl-10 p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white cursor-pointer"
                        value={customDate}
                        onChange={e => setCustomDate(e.target.value)}
                        onClick={(e) => e.currentTarget.showPicker()}
                     />
                 </div>
                 <p className="text-[10px] text-slate-400 mt-1 ml-1">Kutunun herhangi bir yerine tıklayarak takvimi açabilirsiniz.</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Hangi Yazıcıya?</label>
                <select 
                  className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={selectedPrinterId}
                  onChange={(e) => onPrinterSelect(e.target.value)}
                >
                  <option value="">-- Yazıcı Seçiniz --</option>
                  {printers.map(p => (
                    <option key={p.id} value={p.id}>
                      {p.location} ({p.model}) - {getPrinterStatusText(p.status)}
                    </option>
                  ))}
                  <option value="MANUAL">Listede Yok / Manuel Çıkış</option>
                </select>
              </div>

              {selectedPrinterId === 'MANUAL' && (
                 <div>
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Açıklama / Yer</label>
                 <input 
                   className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   placeholder="Örn: 3. Kat Depo"
                   value={description}
                   onChange={e => setDescription(e.target.value)}
                   required
                 />
               </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Verilen Toner Modeli</label>
                <select 
                  required
                  className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={selectedTonerModel}
                  onChange={e => setSelectedTonerModel(e.target.value)}
                >
                  <option value="">-- Model Seçiniz --</option>
                  {stocks.map(s => (
                    <option key={s.modelName} value={s.modelName} disabled={s.quantity <= 0}>
                      {s.modelName} (Stok: {s.quantity})
                    </option>
                  ))}
                </select>
              </div>

              <div className="p-4 bg-orange-50 dark:bg-orange-900/20 rounded-xl text-sm text-orange-800 dark:text-orange-200 border border-orange-100 dark:border-orange-800/30">
                <p>Onayladığınızda stoktan <strong>1 adet</strong> düşülecektir.</p>
                {selectedPrinterId && selectedPrinterId !== 'MANUAL' && (
                  <p className="mt-1">Cihazın "Son Toner Tarihi" güncellenecektir.</p>
                )}
              </div>

              <button type="submit" className="w-full py-4 bg-orange-600 text-white rounded-xl font-bold hover:bg-orange-700 transition-colors shadow-lg shadow-orange-200 dark:shadow-none">
                Çıkış Yap & Onayla
              </button>
            </form>
          </div>

          {/* Recent Outputs Table */}
          <div className="w-full lg:w-1/2">
             <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 h-full max-h-[600px] overflow-hidden flex flex-col">
                <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
                   <Calendar size={20} className="text-slate-500"/> Son Toner Çıkış Hareketleri
                </h3>
                <div className="overflow-y-auto flex-1">
                   <table className="w-full text-left text-sm">
                      <thead className="bg-slate-50 dark:bg-slate-700 sticky top-0">
                         <tr>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium">Toner</th>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium">Tarih</th>
                            <th className="p-3 text-slate-500 dark:text-slate-300 font-medium">Açıklama</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                         {outputLogs.slice(0, 15).map(log => (
                            <tr key={log.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50">
                               <td className="p-3 font-medium text-slate-800 dark:text-white">{log.tonerModel}</td>
                               <td className="p-3 text-xs text-slate-500 dark:text-slate-400">{new Date(log.date).toLocaleDateString('tr-TR')}</td>
                               <td className="p-3 text-slate-600 dark:text-slate-300 max-w-[120px] truncate" title={log.description}>{log.description}</td>
                            </tr>
                         ))}
                         {outputLogs.length === 0 && (
                            <tr><td colSpan={3} className="p-4 text-center text-slate-400">Henüz çıkış kaydı yok.</td></tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, ServiceRecord, User } from '../types';
import { Wrench, Plus, Save, Clock, CheckCircle2, XCircle, Calendar } from 'lucide-react';
import { LoadingScreen } from './LoadingScreen';

interface ServiceManagementProps {
  // empty
}

export const ServiceManagement: React.FC<ServiceManagementProps> = () => {
  const [records, setRecords] = useState<ServiceRecord[]>([]);
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [loading, setLoading] = useState(true);

  // Form State
  const [selectedPrinterId, setSelectedPrinterId] = useState('');
  const [issue, setIssue] = useState('');
  const [action, setAction] = useState('');
  const [provider, setProvider] = useState('');
  const [cost, setCost] = useState(0);
  const [status, setStatus] = useState<'PENDING' | 'COMPLETED' | 'SCRAPPED'>('PENDING');
  const [customDate, setCustomDate] = useState(new Date().toISOString().split('T')[0]); // Default today

  useEffect(() => {
    const fetchData = async () => {
        setLoading(true);
        const r = await StorageService.getServiceRecords();
        const p = await StorageService.getPrinters();
        setRecords(r);
        setPrinters(p);
        setLoading(false);
    };
    fetchData();
  }, []);

  const handlePrinterChange = (printerId: string) => {
    setSelectedPrinterId(printerId);
    const printer = printers.find(p => p.id === printerId);
    if (printer && printer.supplier) {
      setProvider(printer.supplier);
    } else {
      setProvider('');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const printer = printers.find(p => p.id === selectedPrinterId);
    if (!printer) return;

    // Prepare Date
    const now = new Date();
    const serviceDate = new Date(customDate);
    // Keep current time, but use selected date
    serviceDate.setHours(now.getHours(), now.getMinutes(), now.getSeconds());

    const newRecord: ServiceRecord = {
      id: '', // Generated by Firestore
      printerId: printer.id,
      printerName: `${printer.brand} ${printer.model} (${printer.location})`,
      date: serviceDate.toISOString(),
      issue,
      actionTaken: action,
      provider,
      cost,
      status
    };

    await StorageService.addServiceRecord(newRecord);

    // Refresh List
    const updatedRecords = await StorageService.getServiceRecords();
    setRecords(updatedRecords);

    // Reset Form
    setIssue('');
    setAction('');
    setProvider('');
    setCost(0);
    setStatus('PENDING');
    setCustomDate(new Date().toISOString().split('T')[0]);
    alert('Servis kaydı eklendi.');
  };

  if (loading) {
    return <LoadingScreen message="Servis kayıtları yükleniyor..." />;
  }

  return (
    <div className="space-y-6">
       <div className="flex flex-col md:flex-row gap-6">
          {/* Form Side */}
          <div className="md:w-1/3 space-y-4">
             <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
                <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
                   <Wrench size={20} className="text-orange-500"/> Yeni Arıza/Servis Kaydı
                </h3>
                <form onSubmit={handleSubmit} className="space-y-3">
                   {/* DATE SELECTION */}
                   <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Tarih</label>
                      <div className="relative cursor-pointer" onClick={() => document.getElementById('service-date-picker')?.showPicker()}>
                         <Calendar size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                         <input 
                            id="service-date-picker"
                            type="date" 
                            required
                            className="w-full pl-10 p-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500 cursor-pointer"
                            value={customDate}
                            onChange={(e) => setCustomDate(e.target.value)}
                            onClick={(e) => e.currentTarget.showPicker()}
                         />
                      </div>
                   </div>

                   <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Cihaz Seçimi</label>
                      <select 
                        required
                        className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500"
                        value={selectedPrinterId}
                        onChange={(e) => handlePrinterChange(e.target.value)}
                      >
                         <option value="">Seçiniz</option>
                         {printers.map(p => (
                           <option key={p.id} value={p.id}>{p.brand} {p.model} - {p.location}</option>
                         ))}
                      </select>
                   </div>

                   <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Arıza / Sorun</label>
                      <input 
                         required
                         type="text"
                         className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500"
                         placeholder="Örn: Kağıt sıkıştırıyor"
                         value={issue}
                         onChange={(e) => setIssue(e.target.value)}
                      />
                   </div>

                   <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Yapılan İşlem</label>
                      <textarea 
                         required
                         className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500"
                         placeholder="Örn: Fuser ünitesi değişti"
                         value={action}
                         onChange={(e) => setAction(e.target.value)}
                         rows={2}
                      />
                   </div>

                   <div className="grid grid-cols-2 gap-3">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Servis Firması</label>
                         <input 
                           required
                           type="text"
                           className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500"
                           placeholder="Örn: Yetkili Servis"
                           value={provider}
                           onChange={(e) => setProvider(e.target.value)}
                         />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Maliyet (TL)</label>
                         <input 
                           type="number"
                           min="0"
                           className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500"
                           value={cost}
                           onChange={(e) => setCost(Number(e.target.value))}
                         />
                      </div>
                   </div>

                   <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Durum</label>
                      <div className="flex gap-2">
                         <label className="flex items-center gap-1 cursor-pointer bg-slate-100 dark:bg-slate-700 p-2 rounded text-xs">
                           <input type="radio" name="status" checked={status === 'PENDING'} onChange={() => setStatus('PENDING')} /> Bekliyor
                         </label>
                         <label className="flex items-center gap-1 cursor-pointer bg-green-100 dark:bg-green-900/30 p-2 rounded text-xs">
                           <input type="radio" name="status" checked={status === 'COMPLETED'} onChange={() => setStatus('COMPLETED')} /> Tamamlandı
                         </label>
                         <label className="flex items-center gap-1 cursor-pointer bg-red-100 dark:bg-red-900/30 p-2 rounded text-xs">
                           <input type="radio" name="status" checked={status === 'SCRAPPED'} onChange={() => setStatus('SCRAPPED')} /> Hurda/Değişim
                         </label>
                      </div>
                   </div>

                   <button type="submit" className="w-full bg-orange-600 text-white py-3 rounded-lg font-bold hover:bg-orange-700 transition-colors mt-2">
                     Kaydet
                   </button>
                </form>
             </div>
          </div>

          {/* List Side */}
          <div className="flex-1">
             <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-4">Servis Geçmişi</h3>
             <div className="space-y-3">
               {records.length === 0 && <div className="text-slate-400">Henüz servis kaydı bulunmamaktadır.</div>}
               {records.map(record => (
                 <div key={record.id} className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col md:flex-row gap-4 items-start md:items-center justify-between">
                    <div>
                       <div className="flex items-center gap-2 mb-1">
                          <span className={`px-2 py-0.5 rounded text-xs font-bold text-white ${
                             record.status === 'COMPLETED' ? 'bg-green-500' : 
                             record.status === 'PENDING' ? 'bg-yellow-500' : 'bg-red-600'
                          }`}>
                             {record.status === 'COMPLETED' ? 'TAMAMLANDI' : record.status === 'PENDING' ? 'BEKLİYOR' : 'HURDA/DEĞİŞİM'}
                          </span>
                          <span className="text-xs text-slate-400">{new Date(record.date).toLocaleDateString('tr-TR')}</span>
                       </div>
                       <h4 className="font-bold text-slate-800 dark:text-white">{record.printerName}</h4>
                       <p className="text-sm text-red-600 dark:text-red-400 font-medium">Sorun: {record.issue}</p>
                       <p className="text-sm text-slate-600 dark:text-slate-300">İşlem: {record.actionTaken}</p>
                       <p className="text-xs text-slate-400 mt-1">{record.provider}</p>
                    </div>
                    <div className="text-right min-w-[100px]">
                       <p className="text-xs text-slate-500">Maliyet</p>
                       <p className="text-xl font-bold text-slate-800 dark:text-white">{record.cost > 0 ? `${record.cost} ₺` : 'Ücretsiz'}</p>
                    </div>
                 </div>
               ))}
             </div>
          </div>
       </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ArrowDown, ArrowUp, CheckCircle, AlertTriangle, Search, Banknote, Calendar, Settings as SettingsIcon, MessageCircle, Printer as PrinterIcon } from 'lucide-react';
import { TonerStock, Printer, StockLog, SystemConfig } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface StockManagementProps {
  user: { name: string };
}

export const StockManagement: React.FC<StockManagementProps> = ({ user }) => {
  const [stocks, setStocks] = useState<TonerStock[]>([]);
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [logs, setLogs] = useState<StockLog[]>([]); // New State for History
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [] });
  const [activeTab, setActiveTab] = useState<'LIST' | 'IN' | 'OUT'>('LIST');
  const [loading, setLoading] = useState(true);

  // Transaction States
  const [selectedPrinterId, setSelectedPrinterId] = useState('');
  const [selectedTonerModel, setSelectedTonerModel] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [cost, setCost] = useState(0); 
  const [newStockModel, setNewStockModel] = useState(''); 
  const [description, setDescription] = useState('');
  const [customDate, setCustomDate] = useState(new Date().toISOString().split('T')[0]); // Default today YYYY-MM-DD

  // Notification
  const [message, setMessage] = useState<{type: 'success' | 'error', text: string} | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    setLoading(true);
    const [s, p, l, c] = await Promise.all([
      StorageService.getStocks(),
      StorageService.getPrinters(),
      StorageService.getLogs(),
      StorageService.getConfig()
    ]);
    setStocks(s);
    setPrinters(p);
    setLogs(l);
    setConfig(c);
    setLoading(false);
    // Reset date to today on refresh just in case
    setCustomDate(new Date().toISOString().split('T')[0]);
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 3000);
  };

  const checkLowStockAndNotify = (model: string, newQty: number) => {
    if (newQty <= 1) {
       // Config is already loaded in state, no need to fetch again for this
       if (config.whatsappNumber) {
         setTimeout(() => {
            alert(`⚠️ SİSTEM UYARISI: ${model} toneri kritik seviyeye (${newQty}) düştü! WhatsApp bildirimi ${config.whatsappNumber} numarasına gönderildi.`);
         }, 500);
       }
    }
  };

  const handleStockIn = async (e: React.FormEvent) => {
    e.preventDefault();
    const model = newStockModel.trim();
    if (!model) {
      showMessage('error', 'Lütfen bir model seçiniz.');
      return;
    }

    // Calc new quantity
    const existingStock = stocks.find(s => s.modelName === model);
    const newQty = (existingStock ? existingStock.quantity : 0) + quantity;

    // Save Stock (Async)
    await StorageService.saveStock({ modelName: model, quantity: newQty });

    // Log
    const log: StockLog = {
      id: Date.now().toString(), // Will be overwritten by DB ID but kept for type safety
      date: new Date().toISOString(),
      type: 'IN',
      tonerModel: model,
      quantity: quantity,
      description: 'Stok Girişi (Manuel)',
      user: user.name,
      cost: cost 
    };
    await StorageService.addLog(log);

    await refreshData();
    showMessage('success', `${quantity} adet ${model} stoğa eklendi.`);
    setNewStockModel('');
    setQuantity(1);
    setCost(0);
    setActiveTab('LIST');
  };

  const handleStockOut = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTonerModel) {
      showMessage('error', 'Lütfen toner seçiniz.');
      return;
    }

    // Check stock locally first
    const stock = stocks.find(s => s.modelName === selectedTonerModel);

    if (!stock || stock.quantity < 1) {
      showMessage('error', 'Yetersiz stok!');
      return;
    }

    // Prepare Date
    // Combine selected date with current time to preserve order for logs on the same day
    const now = new Date();
    const logDate = new Date(customDate);
    logDate.setHours(now.getHours(), now.getMinutes(), now.getSeconds());
    const isoLogDate = logDate.toISOString();

    // Decrement Stock
    const newQuantity = stock.quantity - 1;
    await StorageService.saveStock({ modelName: selectedTonerModel, quantity: newQuantity });

    // Check Notification
    checkLowStockAndNotify(selectedTonerModel, newQuantity);

    // Update Printer
    let printerDesc = "";

    if (selectedPrinterId && selectedPrinterId !== 'MANUAL') {
      const printer = printers.find(p => p.id === selectedPrinterId);
      if (printer) {
         printerDesc = `${printer.location} (${printer.floor})`;

         // Logic: Only update the printer's "Last Toner Date" if the entered date is NEWER than what is stored.
         // This allows backdating (entering past records) without messing up the current status.
         const isNewerDate = isoLogDate > printer.lastTonerDate;

         const updatedPrinter = {
            ...printer,
            lastTonerDate: isNewerDate ? isoLogDate : printer.lastTonerDate
         };
         await StorageService.updatePrinter(updatedPrinter);
      }
    }

    // Log
    const log: StockLog = {
      id: '',
      date: isoLogDate,
      type: 'OUT',
      tonerModel: selectedTonerModel,
      quantity: 1,
      printerId: selectedPrinterId === 'MANUAL' ? undefined : selectedPrinterId,
      description: (selectedPrinterId && selectedPrinterId !== 'MANUAL') ? `Yazıcıya Takıldı: ${printerDesc}` : `Stok Çıkışı: ${description}`,
      user: user.name
    };
    await StorageService.addLog(log);

    await refreshData();
    showMessage('success', `${selectedTonerModel} stoktan düşüldü.`);
    setSelectedPrinterId('');
    setSelectedTonerModel('');
    setActiveTab('LIST');
  };

  // Helper to auto-select toner when printer is selected
  const onPrinterSelect = (printerId: string) => {
    setSelectedPrinterId(printerId);
    const printer = printers.find(p => p.id === printerId);
    if (printer) {
      if (printer.compatibleToner) setSelectedTonerModel(printer.compatibleToner);
    }
  };

  // WhatsApp Order Generator
  const sendWhatsappOrder = (model: string) => {
     const text = `Merhaba, ${model} model toner stoğumuz kritik seviyenin altına düştü. Sipariş vermek istiyoruz.`;
     const url = `https://wa.me/${config.whatsappNumber}?text=${encodeURIComponent(text)}`;
     window.open(url, '_blank');
  };

  // Filter only OUT logs for the table
  const outputLogs = logs.filter(l => l.type === 'OUT');

  // Printer Status Helper
  const getPrinterStatusText = (status: string) => {
    switch(status) {
      case 'ACTIVE': return 'Aktif';
      case 'SPARE': return 'Yedekte';
      case 'MAINTENANCE': return 'Serviste';
      case 'BROKEN': return 'Arızalı';
      case 'SCRAPPED': return 'Hurda';
      default: return '';
    }
  };

  if (loading) {
    return <LoadingScreen message="Stok verileri güncelleniyor..." />;
  }

  return (
    <div className="space-y-6">
      {message && (
        <div className={`fixed top-4 right-4 p-4 rounded-lg shadow-xl text-white z-50 animate-bounce ${message.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
          {message.text}
        </div>
      )}

      <div className="flex space-x-2 bg-white dark:bg-slate-800 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 w-fit">
        <button 
          onClick={() => setActiveTab('LIST')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'LIST' ? 'bg-primary-900 text-white' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
        >
          Stok Listesi
        </button>
        <button 
          onClick={() => setActiveTab('IN')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'IN' ? 'bg-green-600 text-white' : 'text-green-700 dark:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20'}`}
        >
          <ArrowDown size={16} /> Stok Giriş
        </button>
        <button 
          onClick={() => setActiveTab('OUT')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'OUT' ? 'bg-orange-600 text-white' : 'text-orange-700 dark:text-orange-400 hover:bg-orange-50 dark:hover:bg-orange-900/20'}`}
        >
          <ArrowUp size={16} /> Toner Çıkış
        </button>
      </div>

      {activeTab === 'LIST' && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {stocks.map(stock => (
            <div key={stock.modelName} className="bg-white dark:bg-slate-800 p-6 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col items-center justify-center text-center relative group hover:border-primary-300 transition-colors">
              <h3 className="text-3xl font-bold text-slate-800 dark:text-white mb-1">{stock.quantity}</h3>
              <p className="text-slate-500 dark:text-slate-400 font-medium">Model: {stock.modelName}</p>

              {stock.quantity < 3 && (
                 <div className="mt-2 flex flex-col gap-2 w-full">
                    <span className="text-xs bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 px-2 py-1 rounded-full flex items-center justify-center gap-1 mx-auto">
                      <AlertTriangle size={12} /> Kritik
                    </span>
                    {config.whatsappNumber && (
                        <button 
                          onClick={() => sendWhatsappOrder(stock.modelName)}
                          className="text-xs bg-green-500 text-white px-2 py-1.5 rounded-lg flex items-center justify-center gap-1 hover:bg-green-600"
                        >
                            <MessageCircle size={12} /> Sipariş Ver
                        </button>
                    )}
                 </div>
              )}
            </div>
          ))}
          {stocks.length === 0 && (
            <div className="col-span-full p-8 text-center text-slate-400">Henüz stok kaydı yok.</div>
          )}
        </div>
      )}

      {activeTab === 'IN' && (
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 max-w-lg">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
            <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg text-green-700 dark:text-green-400"><ArrowDown size={20}/></div>
            Stok Girişi Yap
          </h3>
          <form onSubmit={handleStockIn} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Toner/Mürekkep Modeli</label>
              <div className="relative">
                 <select 
                    required
                    className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white appearance-none"
                    value={newStockModel}
                    onChange={e => setNewStockModel(e.target.value)}
                 >
                    <option value="">Listeden Seçiniz</option>
                    {config.tonerModels?.map(s => <option key={s} value={s}>{s}</option>)}
                 </select>
                 <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">▼</div>
              </div>
              <p className="text-xs text-slate-400 mt-2 flex items-center gap-1">
                <SettingsIcon size={12} /> Listede olmayan modelleri "Ayarlar" sayfasından ekleyebilirsiniz.
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Adet</label>
              <div className="flex items-center gap-4">
                <button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">-</button>
                <input 
                  type="number" 
                  min="1"
                  required
                  className="w-full text-center p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none font-bold text-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={quantity}
                  onChange={e => setQuantity(parseInt(e.target.value) || 1)}
                />
                <button type="button" onClick={() => setQuantity(quantity + 1)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-lg font-bold text-slate-700 dark:text-white">+</button>
              </div>
            </div>

             <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                 Toplam Maliyet (TL) 
                 <span className="text-xs font-normal text-slate-400 ml-1">(Ücretsizse 0 giriniz)</span>
              </label>
              <div className="relative">
                 <Banknote className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input 
                   type="number" 
                   min="0"
                   className="w-full pl-10 p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-green-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   value={cost}
                   onChange={e => setCost(parseFloat(e.target.value) || 0)}
                 />
              </div>
            </div>

            <button type="submit" className="w-full py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200 dark:shadow-none">
              Stok Ekle
            </button>
          </form>
        </div>
      )}

      {activeTab === 'OUT' && (
        <div className="flex flex-col lg:flex-row gap-6">
          <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 w-full lg:w-1/2">
             <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
              <div className="p-2 bg-orange-100 dark:bg-orange-900/30 rounded-lg text-orange-700 dark:text-orange-400"><ArrowUp size={20}/></div>
              Toner Çıkışı (Değişim)
            </h3>
            <form onSubmit={handleStockOut} className="space-y-5">

              {/* DATE SELECTOR */}
              <div>
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">İşlem Tarihi</label>
                 <div className="relative cursor-pointer" onClick={() => (document.getElementById('date-picker') as HTMLInputElement)?.showPicker()}>
                     <Calendar size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                     <input 
                        id="date-picker"
                        type="date" 
                        required
                        className="w-full pl-10 p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white cursor-pointer"
                        value={customDate}
                        onChange={e => setCustomDate(e.target.value)}
                        onClick={(e) => e.currentTarget.showPicker()}
                     />
                 </div>
                 <p className="text-[10px] text-slate-400 mt-1 ml-1">Kutunun herhangi bir yerine tıklayarak takvimi açabilirsiniz.</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Hangi Yazıcıya?</label>
                <select 
                  className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={selectedPrinterId}
                  onChange={(e) => onPrinterSelect(e.target.value)}
                >
                  <option value="">-- Yazıcı Seçiniz --</option>
                  {printers.map(p => (
                    <option key={p.id} value={p.id}>
                      {p.location} ({p.model}) - {getPrinterStatusText(p.status)}
                    </option>
                  ))}
                  <option value="MANUAL">Listede Yok / Manuel Çıkış</option>
                </select>
              </div>

              {selectedPrinterId === 'MANUAL' && (
                 <div>
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Açıklama / Yer</label>
                 <input 
                   className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                   placeholder="Örn: 3. Kat Depo"
                   value={description}
                   onChange={e => setDescription(e.target.value)}
                   required
                 />
               </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Verilen Toner Modeli</label>
                <select 
                  required
                  className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  value={selectedTonerModel}
                  onChange={e => setSelectedTonerModel(e.target.value)}
                >
                  <option value="">-- Model Seçiniz --</option>
                  {stocks.map(s => (
                    <option key={s.modelName} value={s.modelName} disabled={s.quantity <= 0}>
                      {s.modelName} (Stok: {s.quantity})
                    </option>
                  ))}
                </select>
              </div>

              <div className="p-4 bg-orange-50 dark:bg-orange-900/20 rounded-xl text-sm text-orange-800 dark:text-orange-200 border border-orange-100 dark:border-orange-800/30">
                <p>Onayladığınızda stoktan <strong>1 adet</strong> düşülecektir.</p>
                {selectedPrinterId && selectedPrinterId !== 'MANUAL' && (
                  <p className="mt-1">Cihazın "Son Toner Tarihi" güncellenecektir.</p>
                )}
              </div>

