            className="w-full flex items-center space-x-3 px-4 py-2.5 text-zinc-400 hover:bg-zinc-800 hover:text-emerald-400 rounded-xl transition-colors"
          >
            {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
