export interface User {
  username: string;
  name: string;
  role: 'admin' | 'user';
  password?: string; // Added for internal DB storage
}

export type ConnectionType = 'USB' | 'Network';

export type PrinterStatus = 'ACTIVE' | 'MAINTENANCE' | 'BROKEN' | 'SCRAPPED' | 'SPARE';

export interface Printer {
  id: string;
  serialNumber: string;
  brand: string;   // e.g. "Canon", "HP"
  model: string;   // e.g. "3325i"
  location: string;
  floor: string;
  lastCounter: number;
  lastTonerDate: string;
  compatibleToner: string;
  connectionType: ConnectionType;
  ipAddress?: string; // Only if Network
  supplier: string; // e.g. "Anahtar Bilgisayar", "Enes Bilişim"
  status: PrinterStatus; // New Visual Status
  connectedUsers?: string[]; // New: List of users connected to this printer
}

export interface TonerStock {
  modelName: string;
  quantity: number;
}

export interface StockLog {
  id: string;
  date: string;
  type: 'IN' | 'OUT';
  tonerModel: string;
  quantity: number;
  description: string;
  printerId?: string;
  user: string;
  cost?: number; // Added for tracking Ink/Toner costs
  pageYield?: number; // New: How many pages printed with the previous toner?
}

export interface ServiceRecord {
  id: string;
  printerId: string;
  printerName: string; // Cache name for easier display
  date: string;
  issue: string; // Arıza tanımı
  actionTaken: string; // Yapılan işlem
  cost: number;
  provider: string; // Servis firması
  status: 'PENDING' | 'COMPLETED' | 'SCRAPPED'; // Bekliyor, Tamamlandı, Hurda
}

export interface SystemConfig {
  brands: string[];
  models: string[];
  suppliers: string[]; // List of vendors
  tonerModels: string[]; // New: List of toner types
  whatsappNumber?: string; // For notifications
  // New Image Maps (Key: Name, Value: Image URL)
  brandImages?: Record<string, string>; 
  modelImages?: Record<string, string>;
}

import { db } from './firebase';
import { collection, getDocs, addDoc, updateDoc, deleteDoc, doc, setDoc, query, orderBy, getDoc } from 'firebase/firestore';
import { Printer, TonerStock, StockLog, SystemConfig, ServiceRecord, User } from '../types';

const COLLECTIONS = {
  PRINTERS: 'printers',
  STOCKS: 'stocks',
  LOGS: 'logs',
  CONFIG: 'config',
  SERVICES: 'services',
  USERS: 'users'
};

const INITIAL_CONFIG: SystemConfig = {
  brands: ['Canon', 'HP', 'Kyocera', 'Xerox', 'Epson'],
  models: ['MF416dw', 'iF1643', 'LBP 251DW', '3325i', 'L3210', 'L1210', 'P2035', 'LBP 6030'],
  suppliers: ['Anahtar Bilgisayar', 'Enes Bilişim', 'Kendi Malımız'],
  tonerModels: ['1643', '505', '259x'],
  whatsappNumber: '',
  brandImages: {},
  modelImages: {}
};

// Helper to handle Firestore errors
const handleDbError = (error: any, context: string) => {
  console.error(`Error in ${context}:`, error);
  if (error.code === 'permission-denied') {
    alert('HATA: Veritabanı yazma izni reddedildi!\n\nFirebase Console > Firestore Database > Rules sekmesinden "allow read, write: if true;" ayarını yaptığınızdan emin olun.');
  } else {
    alert(`İşlem sırasında hata oluştu: ${error.message}`);
  }
  throw error;
};

export const StorageService = {

  // --- AUTH ---
  getUsers: async (): Promise<User[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.USERS));
      const users = snapshot.docs.map(doc => ({ ...doc.data() as any } as User));

      // If no users exist (first run), create admin
      if (users.length === 0) {
        const defaultAdmin: User = { username: 'admin', name: 'Sistem Yöneticisi', role: 'admin', password: 'yasam' }; 
        await addDoc(collection(db, COLLECTIONS.USERS), defaultAdmin).catch(e => handleDbError(e, 'createDefaultUser'));
        return [defaultAdmin];
      }
      return users;
    } catch (error) {
      console.error("Error fetching users:", error);
      return [];
    }
  },

  login: async (username: string, password: string): Promise<User | null> => {
    const users = await StorageService.getUsers();
    const user = users.find(u => u.username.toLowerCase() === username.toLowerCase() && u.password === password);
    if (user) {
      const { password, ...safeUser } = user;
      return safeUser as User;
    }
    return null;
  },

  // --- PRINTERS ---
  getPrinters: async (): Promise<Printer[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.PRINTERS));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Printer));
    } catch (e) {
      console.error("Error getPrinters", e);
      return [];
    }
  },

  addPrinter: async (printer: Printer) => {
    try {
      const { id, ...data } = printer; 
      const docRef = await addDoc(collection(db, COLLECTIONS.PRINTERS), data);
      return docRef.id;
    } catch (e) {
      handleDbError(e, 'addPrinter');
      return '';
    }
  },

  updatePrinter: async (printer: Printer) => {
    if (!printer.id) return;
    try {
      const printerRef = doc(db, COLLECTIONS.PRINTERS, printer.id);
      const { id, ...data } = printer;
      await updateDoc(printerRef, data);
    } catch (e) {
      handleDbError(e, 'updatePrinter');
    }
  },

  deletePrinter: async (printerId: string) => {
    try {
      await deleteDoc(doc(db, COLLECTIONS.PRINTERS, printerId));
    } catch (e) {
      handleDbError(e, 'deletePrinter');
    }
  },

  // --- STOCKS ---
  getStocks: async (): Promise<TonerStock[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.STOCKS));
      return snapshot.docs.map(doc => ({ ...doc.data() as any } as TonerStock));
    } catch (e) {
      console.error("Error getStocks", e);
      return [];
    }
  },

  saveStock: async (stock: TonerStock) => {
    try {
      const q = query(collection(db, COLLECTIONS.STOCKS));
      const snapshot = await getDocs(q);
      const existingDoc = snapshot.docs.find(d => (d.data() as TonerStock).modelName === stock.modelName);

      if (existingDoc) {
        await updateDoc(doc(db, COLLECTIONS.STOCKS, existingDoc.id), { quantity: stock.quantity });
      } else {
        await addDoc(collection(db, COLLECTIONS.STOCKS), stock);
      }
    } catch (e) {
      handleDbError(e, 'saveStock');
    }
  },

  // --- LOGS ---
  getLogs: async (): Promise<StockLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.LOGS), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as StockLog));
    } catch (e) {
      console.error("Error getLogs", e);
      return [];
    }
  },

  addLog: async (log: StockLog) => {
    try {
      const { id, ...data } = log;
      await addDoc(collection(db, COLLECTIONS.LOGS), data);
    } catch (e) {
      handleDbError(e, 'addLog');
    }
  },

  // --- SERVICES ---
  getServiceRecords: async (): Promise<ServiceRecord[]> => {
     try {
      const q = query(collection(db, COLLECTIONS.SERVICES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ServiceRecord));
     } catch (e) {
       return [];
     }
  },

  addServiceRecord: async (record: ServiceRecord) => {
    try {
      const { id, ...data } = record;
      await addDoc(collection(db, COLLECTIONS.SERVICES), data);
    } catch (e) {
      handleDbError(e, 'addServiceRecord');
    }
  },

  // --- CONFIG ---
  getConfig: async (): Promise<SystemConfig> => {
    try {
      const docRef = doc(db, COLLECTIONS.CONFIG, 'main_config');
      const docSnap = await getDoc(docRef);

      if (docSnap.exists()) {
        const data = docSnap.data() as SystemConfig;
        // Merge with initial defaults to ensure new fields exist
        return { ...INITIAL_CONFIG, ...data };
      } else {
        await setDoc(docRef, INITIAL_CONFIG);
        return INITIAL_CONFIG;
      }
    } catch (e) {
      return INITIAL_CONFIG;
    }
  },

  saveConfig: async (config: SystemConfig) => {
    try {
      const docRef = doc(db, COLLECTIONS.CONFIG, 'main_config');
      await setDoc(docRef, config);
    } catch (e) {
      handleDbError(e, 'saveConfig');
    }
  },

  runMaintenance: async () => {
     await StorageService.getConfig();
  }
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Tag, Box, MessageCircle, Truck, RefreshCw, Edit2, X, AlertTriangle, Droplet, Database, CheckCircle2, Loader2, ArrowRight, Image as ImageIcon, Link as LinkIcon } from 'lucide-react';
import { StorageService } from '../services/storage';
import { SystemConfig, Printer } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { INITIAL_PRINTER_DATA } from './Settings'; // Self-reference for data is circular, but usually fine in this structure, correcting below

type ConfigType = 'brands' | 'models' | 'suppliers' | 'tonerModels';

export const Settings: React.FC = () => {
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [loading, setLoading] = useState(true);

  // Import States
  const [showImportConfirm, setShowImportConfirm] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);

  // Input States
  const [newBrand, setNewBrand] = useState('');
  const [newBrandImage, setNewBrandImage] = useState('');

  const [newModel, setNewModel] = useState('');
  const [newModelImage, setNewModelImage] = useState('');

  const [newSupplier, setNewSupplier] = useState('');
  const [newTonerModel, setNewTonerModel] = useState('');
  const [whatsappNumber, setWhatsappNumber] = useState('');

  // Modal States
  // Extended edit modal to handle image URLs
  const [editModal, setEditModal] = useState<{ type: ConfigType, oldVal: string, newVal: string, newImage?: string } | null>(null);
  const [deleteModal, setDeleteModal] = useState<{ type: ConfigType, val: string } | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  // --- ESC KEY LISTENER ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (editModal) setEditModal(null);
        if (deleteModal) setDeleteModal(null);
        if (showImportConfirm) setShowImportConfirm(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [editModal, deleteModal, showImportConfirm]);

  const loadData = async () => {
    setLoading(true);
    const c = await StorageService.getConfig();
    const p = await StorageService.getPrinters();
    setConfig(c);
    setWhatsappNumber(c.whatsappNumber || '');
    setPrinters(p);
    setLoading(false);
  };

  // --- BULK IMPORT ---
  const handleInitialImport = async () => {
    setShowImportConfirm(false);
    setIsImporting(true);
    setImportProgress(0);

    try {
        let count = 0;
        for (const item of INITIAL_PRINTER_DATA) {
            const isUsb = item.ip === 'USB' || item.ip === '-' || item.ip === '' || item.ip === null;
            const connectionType = isUsb ? 'USB' : 'Network';
            let ipAddress = '';
            if (!isUsb) {
                ipAddress = item.ip.length <= 3 ? `192.168.1.${item.ip}` : item.ip;
            }

            const newPrinter: Printer = {
                id: '',
                serialNumber: item.s,
                brand: 'Canon',
                model: item.m,
                location: item.l,
                floor: 'Giriş/Poliklinik',
                lastCounter: 0,
                lastTonerDate: new Date().toISOString(),
                compatibleToner: '',
                connectionType,
                ipAddress,
                supplier: 'Anahtar Bilgisayar',
                status: 'ACTIVE',
                connectedUsers: []
            };
            await StorageService.addPrinter(newPrinter);
            count++;
            setImportProgress(count);
            await new Promise(resolve => setTimeout(resolve, 50));
        }
        await loadData();
        alert(`İŞLEM BAŞARILI!\nToplam ${count} adet yazıcı sisteme kaydedildi.`);
    } catch (e) {
        console.error("IMPORT ERROR:", e);
        alert('İçe aktarma sırasında bir hata oluştu. Veritabanı bağlantınızı kontrol edin.');
    } finally {
        setIsImporting(false);
    }
  };

  // --- ACTIONS ---

  // 1. ADD ITEM (Generic + Image Support)
  const handleAddItem = async (e: React.FormEvent, type: ConfigType, value: string, setter: (s: string) => void, imageValue?: string, imageSetter?: (s: string) => void) => {
    e.preventDefault();
    const val = value.trim();
    if (val && !config[type].includes(val)) {
      let updated = { ...config, [type]: [...config[type], val] };

      // Save Image if provided and applicable
      if (imageValue && (type === 'brands' || type === 'models')) {
         const imgMapKey = type === 'brands' ? 'brandImages' : 'modelImages';
         updated = {
            ...updated,
            [imgMapKey]: {
                ...(updated[imgMapKey as keyof SystemConfig] as Record<string, string>),
                [val]: imageValue.trim()
            }
         }
      }

      await StorageService.saveConfig(updated);
      setConfig(updated);
      setter('');
      if (imageSetter) imageSetter('');
    }
  };

  // 2. OPEN EDIT MODAL
  const openEdit = (type: ConfigType, oldVal: string) => {
    let currentImage = '';
    if (type === 'brands') currentImage = config.brandImages?.[oldVal] || '';
    if (type === 'models') currentImage = config.modelImages?.[oldVal] || '';

    setEditModal({ type, oldVal, newVal: oldVal, newImage: currentImage });
  };

  // 3. PERFORM UPDATE (Cascading Rename + Image Update)
  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editModal || !editModal.newVal.trim()) return;

    const { type, oldVal, newVal, newImage } = editModal;
    const trimmedNewVal = newVal.trim();

    // 1. Update Config List
    const currentList = config[type];
    const updatedList = currentList.map(item => item === oldVal ? trimmedNewVal : item);

    let updatedConfig = { ...config, [type]: updatedList };

    // 2. Update Image Maps (If applicable)
    if (type === 'brands' || type === 'models') {
        const mapKey = type === 'brands' ? 'brandImages' : 'modelImages';
        const currentMap = { ...(updatedConfig[mapKey] || {}) };

        // Remove old key if name changed
        if (oldVal !== trimmedNewVal) {
             delete currentMap[oldVal];
        }
        // Set new key with new image (or empty if cleared)
        if (newImage) {
            currentMap[trimmedNewVal] = newImage.trim();
        } else {
             delete currentMap[trimmedNewVal]; // Remove if empty
        }

        updatedConfig = { ...updatedConfig, [mapKey]: currentMap };
    }

    await StorageService.saveConfig(updatedConfig);
    setConfig(updatedConfig);

    // 3. Cascade Update to Printers (only for renaming)
    if (oldVal !== trimmedNewVal) {
        let printersUpdated = false;
        for (const p of printers) {
            let changed = false;
            let newP = { ...p };

            if (type === 'brands' && p.brand === oldVal) { newP.brand = trimmedNewVal; changed = true; }
            if (type === 'models' && p.model === oldVal) { newP.model = trimmedNewVal; changed = true; }
            if (type === 'suppliers' && p.supplier === oldVal) { newP.supplier = trimmedNewVal; changed = true; }
            if (type === 'tonerModels' && p.compatibleToner === oldVal) { newP.compatibleToner = trimmedNewVal; changed = true; }

            if (changed) {
                await StorageService.updatePrinter(newP);
                printersUpdated = true;
            }
        }

        if (printersUpdated) {
            const updatedPrinters = await StorageService.getPrinters();
            setPrinters(updatedPrinters);
        }
    }

    setEditModal(null);
  };

  // 4. OPEN DELETE MODAL
  const openDelete = (type: ConfigType, val: string) => {
    setDeleteModal({ type, val });
  };

  // 5. PERFORM DELETE
  const handleDelete = async () => {
    if (!deleteModal) return;
    const { type, val } = deleteModal;

    const currentList = config[type];
    const updatedList = currentList.filter(item => item !== val);
    let updatedConfig = { ...config, [type]: updatedList };

    // Also cleanup images
    if (type === 'brands' && updatedConfig.brandImages) {
        const newImages = {...updatedConfig.brandImages};
        delete newImages[val];
        updatedConfig.brandImages = newImages;
    }
    if (type === 'models' && updatedConfig.modelImages) {
        const newImages = {...updatedConfig.modelImages};
        delete newImages[val];
        updatedConfig.modelImages = newImages;
    }

    await StorageService.saveConfig(updatedConfig);
    setConfig(updatedConfig);
    setDeleteModal(null);
  };

  const handleSaveWhatsapp = async () => {
    const updatedConfig = { ...config, whatsappNumber: whatsappNumber };
    await StorageService.saveConfig(updatedConfig);
    setConfig(updatedConfig);
    alert('Numara kaydedildi.');
  };

  const manualMaintenance = async () => {
    setLoading(true);
    await loadData();
    alert('Veritabanı senkronize edildi.');
    setLoading(false);
  };

  // Helper to render list items with images
  const renderList = (type: ConfigType, items: string[]) => (
    <div className="space-y-2 max-h-64 overflow-y-auto pr-1 custom-scrollbar">
      {items.map((item, idx) => {
         let imgUrl = null;
         if (type === 'brands') imgUrl = config.brandImages?.[item];
         if (type === 'models') imgUrl = config.modelImages?.[item];

         return (
            <div key={`${item}-${idx}`} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700 rounded-xl border border-slate-100 dark:border-slate-600 group hover:shadow-sm transition-all">
            <div className="flex items-center gap-3">
                {/* Image Preview */}
                {(type === 'brands' || type === 'models') && (
                    <div className="w-10 h-10 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 flex items-center justify-center overflow-hidden shrink-0">
                        {imgUrl ? (
                            <img src={imgUrl} alt={item} className="w-full h-full object-contain p-1" />
                        ) : (
                            <ImageIcon size={16} className="text-slate-300 dark:text-slate-600" />
                        )}
                    </div>
                )}
                <span className="font-medium text-slate-700 dark:text-slate-200">{item}</span>
            </div>

            <div className="flex gap-2">
                <button 
                type="button" 
                onClick={() => openEdit(type, item)}
                className="p-2 bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900/50 transition-colors"
                title="Düzenle"
                >
                <Edit2 size={16} />
                </button>
                <button 
                type="button" 
                onClick={() => openDelete(type, item)}
                className="p-2 bg-red-50 text-red-600 dark:bg-red-900/30 dark:text-red-400 rounded-lg hover:bg-red-100 dark:hover:bg-red-900/50 transition-colors"
                title="Sil"
                >
                <Trash2 size={16} />
                </button>
            </div>
            </div>
         );
      })}
      {items.length === 0 && <p className="text-slate-400 text-sm text-center py-4">Liste boş.</p>}
    </div>
  );

  if (loading) return <LoadingScreen message="Sistem ayarları yükleniyor..." />;

  return (
    <div className="space-y-6 pb-20">
      <div className="flex justify-between items-center bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700">
        <h2 className="text-2xl font-bold text-slate-800 dark:text-white flex items-center gap-2">
          <Save size={24} className="text-primary-600 dark:text-primary-400" />
          Sistem Ayarları
        </h2>
        <div className="flex gap-2">
            <button 
            onClick={manualMaintenance}
            className="text-xs bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 text-slate-600 dark:text-slate-300 px-3 py-2 rounded-lg flex items-center gap-1 transition-colors"
            >
            <RefreshCw size={14} /> Senkronize Et
            </button>
        </div>
      </div>

      {/* V1 Import Tool */}
      <div className="bg-gradient-to-r from-zinc-900 to-zinc-800 p-6 rounded-xl shadow-lg border border-zinc-700 relative overflow-hidden">
         <div className="relative z-10">
