                                <div className="flex items-center gap-1.5 mt-2 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 px-2 py-1 rounded text-xs w-fit">
                                    <Users size={12} />
                                    <span>{printer.connectedUsers.length} Kullanıcı Bağlı</span>
                                </div>
                            )}
