    if (newVal < printer.lastCounter) {
        if (!confirm(`UYARI: Girdiğiniz sayaç (${newVal}), eski sayaçtan (${printer.lastCounter}) daha düşük. Yine de kaydetmek istiyor musunuz?`)) {
            return;
        }
