      const lines = text.split(/\r\n|\n|\r/);

      if (lines.length < 2) {
          setImportError("Dosya içeriği çok kısa veya boş.");
          return;
      }

      // 1. Find the Header Row (Canon reports often have metadata in first few lines)
      // We look for a line containing "Serial" or "Seri"
      let headerRowIndex = -1;
      let delimiter = ','; // Default

      for (let i = 0; i < Math.min(lines.length, 20); i++) {
          const line = lines[i].toLowerCase();
          if (line.includes('serial') || line.includes('seri')) {
              headerRowIndex = i;
              // Detect delimiter based on occurrence count
              const semicolonCount = (line.match(/;/g) || []).length;
              const commaCount = (line.match(/,/g) || []).length;
              delimiter = semicolonCount > commaCount ? ';' : ',';
