import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Printer as PrinterIcon, QrCode, ArrowRight, CheckCircle2, AlertCircle } from 'lucide-react';

export const QrManagement: React.FC = () => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [loading, setLoading] = useState(true);
  const [isPrintMode, setIsPrintMode] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  // Escape key to exit print mode
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isPrintMode) {
        setIsPrintMode(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPrintMode]);

  const loadData = async () => {
    setLoading(true);
    const p = await StorageService.getPrinters();
    setPrinters(p);
    setLoading(false);
  };

  // Helper to split array into chunks of 20
  const chunkArray = (arr: any[], size: number) => {
    const results = [];
    while (arr.length) {
        results.push(arr.splice(0, size));
    }
    return results;
  };

  if (loading) return <LoadingScreen message="Cihaz listesi hazırlanıyor..." />;

  // --- PRINT MODE VIEW (OVERLAY) ---
  if (isPrintMode) {
    // Create a copy to not mutate state during splice
    const pages = chunkArray([...printers], 20); 

    return (
      <div className="fixed inset-0 z-[100] bg-zinc-100 overflow-auto text-black">
          {/* Control Bar (Hidden when printing) */}
          <div className="sticky top-0 left-0 right-0 bg-zinc-900 text-white p-4 shadow-lg flex justify-between items-center print:hidden z-50">
              <div>
                  <h2 className="text-xl font-bold flex items-center gap-2"><QrCode /> Önizleme Modu</h2>
                  <p className="text-sm text-zinc-400">Toplam {printers.length} etiket. {pages.length} Sayfa.</p>
              </div>
              <div className="flex gap-3">
                  <button 
                      onClick={() => window.print()} 
                      className="bg-emerald-600 hover:bg-emerald-500 text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2"
                  >
                      <PrinterIcon size={20} /> Yazdır (PDF)
                  </button>
                  <button 
                      onClick={() => setIsPrintMode(false)} 
                      className="bg-zinc-700 hover:bg-zinc-600 text-white px-6 py-2 rounded-lg font-bold"
                  >
                      Kapat (ESC)
                  </button>
              </div>
          </div>

          {/* A4 Pages Container */}
          <div className="flex flex-col items-center gap-8 p-8 print:p-0 print:gap-0">
              {pages.map((pagePrinters, pageIndex) => (
                  <div 
                      key={pageIndex} 
                      className="bg-white shadow-xl print:shadow-none w-[210mm] min-h-[297mm] p-[10mm] grid grid-cols-4 grid-rows-5 gap-2 content-start relative page-break-after-always"
                      style={{ pageBreakAfter: 'always' }}
                  >
                      {/* Page Content */}
                      {pagePrinters.map((p) => {
