import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Printer as PrinterIcon, QrCode, ArrowRight, CheckCircle2, AlertCircle, Download, Save } from 'lucide-react';

export const QrManagement: React.FC = () => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [loading, setLoading] = useState(true);
  const [isPrintMode, setIsPrintMode] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  // Escape key to exit print mode
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isPrintMode) {
        setIsPrintMode(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPrintMode]);

  const loadData = async () => {
    setLoading(true);
    const p = await StorageService.getPrinters();
    setPrinters(p);
    setLoading(false);
  };

  // Helper to split array into chunks of 20
  const chunkArray = (arr: any[], size: number) => {
    const results = [];
    while (arr.length) {
        results.push(arr.splice(0, size));
    }
    return results;
  };

  const handlePrint = () => {
    // Small delay to ensure DOM render before print dialog
    setTimeout(() => {
        window.print();
    }, 100);
  };

  if (loading) return <LoadingScreen message="Cihaz listesi hazırlanıyor..." />;

  // --- PRINT MODE VIEW (OVERLAY) ---
  if (isPrintMode) {
    // Create a copy to not mutate state during splice
    const pages = chunkArray([...printers], 20); 

    return (
      <div className="fixed inset-0 z-[100] bg-zinc-100 overflow-auto text-black custom-scrollbar">
          {/* Control Bar (Hidden when printing) */}
          <div className="sticky top-0 left-0 right-0 bg-zinc-900 text-white p-4 shadow-lg flex justify-between items-center print:hidden z-50">
              <div>
                  <h2 className="text-xl font-bold flex items-center gap-2"><QrCode /> Önizleme ve Baskı Modu</h2>
                  <p className="text-sm text-zinc-400">Toplam {printers.length} etiket. {pages.length} Sayfa.</p>
              </div>
              <div className="flex gap-3">
                  <button 
                      onClick={handlePrint} 
                      className="bg-emerald-600 hover:bg-emerald-500 text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 shadow-lg shadow-emerald-900/20 active:scale-95 transition-all"
                  >
                      <Save size={20} /> PDF Olarak Kaydet / Yazdır
                  </button>
                  <button 
                      onClick={() => setIsPrintMode(false)} 
                      className="bg-zinc-700 hover:bg-zinc-600 text-white px-6 py-2 rounded-lg font-bold transition-colors"
                  >
                      Kapat (ESC)
                  </button>
              </div>
          </div>

          {/* Printable Area Wrapper */}
          <div id="printable-area" className="flex flex-col items-center gap-8 p-8 print:p-0 print:gap-0 print:block">
              {pages.map((pagePrinters, pageIndex) => (
                  <div 
                      key={pageIndex} 
                      className="bg-white shadow-xl print:shadow-none w-[210mm] min-h-[297mm] p-[10mm] grid grid-cols-4 grid-rows-5 gap-2 content-start relative page-break-after-always mx-auto"
                      style={{ pageBreakAfter: 'always' }}
                  >
                      {/* Page Content */}
                      {pagePrinters.map((p) => {
                         const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(window.location.origin + window.location.pathname + '?pid=' + p.id)}`;

                         return (
                             <div key={p.id} className="border border-zinc-900 p-2 flex flex-col items-center justify-between text-center h-[52mm] overflow-hidden relative">
                                  {/* Crop Marks (Visual only) */}
                                  <div className="absolute top-0 left-0 w-2 h-2 border-l border-t border-black/20"></div>
                                  <div className="absolute top-0 right-0 w-2 h-2 border-r border-t border-black/20"></div>
                                  <div className="absolute bottom-0 left-0 w-2 h-2 border-l border-b border-black/20"></div>
                                  <div className="absolute bottom-0 right-0 w-2 h-2 border-r border-b border-black/20"></div>

                                  <div className="w-full flex justify-center pt-1">
                                      <img src={qrUrl} alt="QR" className="w-[32mm] h-[32mm] object-contain" />
                                  </div>

                                  <div className="w-full pb-1">
                                      <p className="font-bold text-[10px] uppercase leading-tight truncate px-1 text-black">
                                          {p.brand} {p.model}
                                      </p>
                                      <p className="text-[9px] font-semibold leading-tight mt-0.5 truncate bg-black text-white px-1 mx-2 rounded-sm print-color-adjust">
                                          {p.location}
                                      </p>
                                      <p className="text-[7px] text-zinc-500 mt-0.5 font-mono">{p.serialNumber}</p>
                                  </div>
                             </div>
                         )
                      })}
                  </div>
              ))}
          </div>

          {/* Critical Print Styles */}
          <style>{`
              @media print {
                  @page { 
                      size: A4; 
                      margin: 0; 
                  }
                  body { 
                      visibility: hidden; 
                      background: white;
                  }
                  /* Hide everything by default */
                  body * {
                      visibility: hidden;
                  }
                  /* Only show our printable area and its children */
                  #printable-area, #printable-area * {
                      visibility: visible;
                  }
                  /* Position the printable area absolutely to top left */
                  #printable-area {
                      position: absolute;
                      left: 0;
                      top: 0;
                      width: 100%;
                      margin: 0;
                      padding: 0;
                  }
                  .print\\:hidden { display: none !important; }
                  .page-break-after-always { page-break-after: always !important; }
                  /* Ensure background colors print (for the black pill) */
                  .print-color-adjust {
                      -webkit-print-color-adjust: exact;
                      print-color-adjust: exact;
                  }
              }
          `}</style>
      </div>
    );
  }

  // --- DASHBOARD VIEW ---
  return (
    <div className="space-y-6">
      <div className="bg-white dark:bg-zinc-900 p-6 rounded-2xl shadow-sm border border-zinc-200 dark:border-zinc-800">
        <h2 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2 mb-2">
           <QrCode size={28} className="text-emerald-500" />
