                  >
                      <option value="">Seçiniz</option>
                      {config.tonerModels?.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
               </div>

               <div>
                  <label className="block text-sm font-semibold text-zinc-700 dark:text-zinc-300 mb-2">Tedarikçi / Servis</label>
                  <select 
                      className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white"
                      value={formData.supplier} 
                      onChange={e => setFormData({...formData, supplier: e.target.value})}
                  >
                      <option value="">Seçiniz</option>
                      {config.suppliers.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
               </div>

               <div>
                 <label className="block text-sm font-semibold text-zinc-700 dark:text-zinc-300 mb-2">Durum</label>
                 <select 
                      className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white"
                      value={formData.status} 
                      onChange={e => setFormData({...formData, status: e.target.value as PrinterStatus})}
                  >
                      <option value="ACTIVE">Aktif</option>
                      <option value="SPARE">Yedekte</option>
                      <option value="MAINTENANCE">Serviste/Bakımda</option>
                      <option value="BROKEN">Arızalı</option>
                      <option value="SCRAPPED">Hurda</option>
                  </select>
               </div>

               <div>
                 <label className="block text-sm font-semibold text-zinc-700 dark:text-zinc-300 mb-2">Bağlı Kullanıcılar (Virgülle ayırın)</label>
                 <textarea 
                    rows={2}
                    className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white"
                    placeholder="Ali Yılmaz, Ayşe Demir..."
                    value={connectedUsersInput}
                    onChange={e => setConnectedUsersInput(e.target.value)}
                 />
               </div>

               <div className="pt-4 flex gap-3">
                <button type="button" onClick={closeModalViaBack} className="flex-1 py-4 bg-zinc-100 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-200 rounded-xl hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors font-semibold">İptal</button>
                <button type="submit" className="flex-1 py-4 bg-gradient-to-r from-emerald-600 to-teal-600 text-white rounded-xl hover:from-emerald-500 hover:to-teal-500 transition-colors font-bold shadow-lg shadow-emerald-500/20">
                  Kaydet
                </button>
              </div>
            </form>
          </div>
        </div>
       )}

       {/* HISTORY MODAL WITH STATS & CONFIRMATION OVERLAY */}
       {isHistoryModalOpen && selectedPrinterHistory && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-zinc-900 rounded-2xl w-full max-w-2xl shadow-2xl flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-200 relative overflow-hidden">

            {/* === STOCK CONFIRMATION OVERLAY === */}
            {showStockConfirmation && (
                <div className="absolute inset-0 z-[60] bg-white/95 dark:bg-zinc-900/95 flex items-center justify-center p-6 animate-in fade-in slide-in-from-bottom-4">
                    <div className="w-full max-w-sm text-center">
                        <div className="w-20 h-20 bg-orange-100 dark:bg-orange-900/30 text-orange-600 rounded-full flex items-center justify-center mx-auto mb-6 animate-pulse">
                            <AlertTriangle size={40} />
                        </div>
                        <h3 className="text-2xl font-bold text-zinc-800 dark:text-white mb-2">Emin misiniz?</h3>
                        <p className="text-zinc-500 dark:text-zinc-400 mb-6 text-sm leading-relaxed">
                            <strong>{selectedPrinterHistory.printer.compatibleToner}</strong> model toner stoktan düşülecek ve
                            bu cihazın son toner tarihi güncellenecek.
                        </p>

                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={handleFinalizeStockOut}
                                disabled={isProcessingStock}
                                className="w-full py-4 bg-orange-600 hover:bg-orange-700 text-white rounded-xl font-bold shadow-lg shadow-orange-500/30 flex items-center justify-center gap-2 transition-all active:scale-95"
                            >
                                {isProcessingStock ? (
                                    <>
                                        <Loader2 size={20} className="animate-spin"/> İşleniyor...
                                    </>
                                ) : (
                                    <>
                                        <ArrowUp size={20}/> Evet, Stok Düş
                                    </>
                                )}
                            </button>
                            <button 
                                onClick={() => setShowStockConfirmation(false)}
                                disabled={isProcessingStock}
                                className="w-full py-4 bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-300 rounded-xl font-bold hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors"
                            >
                                Vazgeç
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal Header */}
            <div className="p-6 border-b border-zinc-100 dark:border-zinc-800 flex justify-between items-start bg-zinc-50 dark:bg-zinc-900 rounded-t-2xl">
              <div>
                <h3 className="text-xl font-bold text-zinc-800 dark:text-white">{selectedPrinterHistory.printer.brand} {selectedPrinterHistory.printer.model}</h3>
                <p className="text-zinc-500 dark:text-zinc-400 text-sm mt-1 mb-2">{selectedPrinterHistory.printer.location} - {selectedPrinterHistory.printer.serialNumber}</p>

                {/* --- QUICK STATUS CHANGER --- */}
                <div className="flex items-center gap-2 mt-2">
                    <span className="text-xs font-bold text-zinc-400 uppercase tracking-wide flex items-center gap-1">
                        <Activity size={12}/> Durum:
                    </span>
                    <select
                        className={`text-xs font-bold uppercase rounded px-2 py-1 outline-none border-none cursor-pointer
                            ${selectedPrinterHistory.printer.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : ''}
                            ${selectedPrinterHistory.printer.status === 'SPARE' ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400' : ''}
                            ${selectedPrinterHistory.printer.status === 'MAINTENANCE' ? 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400' : ''}
                            ${selectedPrinterHistory.printer.status === 'BROKEN' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' : ''}
                            ${selectedPrinterHistory.printer.status === 'SCRAPPED' ? 'bg-zinc-200 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-400' : ''}
                        `}
                        value={selectedPrinterHistory.printer.status}
                        onChange={(e) => handleStatusChange(e.target.value as PrinterStatus)}
                    >
                        <option value="ACTIVE">🟢 Aktif</option>
                        <option value="SPARE">📦 Yedekte</option>
                        <option value="MAINTENANCE">🔧 Serviste</option>
                        <option value="BROKEN">⚠️ Arızalı</option>
                        <option value="SCRAPPED">❌ Hurda</option>
                    </select>
                </div>

              </div>
              <button onClick={closeModalViaBack} className="p-2 bg-white dark:bg-zinc-800 rounded-full shadow-sm hover:bg-zinc-100 dark:hover:bg-zinc-700"><X size={20} className="text-zinc-500"/></button>
            </div>

            <div className="overflow-y-auto p-6 space-y-8 custom-scrollbar">

                {/* --- QUICK ACTION: TONER OUT --- */}
                <div className="bg-gradient-to-r from-orange-500 to-red-500 p-4 rounded-xl flex items-center justify-between text-white shadow-lg shadow-orange-500/20">
                    <div>
                        <h4 className="font-bold text-lg flex items-center gap-2"><ArrowUp size={20} className="text-white"/> Hızlı İşlem</h4>
                        <p className="text-orange-100 text-sm">
                             {selectedPrinterHistory.printer.compatibleToner ? 
                                `${selectedPrinterHistory.printer.compatibleToner} toneri stoktan düş.` : 
                                'Uyumlu toner tanımlı değil.'}
                        </p>
                    </div>
                    <button 
                        onClick={handleInitiateQuickStockOut}
                        className="bg-white text-orange-600 px-4 py-2 rounded-lg font-bold hover:bg-orange-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                        disabled={!selectedPrinterHistory.printer.compatibleToner}
                    >
                        Hızlı Stok Düş
                    </button>
                </div>

                {/* 1. SCORECARD (STATS) */}
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                    <div className="bg-gradient-to-br from-emerald-50 to-teal-50 dark:from-emerald-900/20 dark:to-teal-900/20 p-4 rounded-xl border border-emerald-100 dark:border-emerald-800/30">
                        <p className="text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                            <Wallet size={12}/> Toplam Harcama
                        </p>
                        <p className="text-2xl font-bold text-zinc-800 dark:text-white">{selectedPrinterHistory.stats.totalSpent.toLocaleString()} ₺</p>
                    </div>
                    <div className="bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 p-4 rounded-xl border border-blue-100 dark:border-blue-800/30">
                        <p className="text-xs font-bold text-blue-600 dark:text-blue-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                            <Calendar size={12}/> Ort. Toner Ömrü
                        </p>
                        <p className="text-2xl font-bold text-zinc-800 dark:text-white">
                            {typeof selectedPrinterHistory.stats.avgTonerDays === 'number' ? `${selectedPrinterHistory.stats.avgTonerDays} Gün` : '-'}
                        </p>
                    </div>
                    <div className="bg-gradient-to-br from-orange-50 to-amber-50 dark:from-orange-900/20 dark:to-amber-900/20 p-4 rounded-xl border border-orange-100 dark:border-orange-800/30">
                        <p className="text-xs font-bold text-orange-600 dark:text-orange-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                            <Truck size={12}/> Servis Kaydı
                        </p>
                        <p className="text-2xl font-bold text-zinc-800 dark:text-white">{selectedPrinterHistory.stats.totalServiceCount} Kez</p>
                    </div>
                </div>

                {/* 2. TONER HISTORY */}
                <div>
                  <h4 className="font-bold text-zinc-800 dark:text-white mb-4 flex items-center gap-2">
                    <History size={18} className="text-emerald-500"/> Toner Geçmişi
                  </h4>
                  <div className="space-y-3">
                    {selectedPrinterHistory.tonerLogs.length === 0 && <p className="text-zinc-400 text-sm">Toner değişim kaydı yok.</p>}
                    {selectedPrinterHistory.tonerLogs.map(log => (
                      <div key={log.id} className="flex justify-between items-center p-3 bg-zinc-50 dark:bg-zinc-800/50 rounded-xl border border-zinc-100 dark:border-zinc-800">
                        <div>
                          <p className="font-semibold text-zinc-700 dark:text-zinc-200">{log.tonerModel}</p>
                          <p className="text-xs text-zinc-500 dark:text-zinc-400">{new Date(log.date).toLocaleDateString('tr-TR')}</p>
                        </div>
                        <div className="text-right">
                           {log.type === 'OUT' && <span className="text-xs font-bold text-orange-500 bg-orange-100 dark:bg-orange-900/30 px-2 py-0.5 rounded">Değişim</span>}
                           <p className="text-xs text-zinc-400 mt-1">{log.user}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* 3. SERVICE HISTORY */}
                <div>
                   <h4 className="font-bold text-zinc-800 dark:text-white mb-4 flex items-center gap-2">
                    <Truck size={18} className="text-orange-500"/> Servis Geçmişi
                  </h4>
                   <div className="space-y-3">
                    {selectedPrinterHistory.serviceLogs.length === 0 && <p className="text-zinc-400 text-sm">Servis kaydı yok.</p>}
                    {selectedPrinterHistory.serviceLogs.map(srv => (
                      <div key={srv.id} className="p-3 bg-orange-50 dark:bg-orange-900/10 rounded-xl border border-orange-100 dark:border-orange-900/30">
                        <div className="flex justify-between items-start mb-1">
                           <span className="text-xs font-bold text-orange-700 dark:text-orange-400">{new Date(srv.date).toLocaleDateString('tr-TR')}</span>
                           <span className="text-xs font-bold text-zinc-500">{srv.cost > 0 ? `${srv.cost} ₺` : 'Ücretsiz'}</span>
                        </div>
                        <p className="text-sm font-semibold text-zinc-800 dark:text-zinc-200">{srv.issue}</p>
                        <p className="text-xs text-zinc-600 dark:text-zinc-400 mt-1">İşlem: {srv.actionTaken}</p>
                        <p className="text-left text-[10px] text-zinc-400 mt-2">{srv.provider}</p>
                      </div>
                    ))}
                   </div>
                </div>

            </div>
          </div>
        </div>
       )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, SystemConfig } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Box, MapPin, X, Search, CheckCircle2, AlertTriangle, Truck, Archive, XCircle, ChevronRight, Hash, Printer as PrinterIcon } from 'lucide-react';

interface ModelGroup {
  modelName: string;
  count: number;
  printers: Printer[];
}

export const Inventory: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [modelGroups, setModelGroups] = useState<ModelGroup[]>([]);
  const [config, setConfig] = useState<SystemConfig | null>(null);
  const [selectedModel, setSelectedModel] = useState<ModelGroup | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  // --- HISTORY / BACK BUTTON HANDLER ---
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
        if (selectedModel) {
            setSelectedModel(null);
        }
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedModel]);

  // Close modal on ESC
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && selectedModel) {
          window.history.back();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedModel]);

  const loadData = async () => {
    setLoading(true);
    const [allPrinters, sysConfig] = await Promise.all([
      StorageService.getPrinters(),
      StorageService.getConfig()
    ]);

    // Group by Model
    const groups: Record<string, Printer[]> = {};
    allPrinters.forEach(p => {
      const m = p.model || 'Bilinmeyen Model';
      if (!groups[m]) groups[m] = [];
      groups[m].push(p);
    });

    // Convert to Array and Sort by Count (Desc)
    const groupArray: ModelGroup[] = Object.keys(groups).map(key => ({
      modelName: key,
      count: groups[key].length,
      printers: groups[key]
    })).sort((a, b) => b.count - a.count);

    setModelGroups(groupArray);
    setConfig(sysConfig);
    setLoading(false);
  };

  const handleGroupClick = (group: ModelGroup) => {
      // Push history state so back button works
      window.history.pushState({ modal: 'modelDetail' }, '');
      setSelectedModel(group);
  };

  const closeModalViaBack = () => {
      window.history.back();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400"><CheckCircle2 size={12}/> AKTİF</span>;
      case 'SPARE': return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400"><Archive size={12}/> YEDEK</span>;
      case 'MAINTENANCE': return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400"><Truck size={12}/> SERVİSTE</span>;
      case 'BROKEN': return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400"><AlertTriangle size={12}/> ARIZALI</span>;
      default: return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-zinc-100 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-400"><XCircle size={12}/> HURDA</span>;
    }
  };

  const getModelImage = (model: string) => {
      return config?.modelImages?.[model] || null;
  };

  const filteredGroups = modelGroups.filter(g => g.modelName.toLowerCase().includes(searchTerm.toLowerCase()));

  if (loading) return <LoadingScreen message="Envanter analizi yapılıyor..." />;

  return (
    <div className="space-y-6 pb-20 h-full flex flex-col">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-zinc-900 p-6 rounded-2xl shadow-sm border border-zinc-100 dark:border-zinc-800">
        <div>
           <h2 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
             <Box size={28} className="text-blue-600" />
             Model Envanteri
           </h2>
           <p className="text-zinc-500 dark:text-zinc-400 text-sm mt-1">
             Hangi modelden kaç adet cihaz olduğunu ve dağılımlarını inceleyin.
           </p>
        </div>

        <div className="relative w-full md:w-64">
           <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
           <input 
             type="text" 
             placeholder="Model ara..."
             className="w-full pl-10 p-3 bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 text-zinc-800 dark:text-white"
             value={searchTerm}
             onChange={(e) => setSearchTerm(e.target.value)}
           />
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5 overflow-y-auto pb-4">
         {filteredGroups.map((group) => {
            const imgUrl = getModelImage(group.modelName);
            const total = modelGroups.reduce((acc, curr) => acc + curr.count, 0);
            const percentage = Math.round((group.count / total) * 100);

            return (
               <div 
                 key={group.modelName}
                 onClick={() => handleGroupClick(group)}
                 className="group bg-white dark:bg-zinc-900 rounded-2xl p-5 shadow-sm border border-zinc-200 dark:border-zinc-800 hover:shadow-xl hover:border-blue-400/50 dark:hover:border-blue-600/50 transition-all cursor-pointer relative overflow-hidden flex flex-col"
               >
                  {/* Background decoration */}
                  <div className="absolute -right-6 -top-6 w-24 h-24 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/10 dark:to-indigo-900/10 rounded-full group-hover:scale-150 transition-transform duration-500"></div>

                  <div className="flex justify-between items-start mb-4 relative z-10">
                      <div className="bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 px-3 py-1 rounded-lg text-xs font-bold">
                         {percentage}% Pay
                      </div>
                      {imgUrl ? (
                          <div className="w-12 h-12 bg-white rounded-lg p-1 border border-zinc-100 shadow-sm">
                             <img src={imgUrl} alt={group.modelName} className="w-full h-full object-contain" />
                          </div>
                      ) : (
                          <PrinterIcon className="text-zinc-300" size={32} />
                      )}
                  </div>

                  <div className="mt-auto relative z-10">
                      <h3 className="text-xl font-bold text-zinc-800 dark:text-white mb-1 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                          {group.modelName}
                      </h3>
                      <div className="flex items-end gap-2">
                          <span className="text-4xl font-extrabold text-zinc-900 dark:text-white tracking-tighter">
                              {group.count}
                          </span>
                          <span className="text-sm font-medium text-zinc-500 dark:text-zinc-400 mb-1.5">Adet</span>
                      </div>
                  </div>

                  <div className="mt-4 w-full bg-zinc-100 dark:bg-zinc-800 h-1.5 rounded-full overflow-hidden">
                      <div className="bg-gradient-to-r from-blue-500 to-indigo-500 h-full rounded-full" style={{ width: `${percentage}%` }}></div>
                  </div>
               </div>
            );
         })}
      </div>

      {/* DETAIL DRAWER / MODAL */}
      {selectedModel && (
         <div className="fixed inset-0 z-50 flex justify-end">
             {/* Backdrop */}
             <div 
               className="absolute inset-0 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300"
               onClick={closeModalViaBack}
             ></div>

             {/* Slide-over Panel */}
             <div className="relative w-full max-w-md bg-white dark:bg-zinc-900 h-full shadow-2xl border-l border-zinc-200 dark:border-zinc-800 animate-in slide-in-from-right duration-300 flex flex-col">

                 {/* Header */}
                 <div className="p-6 border-b border-zinc-100 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 flex justify-between items-start">
                     <div>
                        <h3 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
                           {selectedModel.modelName}
                        </h3>
                        <p className="text-zinc-500 dark:text-zinc-400 mt-1">
                           Toplam {selectedModel.count} adet cihaz listeleniyor
                        </p>
                     </div>
                     <button 
                       onClick={closeModalViaBack}
                       className="p-2 bg-white dark:bg-zinc-800 rounded-full hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors shadow-sm"
                     >
                        <X size={20} className="text-zinc-500"/>
                     </button>
                 </div>

                 {/* Scrollable Content */}
                 <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-zinc-50/50 dark:bg-black/50">
                    {selectedModel.printers.map((printer) => (
                       <div key={printer.id} className="bg-white dark:bg-zinc-800 p-4 rounded-xl border border-zinc-100 dark:border-zinc-700 shadow-sm flex flex-col gap-2 hover:border-blue-400 dark:hover:border-blue-500 transition-colors">
                           <div className="flex justify-between items-start">
                               <div className="flex items-center gap-2">
                                   <div className="p-2 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-lg">
                                      <MapPin size={18} />
                                   </div>
                                   <div>
                                       <h4 className="font-bold text-zinc-800 dark:text-white text-sm">{printer.location}</h4>
                                       <p className="text-xs text-zinc-500 dark:text-zinc-400">{printer.floor}</p>
                                   </div>
                               </div>
                               {getStatusBadge(printer.status)}
                           </div>

                           <div className="flex items-center gap-4 mt-2 pt-2 border-t border-zinc-100 dark:border-zinc-700 text-xs text-zinc-500 dark:text-zinc-400">
                               <div className="flex items-center gap-1 bg-zinc-50 dark:bg-zinc-900/50 px-2 py-1 rounded">
                                   <Hash size={12} />
                                   <span className="font-mono">{printer.serialNumber}</span>
                               </div>
                               {printer.ipAddress && (
                                   <div className="font-mono">{printer.ipAddress}</div>
                               )}
                           </div>
                       </div>
                    ))}
                 </div>

                 {/* Footer */}
                 <div className="p-4 bg-white dark:bg-zinc-900 border-t border-zinc-100 dark:border-zinc-800">
                    <button 
                      onClick={closeModalViaBack}
                      className="w-full py-3 bg-zinc-100 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-300 font-bold rounded-xl hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors"
                    >
                       Kapat
                    </button>
                 </div>

             </div>
         </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, CounterLog, User } from '../types';
import { Calculator, Upload, Save, AlertTriangle, FileSpreadsheet, CheckCircle2, Search, ArrowRight, ArrowUp, RefreshCw, X, Loader2, Globe, History, Calendar, TrendingUp, Droplet } from 'lucide-react';
import { LoadingScreen } from './LoadingScreen';

interface CounterManagementProps {
  user: { name: string };
}

export const CounterManagement: React.FC<CounterManagementProps> = ({ user }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [allLogs, setAllLogs] = useState<CounterLog[]>([]); // Store all logs
  const [loading, setLoading] = useState(true);
  const [filterTerm, setFilterTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'LIST' | 'IMPORT'>('LIST');
  const [isSaving, setIsSaving] = useState(false);

  // History Modal State
  const [selectedHistoryPrinter, setSelectedHistoryPrinter] = useState<Printer | null>(null);

  // Input States for manual entry
  const [inputValues, setInputValues] = useState<Record<string, string>>({});

  // Import States
  const [parsedData, setParsedData] = useState<any[]>([]);
  const [matchResults, setMatchResults] = useState<{matched: any[], unmatched: any[]}>({matched: [], unmatched: []});
  const [importError, setImportError] = useState<string | null>(null);

  useEffect(() => {
    fetchData();
  }, []);

  // --- HISTORY / BACK BUTTON HANDLER ---
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
        if (selectedHistoryPrinter) {
            setSelectedHistoryPrinter(null);
        }
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedHistoryPrinter]);

  // Close modal on ESC
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && selectedHistoryPrinter) {
          window.history.back();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedHistoryPrinter]);

  const fetchData = async () => {
    setLoading(true);
    const [p, l] = await Promise.all([
        StorageService.getPrinters(),
        StorageService.getCounterLogs()
    ]);
    setPrinters(p);
    setAllLogs(l);
    setLoading(false);
  };

  const openHistoryModal = (printer: Printer) => {
      window.history.pushState({ modal: 'counterHistory' }, '');
      setSelectedHistoryPrinter(printer);
  };

  const closeModalViaBack = () => {
      window.history.back();
  };

  // --- MANUAL ENTRY LOGIC ---
  const handleInputChange = (printerId: string, value: string) => {
    setInputValues(prev => ({ ...prev, [printerId]: value }));
  };

  const handleSingleSave = async (printer: Printer) => {
    const newValStr = inputValues[printer.id];
    if (!newValStr) return;

    const newVal = parseInt(newValStr);
    if (isNaN(newVal)) {
        alert('Lütfen geçerli bir sayı giriniz.');
        return;
    }

    // Validate counter integrity
    if (newVal < printer.lastCounter) {
        if (!confirm(`UYARI: Girdiğiniz sayaç (${newVal}), eski sayaçtan (${printer.lastCounter}) daha düşük. Cihaz sıfırlanmış olabilir mi? Yine de kaydetmek istiyor musunuz?`)) {
            return;
        }
    }

    try {
        await saveCounterLog(printer, newVal, 'Manuel Giriş');
        alert('Sayaç başarıyla güncellendi.');

        // Clear input and refresh
        setInputValues(prev => {
            const copy = {...prev};
            delete copy[printer.id];
            return copy;
        });
        fetchData();
    } catch (error) {
        console.error(error);
        alert('Kayıt sırasında bir hata oluştu.');
    }
  };

  const saveCounterLog = async (printer: Printer, currentCounter: number, method: string) => {
     const usage = currentCounter - printer.lastCounter;

     // 1. Create Log Entry (History)
     const log: CounterLog = {
         id: '',
         printerId: printer.id,
         printerName: `${printer.brand} ${printer.model}`,
         serialNumber: printer.serialNumber,
         date: new Date().toISOString(),
         previousCounter: printer.lastCounter,
         currentCounter: currentCounter,
         usage: usage > 0 ? usage : 0, // Prevent negative usage in logs unless strictly needed
         recordedBy: `${user.name} (${method})`
     };

     // 2. Save to Firestore (This adds log AND updates printer doc)
     await StorageService.addCounterLog(log);
  };

  // --- CSV IMPORT LOGIC (IMPROVED FOR CANON + IP INTEGRATION) ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    setImportError(null);
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
        const text = evt.target?.result as string;
        if (!text) {
            setImportError("Dosya boş veya okunamadı.");
            return;
        }
        parseCSV(text);
    };
    reader.onerror = () => {
        setImportError("Dosya okuma hatası.");
    };
    reader.readAsText(file, 'UTF-8'); // Ensure UTF-8 reading
    e.target.value = ''; // Reset input
  };

  const parseCSV = (text: string) => {
      // Normalize line endings
      const lines = text.split(/\r\n|\n|\r/);

      if (lines.length < 2) {
          setImportError("Dosya içeriği çok kısa veya boş.");
          return;
      }

      // 1. Find the Header Row
      let headerRowIndex = -1;
      let delimiter = ','; // Default

      for (let i = 0; i < Math.min(lines.length, 25); i++) {
          const line = lines[i].toLowerCase();
          // Look for keywords common in Canon/Printer exports
          if (line.includes('serial') || line.includes('seri') || line.includes('mc_serial')) {
              headerRowIndex = i;

              // Detect delimiter based on occurrence count
              const semicolonCount = (line.match(/;/g) || []).length;
              const commaCount = (line.match(/,/g) || []).length;
              const tabCount = (line.match(/\t/g) || []).length;

              if (tabCount > semicolonCount && tabCount > commaCount) delimiter = '\t';
              else if (semicolonCount > commaCount) delimiter = ';';
              else delimiter = ',';

              break;
          }
      }

      if (headerRowIndex === -1) {
          setImportError('Dosyada "Seri No" (Serial) başlığı bulunamadı. Lütfen Canon raporunu değiştirmeden yükleyin.');
          return;
      }

      // 2. Map Headers
      const headers = lines[headerRowIndex].split(delimiter).map(h => h.trim().toLowerCase().replace(/^"|"$/g, '').replace(/^\ufeff/, ''));

      // Determine Indexes
      const serialIndex = headers.findIndex(h => h.includes('serial') || h.includes('seri'));
      const totalCounterIndex = headers.findIndex(h => h.includes('total') || h.includes('toplam') || h.includes('counter') || h.includes('sayaç') || h.includes('101:'));
      const ipIndex = headers.findIndex(h => h.includes('ip address') || h.includes('ip adresi') || h.includes('ipv4') || h.includes('address') || h.includes('adres'));

      if (serialIndex === -1 || totalCounterIndex === -1) {
          setImportError('Gerekli sütunlar bulunamadı. "Seri No" ve "Toplam Sayaç" sütunlarının olduğundan emin olun.');
          return;
      }

      // 3. Extract Data
      const results: any[] = [];
      let successCount = 0;

      for (let i = headerRowIndex + 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          const cols = line.split(delimiter).map(c => c.trim().replace(/^"|"$/g, ''));

          const serial = cols[serialIndex];
          const counterStr = cols[totalCounterIndex];
          const ipStr = ipIndex !== -1 ? cols[ipIndex] : null;

          if (serial && counterStr) {
              const cleanCounter = parseInt(counterStr.replace(/\D/g, ''));

              if (!isNaN(cleanCounter) && cleanCounter > 0) {
                  results.push({ 
                      serial, 
                      counter: cleanCounter,
                      ip: ipStr // Can be null
                  });
                  successCount++;
              }
          }
      }

      if (successCount === 0) {
          setImportError("Dosyada okunabilir veri bulunamadı.");
          return;
      }

      setParsedData(results);
      performMatching(results);
  };

  const normalizeSerial = (s: string) => {
      // Remove all non-alphanumeric chars and lowercase
      return s ? s.replace(/[^a-zA-Z0-9]/g, '').toLowerCase() : '';
  };

  const performMatching = (data: any[]) => {
      const matched: any[] = [];
      const unmatched: any[] = [];

      data.forEach(item => {
          const itemSerialNorm = normalizeSerial(item.serial);

          // Match logic
          const printer = printers.find(p => normalizeSerial(p.serialNumber) === itemSerialNorm);

          if (printer) {
              // Check if IP update is needed
              const needsIpUpdate = item.ip && item.ip !== printer.ipAddress && item.ip.length > 6; // Basic length check for IP

              matched.push({
                  printer,
                  newCounter: item.counter,
                  diff: item.counter - printer.lastCounter,
                  newIp: item.ip,
                  needsIpUpdate
              });
          } else {
              unmatched.push(item);
          }
      });

      setMatchResults({ matched, unmatched });
      if (matched.length === 0 && unmatched.length > 0) {
          setImportError("Seri numaraları eşleşmedi. Sistemdeki seri numaralarını kontrol edin.");
      }
  };

  const confirmImport = async () => {
      if (matchResults.matched.length === 0) return;

      if (!confirm(`${matchResults.matched.length} adet cihazın sayacı güncellenecek. Onaylıyor musunuz?`)) return;

      setIsSaving(true);

      let processedCount = 0;
      let errorCount = 0;

      // Iterate sequentially to ensure DB stability
      for (const item of matchResults.matched) {
          try {
             // 1. Save Counter (Updates Printer LastCounter + Adds History Log)
             await saveCounterLog(item.printer, item.newCounter, 'Canon Import');

             // 2. Update IP Address if detected and changed
             if (item.needsIpUpdate) {
                const updatedPrinter = { 
                    ...item.printer, 
                    ipAddress: item.newIp,
                    lastCounter: item.newCounter // Ensure local object is updated for next operations
                };
                // We need to call StorageService.updatePrinter directly
                await StorageService.updatePrinter(updatedPrinter);
             }

             processedCount++;
          } catch (e) {
             console.error("Error saving for", item.printer.serialNumber, e);
             errorCount++;
          }
      }

      setIsSaving(false);
      alert(`İşlem Tamamlandı.\nBaşarılı: ${processedCount}\nHatalı: ${errorCount}`);

      // Cleanup
      setMatchResults({ matched: [], unmatched: [] });
      setParsedData([]);
      setActiveTab('LIST');
      fetchData(); // Refresh UI with new data
  };

  const resetImport = () => {
      setParsedData([]);
      setMatchResults({matched: [], unmatched: []});
      setImportError(null);
  };

  const filteredPrinters = printers.filter(p => 
      p.location.toLowerCase().includes(filterTerm.toLowerCase()) || 
      p.model.toLowerCase().includes(filterTerm.toLowerCase()) ||
      p.serialNumber.toLowerCase().includes(filterTerm.toLowerCase())
  );

  if (loading) return <LoadingScreen message="Sayaç verileri yükleniyor..." />;

  return (
    <div className="space-y-6 pb-20">
       <div className="flex justify-between items-center bg-white dark:bg-zinc-900 p-4 rounded-2xl shadow-sm border border-zinc-100 dark:border-zinc-800">
        <div>
          <h2 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
             <Calculator size={24} className="text-blue-500" />
             Sayaç (Endeks) Yönetimi
          </h2>
          <p className="text-sm text-zinc-500 dark:text-zinc-400">Excel/CSV ile toplu sayaç ve IP güncelleme</p>
        </div>
        <button onClick={fetchData} className="p-2 bg-zinc-100 dark:bg-zinc-800 rounded-lg hover:bg-zinc-200 transition-colors">
            <RefreshCw size={20} className="text-zinc-500"/>
        </button>
      </div>

      {/* TABS */}
      <div className="flex space-x-2 bg-white dark:bg-zinc-900 p-1 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 w-fit">
        <button 
          onClick={() => setActiveTab('LIST')}
          disabled={isSaving}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'LIST' ? 'bg-zinc-900 dark:bg-zinc-700 text-white' : 'text-zinc-600 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800'}`}
        >
          Manuel Liste
        </button>
        <button 
          onClick={() => setActiveTab('IMPORT')}
          disabled={isSaving}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white' : 'text-blue-700 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20'}`}
        >
          <Upload size={16} /> Excel/CSV İçe Aktar (Canon)
        </button>
      </div>

      {/* --- LIST VIEW --- */}
      {activeTab === 'LIST' && (
        <div className="space-y-4">
           {/* Search */}
           <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
              <input 
                 type="text" 
                 placeholder="Cihaz ara (Model, Konum, Seri No)..." 
                 className="w-full pl-10 p-3 rounded-xl border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-500"
                 value={filterTerm}
                 onChange={e => setFilterTerm(e.target.value)}
              />
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredPrinters.map(printer => {
                 const currentInput = inputValues[printer.id] || '';
                 const diff = currentInput ? (parseInt(currentInput) - printer.lastCounter) : 0;

                 return (
                    <div key={printer.id} className="bg-white dark:bg-zinc-900 p-4 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 flex flex-col gap-3">
                        <div className="flex justify-between items-start">
                           <div>
                              <h4 className="font-bold text-zinc-800 dark:text-white">{printer.model}</h4>
                              <p className="text-xs text-zinc-500 dark:text-zinc-400">{printer.location}</p>
                           </div>
                           <button 
                              onClick={() => openHistoryModal(printer)}
                              className="text-zinc-400 hover:text-blue-500 p-1"
                              title="Geçmişi Gör"
                           >
                               <History size={20} />
                           </button>
                        </div>

                        <div className="bg-zinc-50 dark:bg-zinc-800/50 p-3 rounded-lg grid grid-cols-2 gap-2 text-sm">
                            <div>
                                <p className="text-[10px] text-zinc-400 uppercase font-bold">Son Sayaç</p>
                                <p className="font-mono font-bold text-zinc-700 dark:text-zinc-300">{printer.lastCounter}</p>
                            </div>
                            <div>
                                <p className="text-[10px] text-zinc-400 uppercase font-bold">Anlık Fark</p>
                                <p className={`font-mono font-bold ${diff > 0 ? 'text-emerald-500' : 'text-zinc-400'}`}>
                                    {diff > 0 ? `+${diff}` : '-'}
                                </p>
                            </div>
                        </div>

                        <div className="flex gap-2 items-center mt-auto">
                            <input 
                                type="number" 
                                className="flex-1 p-2 border border-zinc-200 dark:border-zinc-700 rounded-lg bg-white dark:bg-zinc-800 outline-none focus:ring-2 focus:ring-blue-500 font-mono text-sm"
                                placeholder="Yeni Sayaç"
                                value={currentInput}
                                onChange={(e) => handleInputChange(printer.id, e.target.value)}
                            />
                            <button 
                                onClick={() => handleSingleSave(printer)}
                                disabled={!currentInput}
                                className="p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <Save size={18} />
                            </button>
                        </div>
                    </div>
                 );
              })}
           </div>
        </div>
      )}

      {/* --- IMPORT VIEW --- */}
      {activeTab === 'IMPORT' && (
         <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">

             {/* Import Error Message */}
             {importError && (
                 <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-900/50 text-red-700 dark:text-red-300 p-4 rounded-xl flex items-start gap-3">
                     <AlertTriangle className="shrink-0" />
                     <div>
                         <p className="font-bold">Hata Oluştu</p>
                         <p className="text-sm">{importError}</p>
                     </div>
                     <button onClick={() => setImportError(null)} className="ml-auto"><X size={18}/></button>
                 </div>
             )}

             {/* Upload Area */}
             {!isSaving ? (
                <div className="border-2 border-dashed border-zinc-300 dark:border-zinc-700 rounded-2xl p-8 text-center bg-zinc-50 dark:bg-zinc-800/50 hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors">
                    <input 
                    type="file" 
                    accept=".csv,.txt"
                    className="hidden" 
                    id="csv-upload"
                    onChange={handleFileUpload}
                    />
                    <label htmlFor="csv-upload" className="cursor-pointer flex flex-col items-center gap-3">
                        <div className="p-4 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full">
                            <FileSpreadsheet size={32} />
                        </div>
                        <div>
                            <h3 className="font-bold text-lg text-zinc-800 dark:text-white">Canon Raporunu Yükle</h3>
                            <p className="text-zinc-500 text-sm mt-1">Management Console'dan alınan CSV dosyasını seçin</p>
                        </div>
                        <span className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-lg shadow-blue-500/20">Dosya Seç</span>
                    </label>
                </div>
             ) : (
                <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 p-8 rounded-2xl flex flex-col items-center justify-center gap-4">
                    <Loader2 size={40} className="text-blue-600 animate-spin" />
                    <div className="text-center">
                        <h3 className="text-lg font-bold text-blue-700 dark:text-blue-300">Veriler İşleniyor</h3>
                        <p className="text-sm text-blue-600 dark:text-blue-400">Sayaçlar ve IP adresleri güncelleniyor, lütfen bekleyin...</p>
                    </div>
                </div>
             )}

             {/* Results Preview */}
             {matchResults.matched.length > 0 && !isSaving && (
                 <div className="bg-white dark:bg-zinc-900 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 overflow-hidden">
                     <div className="p-4 border-b border-zinc-200 dark:border-zinc-800 flex justify-between items-center bg-emerald-50 dark:bg-emerald-900/10">
                        <h3 className="font-bold text-emerald-700 dark:text-emerald-400 flex items-center gap-2">
                            <CheckCircle2 size={20} />
                            {matchResults.matched.length} Cihaz Eşleşti
                        </h3>
                        <div className="flex gap-2">
                            <button onClick={resetImport} className="text-sm text-zinc-500 hover:text-zinc-700 px-3 py-2">İptal</button>
                            <button 
                                onClick={confirmImport}
                                className="bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-lg shadow-emerald-500/20 flex items-center gap-2"
                            >
                                Verileri Kaydet <ArrowRight size={16}/>
                            </button>
                        </div>
                     </div>
                     <div className="max-h-64 overflow-y-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-zinc-50 dark:bg-zinc-800 text-zinc-500 sticky top-0">
                                <tr>
                                    <th className="p-3">Seri No / Model</th>
                                    <th className="p-3">Eski Sayaç</th>
                                    <th className="p-3">Yeni Sayaç</th>
                                    <th className="p-3">Kullanım</th>
                                    <th className="p-3">IP Durumu</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800">
                                {matchResults.matched.map((item, i) => (
                                    <tr key={i} className="hover:bg-zinc-50 dark:hover:bg-zinc-800/50">
                                        <td className="p-3">
                                            <p className="font-bold text-zinc-800 dark:text-white">{item.printer.model}</p>
                                            <p className="text-xs text-zinc-500 font-mono">{item.printer.serialNumber}</p>
                                        </td>
                                        <td className="p-3 text-zinc-500">{item.printer.lastCounter}</td>
                                        <td className="p-3 font-bold text-blue-600 dark:text-blue-400">{item.newCounter}</td>
                                        <td className="p-3">
                                            <span className={`px-2 py-1 rounded text-xs font-bold ${item.diff >= 0 ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'}`}>
                                                {item.diff > 0 ? '+' : ''}{item.diff}
                                            </span>
                                        </td>
                                        <td className="p-3">
                                            {item.needsIpUpdate ? (
                                                <span className="flex items-center gap-1 text-xs text-blue-600 font-bold bg-blue-100 dark:bg-blue-900/30 px-2 py-1 rounded">
                                                    <Globe size={12}/> {item.newIp}
                                                </span>
                                            ) : (
                                                <span className="text-xs text-zinc-400">-</span>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                     </div>
                 </div>
             )}

             {/* Unmatched Warning */}
             {matchResults.unmatched.length > 0 && !isSaving && (
                 <div className="bg-orange-50 dark:bg-orange-900/10 border border-orange-100 dark:border-orange-800/30 rounded-xl p-4">
                     <h4 className="font-bold text-orange-700 dark:text-orange-400 flex items-center gap-2 mb-2">
                        <AlertTriangle size={18} />
                        {matchResults.unmatched.length} Kayıt Eşleşmedi
                     </h4>
                     <p className="text-xs text-orange-600 dark:text-orange-300 mb-2">
                        Bu seri numaraları sistemde bulunamadı. Lütfen "Yazıcılar" menüsünden seri numaralarını kontrol edin.
                     </p>
                     <div className="flex flex-wrap gap-2">
                        {matchResults.unmatched.map((u, i) => (
                            <span key={i} className="bg-white dark:bg-zinc-800 border border-orange-200 dark:border-orange-900 text-zinc-500 text-xs px-2 py-1 rounded font-mono">
                                {u.serial}
                            </span>
                        ))}
                     </div>
                 </div>
             )}
         </div>
      )}

      {/* --- HISTORY MODAL --- */}
      {selectedHistoryPrinter && (
        <div className="fixed inset-0 z-50 flex justify-end">
             {/* Backdrop */}
             <div 
               className="absolute inset-0 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300"
               onClick={closeModalViaBack}
             ></div>

             {/* Slide-over Panel */}
             <div className="relative w-full max-w-md bg-white dark:bg-zinc-900 h-full shadow-2xl border-l border-zinc-200 dark:border-zinc-800 animate-in slide-in-from-right duration-300 flex flex-col">

                 {/* Header */}
                 <div className="p-6 border-b border-zinc-100 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 flex justify-between items-start">
                     <div>
                        <h3 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
                           {selectedHistoryPrinter.model}
                        </h3>
                        <div className="flex flex-col mt-1">
                            <span className="text-sm font-medium text-zinc-600 dark:text-zinc-300">{selectedHistoryPrinter.location}</span>
                            <span className="text-xs text-zinc-400 font-mono">{selectedHistoryPrinter.serialNumber}</span>
                        </div>
                     </div>
                     <button 
                       onClick={closeModalViaBack}
                       className="p-2 bg-white dark:bg-zinc-800 rounded-full hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors shadow-sm"
                     >
                        <X size={20} className="text-zinc-500"/>
                     </button>
                 </div>

                 {/* Scrollable Content */}
                 <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-zinc-50/50 dark:bg-black/50 custom-scrollbar">

                    {/* Summary Card */}
                    <div className="bg-white dark:bg-zinc-800 p-4 rounded-xl border border-zinc-200 dark:border-zinc-700 shadow-sm flex items-center justify-between">
                        <div>
                            <p className="text-xs text-zinc-500 dark:text-zinc-400 uppercase font-bold">Güncel Sayaç</p>
                            <p className="text-2xl font-bold text-zinc-800 dark:text-white">{selectedHistoryPrinter.lastCounter.toLocaleString()}</p>
                        </div>
                        <div className="bg-blue-50 dark:bg-blue-900/20 p-2 rounded-lg">
                             <Calculator size={24} className="text-blue-600 dark:text-blue-400" />
                        </div>
                    </div>

                    <h4 className="font-bold text-zinc-700 dark:text-zinc-300 flex items-center gap-2 mt-2">
                        <History size={16} /> Sayaç Geçmişi
                    </h4>

                    {(() => {
                        const logs = allLogs.filter(l => l.printerId === selectedHistoryPrinter.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

                        if (logs.length === 0) {
                            return (
                                <div className="flex flex-col items-center justify-center py-10 text-center opacity-60">
                                    <Droplet size={40} className="text-zinc-300 dark:text-zinc-600 mb-2"/>
                                    <p className="text-zinc-500 font-medium">Sayaç kaydı bulunamadı.</p>
                                    <p className="text-xs text-zinc-400 mt-1 max-w-[200px]">Mürekkepli yazıcı veya henüz sayaç girişi yapılmamış cihaz.</p>
                                </div>
                            );
                        }

                        return (
                            <div className="space-y-3 relative">
                                {/* Timeline Line */}
                                <div className="absolute left-4 top-2 bottom-2 w-0.5 bg-zinc-200 dark:bg-zinc-800 z-0"></div>

                                {logs.map((log) => (
                                    <div key={log.id} className="relative z-10 pl-10">
                                        {/* Timeline Dot */}
                                        <div className="absolute left-[11px] top-4 w-3 h-3 rounded-full bg-blue-500 border-2 border-white dark:border-zinc-900"></div>

                                        <div className="bg-white dark:bg-zinc-800 p-3 rounded-xl border border-zinc-100 dark:border-zinc-700 shadow-sm">
                                            <div className="flex justify-between items-start mb-2">
                                                <div className="flex items-center gap-2">
                                                    <Calendar size={14} className="text-zinc-400" />
                                                    <span className="text-sm font-bold text-zinc-700 dark:text-zinc-200">
                                                        {new Date(log.date).toLocaleDateString('tr-TR', { month: 'long', year: 'numeric' })}
                                                    </span>
                                                </div>
                                                <span className="text-[10px] text-zinc-400">
                                                    {new Date(log.date).toLocaleDateString('tr-TR')}
                                                </span>
                                            </div>

                                            <div className="flex justify-between items-center bg-zinc-50 dark:bg-zinc-900/50 p-2 rounded-lg">
                                                <div>
                                                    <p className="text-[10px] text-zinc-400 uppercase">Okunan Değer</p>
                                                    <p className="font-mono font-bold text-zinc-800 dark:text-white">{log.currentCounter.toLocaleString()}</p>
                                                </div>
                                                <div className="text-right">
                                                    <p className="text-[10px] text-zinc-400 uppercase">Aylık Fark</p>
                                                    <p className="font-mono font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
                                                        <TrendingUp size={12}/> {log.usage > 0 ? `+${log.usage.toLocaleString()}` : log.usage}
                                                    </p>
                                                </div>
                                            </div>

                                            <div className="mt-2 text-[10px] text-zinc-400 flex justify-between">
                                                <span>Yöntem: {log.recordedBy}</span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        );
                    })()}

                 </div>
             </div>
        </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Globe, Trash2, History, Truck, AlertTriangle, QrCode, FileSpreadsheet, Download, CheckCircle2, XCircle, AlertCircle, Archive, RefreshCw, Users, UserPlus, Filter, Wallet, Calendar, Database, ArrowRight, Grid, Printer, ArrowUp, Loader2, Activity, Calculator, TrendingUp, BarChart3 } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, PrinterStatus, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';
import { INITIAL_PRINTER_DATA } from './Settings';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

// Stats Interface
interface PrinterStats {
  totalSpent: number;
  avgTonerDays: number | string;
  totalServiceCount: number;
  lastServiceDate: string | null;
}

export const PrinterList: React.FC<PrinterListProps> = ({ onSelectPrinter, targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);

  // Filters
  const [selectedFloor, setSelectedFloor] = useState<string>('ALL');
  const [selectedStatus, setSelectedStatus] = useState<string>('ALL');

  // Modals State
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  // Confirmation Modal State for Stock Out
  const [showStockConfirmation, setShowStockConfirmation] = useState(false);
  const [isProcessingStock, setIsProcessingStock] = useState(false);

  // QR Code Modal (Single)
  const [qrPrinter, setQrPrinter] = useState<PrinterType | null>(null);

  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);
  const [selectedPrinterHistory, setSelectedPrinterHistory] = useState<{
      printer: PrinterType, 
      tonerLogs: StockLog[], 
      serviceLogs: ServiceRecord[], 
      counterLogs: CounterLog[], 
      stats: PrinterStats
  } | null>(null);

  // Quick Import State
  const [isQuickImporting, setIsQuickImporting] = useState(false);

  // Form State
  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '',
    model: '',
    serialNumber: '',
    location: '',
    floor: '',
    lastCounter: 0,
    compatibleToner: '',
    connectionType: 'USB',
    ipAddress: '',
    supplier: '',
    status: 'ACTIVE',
    connectedUsers: []
  });

  // Helper for text area input handling for users
  const [connectedUsersInput, setConnectedUsersInput] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  // --- HISTORY / BACK BUTTON HANDLER ---
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      // If back button is pressed, check which modal is open and close it
      // The state change will be "closing" the modal
      if (showStockConfirmation) {
        setShowStockConfirmation(false);
      } else if (qrPrinter) {
        setQrPrinter(null);
      } else if (isHistoryModalOpen) {
        setIsHistoryModalOpen(false);
      } else if (isFormModalOpen) {
        setIsFormModalOpen(false);
        setEditingPrinter(null);
      } else if (deleteId) {
        setDeleteId(null);
      }
    };

    window.addEventListener('popstate', handlePopState);

    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [showStockConfirmation, qrPrinter, isHistoryModalOpen, isFormModalOpen, deleteId]);


  // Deep Linking Logic
  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const target = printers.find(p => p.id === targetPrinterId);
      if (target) {
        openHistoryModal(target);
      }
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  // --- ESC KEY LISTENER ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        // Trigger back navigation to close modal properly with history
        if (showStockConfirmation || qrPrinter || isHistoryModalOpen || isFormModalOpen || deleteId) {
             window.history.back();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [qrPrinter, isHistoryModalOpen, isFormModalOpen, deleteId, showStockConfirmation]);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([
      StorageService.getPrinters(),
      StorageService.getConfig()
    ]);
    setPrinters(p);
    setConfig(c);
    setLoading(false);
  };

  // --- HELPER: BRAND LOGO ---
  const getBrandLogoUrl = (brand: string) => {
    // 1. Check custom user uploaded image from config
    if (config.brandImages && config.brandImages[brand]) {
        return config.brandImages[brand];
    }

    // 2. Fallback to Simple Icons CDN
    const b = brand.toLowerCase();
    if (b.includes('canon')) return 'https://cdn.simpleicons.org/canon/CC0000';
    if (b.includes('hp')) return 'https://cdn.simpleicons.org/hp/0096D6';
    if (b.includes('epson')) return 'https://cdn.simpleicons.org/epson/003399';
    if (b.includes('xerox')) return 'https://cdn.simpleicons.org/xerox/DA1A32';
    if (b.includes('kyocera')) return 'https://cdn.simpleicons.org/kyocera/E60012';
    if (b.includes('samsung')) return 'https://cdn.simpleicons.org/samsung/1428A0';
    if (b.includes('brother')) return 'https://cdn.simpleicons.org/brother/003C6A';
    if (b.includes('lexmark')) return 'https://cdn.simpleicons.org/lexmark/202020';
    if (b.includes('oki')) return 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/OKI_Logo.svg/320px-OKI_Logo.svg.png'; // Fallback for OKI
    return null; // fallback to text
  };

  // --- HELPER: MODEL IMAGE ---
  const getModelImageUrl = (model: string) => {
      if (config.modelImages && config.modelImages[model]) {
          return config.modelImages[model];
      }
      return null;
  }

  // --- QUICK IMPORT ---
  const handleQuickImport = async () => {
    setIsQuickImporting(true);
    try {
        for (const item of INITIAL_PRINTER_DATA) {
            const isUsb = item.ip === 'USB' || item.ip === '-' || item.ip === '' || item.ip === null;
            const connectionType = isUsb ? 'USB' : 'Network';
            let ipAddress = '';
            if (!isUsb) {
                ipAddress = item.ip.length <= 3 ? `192.168.1.${item.ip}` : item.ip;
            }

            const newPrinter: PrinterType = {
                id: '',
                serialNumber: item.s,
                brand: 'Canon',
                model: item.m,
                location: item.l,
                floor: 'Giriş/Poliklinik',
                lastCounter: 0,
                lastTonerDate: new Date().toISOString(),
                compatibleToner: '',
                connectionType,
                ipAddress,
                supplier: 'Anahtar Bilgisayar',
                status: 'ACTIVE',
                connectedUsers: []
            };
            await StorageService.addPrinter(newPrinter);
            await new Promise(resolve => setTimeout(resolve, 30));
        }
        await loadData();
    } catch (e) {
        alert('Yükleme hatası.');
    } finally {
        setIsQuickImporting(false);
    }
  };

  // --- ACTIONS ---

  const confirmDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    // Use window.confirm for now as the simplest deletion confirmation in this list
    if(window.confirm("Bu yazıcıyı silmek istediğinize emin misiniz?")) {
        setDeleteId(id);
        // Direct call since we are using native confirm
        StorageService.deletePrinter(id).then(() => {
            loadData();
            setDeleteId(null);
        });
    }
  };

  const handleEditClick = (e: React.MouseEvent, printer: PrinterType) => {
    e.preventDefault();
    e.stopPropagation();
    openFormModal(printer);
  };

  const handleQrClick = (e: React.MouseEvent, printer: PrinterType) => {
    e.preventDefault();
    e.stopPropagation();
    // Push history state so back button works
    window.history.pushState({ modal: 'qr' }, '');
    setQrPrinter(printer);
  };

  const handleHistoryClick = (printer: PrinterType) => {
    openHistoryModal(printer);
  };

  // NEW: Handle quick status change from History Modal
  const handleStatusChange = async (newStatus: PrinterStatus) => {
    if (!selectedPrinterHistory) return;

    const updatedPrinter = { ...selectedPrinterHistory.printer, status: newStatus };

    // 1. Optimistic UI Update (Modal)
    setSelectedPrinterHistory({
        ...selectedPrinterHistory,
        printer: updatedPrinter
    });

    // 2. Optimistic UI Update (List Background)
    setPrinters(prev => prev.map(p => p.id === updatedPrinter.id ? updatedPrinter : p));

    // 3. Persist to DB
    try {
        await StorageService.updatePrinter(updatedPrinter);
    } catch (error) {
        console.error("Status update failed", error);
        alert("Durum güncellenemedi.");
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();

    // Convert users string to array
    const usersArray = connectedUsersInput.split(',').map(u => u.trim()).filter(u => u.length > 0);

    const finalData = {
        ...formData,
        connectedUsers: usersArray
    };

    if (editingPrinter && editingPrinter.id) {
       // Update
       const updatedPrinter = { ...editingPrinter, ...finalData } as PrinterType;
       await StorageService.updatePrinter(updatedPrinter);
    } else {
       // Create
       const newPrinter: PrinterType = {
        id: '', // Generated by Firestore
        lastTonerDate: new Date().toISOString(),
        ...finalData as PrinterType,
        status: finalData.status || 'ACTIVE'
       };
       await StorageService.addPrinter(newPrinter);
    }

    // Go back in history to close modal
    window.history.back();
    loadData(); // Reload list from DB
  };

  const downloadInventoryCSV = () => {
    if (printers.length === 0) {
      alert('İndirilecek veri yok.');
      return;
    }

    const headers = ["Marka", "Model", "Seri No", "Konum", "Kat", "Son Sayaç", "Toner", "IP", "Durum", "Tedarikçi", "Kullanıcılar"];

    const rows = printers.map(p => {
        const clean = (val: any) => `"${String(val || '').replace(/"/g, '""')}"`;
        const users = p.connectedUsers ? p.connectedUsers.join('; ') : '';
        return [
            clean(p.brand),
            clean(p.model),
            clean(p.serialNumber),
            clean(p.location),
            clean(p.floor),
            clean(p.lastCounter),
            clean(p.compatibleToner),
            clean(p.ipAddress || 'USB'),
            clean(p.status),
            clean(p.supplier),
            clean(users)
        ].join(",");
    });

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers.join(",") + "\n" + rows.join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `yazici_envanter_${new Date().toLocaleDateString()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // --- MODAL HELPERS ---

  const openFormModal = (printer?: PrinterType) => {
    // Push history state
    window.history.pushState({ modal: 'form' }, '');

    if (printer) {
      setEditingPrinter(printer);
      setFormData(printer);
      setConnectedUsersInput(printer.connectedUsers ? printer.connectedUsers.join(', ') : '');
    } else {
      setEditingPrinter(null);
      setFormData({
        brand: config.brands[0] || '',
        model: config.models[0] || '',
        serialNumber: '',
        location: '',
        floor: '',
        lastCounter: 0,
        compatibleToner: '',
        connectionType: 'USB',
        ipAddress: '',
        supplier: config.suppliers[0] || '',
        status: 'ACTIVE',
        connectedUsers: []
      });
      setConnectedUsersInput('');
    }
    setIsFormModalOpen(true);
  };

  const closeModalViaBack = () => {
    window.history.back(); // This triggers popstate, which closes the modal
  };

  const openHistoryModal = async (printer: PrinterType) => {
    // Push history state
    window.history.pushState({ modal: 'history' }, '');

    // Fetch fresh logs for this specific history view
    const allLogs = await StorageService.getLogs();
    const allServices = await StorageService.getServiceRecords();
    const allCounterLogs = await StorageService.getCounterLogs();

    // 1. Filter Logs
    const printerLogs = allLogs.filter(log => String(log.printerId) === String(printer.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const printerServices = allServices.filter(srv => String(srv.printerId) === String(printer.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // Filter and Sort Counter Logs (Oldest to Newest for Chart)
    const printerCounterLogs = allCounterLogs
        .filter(l => l.printerId === printer.id)
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // 2. Calculate Stats
    // Cost
    const totalTonerCost = printerLogs.reduce((sum, log) => sum + (log.cost || 0), 0);
    const totalServiceCost = printerServices.reduce((sum, srv) => sum + (srv.cost || 0), 0);
    const totalSpent = totalTonerCost + totalServiceCost;

    // Average Toner Life (Days)
    let avgDays = 0;
    if (printerLogs.length > 1) {
        let totalDays = 0;
        let intervals = 0;
        // Iterate chronologically (reverse sorted logs)
        const chronoLogs = [...printerLogs].reverse();
        for (let i = 0; i < chronoLogs.length - 1; i++) {
            const date1 = new Date(chronoLogs[i].date).getTime();
            const date2 = new Date(chronoLogs[i+1].date).getTime();
            const diffDays = (date2 - date1) / (1000 * 3600 * 24);
            if (diffDays > 0) {
                totalDays += diffDays;
                intervals++;
            }
        }
        if (intervals > 0) avgDays = Math.round(totalDays / intervals);
    }

    const stats: PrinterStats = {
        totalSpent,
        avgTonerDays: avgDays > 0 ? avgDays : 'Yetersiz Veri',
        totalServiceCount: printerServices.length,
        lastServiceDate: printerServices.length > 0 ? printerServices[0].date : null
    };

    setSelectedPrinterHistory({
      printer,
      tonerLogs: printerLogs,
      serviceLogs: printerServices,
      counterLogs: printerCounterLogs,
      stats
    });
    setIsHistoryModalOpen(true);
  };

  // Step 1: Check Availability and Show Modal
  const handleInitiateQuickStockOut = async () => {
      if (!selectedPrinterHistory) return;
      const printer = selectedPrinterHistory.printer;

      if (!printer.compatibleToner) {
          alert("HATA: Bu yazıcı için tanımlı 'Uyumlu Toner' modeli yok. Lütfen önce cihazı düzenleyip toner modeli seçin.");
          return;
      }

      // Check stock availability BEFORE showing confirmation
      const allStocks = await StorageService.getStocks();
      const stockItem = allStocks.find(s => s.modelName === printer.compatibleToner);

      if (!stockItem || stockItem.quantity < 1) {
          alert(`HATA: ${printer.compatibleToner} model tonerden stokta kalmamış!`);
          return;
      }

      // If stock exists, show confirmation modal
      // We don't necessarily need pushState here for sub-modal, but we can if we want multi-level back.
      // For simplicity, treating it as an overlay in the current history state.
      setShowStockConfirmation(true);
  };

  // Step 2: Actually Perform Stock Out
  const handleFinalizeStockOut = async () => {
      if (!selectedPrinterHistory) return;
      setIsProcessingStock(true);

      const printer = selectedPrinterHistory.printer;

      try {
          // 1. Re-fetch stocks to be absolutely sure (concurrency check)
          const allStocks = await StorageService.getStocks();
          const stockItem = allStocks.find(s => s.modelName === printer.compatibleToner);

          if (!stockItem || stockItem.quantity < 1) {
              alert(`HATA: İşlem sırasında stok tükendi!`);
              setIsProcessingStock(false);
              setShowStockConfirmation(false);
              return;
          }

          // 2. Decrement Stock
          await StorageService.saveStock({ modelName: printer.compatibleToner, quantity: stockItem.quantity - 1 });

          // 3. Update Printer Date
          const updatedPrinter = { ...printer, lastTonerDate: new Date().toISOString() };
          await StorageService.updatePrinter(updatedPrinter);

          // 4. Create Log
          const log: StockLog = {
              id: '',
              date: new Date().toISOString(),
              type: 'OUT',
              tonerModel: printer.compatibleToner,
              quantity: 1,
              printerId: printer.id,
              description: `Yazıcıya Takıldı: ${printer.location} (${printer.floor}) [QR Hızlı İşlem]`,
              user: 'Sistem (QR)'
          };
          await StorageService.addLog(log);

          // Success Logic
          setShowStockConfirmation(false);
          // Don't close history modal, let user see it updated
          // setIsHistoryModalOpen(false); // Close main modal
          loadData(); // Refresh main list
          alert("İşlem Başarılı! Stok düşüldü ve cihaz güncellendi.");

      } catch (e) {
          console.error(e);
          alert("Bir hata oluştu.");
      } finally {
          setIsProcessingStock(false);
      }
  };


  // FILTER LOGIC
  const uniqueFloors = ['ALL', ...Array.from(new Set(printers.map(p => p.floor))).filter(Boolean)];
  const uniqueStatuses = ['ALL', ...Array.from(new Set(printers.map(p => p.status))).filter(Boolean)];

  const filteredPrinters = printers.filter(p => {
    const matchesSearch = 
        p.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.serialNumber.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesFloor = selectedFloor === 'ALL' || p.floor === selectedFloor;
    const matchesStatus = selectedStatus === 'ALL' || p.status === selectedStatus;

    return matchesSearch && matchesFloor && matchesStatus;
  });

  // ... (Status Helpers remain the same) ...
  const getStatusColor = (status: PrinterStatus) => {
    switch (status) {
      case 'ACTIVE': return 'border-emerald-500/30 bg-white dark:bg-zinc-900';
      case 'SPARE': return 'border-indigo-500/30 bg-white dark:bg-zinc-900';
      case 'MAINTENANCE': return 'border-orange-500/30 bg-orange-50 dark:bg-orange-900/10';
      case 'BROKEN': return 'border-red-500/30 bg-red-50 dark:bg-red-900/10';
      case 'SCRAPPED': return 'border-zinc-500/30 bg-zinc-100 dark:bg-zinc-800 opacity-75';
      default: return 'border-zinc-200 dark:border-zinc-800';
    }
  };

  const getStatusLabel = (status: PrinterStatus) => {
    switch (status) {
      case 'ACTIVE': return { text: 'AKTİF', icon: <CheckCircle2 size={12} /> };
      case 'SPARE': return { text: 'YEDEKTE', icon: <Archive size={12} /> };
      case 'MAINTENANCE': return { text: 'SERVİSTE', icon: <Truck size={12} /> };
      case 'BROKEN': return { text: 'ARIZALI', icon: <AlertTriangle size={12} /> };
