                             <span className="opacity-60 font-normal">| {printer.floor}</span>
                         </div>

                        {/* Status Pill */}
                        <span className={`flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase w-fit tracking-wide
