               <div className="pt-4 flex gap-3">
                <button type="button" onClick={closeModalViaBack} className="flex-1 py-4 bg-zinc-100 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-200 rounded-xl hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors font-semibold">İptal</button>
                <button type="submit" className="flex-1 py-4 bg-gradient-to-r from-emerald-600 to-teal-600 text-white rounded-xl hover:from-emerald-500 hover:to-teal-500 transition-colors font-bold shadow-lg shadow-emerald-500/20">
