                        <div className="h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={selectedPrinterHistory.counterLogs.slice(-12)}> {/* Last 12 entries */}
                                    <CartesianGrid strokeDasharray="3 3" stroke="#e4e4e7" vertical={false} opacity={0.5} />
                                    <XAxis 
                                        dataKey="date" 
                                        tickFormatter={(date) => new Date(date).toLocaleDateString('tr-TR', {month: 'short'})}
                                        tick={{fontSize: 10, fill: '#71717a'}}
                                        axisLine={false}
                                        tickLine={false}
                                    />
                                    <YAxis 
                                        tick={{fontSize: 10, fill: '#71717a'}}
                                        axisLine={false}
                                        tickLine={false}
                                        tickFormatter={(val) => val >= 1000 ? `${(val/1000).toFixed(0)}k` : val}
                                    />
                                    <Tooltip 
                                        cursor={{fill: 'transparent'}}
                                        content={({ active, payload, label }) => {
                                            if (active && payload && payload.length) {
                                            return (
                                                <div className="bg-zinc-900 text-white text-xs p-3 rounded-xl shadow-xl border border-zinc-700">
                                                    <p className="font-bold mb-1">{new Date(label).toLocaleDateString('tr-TR', {month: 'long', year: 'numeric'})}</p>
                                                    <p className="text-emerald-400 font-bold">
                                                        Kullanım: +{payload[0].value?.toLocaleString()}
                                                    </p>
                                                    <p className="text-zinc-400 mt-1">
                                                        Toplam: {payload[0].payload.currentCounter.toLocaleString()}
                                                    </p>
                                                </div>
                                            );
                                            }
                                            return null;
                                        }}
                                    />
                                    <Bar dataKey="usage" radius={[6, 6, 0, 0]}>
                                        {selectedPrinterHistory.counterLogs.slice(-12).map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill="#10b981" />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                        <p className="text-center text-[10px] text-zinc-400 mt-2">Grafik son 12 kaydın aylık kullanım farklarını (Usage) gösterir.</p>
                    </div>
                )}

            </div>
          </div>
        </div>
       )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, CounterLog, User } from '../types';
import { Calculator, Upload, Save, AlertTriangle, FileSpreadsheet, CheckCircle2, Search, ArrowRight, ArrowUp, RefreshCw, X, Loader2, Globe, History, Calendar, TrendingUp, Droplet, PlusCircle, CalendarDays, Usb } from 'lucide-react';
import { LoadingScreen } from './LoadingScreen';

interface CounterManagementProps {
  user: { name: string };
}

export const CounterManagement: React.FC<CounterManagementProps> = ({ user }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [allLogs, setAllLogs] = useState<CounterLog[]>([]); // Store all logs
  const [loading, setLoading] = useState(true);
  const [filterTerm, setFilterTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'LIST' | 'IMPORT' | 'HISTORY_ENTRY'>('LIST');
  const [isSaving, setIsSaving] = useState(false);

  // History Modal State
  const [selectedHistoryPrinter, setSelectedHistoryPrinter] = useState<Printer | null>(null);

  // Input States for manual entry
  const [inputValues, setInputValues] = useState<Record<string, string>>({});

  // Historical Entry States
  const [histPrinterId, setHistPrinterId] = useState('');
  const [histDate, setHistDate] = useState('');
  const [histValue, setHistValue] = useState('');

  // Import States
  const [parsedData, setParsedData] = useState<any[]>([]);
  const [matchResults, setMatchResults] = useState<{matched: any[], unmatched: any[]}>({matched: [], unmatched: []});
  const [importError, setImportError] = useState<string | null>(null);

  useEffect(() => {
    fetchData();
  }, []);

  // --- HISTORY / BACK BUTTON HANDLER ---
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
        if (selectedHistoryPrinter) {
            setSelectedHistoryPrinter(null);
        }
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedHistoryPrinter]);

  // Close modal on ESC
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && selectedHistoryPrinter) {
          window.history.back();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedHistoryPrinter]);

  const fetchData = async () => {
    setLoading(true);
    const [p, l] = await Promise.all([
        StorageService.getPrinters(),
        StorageService.getCounterLogs()
    ]);
    setPrinters(p);
    setAllLogs(l);
    setLoading(false);
  };

  const openHistoryModal = (printer: Printer) => {
      window.history.pushState({ modal: 'counterHistory' }, '');
      setSelectedHistoryPrinter(printer);
  };

  const closeModalViaBack = () => {
      window.history.back();
  };

  // --- MANUAL ENTRY LOGIC ---
  const handleInputChange = (printerId: string, value: string) => {
    setInputValues(prev => ({ ...prev, [printerId]: value }));
  };

  const handleSingleSave = async (printer: Printer) => {
    const newValStr = inputValues[printer.id];
    if (!newValStr) return;

    const newVal = parseInt(newValStr);
    if (isNaN(newVal)) {
        alert('Lütfen geçerli bir sayı giriniz.');
        return;
    }

    // Validate counter integrity
    if (newVal < printer.lastCounter) {
        if (!confirm(`UYARI: Girdiğiniz sayaç (${newVal}), eski sayaçtan (${printer.lastCounter}) daha düşük. Cihaz sıfırlanmış olabilir mi? Yine de kaydetmek istiyor musunuz?`)) {
            return;
        }
    }

    try {
        await saveCounterLog(printer, newVal, 'Manuel Giriş', true);
        alert('Sayaç başarıyla güncellendi.');

        // Clear input and refresh
        setInputValues(prev => {
            const copy = {...prev};
            delete copy[printer.id];
            return copy;
        });
        fetchData();
    } catch (error) {
        console.error(error);
        alert('Kayıt sırasında bir hata oluştu.');
    }
  };

  // --- HISTORICAL ENTRY LOGIC (NEW) ---
  const handleHistoricalSave = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!histPrinterId || !histDate || !histValue) {
          alert("Lütfen tüm alanları doldurun.");
          return;
      }

      const printer = printers.find(p => p.id === histPrinterId);
      if (!printer) return;

      const counterVal = parseInt(histValue);
      const logDate = new Date(histDate);

      // Simple previous Log finding to calculate usage (Approximation)
      const logsForPrinter = allLogs
          .filter(l => l.printerId === printer.id && new Date(l.date) < logDate)
          .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

      const prevCounter = logsForPrinter.length > 0 ? logsForPrinter[0].currentCounter : 0;
      const usage = counterVal - prevCounter;

      try {
          // Log object
          const log: CounterLog = {
            id: '',
            printerId: printer.id,
            printerName: `${printer.brand} ${printer.model}`,
            serialNumber: printer.serialNumber,
            date: logDate.toISOString(),
            previousCounter: prevCounter,
            currentCounter: counterVal,
            usage: usage > 0 ? usage : 0,
            recordedBy: `${user.name} (Geçmiş Veri)`
          };

          // Save with updateMasterRecord = FALSE
          await StorageService.addCounterLog(log, false);

          alert("Geçmiş veri başarıyla eklendi. Cihazın güncel sayacı DEĞİŞTİRİLMEDİ.");
          setHistValue('');
          fetchData(); // Refresh history list
      } catch (error) {
          console.error(error);
          alert("Hata oluştu.");
      }
  };

  const saveCounterLog = async (printer: Printer, currentCounter: number, method: string, updateMaster: boolean) => {
     const usage = currentCounter - printer.lastCounter;

     // 1. Create Log Entry (History)
     const log: CounterLog = {
         id: '',
         printerId: printer.id,
         printerName: `${printer.brand} ${printer.model}`,
         serialNumber: printer.serialNumber,
         date: new Date().toISOString(),
         previousCounter: printer.lastCounter,
         currentCounter: currentCounter,
         usage: usage > 0 ? usage : 0, 
         recordedBy: `${user.name} (${method})`
     };

     // 2. Save to Firestore
     await StorageService.addCounterLog(log, updateMaster);
  };

  // --- CSV IMPORT LOGIC (IMPROVED FOR CANON + IP INTEGRATION) ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    setImportError(null);
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
        const text = evt.target?.result as string;
        if (!text) {
            setImportError("Dosya boş veya okunamadı.");
            return;
        }
        parseCSV(text);
    };
    reader.onerror = () => {
        setImportError("Dosya okuma hatası.");
    };
    reader.readAsText(file, 'UTF-8'); // Ensure UTF-8 reading
    e.target.value = ''; // Reset input
  };

  const parseCSV = (text: string) => {
      // Normalize line endings
      const lines = text.split(/\r\n|\n|\r/);

      if (lines.length < 2) {
          setImportError("Dosya içeriği çok kısa veya boş.");
          return;
      }

      // 1. Find the Header Row
      let headerRowIndex = -1;
      let delimiter = ','; // Default

      for (let i = 0; i < Math.min(lines.length, 25); i++) {
          const line = lines[i].toLowerCase();
          // Look for keywords common in Canon/Printer exports
          if (line.includes('serial') || line.includes('seri') || line.includes('mc_serial')) {
              headerRowIndex = i;

              // Detect delimiter based on occurrence count
              const semicolonCount = (line.match(/;/g) || []).length;
              const commaCount = (line.match(/,/g) || []).length;
              const tabCount = (line.match(/\t/g) || []).length;

              if (tabCount > semicolonCount && tabCount > commaCount) delimiter = '\t';
              else if (semicolonCount > commaCount) delimiter = ';';
              else delimiter = ',';

              break;
          }
      }

      if (headerRowIndex === -1) {
          setImportError('Dosyada "Seri No" (Serial) başlığı bulunamadı. Lütfen Canon raporunu değiştirmeden yükleyin.');
          return;
      }

      // 2. Map Headers
      const headers = lines[headerRowIndex].split(delimiter).map(h => h.trim().toLowerCase().replace(/^"|"$/g, '').replace(/^\ufeff/, ''));

      // Determine Indexes
      const serialIndex = headers.findIndex(h => h.includes('serial') || h.includes('seri'));
      const totalCounterIndex = headers.findIndex(h => h.includes('total') || h.includes('toplam') || h.includes('counter') || h.includes('sayaç') || h.includes('101:'));
      const ipIndex = headers.findIndex(h => h.includes('ip address') || h.includes('ip adresi') || h.includes('ipv4') || h.includes('address') || h.includes('adres'));

      if (serialIndex === -1 || totalCounterIndex === -1) {
          setImportError('Gerekli sütunlar bulunamadı. "Seri No" ve "Toplam Sayaç" sütunlarının olduğundan emin olun.');
          return;
      }

      // 3. Extract Data
      const results: any[] = [];
      let successCount = 0;

      for (let i = headerRowIndex + 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          const cols = line.split(delimiter).map(c => c.trim().replace(/^"|"$/g, ''));

          const serial = cols[serialIndex];
          const counterStr = cols[totalCounterIndex];
          const ipStr = ipIndex !== -1 ? cols[ipIndex] : null;

          if (serial && counterStr) {
              const cleanCounter = parseInt(counterStr.replace(/\D/g, ''));

              if (!isNaN(cleanCounter) && cleanCounter > 0) {
                  results.push({ 
                      serial, 
                      counter: cleanCounter,
                      ip: ipStr // Can be null
                  });
                  successCount++;
              }
          }
      }

      if (successCount === 0) {
          setImportError("Dosyada okunabilir veri bulunamadı.");
          return;
      }

      setParsedData(results);
      performMatching(results);
  };

  const normalizeSerial = (s: string) => {
      // Remove all non-alphanumeric chars and lowercase
      return s ? s.replace(/[^a-zA-Z0-9]/g, '').toLowerCase() : '';
  };

  const performMatching = (data: any[]) => {
      const matched: any[] = [];
      const unmatched: any[] = [];

      data.forEach(item => {
          const itemSerialNorm = normalizeSerial(item.serial);

          // Match logic
          const printer = printers.find(p => normalizeSerial(p.serialNumber) === itemSerialNorm);

          if (printer) {
              // Check if IP update is needed
              const needsIpUpdate = item.ip && item.ip !== printer.ipAddress && item.ip.length > 6; // Basic length check for IP

              matched.push({
                  printer,
                  newCounter: item.counter,
                  diff: item.counter - printer.lastCounter,
                  newIp: item.ip,
                  needsIpUpdate
              });
          } else {
              unmatched.push(item);
          }
      });

      setMatchResults({ matched, unmatched });
      if (matched.length === 0 && unmatched.length > 0) {
          setImportError("Seri numaraları eşleşmedi. Sistemdeki seri numaralarını kontrol edin.");
      }
  };

  const confirmImport = async () => {
      if (matchResults.matched.length === 0) return;

      if (!confirm(`${matchResults.matched.length} adet cihazın sayacı güncellenecek. Onaylıyor musunuz?`)) return;

      setIsSaving(true);

      let processedCount = 0;
      let errorCount = 0;

      // Iterate sequentially to ensure DB stability
      for (const item of matchResults.matched) {
          try {
             // 1. Save Counter (Updates Printer LastCounter + Adds History Log)
             await saveCounterLog(item.printer, item.newCounter, 'Canon Import', true);

             // 2. Update IP Address if detected and changed
             if (item.needsIpUpdate) {
                const updatedPrinter = { 
                    ...item.printer, 
                    ipAddress: item.newIp,
                    lastCounter: item.newCounter // Ensure local object is updated for next operations
                };
                // We need to call StorageService.updatePrinter directly
                await StorageService.updatePrinter(updatedPrinter);
             }

             processedCount++;
          } catch (e) {
             console.error("Error saving for", item.printer.serialNumber, e);
             errorCount++;
          }
      }

      setIsSaving(false);
      alert(`İşlem Tamamlandı.\nBaşarılı: ${processedCount}\nHatalı: ${errorCount}`);

      // Cleanup
      setMatchResults({ matched: [], unmatched: [] });
      setParsedData([]);
      setActiveTab('LIST');
      fetchData(); // Refresh UI with new data
  };

  const resetImport = () => {
      setParsedData([]);
      setMatchResults({matched: [], unmatched: []});
      setImportError(null);
  };

  const filteredPrinters = printers.filter(p => 
      p.location.toLowerCase().includes(filterTerm.toLowerCase()) || 
      p.model.toLowerCase().includes(filterTerm.toLowerCase()) ||
      p.serialNumber.toLowerCase().includes(filterTerm.toLowerCase())
  );

  if (loading) return <LoadingScreen message="Sayaç verileri yükleniyor..." />;

  return (
    <div className="space-y-6 pb-20">
       <div className="flex justify-between items-center bg-white dark:bg-zinc-900 p-4 rounded-2xl shadow-sm border border-zinc-100 dark:border-zinc-800">
        <div>
          <h2 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
             <Calculator size={24} className="text-blue-500" />
             Sayaç (Endeks) Yönetimi
          </h2>
          <p className="text-sm text-zinc-500 dark:text-zinc-400">Excel/CSV ile toplu sayaç ve IP güncelleme</p>
        </div>
        <button onClick={fetchData} className="p-2 bg-zinc-100 dark:bg-zinc-800 rounded-lg hover:bg-zinc-200 transition-colors">
            <RefreshCw size={20} className="text-zinc-500"/>
        </button>
      </div>

      {/* TABS */}
      <div className="flex space-x-2 bg-white dark:bg-zinc-900 p-1 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 w-fit">
        <button 
          onClick={() => setActiveTab('LIST')}
          disabled={isSaving}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'LIST' ? 'bg-zinc-900 dark:bg-zinc-700 text-white' : 'text-zinc-600 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800'}`}
        >
          Güncel Giriş
        </button>
        <button 
          onClick={() => setActiveTab('IMPORT')}
          disabled={isSaving}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white' : 'text-blue-700 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20'}`}
        >
          <Upload size={16} /> Excel/CSV
        </button>
        <button 
          onClick={() => setActiveTab('HISTORY_ENTRY')}
          disabled={isSaving}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'HISTORY_ENTRY' ? 'bg-orange-600 text-white' : 'text-orange-700 dark:text-orange-400 hover:bg-orange-50 dark:hover:bg-orange-900/20'}`}
        >
          <CalendarDays size={16} /> Geçmiş Veri Ekle
        </button>
      </div>

      {/* --- LIST VIEW --- */}
      {activeTab === 'LIST' && (
        <div className="space-y-4">
           {/* Search */}
           <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
              <input 
                 type="text" 
                 placeholder="Cihaz ara (Model, Konum, Seri No)..." 
                 className="w-full pl-10 p-3 rounded-xl border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-500"
                 value={filterTerm}
                 onChange={e => setFilterTerm(e.target.value)}
              />
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredPrinters.map(printer => {
                 const currentInput = inputValues[printer.id] || '';
                 const diff = currentInput ? (parseInt(currentInput) - printer.lastCounter) : 0;

                 return (
                    <div key={printer.id} className="bg-white dark:bg-zinc-900 p-4 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 flex flex-col gap-3">
                        <div className="flex justify-between items-start">
                           <div>
                              <h4 className="font-bold text-zinc-800 dark:text-white">{printer.model}</h4>
                              <div className="flex flex-col gap-1">
                                  <p className="text-xs text-zinc-500 dark:text-zinc-400">{printer.location}</p>

                                  {/* Connection Type Indicator */}
                                  <div className="flex items-center gap-1">
                                      {printer.connectionType === 'Network' ? (
                                          <span className="text-[10px] bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 px-1.5 py-0.5 rounded font-mono flex items-center gap-1 w-fit">
                                              <Globe size={10} /> {printer.ipAddress}
                                          </span>
                                      ) : (
                                          <span className="text-[10px] bg-zinc-100 dark:bg-zinc-800 text-zinc-500 px-1.5 py-0.5 rounded font-mono flex items-center gap-1 w-fit">
                                              <Usb size={10} /> USB
                                          </span>
                                      )}
                                  </div>
                              </div>
                           </div>
                           <button 
                              onClick={() => openHistoryModal(printer)}
                              className="text-zinc-400 hover:text-blue-500 p-1"
                              title="Geçmişi Gör"
                           >
                               <History size={20} />
                           </button>
                        </div>

                        <div className="bg-zinc-50 dark:bg-zinc-800/50 p-3 rounded-lg grid grid-cols-2 gap-2 text-sm">
                            <div>
                                <p className="text-[10px] text-zinc-400 uppercase font-bold">Son Sayaç</p>
                                <p className="font-mono font-bold text-zinc-700 dark:text-zinc-300">{printer.lastCounter}</p>
                            </div>
                            <div>
                                <p className="text-[10px] text-zinc-400 uppercase font-bold">Anlık Fark</p>
                                <p className={`font-mono font-bold ${diff > 0 ? 'text-emerald-500' : 'text-zinc-400'}`}>
                                    {diff > 0 ? `+${diff}` : '-'}
                                </p>
                            </div>
                        </div>

                        <div className="flex gap-2 items-center mt-auto">
                            <input 
                                type="number" 
                                className="flex-1 p-2 border border-zinc-200 dark:border-zinc-700 rounded-lg bg-white dark:bg-zinc-800 outline-none focus:ring-2 focus:ring-blue-500 font-mono text-sm"
                                placeholder="Yeni Sayaç"
                                value={currentInput}
                                onChange={(e) => handleInputChange(printer.id, e.target.value)}
                            />
                            <button 
                                onClick={() => handleSingleSave(printer)}
                                disabled={!currentInput}
                                className="p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <Save size={18} />
                            </button>
                        </div>
                    </div>
                 );
              })}
           </div>
        </div>
      )}

      {/* --- HISTORICAL ENTRY VIEW (NEW) --- */}
      {activeTab === 'HISTORY_ENTRY' && (
          <div className="bg-white dark:bg-zinc-900 p-8 rounded-2xl shadow-sm border border-zinc-200 dark:border-zinc-800 max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-2">
              <h3 className="text-xl font-bold text-zinc-800 dark:text-white flex items-center gap-2 mb-2">
                 <History size={24} className="text-orange-500"/> Geçmiş Sayaç Girişi
              </h3>
              <p className="text-sm text-zinc-500 dark:text-zinc-400 mb-6">
                 Buradan Kasım, Aralık gibi geçmiş aylara ait sayaç verilerini girebilirsiniz. 
                 <br/><span className="text-orange-600 dark:text-orange-400 font-bold">Önemli:</span> Bu işlem cihazın şu anki güncel sayacını değiştirmez, sadece grafik ve raporlara veri ekler.
              </p>

              <form onSubmit={handleHistoricalSave} className="space-y-4">
                  <div>
                      <label className="block text-sm font-bold text-zinc-700 dark:text-zinc-300 mb-1">Cihaz Seçin</label>
                      <select 
                        required
                        className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500"
                        value={histPrinterId}
                        onChange={e => setHistPrinterId(e.target.value)}
                      >
                          <option value="">-- Cihaz Seçiniz --</option>
                          {printers.map(p => (
                              <option key={p.id} value={p.id}>
                                  {p.brand} {p.model} - {p.location} ({p.serialNumber})
                              </option>
                          ))}
                      </select>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                          <label className="block text-sm font-bold text-zinc-700 dark:text-zinc-300 mb-1">Tarih</label>
                          <input 
                            required
                            type="date"
                            className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500 cursor-pointer"
                            value={histDate}
                            onChange={e => setHistDate(e.target.value)}
                            onClick={(e) => e.currentTarget.showPicker()}
                          />
                      </div>
                      <div>
                          <label className="block text-sm font-bold text-zinc-700 dark:text-zinc-300 mb-1">O Tarihteki Sayaç</label>
                          <input 
                            required
                            type="number"
                            placeholder="Örn: 10500"
