                                                            <span className="font-mono font-bold">{c.value.toLocaleString()}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}

                                            <div className="mt-2 text-[10px] text-zinc-400 flex justify-between">
                                                <span>Yöntem: {log.recordedBy}</span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        );
                    })()}

                 </div>
             </div>
        </div>
      )}

    </div>
  );
};

