                     )}
                   </div>

                   {/* --- MULTI-COUNTER TOGGLE --- */}
                   <div className="p-4 bg-zinc-50 dark:bg-zinc-800 rounded-xl border border-zinc-200 dark:border-zinc-700 flex items-center justify-between">
                       <div>
                           <label className="font-bold text-zinc-800 dark:text-white flex items-center gap-2">
                               <Palette size={18} className="text-purple-500"/>
                               Renkli / Çift Sayaç?
                           </label>
                           <p className="text-xs text-zinc-500 dark:text-zinc-400 mt-1">
                               Siyah-Beyaz (SB) ve Renkli (RL) olarak iki ayrı sayaç tutar.
                           </p>
                       </div>
                       <label className="relative inline-flex items-center cursor-pointer">
                            <input 
                                type="checkbox" 
                                className="sr-only peer" 
                                checked={formData.isColor || false}
                                onChange={e => setFormData({...formData, isColor: e.target.checked})}
                            />
                            <div className="w-11 h-6 bg-zinc-300 peer-focus:outline-none rounded-full peer dark:bg-zinc-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-600"></div>
                        </label>
                   </div>

                   <div>
                      <label className="block text-sm font-semibold text-zinc-700 dark:text-zinc-300 mb-2">Uyumlu Toner</label>
                      <select 
                          className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white text-base"
                          value={formData.compatibleToner} 
                          onChange={e => setFormData({...formData, compatibleToner: e.target.value})}
                      >
                          <option value="">Seçiniz</option>
                          {config.tonerModels?.map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                   </div>

                   <div>
                      <label className="block text-sm font-semibold text-zinc-700 dark:text-zinc-300 mb-2">Tedarikçi / Servis</label>
                      <select 
                          className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white text-base"
                          value={formData.supplier} 
                          onChange={e => setFormData({...formData, supplier: e.target.value})}
                      >
                          <option value="">Seçiniz</option>
                          {config.suppliers.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                   </div>

                   <div>
                     <label className="block text-sm font-semibold text-zinc-700 dark:text-zinc-300 mb-2">Durum</label>
                     <select 
                          className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white text-base"
                          value={formData.status} 
                          onChange={e => setFormData({...formData, status: e.target.value as PrinterStatus})}
                      >
                          <option value="ACTIVE">Aktif</option>
                          <option value="SPARE">Yedekte</option>
                          <option value="MAINTENANCE">Serviste/Bakımda</option>
                          <option value="BROKEN">Arızalı</option>
                          <option value="SCRAPPED">Hurda</option>
                      </select>
                   </div>

                   <div>
                     <label className="block text-sm font-semibold text-zinc-700 dark:text-zinc-300 mb-2">Bağlı Kullanıcılar (Virgülle ayırın)</label>
                     <textarea 
                        rows={2}
                        className="w-full p-3 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white text-base"
                        placeholder="Ali Yılmaz, Ayşe Demir..."
                        value={connectedUsersInput}
                        onChange={e => setConnectedUsersInput(e.target.value)}
                     />
                   </div>
                </form>
            </div>

            <div className="p-4 border-t border-zinc-100 dark:border-zinc-800 flex gap-3 bg-white dark:bg-zinc-900 pb-[env(safe-area-inset-bottom)]">
                <button type="button" onClick={closeModalViaBack} className="flex-1 py-3.5 bg-zinc-100 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-200 rounded-xl hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors font-semibold active:scale-95">İptal</button>
                <button form="printer-form" type="submit" className="flex-1 py-3.5 bg-gradient-to-r from-emerald-600 to-teal-600 text-white rounded-xl hover:from-emerald-500 hover:to-teal-500 transition-colors font-bold shadow-lg shadow-emerald-500/20 active:scale-95">
                  Kaydet
                </button>
            </div>

          </div>
        </div>
       )}

       {/* HISTORY MODAL WITH STATS & CONFIRMATION OVERLAY (FULL SCREEN ON MOBILE) */}
       {isHistoryModalOpen && selectedPrinterHistory && (
        <div className="fixed inset-0 bg-zinc-100/50 dark:bg-black/50 backdrop-blur-sm z-50 flex items-end md:items-center justify-center md:p-4">
          <div className="bg-white dark:bg-zinc-900 rounded-t-3xl md:rounded-2xl w-full md:max-w-2xl shadow-2xl flex flex-col h-[95vh] md:h-auto md:max-h-[90vh] animate-in slide-in-from-bottom-full duration-300 relative overflow-hidden">

            {/* ... (Confirmation Overlay) ... */}

            {/* Modal Header */}
            <div className="p-6 border-b border-zinc-100 dark:border-zinc-800 flex justify-between items-start bg-zinc-50 dark:bg-zinc-900 rounded-t-3xl md:rounded-t-2xl shrink-0">
              <div>
                <button onClick={closeModalViaBack} className="md:hidden flex items-center text-zinc-500 mb-2">
                    <ChevronLeft size={16} /> Geri
                </button>
                <h3 className="text-xl font-bold text-zinc-800 dark:text-white leading-tight">{selectedPrinterHistory.printer.brand} {selectedPrinterHistory.printer.model}</h3>
                <p className="text-zinc-500 dark:text-zinc-400 text-sm mt-1 mb-2">{selectedPrinterHistory.printer.location} - {selectedPrinterHistory.printer.serialNumber}</p>

                {/* --- QUICK STATUS CHANGER --- */}
                <div className="flex items-center gap-2 mt-2">
                    <span className="text-xs font-bold text-zinc-400 uppercase tracking-wide flex items-center gap-1">
                        <Activity size={12}/> Durum:
                    </span>
                    <select
                        className={`text-xs font-bold uppercase rounded px-2 py-1 outline-none border-none cursor-pointer
                            ${selectedPrinterHistory.printer.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : ''}
                            ${selectedPrinterHistory.printer.status === 'SPARE' ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400' : ''}
                            ${selectedPrinterHistory.printer.status === 'MAINTENANCE' ? 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400' : ''}
                            ${selectedPrinterHistory.printer.status === 'BROKEN' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' : ''}
                            ${selectedPrinterHistory.printer.status === 'SCRAPPED' ? 'bg-zinc-200 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-400' : ''}
                        `}
                        value={selectedPrinterHistory.printer.status}
                        onChange={(e) => handleStatusChange(e.target.value as PrinterStatus)}
                    >
                        <option value="ACTIVE">🟢 Aktif</option>
                        <option value="SPARE">📦 Yedekte</option>
                        <option value="MAINTENANCE">🔧 Serviste</option>
                        <option value="BROKEN">⚠️ Arızalı</option>
                        <option value="SCRAPPED">❌ Hurda</option>
                    </select>
                </div>

              </div>
              <button onClick={closeModalViaBack} className="p-2 bg-white dark:bg-zinc-800 rounded-full shadow-sm hover:bg-zinc-100 dark:hover:bg-zinc-700"><X size={20} className="text-zinc-500"/></button>
            </div>

            <div className="overflow-y-auto p-6 space-y-8 custom-scrollbar pb-24">

                {/* ... (Quick Actions) ... */}
                {/* ... (Scorecards) ... */}

                {/* 2. TONER HISTORY (MOVED UP) */}
                <div>
                  <h4 className="font-bold text-zinc-800 dark:text-white mb-4 flex items-center gap-2">
                    <History size={18} className="text-emerald-500"/> Toner Geçmişi
                  </h4>
                  <div className="space-y-3">
                    {selectedPrinterHistory.tonerLogs.length === 0 && <p className="text-zinc-400 text-sm">Toner değişim kaydı yok.</p>}
                    {selectedPrinterHistory.tonerLogs.map(log => (
                      <div key={log.id} className="flex justify-between items-center p-3 bg-zinc-50 dark:bg-zinc-800/50 rounded-xl border border-zinc-100 dark:border-zinc-800">
                        <div>
                          <p className="font-semibold text-zinc-700 dark:text-zinc-200">{log.tonerModel}</p>
                          <p className="text-xs text-zinc-500 dark:text-zinc-400">{new Date(log.date).toLocaleDateString('tr-TR')}</p>
                        </div>
                        <div className="text-right">
                           {log.type === 'OUT' && <span className="text-xs font-bold text-orange-500 bg-orange-100 dark:bg-orange-900/30 px-2 py-0.5 rounded">Değişim</span>}
                           <p className="text-xs text-zinc-400 mt-1">{log.user}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* 3. SERVICE HISTORY (MOVED UP) */}
                <div>
                   <h4 className="font-bold text-zinc-800 dark:text-white mb-4 flex items-center gap-2">
                    <Truck size={18} className="text-orange-500"/> Servis Geçmişi
                  </h4>
                   <div className="space-y-3">
                    {selectedPrinterHistory.serviceLogs.length === 0 && <p className="text-zinc-400 text-sm">Servis kaydı yok.</p>}
                    {selectedPrinterHistory.serviceLogs.map(srv => (
                      <div key={srv.id} className="p-3 bg-orange-50 dark:bg-orange-900/10 rounded-xl border border-orange-100 dark:border-orange-900/30">
                        <div className="flex justify-between items-start mb-1">
                           <span className="text-xs font-bold text-orange-700 dark:text-orange-400">{new Date(srv.date).toLocaleDateString('tr-TR')}</span>
                           <span className="text-xs font-bold text-zinc-500">{srv.cost > 0 ? `${srv.cost} ₺` : 'Ücretsiz'}</span>
                        </div>
                        <p className="text-sm font-semibold text-zinc-800 dark:text-zinc-200">{srv.issue}</p>
                        <p className="text-xs text-zinc-600 dark:text-zinc-400 mt-1">İşlem: {srv.actionTaken}</p>
                        <p className="text-left text-[10px] text-zinc-400 mt-2">{srv.provider}</p>
                      </div>
                    ))}
                   </div>
                </div>

                {/* --- COUNTER ANALYSIS CHART (MOVED TO BOTTOM) --- */}
                {selectedPrinterHistory.counterLogs.length > 0 && (
                    <div className="bg-white dark:bg-zinc-800 p-6 rounded-2xl shadow-sm border border-zinc-200 dark:border-zinc-700">
                        <div className="flex justify-between items-center mb-6">
                            <h4 className="font-bold text-zinc-800 dark:text-white flex items-center gap-2">
                                <BarChart3 size={20} className="text-blue-500" /> Aylık Sayaç Analizi
                            </h4>
                            <div className="text-right">
                                <p className="text-xs text-zinc-500 dark:text-zinc-400">Son Sayaç</p>
                                <p className="font-bold text-lg text-blue-600 dark:text-blue-400">{selectedPrinterHistory.printer.lastCounter.toLocaleString()}</p>
                            </div>
                        </div>

                        <div className="h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={selectedPrinterHistory.counterLogs.slice(-12)}> {/* Last 12 entries */}
                                    <CartesianGrid strokeDasharray="3 3" stroke="#e4e4e7" vertical={false} opacity={0.5} />
                                    <XAxis 
                                        dataKey="date" 
                                        tickFormatter={(date) => new Date(date).toLocaleDateString('tr-TR', {month: 'short'})}
                                        tick={{fontSize: 10, fill: '#71717a'}}
                                        axisLine={false}
                                        tickLine={false}
                                    />
                                    <YAxis 
                                        tick={{fontSize: 10, fill: '#71717a'}}
                                        axisLine={false}
                                        tickLine={false}
                                        tickFormatter={(val) => val >= 1000 ? `${(val/1000).toFixed(0)}k` : val}
                                    />
                                    <Tooltip 
                                        cursor={{fill: 'transparent'}}
                                        content={({ active, payload, label }) => {
                                            if (active && payload && payload.length) {
                                            const item = payload[0].payload;
                                            return (
                                                <div className="bg-zinc-900 text-white text-xs p-3 rounded-xl shadow-xl border border-zinc-700">
                                                    <p className="font-bold mb-1">{new Date(label).toLocaleDateString('tr-TR', {month: 'long', year: 'numeric'})}</p>
                                                    {/* SHOW HISTORICAL LOCATION NAME */}
                                                    <p className="text-zinc-400 mb-2 italic border-b border-zinc-700 pb-1">{item.printerName}</p>

                                                    <p className="text-emerald-400 font-bold">
                                                        Kullanım: +{payload[0].value?.toLocaleString()}
                                                    </p>
                                                    {item.usageColor > 0 && (
                                                        <div className="mt-1 pt-1 border-t border-zinc-700">
                                                            <p className="text-zinc-400">SB: {item.usageBW || 0}</p>
                                                            <p className="text-purple-400">RL: {item.usageColor || 0}</p>
                                                        </div>
                                                    )}
                                                    <p className="text-zinc-400 mt-1">
                                                        Toplam: {payload[0].payload.currentCounter.toLocaleString()}
                                                    </p>
                                                </div>
                                            );
                                            }
                                            return null;
                                        }}
                                    />
                                    <Bar dataKey="usage" radius={[6, 6, 0, 0]}>
                                        {selectedPrinterHistory.counterLogs.slice(-12).map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill="#10b981" />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                        <p className="text-center text-[10px] text-zinc-400 mt-2">Grafik son 12 kaydın aylık kullanım farklarını (Usage) gösterir.</p>
                    </div>
                )}

            </div>
          </div>
        </div>
       )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, SystemConfig } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Box, MapPin, X, Search, CheckCircle2, AlertTriangle, Truck, Archive, XCircle, ChevronRight, Hash, Printer as PrinterIcon } from 'lucide-react';

interface ModelGroup {
  modelName: string;
  count: number;
  printers: Printer[];
}

export const Inventory: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [modelGroups, setModelGroups] = useState<ModelGroup[]>([]);
  const [config, setConfig] = useState<SystemConfig | null>(null);
  const [selectedModel, setSelectedModel] = useState<ModelGroup | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  // --- HISTORY / BACK BUTTON HANDLER ---
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
        if (selectedModel) {
            setSelectedModel(null);
        }
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedModel]);

  // Close modal on ESC
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && selectedModel) {
          e.preventDefault(); // Stop other browser actions
          window.history.back(); // Trigger popstate to close
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedModel]);

  const loadData = async () => {
    setLoading(true);
    const [allPrinters, sysConfig] = await Promise.all([
      StorageService.getPrinters(),
      StorageService.getConfig()
    ]);

    // Group by Model
    const groups: Record<string, Printer[]> = {};
    allPrinters.forEach(p => {
      const m = p.model || 'Bilinmeyen Model';
      if (!groups[m]) groups[m] = [];
      groups[m].push(p);
    });

    // Convert to Array and Sort by Count (Desc)
    const groupArray: ModelGroup[] = Object.keys(groups).map(key => ({
      modelName: key,
      count: groups[key].length,
      printers: groups[key]
    })).sort((a, b) => b.count - a.count);

    setModelGroups(groupArray);
    setConfig(sysConfig);
    setLoading(false);
  };

  const handleGroupClick = (group: ModelGroup) => {
      // Push history state so back button works
      window.history.pushState({ modal: 'modelDetail' }, '');
      setSelectedModel(group);
  };

  // This function explicitly calls history back, which triggers the popstate listener
  const closeModalViaBack = () => {
      window.history.back();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400"><CheckCircle2 size={12}/> AKTİF</span>;
      case 'SPARE': return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400"><Archive size={12}/> YEDEK</span>;
      case 'MAINTENANCE': return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400"><Truck size={12}/> SERVİSTE</span>;
      case 'BROKEN': return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400"><AlertTriangle size={12}/> ARIZALI</span>;
      default: return <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-zinc-100 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-400"><XCircle size={12}/> HURDA</span>;
    }
  };

  const getModelImage = (model: string) => {
      return config?.modelImages?.[model] || null;
  };

  const filteredGroups = modelGroups.filter(g => 
    g.modelName.toLocaleLowerCase('tr-TR').includes(searchTerm.toLocaleLowerCase('tr-TR'))
  );

  if (loading) return <LoadingScreen message="Envanter analizi yapılıyor..." />;

  return (
    <div className="space-y-6 pb-20 h-full flex flex-col">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-zinc-900 p-6 rounded-2xl shadow-sm border border-zinc-100 dark:border-zinc-800">
        <div>
           <h2 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
             <Box size={28} className="text-blue-600" />
             Model Envanteri
           </h2>
           <p className="text-zinc-500 dark:text-zinc-400 text-sm mt-1">
             Hangi modelden kaç adet cihaz olduğunu ve dağılımlarını inceleyin.
           </p>
        </div>

        <div className="relative w-full md:w-64">
           <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
           <input 
             type="text" 
             placeholder="Model ara..."
             className="w-full pl-10 p-3 bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 text-zinc-800 dark:text-white"
             value={searchTerm}
             onChange={(e) => setSearchTerm(e.target.value)}
           />
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5 overflow-y-auto pb-4">
         {filteredGroups.map((group) => {
            const imgUrl = getModelImage(group.modelName);
            const total = modelGroups.reduce((acc, curr) => acc + curr.count, 0);
            const percentage = Math.round((group.count / total) * 100);

            return (
               <div 
                 key={group.modelName}
                 onClick={() => handleGroupClick(group)}
                 className="group bg-white dark:bg-zinc-900 rounded-2xl p-5 shadow-sm border border-zinc-200 dark:border-zinc-800 hover:shadow-xl hover:border-blue-400/50 dark:hover:border-blue-600/50 transition-all cursor-pointer relative overflow-hidden flex flex-col"
               >
                  {/* Background decoration */}
                  <div className="absolute -right-6 -top-6 w-24 h-24 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/10 dark:to-indigo-900/10 rounded-full group-hover:scale-150 transition-transform duration-500"></div>

                  <div className="flex justify-between items-start mb-4 relative z-10">
                      <div className="bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 px-3 py-1 rounded-lg text-xs font-bold">
                         {percentage}% Pay
                      </div>
                      {imgUrl ? (
                          <div className="w-12 h-12 bg-white rounded-lg p-1 border border-zinc-100 shadow-sm">
                             <img src={imgUrl} alt={group.modelName} className="w-full h-full object-contain" />
                          </div>
                      ) : (
                          <PrinterIcon className="text-zinc-300" size={32} />
                      )}
                  </div>

                  <div className="mt-auto relative z-10">
                      <h3 className="text-xl font-bold text-zinc-800 dark:text-white mb-1 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                          {group.modelName}
                      </h3>
                      <div className="flex items-end gap-2">
                          <span className="text-4xl font-extrabold text-zinc-900 dark:text-white tracking-tighter">
                              {group.count}
                          </span>
                          <span className="text-sm font-medium text-zinc-500 dark:text-zinc-400 mb-1.5">Adet</span>
                      </div>
                  </div>

                  <div className="mt-4 w-full bg-zinc-100 dark:bg-zinc-800 h-1.5 rounded-full overflow-hidden">
                      <div className="bg-gradient-to-r from-blue-500 to-indigo-500 h-full rounded-full" style={{ width: `${percentage}%` }}></div>
                  </div>
               </div>
            );
         })}
      </div>

      {/* DETAIL DRAWER / MODAL */}
      {selectedModel && (
         <div className="fixed inset-0 z-50 flex justify-end">
             {/* Backdrop */}
             <div 
               className="absolute inset-0 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300"
               onClick={closeModalViaBack}
             ></div>

             {/* Slide-over Panel */}
             <div className="relative w-full max-w-md bg-white dark:bg-zinc-900 h-full shadow-2xl border-l border-zinc-200 dark:border-zinc-800 animate-in slide-in-from-right duration-300 flex flex-col">

                 {/* Header */}
                 <div className="p-6 border-b border-zinc-100 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 flex justify-between items-start">
                     <div>
                        <h3 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
                           {selectedModel.modelName}
                        </h3>
                        <p className="text-zinc-500 dark:text-zinc-400 mt-1">
                           Toplam {selectedModel.count} adet cihaz listeleniyor
                        </p>
                     </div>
                     <button 
                       onClick={closeModalViaBack}
                       className="p-2 bg-white dark:bg-zinc-800 rounded-full hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors shadow-sm"
                     >
                        <X size={20} className="text-zinc-500"/>
                     </button>
                 </div>

                 {/* Scrollable Content */}
                 <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-zinc-50/50 dark:bg-black/50">
                    {selectedModel.printers.map((printer) => (
                       <div key={printer.id} className="bg-white dark:bg-zinc-800 p-4 rounded-xl border border-zinc-100 dark:border-zinc-700 shadow-sm flex flex-col gap-2 hover:border-blue-400 dark:hover:border-blue-500 transition-colors">
                           <div className="flex justify-between items-start">
                               <div className="flex items-center gap-2">
                                   <div className="p-2 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-lg">
                                      <MapPin size={18} />
                                   </div>
                                   <div>
                                       <h4 className="font-bold text-zinc-800 dark:text-white text-sm">{printer.location}</h4>
                                       <p className="text-xs text-zinc-500 dark:text-zinc-400">{printer.floor}</p>
                                   </div>
                               </div>
                               {getStatusBadge(printer.status)}
                           </div>

                           <div className="flex items-center gap-4 mt-2 pt-2 border-t border-zinc-100 dark:border-zinc-700 text-xs text-zinc-500 dark:text-zinc-400">
                               <div className="flex items-center gap-1 bg-zinc-50 dark:bg-zinc-900/50 px-2 py-1 rounded">
                                   <Hash size={12} />
                                   <span className="font-mono">{printer.serialNumber}</span>
                               </div>
                               {printer.ipAddress && (
                                   <div className="font-mono">{printer.ipAddress}</div>
                               )}
                           </div>
                       </div>
                    ))}
                 </div>

                 {/* Footer */}
                 <div className="p-4 bg-white dark:bg-zinc-900 border-t border-zinc-100 dark:border-zinc-800">
                    <button 
                      onClick={closeModalViaBack}
                      className="w-full py-3 bg-zinc-100 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-300 font-bold rounded-xl hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors"
                    >
                       Kapat
                    </button>
                 </div>

             </div>
         </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, CounterLog, User } from '../types';
import { Calculator, Upload, Save, AlertTriangle, FileSpreadsheet, CheckCircle2, Search, ArrowRight, ArrowUp, RefreshCw, X, Loader2, Globe, History, Calendar, TrendingUp, Droplet, PlusCircle, CalendarDays, Usb, Layers, MinusCircle } from 'lucide-react';
import { LoadingScreen } from './LoadingScreen';

interface CounterManagementProps {
  user: { name: string };
}

export const CounterManagement: React.FC<CounterManagementProps> = ({ user }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [allLogs, setAllLogs] = useState<CounterLog[]>([]); // Store all logs
  const [loading, setLoading] = useState(true);
  const [filterTerm, setFilterTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'LIST' | 'IMPORT' | 'HISTORY_ENTRY'>('LIST');
  const [isSaving, setIsSaving] = useState(false);

  // History Modal State
  const [selectedHistoryPrinter, setSelectedHistoryPrinter] = useState<Printer | null>(null);

  // Input States for manual entry (Dictionary key: printerId_TYPE)
  const [inputValues, setInputValues] = useState<Record<string, string>>({});

  // Historical Entry States
  const [histPrinterId, setHistPrinterId] = useState('');
  const [histDate, setHistDate] = useState('');

  // Entry Modes: SIMPLE (Total only), STD (BW/Color), ADVANCED (Custom dynamic)
  const [histEntryMode, setHistEntryMode] = useState<'SIMPLE' | 'STD' | 'ADVANCED'>('SIMPLE');

  // Standard Inputs
  const [histValueTotal, setHistValueTotal] = useState('');
  const [histValueBW, setHistValueBW] = useState('');
  const [histValueColor, setHistValueColor] = useState('');

  // Advanced Inputs
  const [customCounterCount, setCustomCounterCount] = useState<number>(2);
  const [customCounters, setCustomCounters] = useState<{label: string, value: string}[]>([
      { label: 'A4 Siyah', value: '' },
      { label: 'A4 Renkli', value: '' }
  ]);

  // Import States
  const [parsedData, setParsedData] = useState<any[]>([]);
  const [matchResults, setMatchResults] = useState<{matched: any[], unmatched: any[]}>({matched: [], unmatched: []});
  const [importError, setImportError] = useState<string | null>(null);

  useEffect(() => {
    fetchData();
  }, []);

  // --- HISTORY / BACK BUTTON HANDLER ---
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
        if (selectedHistoryPrinter) {
            setSelectedHistoryPrinter(null);
        }
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedHistoryPrinter]);

  // Close modal on ESC
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && selectedHistoryPrinter) {
          window.history.back();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedHistoryPrinter]);

  // Watch for Printer Selection changes to set default mode
  useEffect(() => {
      const printer = printers.find(p => p.id === histPrinterId);
      if (printer) {
          if (printer.isColor) setHistEntryMode('STD');
          else setHistEntryMode('SIMPLE');
      }
  }, [histPrinterId, printers]);

  // Watch for Custom Count changes
  useEffect(() => {
      setCustomCounters(prev => {
          const newArr = [...prev];
          if (customCounterCount > prev.length) {
              // Add rows
              for (let i = prev.length; i < customCounterCount; i++) {
                  newArr.push({ label: '', value: '' });
              }
          } else {
              // Remove rows
              return newArr.slice(0, customCounterCount);
          }
          return newArr;
      });
  }, [customCounterCount]);

  const fetchData = async () => {
    setLoading(true);
    const [p, l] = await Promise.all([
        StorageService.getPrinters(),
        StorageService.getCounterLogs()
    ]);
    setPrinters(p);
    setAllLogs(l);
    setLoading(false);
  };

  const openHistoryModal = (printer: Printer) => {
      window.history.pushState({ modal: 'counterHistory' }, '');
      setSelectedHistoryPrinter(printer);
  };

  const closeModalViaBack = () => {
      window.history.back();
  };

  // --- MANUAL ENTRY LOGIC ---
  const handleInputChange = (key: string, value: string) => {
    setInputValues(prev => ({ ...prev, [key]: value }));
  };

  const handleSingleSave = async (printer: Printer) => {
    let newValTotal = 0;
    let newValBW = 0;
    let newValColor = 0;

    if (printer.isColor) {
        const bwStr = inputValues[`${printer.id}_BW`];
        const colorStr = inputValues[`${printer.id}_COLOR`];

        if (!bwStr && !colorStr) return;

        newValBW = parseInt(bwStr || '0');
        newValColor = parseInt(colorStr || '0');
        newValTotal = newValBW + newValColor; 
    } else {
        const valStr = inputValues[`${printer.id}_TOTAL`];
        if (!valStr) return;
        newValTotal = parseInt(valStr);
    }

    if (isNaN(newValTotal)) {
        alert('Lütfen geçerli bir sayı giriniz.');
        return;
    }

    if (newValTotal < printer.lastCounter) {
        if (!confirm(`UYARI: Girdiğiniz toplam sayaç (${newValTotal}), eski sayaçtan (${printer.lastCounter}) daha düşük. Cihaz sıfırlanmış olabilir mi? Yine de kaydetmek istiyor musunuz?`)) {
            return;
        }
    }

    try {
        await saveCounterLog({
            printer, 
            currentCounter: newValTotal, 
            method: 'Manuel Giriş', 
            updateMaster: true, 
            bw: printer.isColor ? newValBW : undefined, 
            color: printer.isColor ? newValColor : undefined
        });
        alert('Sayaç başarıyla güncellendi.');

        setInputValues(prev => {
            const copy = {...prev};
            delete copy[`${printer.id}_TOTAL`];
            delete copy[`${printer.id}_BW`];
            delete copy[`${printer.id}_COLOR`];
            return copy;
        });
        fetchData();
    } catch (error) {
        console.error(error);
        alert('Kayıt sırasında bir hata oluştu.');
    }
  };

  // --- HISTORICAL ENTRY LOGIC (UPDATED FOR ADVANCED MODE) ---
  const handleHistoricalSave = async (e: React.FormEvent) => {
      e.preventDefault();

      const printer = printers.find(p => p.id === histPrinterId);
      if (!printer) return;

      let totalVal = 0;
      let bwVal: number | undefined = undefined;
      let colorVal: number | undefined = undefined;
      let finalCustomCounters: { label: string; value: number }[] | undefined = undefined;

      if (histEntryMode === 'ADVANCED') {
          // Validate custom counters
          const validCounters = customCounters.filter(c => c.label.trim() !== '' && c.value !== '');
          if (validCounters.length === 0) {
              alert("Lütfen en az bir sayaç tanımı ve değeri giriniz.");
              return;
          }

          finalCustomCounters = validCounters.map(c => ({
              label: c.label,
              value: parseInt(c.value)
          }));

          // Calculate Total from custom fields
          totalVal = finalCustomCounters.reduce((acc, curr) => acc + curr.value, 0);

      } else if (histEntryMode === 'STD') {
          if (!histValueBW || !histValueColor || !histDate) {
              alert("Lütfen Siyah ve Renkli sayaçları doldurun.");
              return;
          }
          bwVal = parseInt(histValueBW);
          colorVal = parseInt(histValueColor);
          totalVal = bwVal + colorVal;
      } else {
          // SIMPLE
          if (!histValueTotal || !histDate) {
              alert("Lütfen sayaç değerini doldurun.");
              return;
          }
          totalVal = parseInt(histValueTotal);
      }

      const logDate = new Date(histDate);

      // Simple previous Log finding to calculate usage (Approximation)
      const logsForPrinter = allLogs
          .filter(l => l.printerId === printer.id && new Date(l.date) < logDate)
          .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

      const prevCounter = logsForPrinter.length > 0 ? logsForPrinter[0].currentCounter : 0;
      const usage = totalVal - prevCounter;

      try {
          // Log object
          const log: CounterLog = {
            id: '',
            printerId: printer.id,
            // CAPTURE HISTORICAL LOCATION SNAPSHOT
            printerName: `${printer.brand} ${printer.model} (${printer.location})`,
            serialNumber: printer.serialNumber,
            date: logDate.toISOString(),
            previousCounter: prevCounter,
            currentCounter: totalVal,
            usage: usage > 0 ? usage : 0,
            recordedBy: `${user.name} (Geçmiş Veri)`,
            currentBW: bwVal,
            currentColor: colorVal,
            customCounters: finalCustomCounters, // Save array
            // Usage calculation for standard fields
            usageBW: (bwVal !== undefined && logsForPrinter[0]?.currentBW) ? Math.max(0, bwVal - logsForPrinter[0].currentBW) : undefined,
            usageColor: (colorVal !== undefined && logsForPrinter[0]?.currentColor) ? Math.max(0, colorVal - logsForPrinter[0].currentColor) : undefined
          };

          await StorageService.addCounterLog(log, false);

          alert("Geçmiş veri başarıyla eklendi.");
          // Reset fields
          setHistValueTotal('');
          setHistValueBW('');
          setHistValueColor('');
          setCustomCounters([{ label: '', value: '' }, { label: '', value: '' }]);
          setCustomCounterCount(2);
          fetchData(); 
      } catch (error) {
          console.error(error);
          alert("Hata oluştu: " + error);
      }
  };

  interface SaveLogParams {
      printer: Printer;
      currentCounter: number;
      method: string;
      updateMaster: boolean;
      bw?: number;
      color?: number;
      customCounters?: { label: string; value: number }[];
  }

  const saveCounterLog = async ({ printer, currentCounter, method, updateMaster, bw, color, customCounters }: SaveLogParams) => {
     const usage = currentCounter - printer.lastCounter;

     let usageBW = undefined;
     let usageColor = undefined;

     if (bw !== undefined && printer.lastCounterBW !== undefined) {
         usageBW = Math.max(0, bw - printer.lastCounterBW);
     }
     if (color !== undefined && printer.lastCounterColor !== undefined) {
         usageColor = Math.max(0, color - printer.lastCounterColor);
     }

     const log: CounterLog = {
         id: '',
         printerId: printer.id,
         // CAPTURE HISTORICAL LOCATION SNAPSHOT
         printerName: `${printer.brand} ${printer.model} (${printer.location})`,
         serialNumber: printer.serialNumber,
         date: new Date().toISOString(),
         previousCounter: printer.lastCounter,
         currentCounter: currentCounter,
         usage: usage > 0 ? usage : 0, 
         recordedBy: `${user.name} (${method})`,
         currentBW: bw,
         currentColor: color,
         usageBW,
         usageColor,
         customCounters
     };

     await StorageService.addCounterLog(log, updateMaster);
  };

  const handleCustomCounterChange = (index: number, field: 'label' | 'value', val: string) => {
      setCustomCounters(prev => {
          const newArr = [...prev];
          newArr[index] = { ...newArr[index], [field]: val };
          return newArr;
      });
  };

  // ... (Import Logic remains the same) ...
  // --- CSV IMPORT LOGIC (IMPROVED FOR CANON + IP INTEGRATION) ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    setImportError(null);
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
        const text = evt.target?.result as string;
        if (!text) {
            setImportError("Dosya boş veya okunamadı.");
            return;
        }
        parseCSV(text);
    };
    reader.onerror = () => {
        setImportError("Dosya okuma hatası.");
    };
    reader.readAsText(file, 'UTF-8');
    e.target.value = '';
  };

  const parseCSV = (text: string) => {
      const lines = text.split(/\r\n|\n|\r/);
      if (lines.length < 2) { setImportError("Dosya içeriği çok kısa."); return; }

      let headerRowIndex = -1;
      let delimiter = ',';

      for (let i = 0; i < Math.min(lines.length, 25); i++) {
          const line = lines[i].toLowerCase();
          if (line.includes('serial') || line.includes('seri') || line.includes('mc_serial')) {
              headerRowIndex = i;
              const semicolonCount = (line.match(/;/g) || []).length;
              const commaCount = (line.match(/,/g) || []).length;
              const tabCount = (line.match(/\t/g) || []).length;
              if (tabCount > semicolonCount && tabCount > commaCount) delimiter = '\t';
              else if (semicolonCount > commaCount) delimiter = ';';
              else delimiter = ',';
              break;
          }
      }

      if (headerRowIndex === -1) { setImportError('Seri No başlığı bulunamadı.'); return; }

      const headers = lines[headerRowIndex].split(delimiter).map(h => h.trim().toLowerCase().replace(/^"|"$/g, '').replace(/^\ufeff/, ''));
      const serialIndex = headers.findIndex(h => h.includes('serial') || h.includes('seri'));
      const totalCounterIndex = headers.findIndex(h => h.includes('total') || h.includes('toplam') || h.includes('counter') || h.includes('sayaç') || h.includes('101:'));
      const ipIndex = headers.findIndex(h => h.includes('ip address') || h.includes('ip adresi') || h.includes('ipv4') || h.includes('address') || h.includes('adres'));

      if (serialIndex === -1 || totalCounterIndex === -1) { setImportError('Gerekli sütunlar eksik.'); return; }

      const results: any[] = [];
      let successCount = 0;

      for (let i = headerRowIndex + 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const cols = line.split(delimiter).map(c => c.trim().replace(/^"|"$/g, ''));
          const serial = cols[serialIndex];
          const counterStr = cols[totalCounterIndex];
          const ipStr = ipIndex !== -1 ? cols[ipIndex] : null;

          if (serial && counterStr) {
              const cleanCounter = parseInt(counterStr.replace(/\D/g, ''));
              if (!isNaN(cleanCounter) && cleanCounter > 0) {
                  results.push({ serial, counter: cleanCounter, ip: ipStr });
                  successCount++;
              }
          }
      }

      if (successCount === 0) { setImportError("Veri bulunamadı."); return; }
      setParsedData(results);
      performMatching(results);
  };

  const normalizeSerial = (s: string) => s ? s.replace(/[^a-zA-Z0-9]/g, '').toLowerCase() : '';

  const performMatching = (data: any[]) => {
      const matched: any[] = [];
      const unmatched: any[] = [];

      data.forEach(item => {
          const itemSerialNorm = normalizeSerial(item.serial);
          const printer = printers.find(p => normalizeSerial(p.serialNumber) === itemSerialNorm);

          if (printer) {
              const needsIpUpdate = item.ip && item.ip !== printer.ipAddress && item.ip.length > 6;
              matched.push({ printer, newCounter: item.counter, diff: item.counter - printer.lastCounter, newIp: item.ip, needsIpUpdate });
          } else {
              unmatched.push(item);
          }
      });
      setMatchResults({ matched, unmatched });
  };

  const confirmImport = async () => {
      if (matchResults.matched.length === 0) return;
      if (!confirm(`${matchResults.matched.length} adet cihazın sayacı güncellenecek.`)) return;
      setIsSaving(true);

      let processedCount = 0;
      for (const item of matchResults.matched) {
          try {
             await saveCounterLog({ printer: item.printer, currentCounter: item.newCounter, method: 'Canon Import', updateMaster: true });
             if (item.needsIpUpdate) {
                const updatedPrinter = { ...item.printer, ipAddress: item.newIp, lastCounter: item.newCounter };
                await StorageService.updatePrinter(updatedPrinter);
             }
             processedCount++;
          } catch (e) { console.error(e); }
      }

      setIsSaving(false);
      alert(`İşlem Tamamlandı. Başarılı: ${processedCount}`);
      setMatchResults({ matched: [], unmatched: [] });
      setParsedData([]);
      setActiveTab('LIST');
      fetchData(); 
  };

  const resetImport = () => { setParsedData([]); setMatchResults({matched: [], unmatched: []}); setImportError(null); };

  // UPDATED FILTER LOGIC FOR TURKISH CHARACTERS
  const filteredPrinters = printers.filter(p => {
      const searchLower = filterTerm.toLocaleLowerCase('tr-TR');
      return (
        p.location.toLocaleLowerCase('tr-TR').includes(searchLower) || 
        p.model.toLocaleLowerCase('tr-TR').includes(searchLower) ||
        p.serialNumber.toLocaleLowerCase('tr-TR').includes(searchLower)
      );
  });

  if (loading) return <LoadingScreen message="Sayaç verileri yükleniyor..." />;

  return (
    <div className="space-y-6 pb-20">
       <div className="flex justify-between items-center bg-white dark:bg-zinc-900 p-4 rounded-2xl shadow-sm border border-zinc-100 dark:border-zinc-800">
        <div>
          <h2 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
             <Calculator size={24} className="text-blue-500" />
             Sayaç (Endeks) Yönetimi
          </h2>
          <p className="text-sm text-zinc-500 dark:text-zinc-400">Excel/CSV ile toplu sayaç ve IP güncelleme</p>
        </div>
        <button onClick={fetchData} className="p-2 bg-zinc-100 dark:bg-zinc-800 rounded-lg hover:bg-zinc-200 transition-colors">
            <RefreshCw size={20} className="text-zinc-500"/>
        </button>
      </div>

      {/* TABS */}
      <div className="flex space-x-2 bg-white dark:bg-zinc-900 p-1 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 w-fit overflow-x-auto">
        <button 
          onClick={() => setActiveTab('LIST')}
          disabled={isSaving}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'LIST' ? 'bg-zinc-900 dark:bg-zinc-700 text-white' : 'text-zinc-600 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800'}`}
        >
          Güncel Giriş
        </button>
        <button 
          onClick={() => setActiveTab('IMPORT')}
          disabled={isSaving}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white' : 'text-blue-700 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20'}`}
        >
          <Upload size={16} /> Excel/CSV
        </button>
        <button 
          onClick={() => setActiveTab('HISTORY_ENTRY')}
          disabled={isSaving}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'HISTORY_ENTRY' ? 'bg-orange-600 text-white' : 'text-orange-700 dark:text-orange-400 hover:bg-orange-50 dark:hover:bg-orange-900/20'}`}
        >
          <CalendarDays size={16} /> Geçmiş Veri Ekle
        </button>
      </div>

      {/* --- LIST VIEW --- */}
      {activeTab === 'LIST' && (
        <div className="space-y-4">
           {/* Search */}
           <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
              <input 
                 type="text" 
                 placeholder="Cihaz ara (Model, Konum, Seri No)..." 
                 className="w-full pl-10 p-3 rounded-xl border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-500"
                 value={filterTerm}
                 onChange={e => setFilterTerm(e.target.value)}
              />
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredPrinters.map(printer => {
                 // For Color printers, check logic slightly differently
                 let currentInputTotal = '';
                 let inputValid = false;

                 if (printer.isColor) {
                     const bw = inputValues[`${printer.id}_BW`] || '';
                     const col = inputValues[`${printer.id}_COLOR`] || '';
                     inputValid = (bw !== '' || col !== ''); // At least one entry
                     currentInputTotal = (parseInt(bw || '0') + parseInt(col || '0')).toString();
                 } else {
                     currentInputTotal = inputValues[`${printer.id}_TOTAL`] || '';
                     inputValid = currentInputTotal !== '';
                 }

                 const diff = currentInputTotal ? (parseInt(currentInputTotal) - printer.lastCounter) : 0;

                 return (
                    <div key={printer.id} className="bg-white dark:bg-zinc-900 p-4 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 flex flex-col gap-3">
                        <div className="flex justify-between items-start">
                           <div>
                              <h4 className="font-bold text-zinc-800 dark:text-white">{printer.model}</h4>
                              <div className="flex flex-col gap-1">
                                  <p className="text-xs text-zinc-500 dark:text-zinc-400">{printer.location}</p>

                                  {/* Connection Type Indicator */}
                                  <div className="flex items-center gap-1">
                                      {printer.connectionType === 'Network' ? (
