const handleDbError = (error: any, context: string) => {
  console.error(`Error in ${context}:`, error);
  if (error.code === 'permission-denied') {
    alert('HATA: Veritabanı yazma izni reddedildi!');
  } else {
    alert(`İşlem sırasında hata oluştu: ${error.message}`);
  }
  throw error;
};

const cleanData = (data: any) => {
  const newObj = { ...data };
  Object.keys(newObj).forEach(key => {
    if (newObj[key] === undefined) {
      delete newObj[key];
    }
  });
  return newObj;
};

export const StorageService = {

  // --- AUTH ---
  getUsers: async (): Promise<User[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.USERS));
      const users = snapshot.docs.map(doc => ({ ...doc.data() as any } as User));
      if (users.length === 0) {
        const defaultAdmin: User = { username: 'admin', name: 'Sistem Yöneticisi', role: 'admin', password: 'yasam' }; 
        await addDoc(collection(db, COLLECTIONS.USERS), defaultAdmin);
        return [defaultAdmin];
      }
      return users;
    } catch (error) {
      return [];
    }
  },

  login: async (username: string, password: string): Promise<User | null> => {
    const users = await StorageService.getUsers();
    const user = users.find(u => u.username.toLowerCase() === username.toLowerCase() && u.password === password);
    if (user) {
      const { password, ...safeUser } = user;
      return safeUser as User;
    }
    return null;
  },

  // --- PRINTERS ---
  getPrinters: async (): Promise<Printer[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.PRINTERS));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Printer));
    } catch (e) {
      return [];
    }
  },

  addPrinter: async (printer: Printer) => {
    try {
      const printers = await StorageService.getPrinters();

      // Auto-generate shortCode if missing
      if (!printer.shortCode) {
        const codes = printers.map(p => parseInt(p.shortCode || '1000')).filter(n => !isNaN(n));
        const maxCode = codes.length > 0 ? Math.max(...codes) : 1000;
        printer.shortCode = (maxCode + 1).toString();
      }

      const { id, ...data } = printer; 
      const docRef = await addDoc(collection(db, COLLECTIONS.PRINTERS), cleanData(data));
      return docRef.id;
    } catch (e) {
      handleDbError(e, 'addPrinter');
      return '';
    }
  },

  updatePrinter: async (printer: Printer) => {
    if (!printer.id) return;
    try {
      const printerRef = doc(db, COLLECTIONS.PRINTERS, printer.id);
      const { id, ...data } = printer;
      await updateDoc(printerRef, cleanData(data));
    } catch (e) {
      handleDbError(e, 'updatePrinter');
    }
  },

  deletePrinter: async (printerId: string) => {
    try {
      await deleteDoc(doc(db, COLLECTIONS.PRINTERS, printerId));
    } catch (e) {
      handleDbError(e, 'deletePrinter');
    }
  },

  findPrinterByShortCode: async (code: string): Promise<Printer | null> => {
    try {
      const q = query(collection(db, COLLECTIONS.PRINTERS), where('shortCode', '==', code.trim()));
      const snapshot = await getDocs(q);
      if (snapshot.empty) return null;
      const doc = snapshot.docs[0];
      return { id: doc.id, ...doc.data() as any } as Printer;
    } catch (e) {
      return null;
    }
  },

  // --- STOCKS ---
  getStocks: async (): Promise<TonerStock[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.STOCKS));
      return snapshot.docs.map(doc => ({ ...doc.data() as any } as TonerStock));
    } catch (e) {
      return [];
    }
  },

  saveStock: async (stock: TonerStock) => {
    try {
      const q = query(collection(db, COLLECTIONS.STOCKS));
      const snapshot = await getDocs(q);
      const existingDoc = snapshot.docs.find(d => (d.data() as TonerStock).modelName === stock.modelName);

      if (existingDoc) {
        await updateDoc(doc(db, COLLECTIONS.STOCKS, existingDoc.id), { quantity: stock.quantity });
      } else {
        await addDoc(collection(db, COLLECTIONS.STOCKS), cleanData(stock));
      }
    } catch (e) {
      handleDbError(e, 'saveStock');
    }
  },

  // --- LOGS ---
  getLogs: async (): Promise<StockLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.LOGS), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as StockLog));
    } catch (e) {
      return [];
    }
  },

  addLog: async (log: StockLog) => {
    try {
      const { id, ...data } = log;
      await addDoc(collection(db, COLLECTIONS.LOGS), cleanData(data));
    } catch (e) {
      handleDbError(e, 'addLog');
    }
  },

  // --- SERVICES ---
  getServiceRecords: async (): Promise<ServiceRecord[]> => {
     try {
      const q = query(collection(db, COLLECTIONS.SERVICES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ServiceRecord));
     } catch (e) {
       return [];
     }
  },

  addServiceRecord: async (record: ServiceRecord) => {
    try {
      const { id, ...data } = record;
      await addDoc(collection(db, COLLECTIONS.SERVICES), cleanData(data));
    } catch (e) {
      handleDbError(e, 'addServiceRecord');
    }
  },

  // --- COUNTERS ---
  getCounterLogs: async (): Promise<CounterLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.COUNTERS), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as CounterLog));
    } catch (e) {
      return [];
    }
  },

  addCounterLog: async (log: CounterLog, updateMasterRecord: boolean = true) => {
    try {
       const { id, ...data } = log;
       await addDoc(collection(db, COLLECTIONS.COUNTERS), cleanData(data));
       if (updateMasterRecord) {
         const printerRef = doc(db, COLLECTIONS.PRINTERS, log.printerId);
         const updatePayload: any = { lastCounter: log.currentCounter };
         if (log.currentBW !== undefined) updatePayload.lastCounterBW = log.currentBW;
         if (log.currentColor !== undefined) updatePayload.lastCounterColor = log.currentColor;
         await updateDoc(printerRef, cleanData(updatePayload));
       }
    } catch (e) {
      handleDbError(e, 'addCounterLog');
    }
  },

  // --- CONFIG ---
  getConfig: async (): Promise<SystemConfig> => {
    try {
      const docRef = doc(db, COLLECTIONS.CONFIG, 'main_config');
      const docSnap = await getDoc(docRef);
      if (docSnap.exists()) {
        return { ...INITIAL_CONFIG, ...docSnap.data() as SystemConfig };
      } else {
        await setDoc(docRef, INITIAL_CONFIG);
        return INITIAL_CONFIG;
      }
    } catch (e) {
      return INITIAL_CONFIG;
    }
  },

  saveConfig: async (config: SystemConfig) => {
    try {
      const docRef = doc(db, COLLECTIONS.CONFIG, 'main_config');
      await setDoc(docRef, cleanData(config));
    } catch (e) {
      handleDbError(e, 'saveConfig');
    }
  },

  runMaintenance: async () => {
     await StorageService.getConfig();
  }
};

import React, { useEffect, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { Camera, X, Zap, Hash, ArrowRight, Loader2 } from 'lucide-react';
import { StorageService } from '../services/storage';

export const QrScanner: React.FC = () => {
  const [scanResult, setScanResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [manualCode, setManualCode] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  useEffect(() => {
    const html5QrCode = new Html5Qrcode("reader");
    const config = { 
        fps: 15, 
        qrbox: { width: 250, height: 250 },
        aspectRatio: 1.0
    };

    html5QrCode.start(
      { facingMode: "environment" }, 
      config,
      (decodedText) => {
        setScanResult(decodedText);
        html5QrCode.stop().then(() => {
             handleScanSuccess(decodedText);
        }).catch(err => console.error(err));
      },
      (errorMessage) => {}
    ).catch(err => {
      setError("Kamera başlatılamadı. Lütfen izinleri kontrol edin.");
    });

    return () => {
       if (html5QrCode.isScanning) {
           html5QrCode.stop().catch(err => console.error("Error stopping scanner", err));
       }
       html5QrCode.clear();
    };
  }, []);

  const handleScanSuccess = (url: string) => {
      try {
          const urlObj = new URL(url);
          const pid = urlObj.searchParams.get("pid");
          const sc = urlObj.searchParams.get("sc");

          if (pid) {
              window.location.href = window.location.origin + window.location.pathname + "?pid=" + pid;
          } else if (sc) {
              handleManualSubmit(sc);
          } else {
              setError("Geçersiz QR Kod.");
          }
      } catch (e) {
          setError("QR Kod okunamadı.");
      }
  };

  const handleManualSubmit = async (codeToSearch?: string) => {
      const code = codeToSearch || manualCode;
      if (!code) return;

      setIsSearching(true);
      setError(null);

      try {
          const printer = await StorageService.findPrinterByShortCode(code);
          if (printer) {
              window.location.href = window.location.origin + window.location.pathname + "?pid=" + printer.id;
          } else {
              setError("Cihaz bulunamadı. Lütfen kodu kontrol edin.");
              setIsSearching(false);
          }
      } catch (e) {
          setError("Bir hata oluştu.");
          setIsSearching(false);
      }
  };

  return (
    <div className="flex flex-col h-full max-w-md mx-auto animate-in fade-in duration-500">

      {/* Scanner Viewport */}
      <div className="relative w-full bg-black aspect-square overflow-hidden rounded-2xl shadow-2xl border-4 border-zinc-900">
          <div id="reader" className="w-full h-full object-cover"></div>

          {!scanResult && !error && (
              <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                  <div className="w-64 h-64 border-2 border-emerald-500/30 rounded-3xl relative">
                      <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-emerald-500 rounded-tl-xl"></div>
                      <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-emerald-500 rounded-tr-xl"></div>
                      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-emerald-500 rounded-bl-xl"></div>
                      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-emerald-500 rounded-br-xl"></div>
                      <div className="absolute top-1/2 left-0 w-full h-0.5 bg-red-500/50 animate-pulse"></div>
                  </div>
              </div>
          )}

          {scanResult && (
              <div className="absolute inset-0 bg-emerald-900/90 flex flex-col items-center justify-center text-white p-8 text-center">
                  <Zap size={48} className="text-yellow-400 mb-4 animate-bounce" />
                  <h3 className="text-2xl font-bold mb-2">Okundu!</h3>
              </div>
          )}
      </div>

      {/* Manual Entry Section */}
      <div className="mt-6 space-y-4">
          <div className="flex flex-col items-center gap-2">
              <span className="text-xs font-bold text-zinc-400 uppercase tracking-widest">VEYA EL İLE GİRİN</span>
              <div className="flex w-full gap-2">
                  <div className="relative flex-1">
                      <Hash className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
                      <input 
                        type="number" 
                        pattern="[0-9]*"
                        inputMode="numeric"
                        placeholder="Hızlı Kod (Örn: 1005)"
                        className="w-full pl-10 pr-4 py-4 rounded-xl border-2 border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-white outline-none focus:border-emerald-500 transition-all font-bold text-lg"
                        value={manualCode}
                        onChange={(e) => setManualCode(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleManualSubmit()}
                      />
                  </div>
                  <button 
                    onClick={() => handleManualSubmit()}
                    disabled={!manualCode || isSearching}
                    className="bg-emerald-600 hover:bg-emerald-500 text-white p-4 rounded-xl shadow-lg disabled:opacity-50 transition-all"
                  >
                      {isSearching ? <Loader2 className="animate-spin" /> : <ArrowRight />}
                  </button>
              </div>
          </div>

          {error && (
              <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4 rounded-xl flex items-center gap-3 text-red-600 dark:text-red-400 text-sm">
                  <X size={20} />
                  <span>{error}</span>
              </div>
          )}

          <div className="p-4 bg-zinc-100 dark:bg-zinc-900 rounded-xl text-xs text-zinc-500 dark:text-zinc-400 leading-relaxed">
             <p><strong>Kamera odaklamıyorsa:</strong> Etiket üzerinde yazan 4 haneli <strong>Hızlı Kod</strong>'u yukarıya yazarak cihaza erişebilirsiniz.</p>
          </div>
      </div>

    </div>
  );
};

import React, { useState, useEffect } from 'react';
