                          style={{ pageBreakAfter: 'always' }}
                      >
                          {pagePrinters.map((p) => {
                             const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(window.location.origin + window.location.pathname + '?pid=' + p.id + '&sc=' + (p.shortCode || ''))}`;

