                     <input type="text" className="w-full p-3 border rounded-xl bg-slate-50 dark:bg-slate-700 text-xs" placeholder="Resim URL" value={editModal.newImage || ''} onChange={(e) => setEditModal({...editModal, newImage: e.target.value})} />
