              <div className="grid grid-cols-2 gap-3 mt-6"><button onClick={() => setDeleteModal(null)} className="py-3 bg-slate-100 rounded-xl">Vazgeç</button><button onClick={handleDelete} className="py-3 bg-red-600 text-white rounded-xl">Evet, Sil</button></div>
           </div>
        </div>
      )}
    </div>
  );
};

import { db } from './firebase';
import { collection, getDocs, addDoc, updateDoc, deleteDoc, doc, setDoc, query, orderBy, getDoc, where, writeBatch } from 'firebase/firestore';
import { Printer, TonerStock, StockLog, SystemConfig, ServiceRecord, User, CounterLog } from '../types';

const COLLECTIONS = {
  PRINTERS: 'printers',
  STOCKS: 'stocks',
  LOGS: 'logs',
  CONFIG: 'config',
  SERVICES: 'services',
  USERS: 'users',
  COUNTERS: 'counters'
};

const INITIAL_CONFIG: SystemConfig = {
  brands: ['Canon', 'HP', 'Kyocera', 'Xerox', 'Epson'],
  models: ['MF416dw', 'iF1643', 'LBP 251DW', '3325i', 'L3210', 'L1210', 'P2035', 'LBP 6030'],
  suppliers: ['Anahtar Bilgisayar', 'Enes Bilişim', 'Kendi Malımız'],
  tonerModels: ['1643', '505', '259x'],
  whatsappNumber: '',
  brandImages: {},
  modelImages: {}
};

const handleDbError = (error: any, context: string) => {
  console.error(`Error in ${context}:`, error);
  if (error.code === 'permission-denied') {
    alert('HATA: Veritabanı yazma izni reddedildi!');
  } else {
    alert(`İşlem sırasında hata oluştu: ${error.message}`);
  }
  throw error;
};

const cleanData = (data: any) => {
  const newObj = { ...data };
  Object.keys(newObj).forEach(key => {
    if (newObj[key] === undefined) {
      delete newObj[key];
    }
  });
  return newObj;
};

export const StorageService = {

  // --- AUTH ---
  getUsers: async (): Promise<User[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.USERS));
      const users = snapshot.docs.map(doc => ({ ...doc.data() as any } as User));
      if (users.length === 0) {
        const defaultAdmin: User = { username: 'admin', name: 'Sistem Yöneticisi', role: 'admin', password: 'yasam' }; 
        await addDoc(collection(db, COLLECTIONS.USERS), defaultAdmin);
        return [defaultAdmin];
      }
      return users;
    } catch (error) {
      return [];
    }
  },

  login: async (username: string, password: string): Promise<User | null> => {
    const users = await StorageService.getUsers();
    const user = users.find(u => u.username.toLowerCase() === username.toLowerCase() && u.password === password);
    if (user) {
      const { password, ...safeUser } = user;
      return safeUser as User;
    }
    return null;
  },

  // --- PRINTERS ---
  getPrinters: async (): Promise<Printer[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.PRINTERS));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Printer));
    } catch (e) {
      return [];
    }
  },

  addPrinter: async (printer: Printer) => {
    try {
      const printers = await StorageService.getPrinters();

      if (!printer.shortCode) {
        const codes = printers.map(p => parseInt(p.shortCode || '1000')).filter(n => !isNaN(n) && n >= 1000);
        const maxCode = codes.length > 0 ? Math.max(...codes) : 1000;
        printer.shortCode = (maxCode + 1).toString();
      }

      const { id, ...data } = printer; 
      const docRef = await addDoc(collection(db, COLLECTIONS.PRINTERS), cleanData(data));
      return docRef.id;
    } catch (e) {
      handleDbError(e, 'addPrinter');
      return '';
    }
  },

  updatePrinter: async (printer: Printer) => {
    if (!printer.id) return;
    try {
      const printerRef = doc(db, COLLECTIONS.PRINTERS, printer.id);
      const { id, ...data } = printer;
      await updateDoc(printerRef, cleanData(data));
    } catch (e) {
      handleDbError(e, 'updatePrinter');
    }
  },

  // Simulated live fetch for network printers
  // In real life, this would call a local Python/Node proxy that executes SNMP
  fetchPrinterCounterSimulated: async (printer: Printer): Promise<{total: number, bw: number, color?: number}> => {
    await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 1200));

    // Simulate a counter increase based on average daily usage (e.g., 5-50 pages)
    const dailyUsage = Math.floor(Math.random() * 45) + 5;
    const newTotal = printer.lastCounter + dailyUsage;

    if (printer.isColor) {
      const colorUsage = Math.floor(dailyUsage * 0.2);
      const bwUsage = dailyUsage - colorUsage;
      return {
        total: newTotal,
        bw: (printer.lastCounterBW || 0) + bwUsage,
        color: (printer.lastCounterColor || 0) + colorUsage
      };
    }

    return {
      total: newTotal,
      bw: newTotal
    };
  },

  deletePrinter: async (printerId: string) => {
    try {
      await deleteDoc(doc(db, COLLECTIONS.PRINTERS, printerId));
    } catch (e) {
      handleDbError(e, 'deletePrinter');
    }
  },

  fixMissingShortCodes: async () => {
    try {
      const printers = await StorageService.getPrinters();
      const batch = writeBatch(db);
      let updatedCount = 0;

      const existingCodes = printers
        .map(p => parseInt(p.shortCode || '0'))
        .filter(n => n >= 1000);

      let nextCode = existingCodes.length > 0 ? Math.max(...existingCodes) + 1 : 1001;

      for (const p of printers) {
        if (!p.shortCode || parseInt(p.shortCode) < 1000) {
          const printerRef = doc(db, COLLECTIONS.PRINTERS, p.id);
          batch.update(printerRef, { shortCode: nextCode.toString() });
          nextCode++;
          updatedCount++;
        }
      }

      if (updatedCount > 0) {
        await batch.commit();
      }
      return updatedCount;
    } catch (e) {
      console.error("Fixing short codes failed:", e);
      return 0;
    }
  },

  findPrinterByShortCode: async (code: string): Promise<Printer | null> => {
    try {
      const q = query(collection(db, COLLECTIONS.PRINTERS), where('shortCode', '==', code.trim()));
      const snapshot = await getDocs(q);
      if (snapshot.empty) return null;
      const doc = snapshot.docs[0];
      return { id: doc.id, ...doc.data() as any } as Printer;
    } catch (e) {
      return null;
    }
  },

  // --- STOCKS ---
  getStocks: async (): Promise<TonerStock[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.STOCKS));
      return snapshot.docs.map(doc => ({ ...doc.data() as any } as TonerStock));
    } catch (e) {
      return [];
    }
  },

  saveStock: async (stock: TonerStock) => {
    try {
      const q = query(collection(db, COLLECTIONS.STOCKS));
      const snapshot = await getDocs(q);
      const existingDoc = snapshot.docs.find(d => (d.data() as TonerStock).modelName === stock.modelName);

      if (existingDoc) {
        await updateDoc(doc(db, COLLECTIONS.STOCKS, existingDoc.id), { quantity: stock.quantity });
      } else {
        await addDoc(collection(db, COLLECTIONS.STOCKS), cleanData(stock));
      }
    } catch (e) {
      handleDbError(e, 'saveStock');
    }
  },

  // --- LOGS ---
  getLogs: async (): Promise<StockLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.LOGS), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as StockLog));
    } catch (e) {
      return [];
    }
  },

  addLog: async (log: StockLog) => {
    try {
      const { id, ...data } = log;
      await addDoc(collection(db, COLLECTIONS.LOGS), cleanData(data));
    } catch (e) {
      handleDbError(e, 'addLog');
    }
  },

  // --- SERVICES ---
  getServiceRecords: async (): Promise<ServiceRecord[]> => {
     try {
      const q = query(collection(db, COLLECTIONS.SERVICES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ServiceRecord));
     } catch (e) {
       return [];
     }
  },

  addServiceRecord: async (record: ServiceRecord) => {
    try {
      const { id, ...data } = record;
      await addDoc(collection(db, COLLECTIONS.SERVICES), cleanData(data));
    } catch (e) {
      handleDbError(e, 'addServiceRecord');
    }
  },

  // --- COUNTERS ---
  getCounterLogs: async (): Promise<CounterLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.COUNTERS), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as CounterLog));
    } catch (e) {
      return [];
    }
  },

  addCounterLog: async (log: CounterLog, updateMasterRecord: boolean = true) => {
    try {
       const { id, ...data } = log;
       await addDoc(collection(db, COLLECTIONS.COUNTERS), cleanData(data));
       if (updateMasterRecord) {
         const printerRef = doc(db, COLLECTIONS.PRINTERS, log.printerId);
         const updatePayload: any = { lastCounter: log.currentCounter };
         if (log.currentBW !== undefined) updatePayload.lastCounterBW = log.currentBW;
         if (log.currentColor !== undefined) updatePayload.lastCounterColor = log.currentColor;
         await updateDoc(printerRef, cleanData(updatePayload));
       }
    } catch (e) {
      handleDbError(e, 'addCounterLog');
    }
  },

  // --- CONFIG ---
  getConfig: async (): Promise<SystemConfig> => {
    try {
      const docRef = doc(db, COLLECTIONS.CONFIG, 'main_config');
      const docSnap = await getDoc(docRef);
      if (docSnap.exists()) {
        return { ...INITIAL_CONFIG, ...docSnap.data() as SystemConfig };
      } else {
        await setDoc(docRef, INITIAL_CONFIG);
        return INITIAL_CONFIG;
      }
    } catch (e) {
      return INITIAL_CONFIG;
    }
  },

  saveConfig: async (config: SystemConfig) => {
    try {
      const docRef = doc(db, COLLECTIONS.CONFIG, 'main_config');
      await setDoc(docRef, cleanData(config));
    } catch (e) {
      handleDbError(e, 'saveConfig');
    }
  },

  runMaintenance: async () => {
     await StorageService.getConfig();
  }
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, CounterLog, User } from '../types';
import { Calculator, Upload, Save, AlertTriangle, FileSpreadsheet, CheckCircle2, Search, ArrowRight, ArrowUp, RefreshCw, X, Loader2, Globe, History, Calendar, TrendingUp, Droplet, PlusCircle, CalendarDays, Usb, Layers, MinusCircle, Scan, Cpu, Zap } from 'lucide-react';
import { LoadingScreen } from './LoadingScreen';

interface CounterManagementProps {
  user: { name: string };
}

export const CounterManagement: React.FC<CounterManagementProps> = ({ user }) => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [allLogs, setAllLogs] = useState<CounterLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterTerm, setFilterTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'LIST' | 'IMPORT' | 'HISTORY_ENTRY' | 'SCAN'>('LIST');
  const [isSaving, setIsSaving] = useState(false);

  // History Modal State
  const [selectedHistoryPrinter, setSelectedHistoryPrinter] = useState<Printer | null>(null);

  // Input States for manual entry
  const [inputValues, setInputValues] = useState<Record<string, string>>({});

  // Historical Entry States
  const [histPrinterId, setHistPrinterId] = useState('');
  const [histDate, setHistDate] = useState('');
  const [histEntryMode, setHistEntryMode] = useState<'SIMPLE' | 'STD' | 'ADVANCED'>('SIMPLE');
  const [histValueTotal, setHistValueTotal] = useState('');
  const [histValueBW, setHistValueBW] = useState('');
  const [histValueColor, setHistValueColor] = useState('');

  // Scanning States
  const [isScanning, setIsScanning] = useState(false);
  const [scanResults, setScanResults] = useState<Record<string, { status: 'waiting' | 'loading' | 'done' | 'error', value?: number }>>({});

  // Advanced Inputs
  const [customCounterCount, setCustomCounterCount] = useState<number>(2);
  const [customCounters, setCustomCounters] = useState<{label: string, value: string}[]>([
      { label: 'A4 Siyah', value: '' },
      { label: 'A4 Renkli', value: '' }
  ]);

  // Import States
  const [parsedData, setParsedData] = useState<any[]>([]);
  const [matchResults, setMatchResults] = useState<{matched: any[], unmatched: any[]}>({matched: [], unmatched: []});
  const [importError, setImportError] = useState<string | null>(null);

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
        if (selectedHistoryPrinter) {
            setSelectedHistoryPrinter(null);
        }
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedHistoryPrinter]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && selectedHistoryPrinter) {
          window.history.back();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedHistoryPrinter]);

  useEffect(() => {
      const printer = printers.find(p => p.id === histPrinterId);
      if (printer) {
          if (printer.isColor) setHistEntryMode('STD');
          else setHistEntryMode('SIMPLE');
      }
  }, [histPrinterId, printers]);

  useEffect(() => {
      setCustomCounters(prev => {
          const newArr = [...prev];
          if (customCounterCount > prev.length) {
              for (let i = prev.length; i < customCounterCount; i++) {
                  newArr.push({ label: '', value: '' });
              }
          } else {
              return newArr.slice(0, customCounterCount);
          }
          return newArr;
      });
  }, [customCounterCount]);

  const fetchData = async () => {
    setLoading(true);
    const [p, l] = await Promise.all([
        StorageService.getPrinters(),
        StorageService.getCounterLogs()
    ]);
    setPrinters(p);
    setAllLogs(l);
    setLoading(false);
  };

  const openHistoryModal = (printer: Printer) => {
      window.history.pushState({ modal: 'counterHistory' }, '');
      setSelectedHistoryPrinter(printer);
  };

  const closeModalViaBack = () => {
      window.history.back();
  };

  const handleInputChange = (key: string, value: string) => {
    setInputValues(prev => ({ ...prev, [key]: value }));
  };

  const handleSingleSave = async (printer: Printer) => {
    let newValTotal = 0;
    let newValBW = 0;
    let newValColor = 0;

    if (printer.isColor) {
        const bwStr = inputValues[`${printer.id}_BW`];
        const colorStr = inputValues[`${printer.id}_COLOR`];
        if (!bwStr && !colorStr) return;
        newValBW = parseInt(bwStr || '0');
        newValColor = parseInt(colorStr || '0');
        newValTotal = newValBW + newValColor; 
    } else {
        const valStr = inputValues[`${printer.id}_TOTAL`];
        if (!valStr) return;
        newValTotal = parseInt(valStr);
    }

    if (isNaN(newValTotal)) return;

    if (newValTotal < printer.lastCounter) {
        if (!confirm(`UYARI: Girdiğiniz sayaç (${newValTotal}), eskiden (${printer.lastCounter}) düşük.`)) return;
    }

    try {
        await saveCounterLog({
            printer, 
            currentCounter: newValTotal, 
            method: 'Manuel Giriş', 
            updateMaster: true, 
            bw: printer.isColor ? newValBW : undefined, 
            color: printer.isColor ? newValColor : undefined
        });
        setInputValues(prev => {
            const copy = {...prev};
            delete copy[`${printer.id}_TOTAL`];
            delete copy[`${printer.id}_BW`];
            delete copy[`${printer.id}_COLOR`];
            return copy;
        });
        fetchData();
    } catch (error) {
        alert('Hata oluştu.');
    }
  };

  const handleAutoScan = async () => {
      const networkPrinters = printers.filter(p => p.connectionType === 'Network' && p.ipAddress);
      if (networkPrinters.length === 0) {
          alert("Ağ üzerinde (Network) tanımlı yazıcı bulunamadı.");
          return;
      }

      setIsScanning(true);
      const initialStatus: Record<string, any> = {};
      networkPrinters.forEach(p => initialStatus[p.id] = { status: 'waiting' });
      setScanResults(initialStatus);

      for (const p of networkPrinters) {
          setScanResults(prev => ({ ...prev, [p.id]: { status: 'loading' } }));
          try {
              const data = await StorageService.fetchPrinterCounterSimulated(p);
              await saveCounterLog({
                  printer: p,
                  currentCounter: data.total,
                  method: 'Otomatik Tarama (Ağ)',
                  updateMaster: true,
                  bw: data.bw,
                  color: data.color
              });
              setScanResults(prev => ({ ...prev, [p.id]: { status: 'done', value: data.total } }));
          } catch (error) {
              setScanResults(prev => ({ ...prev, [p.id]: { status: 'error' } }));
          }
      }
      setIsScanning(false);
      fetchData();
  };

  const handleHistoricalSave = async (e: React.FormEvent) => {
      e.preventDefault();
      const printer = printers.find(p => p.id === histPrinterId);
      if (!printer) return;

      let totalVal = 0;
      let bwVal: number | undefined = undefined;
      let colorVal: number | undefined = undefined;
      let finalCustomCounters: { label: string; value: number }[] | undefined = undefined;

      if (histEntryMode === 'ADVANCED') {
          const validCounters = customCounters.filter(c => c.label.trim() !== '' && c.value !== '');
          finalCustomCounters = validCounters.map(c => ({ label: c.label, value: parseInt(c.value) }));
          totalVal = finalCustomCounters.reduce((acc, curr) => acc + curr.value, 0);
      } else if (histEntryMode === 'STD') {
          bwVal = parseInt(histValueBW);
          colorVal = parseInt(histValueColor);
          totalVal = bwVal + colorVal;
      } else {
          totalVal = parseInt(histValueTotal);
      }

      const logDate = new Date(histDate);
      const logsForPrinter = allLogs.filter(l => l.printerId === printer.id && new Date(l.date) < logDate).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      const prevCounter = logsForPrinter.length > 0 ? logsForPrinter[0].currentCounter : 0;
      const usage = totalVal - prevCounter;

      try {
          const log: CounterLog = {
            id: '',
            printerId: printer.id,
            printerName: `${printer.brand} ${printer.model} (${printer.location})`,
            serialNumber: printer.serialNumber,
            date: logDate.toISOString(),
            previousCounter: prevCounter,
            currentCounter: totalVal,
            usage: usage > 0 ? usage : 0,
            recordedBy: `${user.name} (Geçmiş Veri)`,
            currentBW: bwVal,
            currentColor: colorVal,
            customCounters: finalCustomCounters,
            usageBW: (bwVal !== undefined && logsForPrinter[0]?.currentBW) ? Math.max(0, bwVal - logsForPrinter[0].currentBW) : undefined,
            usageColor: (colorVal !== undefined && logsForPrinter[0]?.currentColor) ? Math.max(0, colorVal - logsForPrinter[0].currentColor) : undefined
          };
          await StorageService.addCounterLog(log, false);
          alert("Kaydedildi.");
          setActiveTab('LIST');
          fetchData(); 
      } catch (error) { alert("Hata"); }
  };

  interface SaveLogParams {
      printer: Printer;
      currentCounter: number;
      method: string;
      updateMaster: boolean;
      bw?: number;
      color?: number;
      customCounters?: { label: string; value: number }[];
  }

  const saveCounterLog = async ({ printer, currentCounter, method, updateMaster, bw, color, customCounters }: SaveLogParams) => {
     const usage = currentCounter - printer.lastCounter;
     let usageBW = (bw !== undefined && printer.lastCounterBW !== undefined) ? Math.max(0, bw - printer.lastCounterBW) : undefined;
     let usageColor = (color !== undefined && printer.lastCounterColor !== undefined) ? Math.max(0, color - printer.lastCounterColor) : undefined;

     const log: CounterLog = {
         id: '',
         printerId: printer.id,
         printerName: `${printer.brand} ${printer.model} (${printer.location})`,
         serialNumber: printer.serialNumber,
         date: new Date().toISOString(),
         previousCounter: printer.lastCounter,
         currentCounter: currentCounter,
         usage: usage > 0 ? usage : 0, 
         recordedBy: `${user.name} (${method})`,
         currentBW: bw,
         currentColor: color,
         usageBW,
         usageColor,
         customCounters
     };
     await StorageService.addCounterLog(log, updateMaster);
  };

  const filteredPrinters = printers.filter(p => {
      const searchLower = filterTerm.toLocaleLowerCase('tr-TR');
      return (p.location.toLocaleLowerCase('tr-TR').includes(searchLower) || p.model.toLocaleLowerCase('tr-TR').includes(searchLower) || p.serialNumber.toLocaleLowerCase('tr-TR').includes(searchLower));
  });

  if (loading) return <LoadingScreen message="Sayaç verileri yükleniyor..." />;

  return (
    <div className="space-y-6 pb-20">
       <div className="flex justify-between items-center bg-white dark:bg-zinc-900 p-4 rounded-2xl shadow-sm border border-zinc-100 dark:border-zinc-800">
        <div>
          <h2 className="text-2xl font-bold text-zinc-800 dark:text-white flex items-center gap-2">
             <Calculator size={24} className="text-blue-500" /> Sayaç Yönetimi
          </h2>
          <p className="text-sm text-zinc-500 dark:text-zinc-400">Otomatik ve manuel endeks takibi</p>
