                    {/* Service Records */}
                    <section>
                        <h4 className="flex items-center gap-2 text-xl font-black text-zinc-900 dark:text-white mb-6"><Wrench className="text-blue-500" /> Servis & Bakım Kayıtları</h4>
                        <div className="space-y-5">
                             {selectedPrinterHistory.serviceLogs.length === 0 ? (
                                <div className="text-center p-12 bg-zinc-100 dark:bg-zinc-900/50 rounded-3xl border-2 border-dashed border-zinc-200 dark:border-zinc-800 text-zinc-400 font-bold text-sm">Cihaza ait teknik servis kaydı bulunmuyor.</div>
                            ) : (
                                selectedPrinterHistory.serviceLogs.map(srv => (
                                    <div key={srv.id} className="bg-white dark:bg-zinc-900 p-6 rounded-3xl border-l-[6px] border-blue-500 shadow-sm relative overflow-hidden group">
                                        <div className="flex justify-between items-start mb-4">
                                            <span className={`text-[10px] font-black px-3 py-1 rounded-full tracking-widest ${srv.status === 'COMPLETED' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                                {srv.status === 'COMPLETED' ? 'TAMAMLANDI' : 'BEKLEMEDE'}
                                            </span>
                                            <span className="text-xs text-zinc-400 font-mono font-bold">{new Date(srv.date).toLocaleDateString('tr-TR')}</span>
