                                        <p className="font-black text-zinc-900 dark:text-white text-lg mb-1 leading-tight">{srv.issue}</p>
                                        <p className="text-sm text-zinc-500 dark:text-zinc-400 font-medium">{srv.actionTaken}</p>
                                        <div className="mt-5 pt-4 border-t border-zinc-50 dark:border-zinc-800/50 flex justify-between items-center">
                                            <p className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">{srv.provider}</p>
                                            <p className="font-black text-xl text-blue-600 dark:text-blue-400 font-mono">{srv.cost.toLocaleString()} ₺</p>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </section>

                    {/* Counter Table */}
                    <section>
                         <h4 className="flex items-center gap-2 text-xl font-black text-zinc-900 dark:text-white mb-6"><BarChart3 className="text-purple-500" /> Endeks Analiz Tablosu</h4>
                         <div className="bg-white dark:bg-zinc-900 rounded-[2rem] border border-zinc-200 dark:border-zinc-800 overflow-hidden shadow-sm">
                             <table className="w-full text-left">
                                 <thead className="bg-zinc-50 dark:bg-zinc-800/50">
                                     <tr>
                                         <th className="p-4 text-[10px] text-zinc-400 font-black uppercase tracking-widest">Dönem Tarihi</th>
                                         <th className="p-4 text-[10px] text-zinc-400 font-black uppercase tracking-widest">Endeks</th>
                                         <th className="p-4 text-[10px] text-zinc-400 font-black uppercase tracking-widest text-right">Fark</th>
                                     </tr>
                                 </thead>
                                 <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800">
                                     {selectedPrinterHistory.counterLogs.length === 0 ? (
                                         <tr><td colSpan={3} className="p-12 text-center text-zinc-400 font-bold">Sayaç verisi henüz işlenmemiş.</td></tr>
                                     ) : (
                                         selectedPrinterHistory.counterLogs.map(log => (
                                             <tr key={log.id} className="hover:bg-zinc-50 dark:hover:bg-zinc-800/30 transition-colors">
                                                 <td className="p-4 text-sm font-bold text-zinc-600 dark:text-zinc-400">{new Date(log.date).toLocaleDateString('tr-TR')}</td>
                                                 <td className="p-4 font-black text-zinc-900 dark:text-white font-mono">{log.currentCounter.toLocaleString()}</td>
