                    </section>
                 </div>

                 {/* Detail Footer */}
                 <div className="p-6 bg-white dark:bg-zinc-900 border-t border-zinc-200 dark:border-zinc-800 flex gap-4 pb-[env(safe-area-inset-bottom)]">
                     <button onClick={() => { window.history.back(); openFormModal(selectedPrinterHistory.printer); }} className="flex-1 py-5 bg-zinc-100 dark:bg-zinc-800 text-zinc-800 dark:text-white rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-blue-50 dark:hover:bg-blue-900/20 hover:text-blue-600 transition-all active:scale-95">
                        <Edit2 size={20}/> Cihazı Düzenle
                     </button>
                     <button onClick={() => window.history.back()} className="flex-1 py-5 bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 rounded-2xl font-black transition-all active:scale-95 shadow-xl shadow-zinc-500/10">
                        Pencereyi Kapat
                     </button>
                 </div>
             </div>
         </div>
       )}

       {/* QR MODAL VIEWER */}
       {qrPrinter && (
          <div className="fixed inset-0 bg-black/90 backdrop-blur-xl z-[100] flex items-center justify-center p-4 animate-in fade-in duration-300">
              <div className="bg-white dark:bg-zinc-900 rounded-[3rem] w-full max-w-sm overflow-hidden shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] relative animate-in zoom-in-95 duration-300 border border-zinc-200 dark:border-zinc-800">
                  <button onClick={() => window.history.back()} className="absolute top-6 right-6 p-3 bg-zinc-100 dark:bg-zinc-800 rounded-2xl text-zinc-500 hover:text-red-500 transition-all active:scale-90"><X size={24}/></button>

                  <div className="p-10 flex flex-col items-center text-center">
                      <div className="mb-8 bg-zinc-50 dark:bg-zinc-800 p-6 rounded-[2.5rem] shadow-inner border-2 border-zinc-100 dark:border-zinc-700">
                          <img 
                            src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(window.location.origin + window.location.pathname + '?pid=' + qrPrinter.id + '&sc=' + (qrPrinter.shortCode || ''))}`}
