                            className="w-44 h-44 object-contain"
                          />
                      </div>

                      <h3 className="text-3xl font-black text-zinc-900 dark:text-white mb-2 leading-tight">{qrPrinter.brand} {qrPrinter.model}</h3>
                      <p className="text-emerald-600 dark:text-emerald-400 font-black mb-8 flex items-center gap-1.5"><MapPin size={18}/> {qrPrinter.location}</p>

                      <div className="w-full bg-zinc-900 dark:bg-emerald-950 p-6 rounded-3xl mb-8 border border-zinc-800 dark:border-emerald-500/30">
                          <p className="text-[10px] text-zinc-400 dark:text-emerald-400/60 font-black uppercase tracking-[0.4em] mb-2">HIZLI ERİŞİM KODU</p>
                          <div className="flex items-center justify-center gap-4">
                              <span className="text-5xl font-black text-white dark:text-emerald-400 tracking-tighter">#{qrPrinter.shortCode}</span>
                              <button onClick={() => copyShortCode(qrPrinter.shortCode || '')} className="p-3 text-zinc-500 hover:text-emerald-400 transition-all active:scale-90"><Copy size={24}/></button>
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4 w-full">
                          <button 
                            onClick={() => window.print()}
                            className="flex items-center justify-center gap-2 py-4 bg-zinc-100 dark:bg-zinc-800 text-zinc-900 dark:text-white rounded-2xl font-black hover:bg-zinc-200 transition-all active:scale-95"
                          >
                             <Download size={20}/> Yazdır
                          </button>
                          <button 
                            onClick={() => copyShortCode(qrPrinter.shortCode || '')}
                            className="flex items-center justify-center gap-2 py-4 bg-emerald-600 text-white rounded-2xl font-black shadow-lg shadow-emerald-500/20 active:scale-95 transition-all"
                          >
                             <Share2 size={20}/> Paylaş
                          </button>
                      </div>
                  </div>

                  <div className="p-5 bg-zinc-50 dark:bg-zinc-800/50 text-center border-t border-zinc-100 dark:border-zinc-800">
                      <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest">Bu QR kod doğrudan teknik servise ve sayaç girişine yönlendirir.</p>
                  </div>
              </div>
          </div>
       )}

       {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-md z-[110] flex items-end md:items-center justify-center md:p-4 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-zinc-900 rounded-t-[3rem] md:rounded-[3rem] w-full md:max-w-xl shadow-2xl h-[92vh] md:h-auto overflow-hidden flex flex-col animate-in slide-in-from-bottom-full duration-500">
             <div className="p-8 border-b border-zinc-100 dark:border-zinc-800 flex justify-between items-center">
              <div>
                <h3 className="font-black text-2xl text-zinc-900 dark:text-white">{editingPrinter ? 'Cihazı Düzenle' : 'Yeni Cihaz Kaydı'}</h3>
                <p className="text-sm text-zinc-500 mt-1">Lütfen cihaz bilgilerini eksiksiz doldurun.</p>
              </div>
              <button type="button" onClick={() => window.history.back()} className="p-3 bg-zinc-100 dark:bg-zinc-800 rounded-2xl hover:text-red-500 transition-all"><X size={24}/></button>
            </div>
            <div className="overflow-y-auto p-8 space-y-6 flex-1 custom-scrollbar">
                <form id="printer-form" onSubmit={handleSave} className="space-y-6">
                   <div className="grid grid-cols-2 gap-4">
                        <div><label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-2 ml-1">MARKA</label><select required className="w-full p-4 border border-zinc-200 dark:border-zinc-700 rounded-2xl bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-emerald-500" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})}><option value="">Seçiniz</option>{config.brands.map(b => <option key={b} value={b}>{b}</option>)}</select></div>
                        <div><label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-2 ml-1">MODEL</label><select required className="w-full p-4 border border-zinc-200 dark:border-zinc-700 rounded-2xl bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-emerald-500" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})}><option value="">Seçiniz</option>{config.models.map(m => <option key={m} value={m}>{m}</option>)}</select></div>
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                        <div><label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-2 ml-1">KONUM</label><input type="text" required placeholder="Örn: MUHASEBE" className="w-full p-4 border border-zinc-200 dark:border-zinc-700 rounded-2xl bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-emerald-500" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} /></div>
                        <div><label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-2 ml-1">KAT</label><input type="text" required placeholder="Örn: 2. KAT" className="w-full p-4 border border-zinc-200 dark:border-zinc-700 rounded-2xl bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-emerald-500" value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} /></div>
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                        <div><label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-2 ml-1">SERİ NO</label><input type="text" required placeholder="S/N" className="w-full p-4 border border-zinc-200 dark:border-zinc-700 rounded-2xl bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-white font-mono font-bold outline-none focus:ring-2 focus:ring-emerald-500" value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} /></div>
                        <div><label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-2 ml-1">HIZLI KOD (#)</label><input type="text" className="w-full p-4 border border-zinc-200 dark:border-zinc-700 rounded-2xl bg-zinc-100 dark:bg-zinc-700 text-zinc-500 font-black outline-none" value={formData.shortCode} disabled placeholder="Oto Atanır" /></div>
                   </div>
                   <div className="bg-zinc-50 dark:bg-zinc-800/50 p-6 rounded-[2rem] border border-zinc-100 dark:border-zinc-800">
                        <label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-4 ml-1">BAĞLANTI TİPİ</label>
                        <div className="flex gap-4">
                            <button type="button" onClick={() => setFormData({...formData, connectionType: 'Network'})} className={`flex-1 py-4 rounded-2xl font-black text-sm transition-all border-2 flex items-center justify-center gap-2 ${formData.connectionType === 'Network' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white dark:bg-zinc-800 border-zinc-200 dark:border-zinc-700 text-zinc-500'}`}><Wifi size={18}/> Network</button>
                            <button type="button" onClick={() => setFormData({...formData, connectionType: 'USB'})} className={`flex-1 py-4 rounded-2xl font-black text-sm transition-all border-2 flex items-center justify-center gap-2 ${formData.connectionType === 'USB' ? 'bg-zinc-900 border-zinc-900 text-white shadow-lg' : 'bg-white dark:bg-zinc-800 border-zinc-200 dark:border-zinc-700 text-zinc-500'}`}><Usb size={18}/> USB</button>
                        </div>
                        {formData.connectionType === 'Network' && (
                            <div className="mt-6 animate-in slide-in-from-top-2 duration-300">
                                <label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-2 ml-1">IP ADRESİ</label>
                                <input type="text" placeholder="192.168.1.xxx" className="w-full p-4 border border-zinc-200 dark:border-zinc-700 rounded-2xl bg-white dark:bg-zinc-900 text-zinc-900 dark:text-white font-mono font-bold outline-none focus:ring-2 focus:ring-blue-500" value={formData.ipAddress} onChange={e => setFormData({...formData, ipAddress: e.target.value})} />
                            </div>
                        )}
                   </div>
                </form>
            </div>
            <div className="p-6 border-t border-zinc-100 dark:border-zinc-800 flex gap-4 bg-white dark:bg-zinc-900 pb-[env(safe-area-inset-bottom)]">
                <button type="button" onClick={() => window.history.back()} className="flex-1 py-5 bg-zinc-100 dark:bg-zinc-800 rounded-2xl font-black text-zinc-700 dark:text-zinc-300 transition-all active:scale-95">Vazgeç</button>
                <button form="printer-form" type="submit" className="flex-1 py-5 bg-emerald-600 text-white rounded-2xl font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all">Kaydet ve Bitir</button>
            </div>
          </div>
        </div>
       )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, History, QrCode, Download, CheckCircle2, RefreshCw, Wallet, Calendar, Calculator, BarChart3, Copy, Share2, Wrench, Droplet, Globe, Monitor, Activity } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, PrinterStatus, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

interface PrinterStats {
  totalSpent: number;
  totalServiceCost: number;
  totalTonerCost: number;
  lastServiceDate: string | null;
  tonerCount: number;
}

export const PrinterList: React.FC<PrinterListProps> = ({ onSelectPrinter, targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [qrPrinter, setQrPrinter] = useState<PrinterType | null>(null);
  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);
  const [selectedPrinterHistory, setSelectedPrinterHistory] = useState<{
      printer: PrinterType, 
      tonerLogs: StockLog[], 
      serviceLogs: ServiceRecord[], 
      counterLogs: CounterLog[], 
      stats: PrinterStats
  } | null>(null);

  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '',
    model: '',
    serialNumber: '',
    shortCode: '',
    location: '',
    floor: '',
    lastCounter: 0,
    connectionType: 'USB',
    ipAddress: '',
    status: 'ACTIVE'
  });

  useEffect(() => { loadData(); }, []);

  // ESC Listener & Navigation Handler
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      if (qrPrinter) setQrPrinter(null);
      if (isHistoryModalOpen) setIsHistoryModalOpen(false);
      if (isFormModalOpen) {
        setIsFormModalOpen(false);
        setEditingPrinter(null);
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (qrPrinter || isHistoryModalOpen || isFormModalOpen) {
          window.history.back();
        }
      }
    };

    window.addEventListener('popstate', handlePopState);
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('popstate', handlePopState);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [qrPrinter, isHistoryModalOpen, isFormModalOpen]);

  // Handle Deep Linking from QR Code
  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const target = printers.find(p => p.id === targetPrinterId);
      if (target) openHistoryModal(target);
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([StorageService.getPrinters(), StorageService.getConfig()]);

    // Auto-fix missing or legacy short codes
    const needsFix = p.some(printer => !printer.shortCode || printer.shortCode.length < 4);
    if (needsFix) {
       await StorageService.fixMissingShortCodes();
       const updatedP = await StorageService.getPrinters();
       setPrinters(updatedP);
    } else {
       setPrinters(p);
    }

    setConfig(c);
    setLoading(false);
  };

  const handleEditClick = (e: React.MouseEvent, printer: PrinterType) => {
    e.preventDefault(); e.stopPropagation();
    openFormModal(printer);
  };

  const handleQrClick = (e: React.MouseEvent, printer: PrinterType) => {
    e.preventDefault(); e.stopPropagation();
    window.history.pushState({ modal: 'qr' }, '');
    setQrPrinter(printer);
  };

  const openFormModal = (printer?: PrinterType) => {
    window.history.pushState({ modal: 'form' }, '');
    if (printer) {
      setEditingPrinter(printer); 
      setFormData(printer);
    } else {
      setEditingPrinter(null);
      setFormData({ brand: config.brands[0] || '', model: config.models[0] || '', status: 'ACTIVE', connectionType: 'USB' });
    }
    setIsFormModalOpen(true);
  };

  const openHistoryModal = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'history' }, '');
    const [allLogs, allServices, allCounterLogs] = await Promise.all([
        StorageService.getLogs(), 
        StorageService.getServiceRecords(), 
        StorageService.getCounterLogs()
    ]);

    const tonerLogs = allLogs.filter(log => log.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const serviceLogs = allServices.filter(srv => srv.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const counterLogs = allCounterLogs.filter(l => l.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const totalTonerCost = tonerLogs.reduce((sum, log) => sum + (log.cost || 0), 0);
    const totalServiceCost = serviceLogs.reduce((sum, srv) => sum + (srv.cost || 0), 0);

    setSelectedPrinterHistory({ 
        printer, 
        tonerLogs, 
        serviceLogs, 
        counterLogs, 
        stats: { 
            totalSpent: totalTonerCost + totalServiceCost, 
            totalTonerCost,
            totalServiceCost,
            lastServiceDate: serviceLogs[0]?.date || null,
            tonerCount: tonerLogs.length
        } 
    });
    setIsHistoryModalOpen(true);
  };

  // Add missing confirmDelete function
  const confirmDelete = async (e: React.MouseEvent, id: string) => {
    e.preventDefault(); e.stopPropagation();
    if (window.confirm('Bu yazıcıyı silmek istediğinize emin misiniz?')) {
      await StorageService.deletePrinter(id);
      loadData();
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingPrinter?.id) {
       await StorageService.updatePrinter({ ...editingPrinter, ...formData } as PrinterType);
    } else {
       await StorageService.addPrinter({ id: '', lastTonerDate: new Date().toISOString(), ...formData as PrinterType });
    }
    window.history.back();
    loadData();
  };

  const copyShortCode = (code: string) => {
      navigator.clipboard.writeText(code);
      alert("Hızlı kod kopyalandı: " + code);
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-400';
      case 'MAINTENANCE': return 'bg-orange-100 text-orange-700 dark:bg-orange-900/40 dark:text-orange-400';
      case 'BROKEN': return 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-400';
      case 'SPARE': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-400';
      default: return 'bg-zinc-100 text-zinc-700 dark:bg-zinc-800 dark:text-zinc-400';
    }
  };

  const filteredPrinters = printers.filter(p => {
    const searchLower = searchTerm.toLocaleLowerCase('tr-TR');
    return (
        p.model.toLocaleLowerCase('tr-TR').includes(searchLower) || 
        p.location.toLocaleLowerCase('tr-TR').includes(searchLower) || 
        p.shortCode?.includes(searchLower) || 
        p.serialNumber.toLocaleLowerCase('tr-TR').includes(searchLower) ||
