                      <h3 className="text-3xl font-black text-zinc-900 dark:text-white mb-2 leading-none">TONER TAKİP</h3>
                      <p className="text-zinc-500 font-bold mb-4">{qrPrinter.brand} {qrPrinter.model}</p>
