import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, ServiceRecord, User } from '../types';
import { Wrench, Plus, Save, Clock, CheckCircle2, XCircle, Calendar } from 'lucide-react';
import { LoadingScreen } from './LoadingScreen';

interface ServiceManagementProps {
  // empty
}

export const ServiceManagement: React.FC<ServiceManagementProps> = () => {
  const [records, setRecords] = useState<ServiceRecord[]>([]);
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [loading, setLoading] = useState(true);

  // Form State
  const [selectedPrinterId, setSelectedPrinterId] = useState('');
  const [issue, setIssue] = useState('');
  const [action, setAction] = useState('');
  const [provider, setProvider] = useState('');
  const [cost, setCost] = useState(0);
  const [status, setStatus] = useState<'PENDING' | 'COMPLETED' | 'SCRAPPED'>('PENDING');
  const [customDate, setCustomDate] = useState(new Date().toISOString().split('T')[0]); // Default today

  useEffect(() => {
    const fetchData = async () => {
        setLoading(true);
        const r = await StorageService.getServiceRecords();
        const p = await StorageService.getPrinters();
        setRecords(r);
        setPrinters(p);
        setLoading(false);
    };
    fetchData();
  }, []);

  const handlePrinterChange = (printerId: string) => {
    setSelectedPrinterId(printerId);
    const printer = printers.find(p => p.id === printerId);
    if (printer && printer.supplier) {
      setProvider(printer.supplier);
    } else {
      setProvider('');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const printer = printers.find(p => p.id === selectedPrinterId);
    if (!printer) return;

    // Prepare Date
    const now = new Date();
    const serviceDate = new Date(customDate);
    // Keep current time, but use selected date
    serviceDate.setHours(now.getHours(), now.getMinutes(), now.getSeconds());

    const newRecord: ServiceRecord = {
      id: '', // Generated by Firestore
      printerId: printer.id,
      printerName: `${printer.brand} ${printer.model} (${printer.location})`,
      date: serviceDate.toISOString(),
      issue,
      actionTaken: action,
      provider,
      cost,
      status
    };

    await StorageService.addServiceRecord(newRecord);

    // Refresh List
    const updatedRecords = await StorageService.getServiceRecords();
    setRecords(updatedRecords);

    // Reset Form
    setIssue('');
    setAction('');
    setProvider('');
    setCost(0);
    setStatus('PENDING');
    setCustomDate(new Date().toISOString().split('T')[0]);
    alert('Servis kaydı eklendi.');
  };

  if (loading) {
    return <LoadingScreen message="Servis kayıtları yükleniyor..." />;
  }

  return (
    <div className="space-y-6">
       <div className="flex flex-col md:flex-row gap-6">
          {/* Form Side */}
          <div className="md:w-1/3 space-y-4">
             <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
                <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
                   <Wrench size={20} className="text-orange-500"/> Yeni Arıza/Servis Kaydı
                </h3>
                <form onSubmit={handleSubmit} className="space-y-3">
                   {/* DATE SELECTION */}
                   <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Tarih</label>
                      <div className="relative cursor-pointer" onClick={() => (document.getElementById('service-date-picker') as HTMLInputElement)?.showPicker()}>
                         <Calendar size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                         <input 
                            id="service-date-picker"
                            type="date" 
                            required
                            className="w-full pl-10 p-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500 cursor-pointer"
                            value={customDate}
                            onChange={(e) => setCustomDate(e.target.value)}
                            onClick={(e) => e.currentTarget.showPicker()}
                         />
                      </div>
