import { StickyNote, Plus, Trash2, Calendar, User as UserIcon, X, Save, AlertCircle, Image as ImageIcon, Camera } from 'lucide-react';

interface NotesProps {
    user: { name: string };
}

export const Notes: React.FC<NotesProps> = ({ user }) => {
    const [notes, setNotes] = useState<Note[]>([]);
    const [loading, setLoading] = useState(true);
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [newNote, setNewNote] = useState({ title: '', content: '', imageUrl: '' });

    useEffect(() => { loadData(); }, []);

    const loadData = async () => {
        setLoading(true);
        const data = await StorageService.getNotes();
        setNotes(data);
        setLoading(false);
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setNewNote(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleAddNote = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newNote.title.trim() || !newNote.content.trim()) return;

        const note: Note = {
            id: '',
            title: newNote.title,
            content: newNote.content,
            date: new Date().toISOString(),
            user: user.name,
            imageUrl: newNote.imageUrl || undefined
        };

        await StorageService.addNote(note);
        setNewNote({ title: '', content: '', imageUrl: '' });
        setIsAddModalOpen(false);
        loadData();
    };

    const handleDelete = async (id: string) => {
        if (window.confirm("Bu notu silmek istediğinize emin misiniz?")) {
            await StorageService.deleteNote(id);
            loadData();
        }
    };

    if (loading) return <LoadingScreen message="Notlar yükleniyor..." />;

    return (
