            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {notes.map(note => (
                    <div key={note.id} className="bg-white dark:bg-zinc-950 rounded-[2.5rem] border border-zinc-100 dark:border-zinc-900 shadow-xl group hover:border-emerald-500/30 transition-all flex flex-col overflow-hidden">
                        {note.imageUrl && (
                            <div className="w-full h-48 overflow-hidden bg-zinc-100 dark:bg-zinc-900 border-b border-zinc-100 dark:border-zinc-900">
                                <img src={note.imageUrl} alt={note.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                            </div>
