                                <input required type="text" className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" placeholder="Örn: Fizik Tedavi Cihaz Değişimi" value={newNote.title} onChange={e => setNewNote({...newNote, title: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-1">NOT İÇERİĞİ</label>
                                <textarea required rows={4} className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" placeholder="Detaylı bilgileri buraya yazın..." value={newNote.content} onChange={e => setNewNote({...newNote, content: e.target.value})} />
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-1">RESİM EKLE (OPSİYONEL)</label>
                                <div className="flex flex-col gap-4">
                                    <label className="flex items-center justify-center w-full p-8 border-2 border-dashed border-zinc-200 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 cursor-pointer hover:border-emerald-500 transition-colors group">
                                        <div className="flex flex-col items-center gap-2">
                                            <ImageIcon size={32} className="text-zinc-400 group-hover:text-emerald-500 transition-colors" />
                                            <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">RESİM SEÇ VEYA ÇEK</span>
                                        </div>
