import { db } from './firebase';
import { collection, getDocs, addDoc, updateDoc, deleteDoc, doc, setDoc, query, orderBy, getDoc, absenteeism, where, writeBatch } from 'firebase/firestore';
import { Printer, TonerStock, StockLog, SystemConfig, ServiceRecord, User, CounterLog, Note, ActivityLog } from '../types';

const COLLECTIONS = {
  PRINTERS: 'printers',
  STOCKS: 'stocks',
  LOGS: 'logs',
  CONFIG: 'config',
  SERVICES: 'services',
  USERS: 'users',
  COUNTERS: 'counters',
  NOTES: 'notes',
  ACTIVITIES: 'activities'
};

const INITIAL_CONFIG: SystemConfig = {
  brands: ['Canon', 'HP', 'Kyocera', 'Xerox', 'Epson'],
  models: ['MF416dw', 'iF1643', 'LBP 251DW', '3325i', 'L3210', 'L1210', 'P2035', 'LBP 6030'],
  suppliers: ['Anahtar Bilgisayar', 'Enes Bilişim', 'Kendi Malımız'],
  tonerModels: ['1643', '505', '259x'],
  whatsappNumber: '',
  brandImages: {},
  modelImages: {}
};

const cleanData = (data: any) => {
  const newObj = { ...data };
  Object.keys(newObj).forEach(key => {
    if (newObj[key] === undefined) delete newObj[key];
  });
  return newObj;
};

export const StorageService = {
  // --- AUTH ---
  getUsers: async (): Promise<User[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.USERS));
      return snapshot.docs.map(doc => ({ ...doc.data() as any } as User));
    } catch (error) { return []; }
  },

  login: async (username: string, password: string): Promise<User | null> => {
    const users = await StorageService.getUsers();
    const user = users.find(u => u.username.toLowerCase() === username.toLowerCase() && u.password === password);
    if (user) {
      const { password, ...safeUser } = user;
      return safeUser as User;
    }
    return null;
  },

  // --- PRINTERS ---
  getPrinters: async (): Promise<Printer[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.PRINTERS));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Printer));
    } catch (e) { return []; }
  },

  addPrinter: async (printer: Printer) => {
    const printers = await StorageService.getPrinters();
    if (!printer.shortCode) {
      const codes = printers.map(p => parseInt(p.shortCode || '1000')).filter(n => !isNaN(n) && n >= 1000);
      const maxCode = codes.length > 0 ? Math.max(...codes) : 1000;
      printer.shortCode = (maxCode + 1).toString();
    }
    const { id, ...data } = printer;
    const docRef = await addDoc(collection(db, COLLECTIONS.PRINTERS), cleanData(data));
    return docRef.id;
  },

  updatePrinter: async (printer: Printer) => {
    if (!printer.id) return;
    await updateDoc(doc(db, COLLECTIONS.PRINTERS, printer.id), cleanData(printer));
  },

  deletePrinter: async (printerId: string) => {
    await deleteDoc(doc(db, COLLECTIONS.PRINTERS, printerId));
  },

  findPrinterByShortCode: async (code: string): Promise<Printer | null> => {
    const q = query(collection(db, COLLECTIONS.PRINTERS), where('shortCode', '==', code.trim()));
    const snapshot = await getDocs(q);
    if (snapshot.empty) return null;
    return { id: snapshot.docs[0].id, ...snapshot.docs[0].data() as any } as Printer;
  },

  fixMissingShortCodes: async () => {
    const printers = await StorageService.getPrinters();
    const batch = writeBatch(db);
    let nextCode = 1001;
    for (const p of printers) {
      if (!p.shortCode || parseInt(p.shortCode) < 1000) {
        batch.update(doc(db, COLLECTIONS.PRINTERS, p.id), { shortCode: nextCode.toString() });
        nextCode++;
      }
    }
    await batch.commit();
    return printers.length;
  },

  // --- NOTES ---
  getNotes: async (): Promise<Note[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.NOTES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Note));
    } catch (e) { return []; }
  },

  addNote: async (note: Note) => {
    const { id, ...data } = note;
    const docRef = await addDoc(collection(db, COLLECTIONS.NOTES), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: note.user,
      action: 'NOT_EKLENDI',
      details: `"${note.title}" başlıklı yeni not oluşturuldu.`
    });
    return docRef.id;
  },

  updateNote: async (note: Note) => {
    if (!note.id) return;
    const { id, ...data } = note;
    await updateDoc(doc(db, COLLECTIONS.NOTES, id), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: note.user,
      action: 'NOT_GUNCELLEME',
      details: `"${note.title}" başlıklı not üzerinde değişiklik yapıldı.`
    });
  },

  deleteNote: async (id: string, user: string, title: string) => {
    await deleteDoc(doc(db, COLLECTIONS.NOTES, id));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'NOT_SILINDI',
      details: `"${title}" başlıklı not kalıcı olarak silindi.`
    });
  },

  // --- ACTIVITIES ---
  getActivities: async (): Promise<ActivityLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.ACTIVITIES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ActivityLog));
    } catch (e) { return []; }
  },

  addActivity: async (activity: ActivityLog) => {
    const { id, ...data } = activity;
    await addDoc(collection(db, COLLECTIONS.ACTIVITIES), cleanData(data));
  },

  // --- STOCKS & LOGS ---
  getStocks: async (): Promise<TonerStock[]> => {
    const snapshot = await getDocs(collection(db, COLLECTIONS.STOCKS));
    return snapshot.docs.map(doc => ({ ...doc.data() as any } as TonerStock));
  },

  saveStock: async (stock: TonerStock) => {
    const q = query(collection(db, COLLECTIONS.STOCKS));
    const snapshot = await getDocs(q);
    const existing = snapshot.docs.find(d => (d.data() as TonerStock).modelName === stock.modelName);
    if (existing) await updateDoc(doc(db, COLLECTIONS.STOCKS, existing.id), { quantity: stock.quantity });
    else await addDoc(collection(db, COLLECTIONS.STOCKS), cleanData(stock));
  },

  getLogs: async (): Promise<StockLog[]> => {
    const q = query(collection(db, COLLECTIONS.LOGS), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as StockLog));
  },

  addLog: async (log: StockLog) => {
    const { id, ...data } = log;
    await addDoc(collection(db, COLLECTIONS.LOGS), cleanData(data));
  },

  getServiceRecords: async (): Promise<ServiceRecord[]> => {
    const q = query(collection(db, COLLECTIONS.SERVICES), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ServiceRecord));
  },

  addServiceRecord: async (record: ServiceRecord) => {
    const { id, ...data } = record;
    await addDoc(collection(db, COLLECTIONS.SERVICES), cleanData(data));
  },

  getCounterLogs: async (): Promise<CounterLog[]> => {
    const q = query(collection(db, COLLECTIONS.COUNTERS), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as CounterLog));
  },

  addCounterLog: async (log: CounterLog, updateMaster: boolean = true) => {
    const { id, ...data } = log;
    await addDoc(collection(db, COLLECTIONS.COUNTERS), cleanData(data));
    if (updateMaster) {
      await updateDoc(doc(db, COLLECTIONS.PRINTERS, log.printerId), { 
        lastCounter: log.currentCounter,
        lastCounterBW: log.currentBW,
        lastCounterColor: log.currentColor
      });
    }
  },

  getConfig: async (): Promise<SystemConfig> => {
    const docSnap = await getDoc(doc(db, COLLECTIONS.CONFIG, 'main_config'));
    return docSnap.exists() ? { ...INITIAL_CONFIG, ...docSnap.data() as SystemConfig } : INITIAL_CONFIG;
  },

  saveConfig: async (config: SystemConfig) => {
    await setDoc(doc(db, COLLECTIONS.CONFIG, 'main_config'), cleanData(config));
  },

  fetchPrinterCounterSimulated: async (printer: Printer) => {
    await new Promise(r => setTimeout(r, 1000));
    const inc = Math.floor(Math.random() * 50) + 10;
    const bwInc = Math.floor(inc * 0.7);
    const colorInc = inc - bwInc;
    return { 
      total: printer.lastCounter + inc, 
      bw: (printer.lastCounterBW || 0) + bwInc,
      color: printer.isColor ? (printer.lastCounterColor || 0) + colorInc : 0
    };
  }
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Note } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { StickyNote, Plus, Trash2, Calendar, User as UserIcon, X, Save, AlertCircle, Image as ImageIcon, Edit3, Loader2 } from 'lucide-react';

interface NotesProps {
    user: { name: string };
}

export const Notes: React.FC<NotesProps> = ({ user }) => {
    const [notes, setNotes] = useState<Note[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingNote, setEditingNote] = useState<Note | null>(null);
    const [formData, setFormData] = useState({ title: '', content: '', imageUrl: '' });
    const [saving, setSaving] = useState(false);

    useEffect(() => { loadData(); }, []);

    const loadData = async () => {
        setLoading(true);
        const data = await StorageService.getNotes();
        setNotes(data);
        setLoading(false);
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const openAddModal = () => {
        setEditingNote(null);
        setFormData({ title: '', content: '', imageUrl: '' });
        setIsModalOpen(true);
    };

    const openEditModal = (note: Note) => {
        setEditingNote(note);
        setFormData({ title: note.title, content: note.content, imageUrl: note.imageUrl || '' });
        setIsModalOpen(true);
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.title.trim() || !formData.content.trim()) return;

        setSaving(true);
        try {
            if (editingNote) {
                // UPDATE
                const updatedNote: Note = {
                    ...editingNote,
                    title: formData.title,
                    content: formData.content,
                    imageUrl: formData.imageUrl || undefined,
                    user: user.name // Track who made the last change
                };
                await StorageService.updateNote(updatedNote);
            } else {
                // CREATE
                const note: Note = {
                    id: '',
                    title: formData.title,
                    content: formData.content,
                    date: new Date().toISOString(),
                    user: user.name,
                    imageUrl: formData.imageUrl || undefined
                };
                await StorageService.addNote(note);
            }
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            alert("Kaydedilirken bir hata oluştu.");
        } finally {
            setSaving(false);
        }
    };

    const handleDelete = async (note: Note) => {
        if (window.confirm(`"${note.title}" başlıklı notu kalıcı olarak silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`)) {
            setLoading(true);
            await StorageService.deleteNote(note.id, user.name, note.title);
            loadData();
        }
    };

    if (loading) return <LoadingScreen message="Notlar senkronize ediliyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            {/* Header */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center gap-4 tracking-tighter uppercase">
                        <StickyNote size={48} className="text-emerald-500" /> Notlarım
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Operasyonel notları, arıza detaylarını ve yer değişikliklerini buradan yönetin.</p>
                </div>
                <button onClick={openAddModal} className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase">
                    <Plus size={24} /> YENİ NOT EKLE
                </button>
            </div>

            {/* Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {notes.map(note => (
                    <div key={note.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl group hover:border-emerald-500/30 transition-all flex flex-col overflow-hidden">
                        {note.imageUrl && (
                            <div className="w-full h-52 overflow-hidden bg-zinc-100 dark:bg-zinc-900 border-b border-zinc-100 dark:border-zinc-900">
                                <img src={note.imageUrl} alt={note.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                            </div>
                        )}
                        <div className="p-8 flex-1 flex flex-col">
                            <div className="flex justify-between items-start mb-6">
                                <div className="p-4 bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 rounded-2xl shadow-sm"><StickyNote size={28}/></div>
                                <div className="flex flex-col items-end gap-1 text-[10px] font-black uppercase tracking-widest text-zinc-400">
                                    <span className="flex items-center gap-1.5"><Calendar size={14}/> {new Date(note.date).toLocaleDateString('tr-TR')}</span>
                                    <span className="flex items-center gap-1.5 bg-zinc-50 dark:bg-zinc-900 px-3 py-1.5 rounded-full"><UserIcon size={12}/> {note.user}</span>
                                </div>
                            </div>
                            <h3 className="text-2xl font-black text-zinc-900 dark:text-white mb-4 uppercase leading-tight tracking-tighter">{note.title}</h3>
                            <p className="text-zinc-500 dark:text-zinc-400 text-sm font-medium leading-relaxed flex-1 mb-10">{note.content}</p>

                            <div className="pt-6 border-t border-zinc-100 dark:border-zinc-900 grid grid-cols-2 gap-4">
                                <button 
                                    onClick={() => openEditModal(note)}
                                    className="py-4 bg-zinc-100 dark:bg-zinc-900 text-zinc-900 dark:text-white rounded-2xl font-black text-[10px] tracking-widest uppercase hover:bg-blue-500 hover:text-white transition-all flex items-center justify-center gap-2"
                                >
                                    <Edit3 size={16} /> DÜZENLE
                                </button>
                                <button 
                                    onClick={() => handleDelete(note)}
                                    className="py-4 bg-red-50 dark:bg-red-950/20 text-red-600 rounded-2xl font-black text-[10px] tracking-widest uppercase hover:bg-red-600 hover:text-white transition-all flex items-center justify-center gap-2"
                                >
                                    <Trash2 size={16} /> NOTU SİL
                                </button>
                            </div>
                        </div>
                    </div>
                ))}

                {notes.length === 0 && (
                    <div className="col-span-full py-32 bg-zinc-50 dark:bg-zinc-900/50 rounded-[4rem] border-4 border-dashed border-zinc-200 dark:border-zinc-800 flex flex-col items-center justify-center text-zinc-400 gap-6">
                        <div className="p-8 bg-white dark:bg-zinc-800 rounded-full shadow-2xl opacity-50"><AlertCircle size={64} /></div>
                        <p className="font-black text-2xl uppercase tracking-tighter">Henüz hiçbir kayıt bulunmuyor.</p>
                        <button onClick={openAddModal} className="text-emerald-500 font-black text-sm underline decoration-2 underline-offset-8 uppercase tracking-widest hover:text-emerald-400 transition-colors">İLK NOTU ŞİMDİ EKLE</button>
                    </div>
                )}
            </div>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[200] flex items-center justify-center p-6 animate-in fade-in duration-500">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-2xl shadow-[0_40px_100px_-20px_rgba(0,0,0,1)] overflow-hidden animate-in zoom-in-95 duration-500 border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
                        <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                            <div>
                                <h3 className="font-black text-3xl text-zinc-900 dark:text-white tracking-tighter uppercase">
                                    {editingNote ? 'NOTU DÜZENLE' : 'YENİ NOT OLUŞTUR'}
                                </h3>
                                <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-[0.3em] mt-2">Operasyonel Kayıt Sistemi</p>
                            </div>
                            <button onClick={() => setIsModalOpen(false)} className="p-4 bg-white dark:bg-zinc-800 rounded-3xl shadow-xl hover:text-red-500 hover:rotate-90 transition-all"><X size={32}/></button>
                        </div>

                        <form onSubmit={handleSave} className="p-10 space-y-8 overflow-y-auto custom-scrollbar flex-1">
                            <div className="space-y-3">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.4em] ml-2">BAŞLIK / KONU</label>
                                <input 
                                    required 
                                    type="text" 
                                    className="w-full p-6 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-black text-lg outline-none focus:border-emerald-500 focus:bg-white dark:focus:bg-black transition-all" 
                                    placeholder="Örn: 2. Kat Poliklinik Cihaz Değişimi" 
                                    value={formData.title} 
                                    onChange={e => setFormData({...formData, title: e.target.value})} 
                                />
                            </div>

                            <div className="space-y-3">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.4em] ml-2">NOT İÇERİĞİ VE DETAYLAR</label>
                                <textarea 
                                    required 
                                    rows={5} 
                                    className="w-full p-6 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500 focus:bg-white dark:focus:bg-black transition-all leading-relaxed" 
                                    placeholder="Operasyonla ilgili tüm detayları buraya aktarın..." 
                                    value={formData.content} 
                                    onChange={e => setFormData({...formData, content: e.target.value})} 
                                />
                            </div>

                            <div className="space-y-4">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.4em] ml-2">GÖRSEL KANIT (OPSİYONEL)</label>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                    <label className="flex flex-col items-center justify-center p-10 border-4 border-dashed border-zinc-100 dark:border-zinc-800 rounded-[2.5rem] bg-zinc-50 dark:bg-zinc-900 cursor-pointer hover:border-emerald-500 hover:bg-emerald-50/10 transition-all group">
                                        <ImageIcon size={48} className="text-zinc-300 group-hover:text-emerald-500 transition-colors mb-4" />
                                        <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest group-hover:text-emerald-500">RESİM ÇEK VEYA YÜKLE</span>
                                        <input type="file" accept="image/*" onChange={handleImageChange} className="hidden" />
                                    </label>

                                    {formData.imageUrl ? (
                                        <div className="relative group rounded-[2.5rem] overflow-hidden border-2 border-zinc-100 dark:border-zinc-800 shadow-2xl">
                                            <img src={formData.imageUrl} className="w-full h-full object-cover" />
                                            <button 
                                                type="button" 
                                                onClick={() => setFormData(prev => ({ ...prev, imageUrl: '' }))} 
                                                className="absolute top-4 right-4 p-3 bg-red-600 text-white rounded-2xl shadow-xl hover:scale-110 active:scale-90 transition-all"
                                            >
                                                <X size={20} />
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="flex items-center justify-center rounded-[2.5rem] border-4 border-zinc-50 dark:border-zinc-900/50 bg-zinc-50/50 dark:bg-zinc-950/50 text-zinc-300 font-black text-[10px] uppercase tracking-widest text-center px-10">
                                            Henüz bir görsel eklenmedi
                                        </div>
                                    )}
                                </div>
                            </div>

                            <button 
                                type="submit" 
                                disabled={saving}
                                className="w-full py-8 bg-emerald-600 text-white rounded-[2.5rem] font-black shadow-2xl shadow-emerald-500/30 active:scale-95 transition-all flex items-center justify-center gap-4 uppercase tracking-[0.2em] mt-6 disabled:opacity-50"
                            >
                                {saving ? <Loader2 className="animate-spin" size={24}/> : <Save size={24} />} 
                                {editingNote ? 'DEĞİŞİKLİKLERİ KAYDET' : 'NOTU SİSTEME EKLE'}
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { StorageService } from '../services/storage';
import { StockLog, ActivityLog } from '../types';
import { ArrowDown, ArrowUp, Download, FileSpreadsheet, History as HistoryIcon, Clock, User as UserIcon, Activity } from 'lucide-react';
import { LoadingScreen } from './LoadingScreen';

export const History: React.FC = () => {
  const [logs, setLogs] = useState<StockLog[]>([]);
  const [activities, setActivities] = useState<ActivityLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'STOCK' | 'SYSTEM'>('STOCK');

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
      setLoading(true);
      const [stockLogs, activityLogs] = await Promise.all([
          StorageService.getLogs(),
          StorageService.getActivities()
      ]);
      setLogs(stockLogs);
      setActivities(activityLogs);
      setLoading(false);
  };

  const downloadCSV = () => {
    if (tab === 'STOCK' && logs.length === 0) return;

    const headers = tab === 'STOCK' 
        ? ["Tarih", "Saat", "Islem Turu", "Toner Modeli", "Miktar", "Maliyet", "Aciklama", "Kullanici"]
        : ["Tarih", "Saat", "Aktivite", "Detay", "Kullanici"];

    const rows = tab === 'STOCK' 
        ? logs.map(log => {
            const d = new Date(log.date);
            return [d.toLocaleDateString('tr-TR'), d.toLocaleTimeString('tr-TR'), log.type === 'IN' ? 'Giris' : 'Cikis', log.tonerModel, log.quantity, log.cost || 0, `"${log.description}"`, log.user].join(",");
          })
        : activities.map(act => {
            const d = new Date(act.date);
            return [d.toLocaleDateString('tr-TR'), d.toLocaleTimeString('tr-TR'), act.action, `"${act.details}"`, act.user].join(",");
          });

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers.join(",") + "\n" + rows.join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", `toner_${tab.toLowerCase()}_gecmis_${new Date().toLocaleDateString()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) return <LoadingScreen message="Geçmiş kayıtlar analiz ediliyor..." />;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <h2 className="text-2xl font-black text-zinc-900 dark:text-white uppercase tracking-tighter">İşlem Geçmişi & Loglar</h2>
          <div className="flex gap-2 w-full sm:w-auto">
              <div className="bg-zinc-100 dark:bg-zinc-900 p-1 rounded-xl flex gap-1">
                  <button onClick={() => setTab('STOCK')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${tab === 'STOCK' ? 'bg-zinc-900 dark:bg-zinc-700 text-white shadow-lg' : 'text-zinc-500'}`}>Stok</button>
                  <button onClick={() => setTab('SYSTEM')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${tab === 'SYSTEM' ? 'bg-zinc-900 dark:bg-zinc-700 text-white shadow-lg' : 'text-zinc-500'}`}>Sistem</button>
              </div>
              <button onClick={downloadCSV} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2.5 rounded-xl font-black text-xs uppercase transition-all shadow-lg shadow-emerald-500/20"><FileSpreadsheet size={18} /> Aktar</button>
          </div>
      </div>

      <div className="bg-white dark:bg-zinc-900 rounded-3xl shadow-xl border border-zinc-100 dark:border-zinc-800 overflow-hidden">
        <div className="overflow-x-auto">
          {tab === 'STOCK' ? (
              <table className="w-full text-left text-sm text-zinc-600 dark:text-zinc-300">
                <thead className="bg-zinc-50 dark:bg-zinc-800/50 text-zinc-900 dark:text-white font-black uppercase text-[10px] tracking-widest border-b border-zinc-100 dark:border-zinc-800">
                  <tr>
                    <th className="p-5">Zaman</th>
                    <th className="p-5">Tür</th>
                    <th className="p-5">Toner</th>
                    <th className="p-5">Miktar</th>
                    <th className="p-5">Maliyet</th>
                    <th className="p-5">Açıklama</th>
                    <th className="p-5">Kullanıcı</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800">
                  {logs.map(log => (
                    <tr key={log.id} className="hover:bg-zinc-50 dark:hover:bg-zinc-800/30 transition-colors">
                      <td className="p-5 whitespace-nowrap">
                        <span className="font-bold">{new Date(log.date).toLocaleDateString('tr-TR')}</span><br/>
                        <span className="text-[10px] opacity-40 font-mono">{new Date(log.date).toLocaleTimeString('tr-TR')}</span>
                      </td>
                      <td className="p-5">
                        <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${log.type === 'IN' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                          {log.type === 'IN' ? <ArrowDown size={12} /> : <ArrowUp size={12} />}
                          {log.type === 'IN' ? 'Giriş' : 'Çıkış'}
                        </span>
                      </td>
                      <td className="p-5 font-black text-zinc-900 dark:text-white">{log.tonerModel}</td>
                      <td className="p-5 font-mono">{log.quantity}</td>
                      <td className="p-5 font-bold">{log.cost ? `${log.cost} ₺` : '-'}</td>
                      <td className="p-5 text-xs italic">{log.description}</td>
                      <td className="p-5 font-bold">{log.user}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
          ) : (
              <div className="divide-y divide-zinc-100 dark:divide-zinc-800">
                  {activities.map(act => (
                      <div key={act.id} className="p-6 hover:bg-zinc-50 dark:hover:bg-zinc-800/30 transition-all flex items-start gap-4">
                          <div className={`p-3 rounded-2xl ${act.action.includes('SILINDI') ? 'bg-red-50 text-red-500' : act.action.includes('GUNCELLEME') ? 'bg-blue-50 text-blue-500' : 'bg-emerald-50 text-emerald-500'}`}>
                              <Activity size={20} />
                          </div>
                          <div className="flex-1">
                              <div className="flex justify-between items-start mb-1">
                                  <h4 className="font-black text-zinc-900 dark:text-white text-xs uppercase tracking-widest">{act.action.replace('_', ' ')}</h4>
                                  <span className="text-[10px] font-mono text-zinc-400">{new Date(act.date).toLocaleString('tr-TR')}</span>
                              </div>
                              <p className="text-sm text-zinc-500 dark:text-zinc-400 font-medium">{act.details}</p>
                              <div className="mt-3 flex items-center gap-1.5 text-[9px] font-black uppercase text-zinc-400 bg-zinc-100 dark:bg-zinc-800 w-fit px-2 py-1 rounded-md">
                                  <UserIcon size={12}/> {act.user}
                              </div>
                          </div>
                      </div>
                  ))}
                  {activities.length === 0 && <div className="p-20 text-center text-zinc-400 font-bold uppercase tracking-widest">Aktivite kaydı bulunamadı.</div>}
              </div>
          )}
        </div>
      </div>
    </div>
  );
};

