  id: string;
  serialNumber: string;
  shortCode?: string;
  brand: string;
  model: string;
  location: string;
  floor: string;
  lastCounter: number;
  lastTonerDate: string;
  compatibleToner: string;
  connectionType: ConnectionType;
  ipAddress?: string;
  supplier: string;
  status: PrinterStatus;
  monthlyRentalCost: number; // Yeni: Aylık sabit kiralama bedeli
  connectedUsers?: string[];
  isColor?: boolean;
  lastCounterBW?: number;
  lastCounterColor?: number;
}

export interface Note {
  id: string;
  title: string;
  content: string;
  date: string;
  user: string;
  imageUrl?: string;
}

export interface ActivityLog {
  id: string;
  date: string;
  user: string;
  action: string;
  details: string;
}

export interface TonerStock {
