  actionTaken: string;
  note?: string;
  imageUrl?: string;
  cost: number;
  provider: string;
  status: 'PENDING' | 'COMPLETED' | 'SCRAPPED';
  lastModifiedBy?: string;
}

export interface CounterLog {
  id: string;
  printerId: string;
  printerName: string;
  serialNumber: string;
  date: string;
  previousCounter: number;
  currentCounter: number;
  usage: number;
  recordedBy: string;
  usageBW?: number;
  usageColor?: number;
  currentBW?: number;
  currentColor?: number;
  customCounters?: { label: string; value: number }[];
}

export interface SystemConfig {
  brands: string[];
  models: string[];
  suppliers: string[];
  tonerModels: string[];
  whatsappNumber?: string;
  brandImages?: Record<string, string>; 
  modelImages?: Record<string, string>;
