import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, QrCode, Download, RefreshCw, Wallet, Calendar, Calculator, BarChart3, Copy, Share2, Wrench, Droplet, Globe, Activity, ChevronRight, TrendingUp, Clock, User as UserIcon, Banknote } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, PrinterStatus, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

interface PrinterStats {
  totalSpent: number;
  totalServiceCost: number;
  totalTonerCost: number;
  lastServiceDate: string | null;
  tonerCount: number;
}

export const PrinterList: React.FC<PrinterListProps> = ({ targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [qrPrinter, setQrPrinter] = useState<PrinterType | null>(null);
  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);
  const [selectedPrinterHistory, setSelectedPrinterHistory] = useState<{
      printer: PrinterType, 
      tonerLogs: StockLog[], 
      serviceLogs: ServiceRecord[], 
      counterLogs: CounterLog[], 
      stats: PrinterStats
  } | null>(null);

  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '',
    model: '',
    serialNumber: '',
    shortCode: '',
    location: '',
    floor: '',
    lastCounter: 0,
    connectionType: 'USB',
    ipAddress: '',
    status: 'ACTIVE',
    monthlyRentalCost: 0
  });

  useEffect(() => { loadData(); }, []);

  useEffect(() => {
    const handlePopState = () => {
      setQrPrinter(null);
      setIsHistoryModalOpen(false);
      setIsFormModalOpen(false);
      setEditingPrinter(null);
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const target = printers.find(p => p.id === targetPrinterId);
      if (target) openHistoryModal(target);
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([StorageService.getPrinters(), StorageService.getConfig()]);
    setPrinters(p);
    setConfig(c);
    setLoading(false);
  };

  const openFormModal = (printer?: PrinterType) => {
    window.history.pushState({ modal: 'form' }, '');
    if (printer) {
      setEditingPrinter(printer); 
      setFormData({
        ...printer,
        monthlyRentalCost: printer.monthlyRentalCost || 0
      });
    } else {
      setEditingPrinter(null);
      setFormData({ 
        brand: config.brands[0] || '', 
        model: config.models[0] || '', 
        status: 'ACTIVE', 
        connectionType: 'USB',
        monthlyRentalCost: 0 
      });
    }
    setIsFormModalOpen(true);
  };

  const openHistoryModal = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'history' }, '');
    const [allLogs, allServices, allCounterLogs] = await Promise.all([
        StorageService.getLogs(), 
        StorageService.getServiceRecords(), 
        StorageService.getCounterLogs()
    ]);

    const tonerLogs = allLogs.filter(log => log.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const serviceLogs = allServices.filter(srv => srv.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const counterLogs = allCounterLogs.filter(l => l.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const totalTonerCost = tonerLogs.reduce((sum, log) => sum + (log.cost || 0), 0);
    const totalServiceCost = serviceLogs.reduce((sum, srv) => sum + (srv.cost || 0), 0);

    setSelectedPrinterHistory({ 
        printer, tonerLogs, serviceLogs, counterLogs, 
        stats: { totalSpent: totalTonerCost + totalServiceCost, totalTonerCost, totalServiceCost, lastServiceDate: serviceLogs[0]?.date || null, tonerCount: tonerLogs.length } 
    });
    setIsHistoryModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const cleanFormData = {
      ...formData,
      monthlyRentalCost: Number(formData.monthlyRentalCost) || 0
    };

    if (editingPrinter?.id) {
       await StorageService.updatePrinter({ ...editingPrinter, ...cleanFormData } as PrinterType);
    } else {
       await StorageService.addPrinter({ id: '', lastTonerDate: new Date().toISOString(), ...cleanFormData as PrinterType });
    }
    window.history.back();
    loadData();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]';
      case 'MAINTENANCE': return 'bg-orange-500 shadow-[0_0_15px_rgba(249,115,22,0.5)]';
      case 'BROKEN': return 'bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.5)]';
      case 'SPARE': return 'bg-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.5)]';
      default: return 'bg-zinc-500';
    }
  };

  const filteredPrinters = printers.filter(p => {
    const s = searchTerm.toLocaleLowerCase('tr-TR');
    return (p.model.toLocaleLowerCase('tr-TR').includes(s) || p.location.toLocaleLowerCase('tr-TR').includes(s) || p.shortCode?.includes(s));
  });

  return (
    <div className="space-y-8 pb-32">
      {/* Header Panel */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 bg-white dark:bg-zinc-950 p-8 rounded-[2rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 overflow-hidden relative group transition-all">
        <div>
          <h2 className="text-3xl font-black text-zinc-900 dark:text-white tracking-tighter uppercase">CİHAZ HAVUZU</h2>
          <p className="text-sm font-bold text-zinc-400 mt-1 uppercase tracking-widest">{printers.length} Kayıtlı Cihaz</p>
        </div>
        <div className="flex gap-3 w-full sm:w-auto relative z-10">
            <button onClick={loadData} className="p-4 bg-zinc-100 dark:bg-zinc-900 rounded-2xl text-zinc-500 dark:text-zinc-400 hover:text-emerald-500 transition-all"><RefreshCw size={24}/></button>
            <button onClick={() => openFormModal()} className="flex-1 sm:flex-none bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl flex items-center justify-center gap-3 font-black shadow-xl transition-all"><Plus size={24} /> YENİ KAYIT</button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative group">
        <div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none text-zinc-400 group-focus-within:text-emerald-500 transition-colors"><Search size={24} /></div>
        <input type="text" placeholder="Model, Hızlı Kod veya Lokasyon ara..." className="w-full pl-16 pr-8 py-6 rounded-[2rem] border-2 border-transparent bg-white dark:bg-zinc-950 text-zinc-900 dark:text-white shadow-xl focus:border-emerald-500 outline-none transition-all font-bold text-lg" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredPrinters.map(printer => (
          <div key={printer.id} className="group rounded-[2.5rem] shadow-lg hover:shadow-2xl border border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950 overflow-hidden transition-all duration-500 flex flex-col relative hover:-translate-y-2">
            <div className={`absolute top-6 left-6 w-3 h-3 rounded-full ${getStatusBadge(printer.status)} z-20`}></div>
            <div className="p-8 flex-1 cursor-pointer active:opacity-90 transition-opacity" onClick={() => openHistoryModal(printer)}>
              <div className="flex flex-col gap-4">
                  <div className="space-y-1">
                       <div className="flex items-center gap-2 text-zinc-900 dark:text-white font-black text-xs uppercase tracking-widest pl-5"><MapPin size={14} className="text-emerald-500" /> {printer.location}</div>
                  </div>
                  <div className="flex gap-4">
                      <div className="flex-1">
                          <h3 className="text-2xl font-black text-zinc-900 dark:text-white leading-tight group-hover:text-emerald-500 transition-colors">{printer.brand} {printer.model}</h3>
                          <div className="flex flex-wrap gap-2 mt-4">
                            <span className="text-xs font-black text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/40 px-3 py-1.5 rounded-xl border border-emerald-100 dark:border-emerald-900/50 tracking-widest">#{printer.shortCode}</span>
                            {printer.monthlyRentalCost > 0 && (
                               <span className="flex items-center gap-1.5 text-[10px] font-black text-orange-600 dark:text-orange-400 bg-orange-50 dark:bg-orange-950/40 px-3 py-1.5 rounded-xl border border-orange-100 dark:border-orange-900/50 uppercase"><Banknote size={14}/> {printer.monthlyRentalCost} ₺ / Ay</span>
                            )}
                          </div>
                      </div>
                  </div>
              </div>
              <div className="mt-8 pt-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-between items-center">
                  <div className="flex flex-col">
                      <span className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">Güncel Sayaç</span>
                      <span className="text-xl font-mono font-black text-zinc-900 dark:text-white">{printer.lastCounter.toLocaleString()}</span>
                  </div>
                  <div className="bg-emerald-50 dark:bg-emerald-950 p-3 rounded-2xl text-emerald-500 group-hover:scale-110 transition-transform"><TrendingUp size={24}/></div>
              </div>
            </div>
            <div className="grid grid-cols-2 border-t border-zinc-100 dark:border-zinc-900 bg-zinc-50/50 dark:bg-zinc-900/50">
                <button onClick={() => openFormModal(printer)} className="py-6 flex items-center justify-center gap-2 text-zinc-500 dark:text-zinc-400 font-black text-xs uppercase tracking-widest hover:bg-emerald-50 dark:hover:bg-emerald-950 hover:text-emerald-600 transition-all border-r border-zinc-100 dark:border-zinc-900"><Edit2 size={18} /> DÜZENLE</button>
                <button onClick={async () => { if(confirm('Emin misiniz?')) { await StorageService.deletePrinter(printer.id); loadData(); } }} className="py-6 flex items-center justify-center gap-2 text-zinc-500 dark:text-zinc-400 font-black text-xs uppercase tracking-widest hover:bg-red-50 dark:hover:bg-red-950 hover:text-red-500 transition-all"><Trash2 size={18} /> SİL</button>
            </div>
          </div>
        ))}
      </div>

      {/* Printer Form Modal */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[200] flex items-center justify-center p-6 animate-in fade-in duration-500">
          <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-500 border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
            <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
              <div>
                <h3 className="font-black text-3xl text-zinc-900 dark:text-white tracking-tighter uppercase">{editingPrinter ? 'CİHAZ GÜNCELLE' : 'YENİ CİHAZ EKLE'}</h3>
                <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-[0.3em] mt-2">Envanter Kayıt Paneli</p>
              </div>
              <button onClick={() => window.history.back()} className="p-4 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all"><X size={32} strokeWidth={3} /></button>
            </div>
            <form onSubmit={handleSave} className="p-10 space-y-6 overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Marka</label>
                  <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})}>
                    {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Model</label>
                  <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})}>
                    {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Seri Numarası</label>
                  <input required type="text" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Lokasyon</label>
                  <input required type="text" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Kat</label>
                  <input type="text" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Durum</label>
                  <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as PrinterStatus})}>
                    <option value="ACTIVE">Aktif</option>
                    <option value="MAINTENANCE">Bakımda</option>
                    <option value="BROKEN">Arızalı</option>
                    <option value="SPARE">Yedek</option>
                    <option value="SCRAPPED">Hurda</option>
                  </select>
                </div>
              </div>

              {/* Yeni: Kiralama Bedeli Alanı */}
              <div className="bg-orange-50 dark:bg-orange-950/20 p-6 rounded-[2rem] border-2 border-orange-100 dark:border-orange-900/30">
                <div className="flex items-center gap-3 mb-4">
                  <Banknote className="text-orange-500" />
                  <h4 className="font-black text-orange-900 dark:text-orange-400 text-xs uppercase tracking-widest">Finansal Bilgiler (Kiralama)</h4>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-orange-500 uppercase tracking-widest ml-2">Aylık Kiralama Bedeli (TL)</label>
                  <input 
                    type="number" 
                    min="0"
                    placeholder="0.00"
                    className="w-full p-4 border-2 border-orange-200 dark:border-orange-800 rounded-2xl bg-white dark:bg-zinc-900 text-zinc-900 dark:text-white font-black font-mono outline-none focus:border-orange-500" 
                    value={formData.monthlyRentalCost} 
                    onChange={e => setFormData({...formData, monthlyRentalCost: Number(e.target.value)})} 
                  />
                  <p className="text-[9px] text-orange-400 font-bold uppercase mt-2 ml-2">Bu bedel, her ay ayın 15'inde faturanıza yansıyan sabit fiks bedeldir.</p>
                </div>
              </div>

              <button type="submit" className="w-full py-6 bg-emerald-600 text-white rounded-[2rem] font-black shadow-xl transition-all active:scale-95 uppercase tracking-widest">KAYDET VE SİSTEME İŞLE</button>
            </form>
          </div>
        </div>
      )}

      {/* History Drawer Section (Existing) */}
      {isHistoryModalOpen && selectedPrinterHistory && (
         <div className="fixed inset-0 z-[120] flex justify-end">
             <div className="absolute inset-0 bg-black/90 backdrop-blur-xl animate-in fade-in duration-300" onClick={() => window.history.back()}></div>
             <div className="relative w-full max-w-2xl bg-white dark:bg-zinc-950 h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden">
                 {/* Detail Header */}
                 <div className="p-10 bg-zinc-50 dark:bg-zinc-900 border-b border-zinc-200 dark:border-zinc-800 flex justify-between items-start">
                     <div>
                        <div className="flex items-center gap-3 mb-4">
                           <span className="bg-emerald-600 text-white px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-[0.3em] shadow-[0_0_20px_rgba(16,185,129,0.3)]">#{selectedPrinterHistory.printer.shortCode}</span>
                           <span className="text-zinc-400 text-xs font-mono font-black tracking-widest">{selectedPrinterHistory.printer.serialNumber}</span>
                        </div>
                        <h3 className="text-4xl font-black text-zinc-900 dark:text-white leading-none tracking-tighter uppercase">{selectedPrinterHistory.printer.brand} {selectedPrinterHistory.printer.model}</h3>
                        <div className="flex flex-wrap items-center gap-3 mt-5">
                           <p className="text-emerald-600 dark:text-emerald-400 font-black text-xs flex items-center gap-2 bg-emerald-50 dark:bg-emerald-950 p-2.5 rounded-2xl border border-emerald-100 dark:border-emerald-900"><MapPin size={18}/> {selectedPrinterHistory.printer.location}</p>
                           {selectedPrinterHistory.printer.monthlyRentalCost > 0 && (
                               <p className="text-orange-600 dark:text-orange-400 font-black text-xs flex items-center gap-2 bg-orange-50 dark:bg-orange-950 p-2.5 rounded-2xl border border-orange-100 dark:border-orange-900"><Banknote size={18}/> {selectedPrinterHistory.printer.monthlyRentalCost} ₺/AY (KİRA)</p>
                           )}
                        </div>
                     </div>
                     <button onClick={() => window.history.back()} className="p-4 bg-white dark:bg-zinc-800 rounded-[1.5rem] text-zinc-400 hover:text-red-500 shadow-2xl transition-all active:scale-90"><X size={32}/></button>
                 </div>

                 <div className="flex-1 overflow-y-auto p-10 space-y-12 custom-scrollbar bg-zinc-50/20 dark:bg-black">
                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-6">
                        <div className="bg-white dark:bg-zinc-900 p-6 rounded-[2rem] border border-zinc-200 dark:border-zinc-800 shadow-sm">
                            <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-3">GÜNCEL SAYAÇ</p>
                            <p className="text-3xl font-black text-zinc-900 dark:text-white font-mono">{selectedPrinterHistory.printer.lastCounter.toLocaleString()}</p>
                        </div>
                        <div className="bg-white dark:bg-zinc-900 p-6 rounded-[2rem] border border-zinc-200 dark:border-zinc-800 shadow-sm">
                            <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-3">TOPLAM MALİYET</p>
                            <p className="text-3xl font-black text-emerald-600 font-mono">{(selectedPrinterHistory.stats.totalSpent).toLocaleString()} ₺</p>
                        </div>
                        <div className="bg-white dark:bg-zinc-900 p-6 rounded-[2rem] border border-zinc-200 dark:border-zinc-800 shadow-sm">
                            <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-3">KİRA BEDELİ</p>
                            <p className="text-3xl font-black text-orange-500 font-mono">{selectedPrinterHistory.printer.monthlyRentalCost.toLocaleString()} ₺</p>
                        </div>
                    </div>
                    {/* Rest of history... */}
                 </div>
             </div>
         </div>
       )}
    </div>
  );
};

