              <p className="font-bold mb-2">"{deleteModal.val}" Silinsin mi?</p>
              <div className="grid grid-cols-2 gap-3 mt-6"><button onClick={() => setDeleteModal(null)} className="py-3 bg-slate-100 rounded-xl">Vazgeç</button><button onClick={handleDelete} className="py-3 bg-red-600 text-white rounded-xl">Evet, Sil</button></div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { StorageService } from '../services/storage';
import { Printer, TonerStock, StockLog, ServiceRecord } from '../types';
import { AlertCircle, CheckCircle2, Clock, Printer as PrinterIcon, Wallet, Wrench, RefreshCw, TrendingUp, Banknote, Package, Activity } from 'lucide-react';
import { LoadingScreen } from './LoadingScreen';

export const Dashboard: React.FC = () => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [stocks, setStocks] = useState<TonerStock[]>([]);
  const [logs, setLogs] = useState<StockLog[]>([]);
  const [services, setServices] = useState<ServiceRecord[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    setLoading(true);
    const [p, s, l, srv] = await Promise.all([
        StorageService.getPrinters(),
        StorageService.getStocks(),
        StorageService.getLogs(),
        StorageService.getServiceRecords()
    ]);
    setPrinters(p);
    setStocks(s);
    setLogs(l);
    setServices(srv);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, []);

  if (loading) {
      return <LoadingScreen message="Sistem durumu analiz ediliyor..." />;
  }

  // Hesaplamalar
  const totalActive = printers.filter(p => p.status === 'ACTIVE').length;
  const lowStockCount = stocks.filter(s => s.quantity < 3).length;
  const totalMonthlyRental = printers.reduce((acc, curr) => acc + (curr.monthlyRentalCost || 0), 0);
  const totalServiceCost = services.reduce((acc, curr) => acc + (curr.cost || 0), 0);

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Üst Bilgi */}
      <div className="flex justify-between items-center">
          <div>
            <h2 className="text-3xl font-black text-zinc-900 dark:text-white uppercase tracking-tighter">SİSTEM ÖZETİ</h2>
