import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, CounterLog } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, Calendar, ChevronRight, FileText, Download, Hash, Globe, Calculator, ArrowRight, TrendingUp } from 'lucide-react';

export const CostAnalysis: React.FC = () => {
    const [printers, setPrinters] = useState<Printer[]>([]);
    const [counterLogs, setCounterLogs] = useState<CounterLog[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setLoading(true);
        const [p, l] = await Promise.all([
            StorageService.getPrinters(),
            StorageService.getCounterLogs()
        ]);
        setPrinters(p);
        setCounterLogs(l);
        setLoading(false);
    };

    // 15-15 Periyodu Hesaplama
    const getPeriodUsage = (printerId: string) => {
        const now = new Date();
        const current15 = new Date(now.getFullYear(), now.getMonth(), 15);
        if (now.getDate() < 15) current15.setMonth(current15.getMonth() - 1);

        const previous15 = new Date(current15);
        previous15.setMonth(previous15.getMonth() - 1);

        const logs = counterLogs.filter(l => l.printerId === printerId);

        // En yakın sayaçları bul
        const currentLog = logs.find(l => {
            const d = new Date(l.date);
            return d.getDate() >= 13 && d.getDate() <= 17 && d.getMonth() === current15.getMonth();
        });

        const previousLog = logs.find(l => {
            const d = new Date(l.date);
            return d.getDate() >= 13 && d.getDate() <= 17 && d.getMonth() === previous15.getMonth();
        });

        const usage = (currentLog && previousLog) ? (currentLog.currentCounter - previousLog.currentCounter) : 0;

        return {
            usage,
            currentVal: currentLog?.currentCounter || 0,
            prevVal: previousLog?.currentCounter || 0,
            period: `${previous15.toLocaleDateString('tr-TR')} - ${current15.toLocaleDateString('tr-TR')}`
        };
    };

    if (loading) return <LoadingScreen message="Maliyet tabloları oluşturuluyor..." />;

    const totalRental = printers.reduce((acc, curr) => acc + (curr.monthlyRentalCost || 0), 0);

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Maliyet Analizi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Kiralama bedelleri ve 15-15 sayaç bazlı kullanım raporu.</p>
                </div>
                <div className="relative z-10 bg-emerald-50 dark:bg-emerald-950 px-8 py-5 rounded-[2rem] border border-emerald-100 dark:border-emerald-900 text-center">
                    <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-1">Toplam Aylık Sabit</p>
                    <p className="text-3xl font-black text-zinc-900 dark:text-white tracking-tighter">{totalRental.toLocaleString()} ₺</p>
                </div>
            </div>

            {/* Maliyet Tablosu */}
            <div className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden">
                <div className="p-8 border-b border-zinc-50 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                    <h3 className="font-black text-xl uppercase tracking-tighter flex items-center gap-3">
                        <Calculator size={24} className="text-emerald-500" /> Yazıcı Bazlı Gider Tablosu
                    </h3>
                    <div className="flex items-center gap-2 text-[10px] font-black text-zinc-400 uppercase tracking-widest">
                        <Calendar size={14} /> Sayaç Periyodu: 15'ten 15'ine
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-zinc-50 dark:bg-zinc-900 text-[10px] font-black uppercase tracking-widest text-zinc-400 border-b border-zinc-100 dark:border-zinc-800">
                            <tr>
                                <th className="p-6">Yazıcı / Lokasyon</th>
                                <th className="p-6">IP / Seri No</th>
                                <th className="p-6 text-center">Aylık Sabit</th>
                                <th className="p-6 text-center">Önceki Sayaç (15)</th>
                                <th className="p-6 text-center">Güncel Sayaç (15)</th>
                                <th className="p-6 text-center text-emerald-600">Dönemlik Kullanım</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-zinc-100 dark:divide-zinc-900">
                            {printers.map(printer => {
                                const stats = getPeriodUsage(printer.id);
                                return (
                                    <tr key={printer.id} className="hover:bg-zinc-50 dark:hover:bg-zinc-900/50 transition-colors">
                                        <td className="p-6">
                                            <p className="font-black text-zinc-900 dark:text-white uppercase text-sm">{printer.brand} {printer.model}</p>
                                            <p className="text-[10px] text-zinc-400 font-bold uppercase mt-0.5">{printer.location}</p>
                                        </td>
                                        <td className="p-6">
                                            <div className="flex flex-col gap-1">
                                                <span className="text-[10px] font-mono font-bold bg-zinc-100 dark:bg-zinc-800 px-2 py-0.5 rounded w-fit text-zinc-600 dark:text-zinc-400">{printer.ipAddress || 'USB'}</span>
                                                <span className="text-[10px] font-mono text-zinc-400">{printer.serialNumber}</span>
                                            </div>
                                        </td>
                                        <td className="p-6 text-center">
                                            <span className="font-black text-zinc-900 dark:text-white font-mono">{printer.monthlyRentalCost?.toLocaleString() || 0} ₺</span>
                                        </td>
                                        <td className="p-6 text-center text-zinc-400 font-mono text-xs">
                                            {stats.prevVal.toLocaleString()}
                                        </td>
                                        <td className="p-6 text-center text-zinc-400 font-mono text-xs">
                                            {stats.currentVal.toLocaleString()}
                                        </td>
                                        <td className="p-6 text-center">
                                            <div className="inline-flex items-center gap-2 bg-emerald-50 dark:bg-emerald-950/40 px-4 py-2 rounded-2xl border border-emerald-100 dark:border-emerald-900">
                                                <TrendingUp size={14} className="text-emerald-500" />
