import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, CounterLog } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, Calendar, Calculator, TrendingUp, Globe, Hash, LayoutList } from 'lucide-react';

export const CostAnalysis: React.FC = () => {
    const [printers, setPrinters] = useState<Printer[]>([]);
    const [counterLogs, setCounterLogs] = useState<CounterLog[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setLoading(true);
        const [p, l] = await Promise.all([
            StorageService.getPrinters(),
            StorageService.getCounterLogs()
        ]);
        setPrinters(p);
        setCounterLogs(l);
        setLoading(false);
    };

    // 15-15 Periyodu Hesaplama Mantığı
    const getPeriodUsage = (printerId: string) => {
        const now = new Date();
        // Bu ayın 15'i
        const current15 = new Date(now.getFullYear(), now.getMonth(), 15);
        if (now.getDate() < 15) current15.setMonth(current15.getMonth() - 1);

        // Geçen ayın 15'i
        const previous15 = new Date(current15);
        previous15.setMonth(previous15.getMonth() - 1);

        const logs = counterLogs.filter(l => l.printerId === printerId);

        // Bu dönemin son sayacını bul (Ayın 15'i civarı girilen)
        const currentLog = logs.find(l => {
            const d = new Date(l.date);
            return d.getDate() >= 13 && d.getDate() <= 17 && d.getMonth() === current15.getMonth();
        });

        // Geçen dönemin son sayacını bul
        const previousLog = logs.find(l => {
            const d = new Date(l.date);
            return d.getDate() >= 13 && d.getDate() <= 17 && d.getMonth() === previous15.getMonth();
        });

        const usage = (currentLog && previousLog) ? (currentLog.currentCounter - previousLog.currentCounter) : 0;

        return {
            usage: usage > 0 ? usage : 0,
            currentVal: currentLog?.currentCounter || 0,
            prevVal: previousLog?.currentCounter || 0,
            period: `${previous15.toLocaleDateString('tr-TR')} - ${current15.toLocaleDateString('tr-TR')}`
        };
    };

    if (loading) return <LoadingScreen message="Maliyet tabloları oluşturuluyor..." />;

    const totalRental = printers.reduce((acc, curr) => acc + (curr.monthlyRentalCost || 0), 0);

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header Panel */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Maliyet Analizi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Kiralama bedelleri ve 15-15 sayaç bazlı kullanım raporu.</p>
                </div>
                <div className="relative z-10 bg-emerald-50 dark:bg-emerald-950 px-10 py-6 rounded-[2.5rem] border border-emerald-100 dark:border-emerald-900 text-center">
                    <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-1">Toplam Aylık Fiks Kira</p>
                    <p className="text-4xl font-black text-zinc-900 dark:text-white tracking-tighter">{totalRental.toLocaleString()} ₺</p>
                </div>
            </div>

            {/* Maliyet Tablosu */}
            <div className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden">
                <div className="p-8 border-b border-zinc-50 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                    <h3 className="font-black text-xl uppercase tracking-tighter flex items-center gap-3">
                        <LayoutList size={24} className="text-emerald-500" /> Kurumsal Gider Tablosu
                    </h3>
                    <div className="flex items-center gap-2 text-[10px] font-black text-zinc-400 uppercase tracking-widest">
                        <Calendar size={14} /> Sayaç Periyodu: Her Ayın 15'i
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-zinc-50 dark:bg-zinc-900 text-[10px] font-black uppercase tracking-widest text-zinc-400 border-b border-zinc-100 dark:border-zinc-800">
                            <tr>
                                <th className="p-8">Cihaz / Lokasyon</th>
                                <th className="p-8">IP / Seri No</th>
                                <th className="p-8 text-center">Aylık Sabit (Kira)</th>
                                <th className="p-8 text-center">Önceki Sayaç (15)</th>
                                <th className="p-8 text-center">Güncel Sayaç (15)</th>
                                <th className="p-8 text-center text-emerald-600">Dönemlik Kullanım</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-zinc-100 dark:divide-zinc-900">
                            {printers.map(printer => {
                                const stats = getPeriodUsage(printer.id);
                                return (
                                    <tr key={printer.id} className="hover:bg-zinc-50 dark:hover:bg-zinc-900/50 transition-colors group">
                                        <td className="p-8">
                                            <p className="font-black text-zinc-900 dark:text-white uppercase text-base">{printer.brand} {printer.model}</p>
                                            <p className="text-[10px] text-zinc-400 font-bold uppercase mt-1 tracking-wider">{printer.location}</p>
                                        </td>
                                        <td className="p-8">
                                            <div className="flex flex-col gap-1.5">
                                                <span className="text-[10px] font-mono font-bold bg-zinc-100 dark:bg-zinc-800 px-3 py-1 rounded-lg w-fit text-zinc-600 dark:text-zinc-400 border border-zinc-200 dark:border-zinc-700">{printer.ipAddress || 'USB'}</span>
                                                <span className="text-[10px] font-mono text-zinc-400 ml-1">{printer.serialNumber}</span>
                                            </div>
                                        </td>
                                        <td className="p-8 text-center">
                                            <span className="font-black text-zinc-900 dark:text-white font-mono text-lg">{printer.monthlyRentalCost?.toLocaleString() || 0} ₺</span>
                                        </td>
                                        <td className="p-8 text-center text-zinc-400 font-mono text-xs font-bold">
                                            {stats.prevVal > 0 ? stats.prevVal.toLocaleString() : '-'}
                                        </td>
                                        <td className="p-8 text-center text-zinc-400 font-mono text-xs font-bold">
                                            {stats.currentVal > 0 ? stats.currentVal.toLocaleString() : '-'}
                                        </td>
                                        <td className="p-8 text-center">
                                            <div className="inline-flex items-center gap-3 bg-emerald-50 dark:bg-emerald-950/40 px-5 py-2.5 rounded-2xl border border-emerald-100 dark:border-emerald-900 shadow-sm">
                                                <TrendingUp size={16} className="text-emerald-500" />
                                                <span className="font-black text-emerald-600 dark:text-emerald-400 font-mono text-sm">{stats.usage.toLocaleString()} Sayfa</span>
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>

                {printers.length === 0 && (
                    <div className="p-32 text-center">
                        <p className="text-zinc-400 font-black uppercase tracking-widest text-xl opacity-30">Hesaplanacak veri bulunamadı.</p>
                    </div>
                )}
            </div>

            {/* Bilgi Kutusu */}
            <div className="bg-zinc-900 p-10 rounded-[3.5rem] text-white flex flex-col md:flex-row items-center gap-10 border border-zinc-800 shadow-2xl relative overflow-hidden">
                <div className="absolute right-0 top-0 w-32 h-32 bg-emerald-500/10 blur-3xl"></div>
                <div className="p-8 bg-emerald-600 rounded-[2.5rem] shadow-2xl shadow-emerald-500/20">
                    <Calculator size={56} />
                </div>
                <div>
                    <h4 className="text-3xl font-black uppercase tracking-tighter mb-4">Sistem Nasıl Çalışır?</h4>
                    <p className="text-zinc-400 font-medium leading-relaxed max-w-3xl text-lg">
                        Bu tablo, her ayın 15'inde alınan sayaç verilerini baz alır. Eğer 15'inde (±2 gün esneklik payı ile) sayaç girilmişse, bir önceki ayın aynı dönemindeki veriyle kıyaslayarak **Dönemlik Kullanım** miktarını otomatik hesaplar. Sabit kira bedelleri her ay toplam maliyete eklenir.
                    </p>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
import { Dashboard } from './components/Dashboard';
import { PrinterList } from './components/PrinterList';
import { StockManagement } from './components/StockManagement';
import { History } from './components/History';
import { Settings } from './components/Settings';
import { ServiceManagement } from './components/ServiceManagement';
import { QrManagement } from './components/QrManagement';
import { QrScanner } from './components/QrScanner';
import { Inventory } from './components/Inventory';
import { CounterManagement } from './components/CounterManagement';
import { Notes } from './components/Notes';
import { CostAnalysis } from './components/CostAnalysis';
import { User } from './types';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [targetPrinterId, setTargetPrinterId] = useState<string | null>(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('app_user');
    if (savedUser) setUser(JSON.parse(savedUser));

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme === 'dark') setIsDarkMode(true);

    const params = new URLSearchParams(window.location.search);
    const pid = params.get('pid');
    if (pid) setTargetPrinterId(pid);
  }, []);

  useEffect(() => {
    if (user && targetPrinterId) setActiveTab('printers');
  }, [user, targetPrinterId]);

  const handleLogin = (user: User) => {
    localStorage.setItem('app_user', JSON.stringify(user));
    setUser(user);
  };

  const handleLogout = () => {
    localStorage.removeItem('app_user');
    setUser(null);
    setActiveTab('dashboard');
    setTargetPrinterId(null);
    window.history.replaceState({}, '', window.location.pathname);
  };

  const toggleTheme = () => {
    const newMode = !isDarkMode;
    setIsDarkMode(newMode);
    localStorage.setItem('app_theme', newMode ? 'dark' : 'light');
  };

  if (!user) {
    return (
      <div className={isDarkMode ? 'dark' : ''}>
        <Login onLogin={handleLogin} isDarkMode={isDarkMode} toggleTheme={toggleTheme} />
      </div>
    );
  }

  return (
    <div className={isDarkMode ? 'dark' : ''}>
      <Layout 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={handleLogout} 
        user={user}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      >
        {activeTab === 'dashboard' && <Dashboard />}
        {activeTab === 'costs' && <CostAnalysis />}
        {activeTab === 'scan' && <QrScanner />}
        {activeTab === 'qr' && <QrManagement />}
        {activeTab === 'notes' && <Notes user={user} />}
        {activeTab === 'printers' && <PrinterList targetPrinterId={targetPrinterId} clearTarget={() => setTargetPrinterId(null)} />}
        {activeTab === 'inventory' && <Inventory />} 
        {activeTab === 'counters' && <CounterManagement user={user} />}
        {activeTab === 'service' && <ServiceManagement user={user} />}
        {activeTab === 'stock' && <StockManagement user={user} />}
        {activeTab === 'history' && <History />}
        {activeTab === 'settings' && <Settings />}
      </Layout>
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, QrCode, Download, RefreshCw, Wallet, Calendar, Calculator, BarChart3, Copy, Share2, Wrench, Droplet, Globe, Activity, ChevronRight, TrendingUp, Clock, User as UserIcon, Banknote } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, PrinterStatus, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

interface PrinterStats {
  totalSpent: number;
  totalServiceCost: number;
  totalTonerCost: number;
  lastServiceDate: string | null;
  tonerCount: number;
}

export const PrinterList: React.FC<PrinterListProps> = ({ targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [qrPrinter, setQrPrinter] = useState<PrinterType | null>(null);
  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);
  const [selectedPrinterHistory, setSelectedPrinterHistory] = useState<{
      printer: PrinterType, 
      tonerLogs: StockLog[], 
      serviceLogs: ServiceRecord[], 
      counterLogs: CounterLog[], 
      stats: PrinterStats
  } | null>(null);

  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '',
    model: '',
    serialNumber: '',
    shortCode: '',
    location: '',
    floor: '',
    lastCounter: 0,
    connectionType: 'USB',
    ipAddress: '',
    status: 'ACTIVE',
    monthlyRentalCost: 0
  });

  useEffect(() => { loadData(); }, []);

  useEffect(() => {
    const handlePopState = () => {
      setQrPrinter(null);
      setIsHistoryModalOpen(false);
      setIsFormModalOpen(false);
      setEditingPrinter(null);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([StorageService.getPrinters(), StorageService.getConfig()]);
    setPrinters(p);
    setConfig(c);
    setLoading(false);
  };

  const openFormModal = (printer?: PrinterType) => {
    window.history.pushState({ modal: 'form' }, '');
    if (printer) {
      setEditingPrinter(printer); 
      setFormData({
        ...printer,
        monthlyRentalCost: printer.monthlyRentalCost || 0
      });
    } else {
      setEditingPrinter(null);
      setFormData({ brand: config.brands[0] || '', model: config.models[0] || '', status: 'ACTIVE', connectionType: 'USB', monthlyRentalCost: 0 });
    }
    setIsFormModalOpen(true);
  };

  const openHistoryModal = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'history' }, '');
    const [allLogs, allServices, allCounterLogs] = await Promise.all([
        StorageService.getLogs(), 
        StorageService.getServiceRecords(), 
        StorageService.getCounterLogs()
    ]);

    const tonerLogs = allLogs.filter(log => log.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const serviceLogs = allServices.filter(srv => srv.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const counterLogs = allCounterLogs.filter(l => l.printerId === printer.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const totalTonerCost = tonerLogs.reduce((sum, log) => sum + (log.cost || 0), 0);
    const totalServiceCost = serviceLogs.reduce((sum, srv) => sum + (srv.cost || 0), 0);

    setSelectedPrinterHistory({ 
        printer, tonerLogs, serviceLogs, counterLogs, 
        stats: { totalSpent: totalTonerCost + totalServiceCost, totalTonerCost, totalServiceCost, lastServiceDate: serviceLogs[0]?.date || null, tonerCount: tonerLogs.length } 
    });
    setIsHistoryModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = { ...formData, monthlyRentalCost: Number(formData.monthlyRentalCost) || 0 };
    if (editingPrinter?.id) {
       await StorageService.updatePrinter({ ...editingPrinter, ...finalData } as PrinterType);
    } else {
       await StorageService.addPrinter({ id: '', lastTonerDate: new Date().toISOString(), ...finalData as PrinterType });
    }
    window.history.back();
    loadData();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]';
