import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, QrCode, Download, RefreshCw, Calendar, Calculator, Wrench, Droplet, Globe, Activity, ChevronRight, TrendingUp, Clock, User as UserIcon } from 'lucide-react';
