import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Trash2, Calendar, TrendingUp, CheckCircle2, AlertCircle, Upload } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewImage, setViewImage] = useState<string | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    // Form State
    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    useEffect(() => { loadData(); }, []);

    const loadData = async () => {
        setLoading(true);
        const data = await StorageService.getMonthlyInvoices();
        setInvoices(data.sort((a, b) => {
            const m1 = months.indexOf(a.month);
            const m2 = months.indexOf(b.month);
            return m2 - m1; // Yeniden eskiye
        }));
        setLoading(false);
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        await StorageService.saveMonthlyInvoice({
            ...formData,
            createdAt: new Date().toISOString()
        });
        setIsModalOpen(false);
        loadData();
    };

    const handleDelete = async (id: string) => {
        if (confirm("Bu fatura kaydını silmek istediğinize emin misiniz?")) {
            await StorageService.deleteMonthlyInvoice(id);
            loadData();
        }
    };

    if (loading) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header Panel */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">2025 yılı kiralama faturalarını ve sayaç dökümlerini buradan takip edin.</p>
                </div>
                <button onClick={() => { setFormData({ ...formData, id: '', imageUrl: '' }); setIsModalOpen(true); }} className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase">
                    <Plus size={24} /> YENİ FATURA EKLE
                </button>
            </div>

            {/* Invoices List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col h-full">
                        <div className="relative h-48 overflow-hidden bg-zinc-100 dark:bg-zinc-900">
                            {inv.imageUrl ? (
                                <img src={inv.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Fatura" />
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300">
                                    <FileText size={48} />
                                    <span className="text-[10px] font-black mt-2">GÖRSEL YOK</span>
                                </div>
                            )}
                            <div className="absolute top-4 left-4 bg-zinc-900/80 backdrop-blur-md text-white px-4 py-2 rounded-2xl font-black text-xs uppercase tracking-widest">
                                {inv.month} {inv.year}
                            </div>
                            <div className="absolute top-4 right-4 flex gap-2">
                                {inv.imageUrl && (
                                    <button onClick={() => setViewImage(inv.imageUrl!)} className="p-2 bg-emerald-500 text-white rounded-xl shadow-lg hover:scale-110 active:scale-90 transition-all"><Eye size={18}/></button>
                                )}
                                <button onClick={() => handleDelete(inv.id)} className="p-2 bg-red-600 text-white rounded-xl shadow-lg hover:scale-110 active:scale-90 transition-all"><Trash2 size={18}/></button>
                            </div>
                        </div>
                        <div className="p-8 flex-1 flex flex-col">
                            <div className="grid grid-cols-2 gap-4 mb-8">
