const cleanData = (data: any) => {
  const newObj = { ...data };
  Object.keys(newObj).forEach(key => {
    if (newObj[key] === undefined) delete newObj[key];
  });
  return newObj;
};

export const StorageService = {
  // --- INVOICES (Detailed Records for Cost Analysis) ---
  // Added getInvoices to retrieve detailed invoice records for CostAnalysis.tsx
  getInvoices: async (): Promise<InvoiceRecord[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.INVOICES));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as InvoiceRecord));
    } catch (e) { return []; }
  },

  // Added addInvoice to save new detailed invoice records for CostAnalysis.tsx
  addInvoice: async (invoice: InvoiceRecord) => {
    const { id, ...data } = invoice;
    return await addDoc(collection(db, COLLECTIONS.INVOICES), cleanData(data));
  },

  // Added updateInvoice to update existing detailed invoice records for CostAnalysis.tsx
  updateInvoice: async (invoice: InvoiceRecord) => {
    if (!invoice.id) return;
    const { id, ...data } = invoice;
    await updateDoc(doc(db, COLLECTIONS.INVOICES, id), cleanData(data));
  },

  // --- MONTHLY INVOICES ---
  getMonthlyInvoices: async (): Promise<MonthlyInvoice[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.MONTHLY_INVOICES));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as MonthlyInvoice));
    } catch (e) { return []; }
  },

  saveMonthlyInvoice: async (invoice: MonthlyInvoice) => {
    const { id, ...data } = invoice;
    if (id) {
      await updateDoc(doc(db, COLLECTIONS.MONTHLY_INVOICES, id), cleanData(data));
    } else {
      await addDoc(collection(db, COLLECTIONS.MONTHLY_INVOICES), cleanData(data));
    }
  },

  deleteMonthlyInvoice: async (id: string) => {
    await deleteDoc(doc(db, COLLECTIONS.MONTHLY_INVOICES, id));
  },

  // --- AUTH ---
  getUsers: async (): Promise<User[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.USERS));
      return snapshot.docs.map(doc => ({ ...doc.data() as any } as User));
    } catch (error) { return []; }
  },

  login: async (username: string, password: string): Promise<User | null> => {
    const users = await StorageService.getUsers();
    const user = users.find(u => u.username.toLowerCase() === username.toLowerCase() && u.password === password);
    if (user) {
      const { password, ...safeUser } = user;
      return safeUser as User;
    }
    return null;
  },

  // --- PRINTERS ---
  getPrinters: async (): Promise<Printer[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.PRINTERS));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Printer));
    } catch (e) { return []; }
  },

  addPrinter: async (printer: Printer) => {
    const printers = await StorageService.getPrinters();
    if (!printer.shortCode) {
      const codes = printers.map(p => parseInt(p.shortCode || '1000')).filter(n => !isNaN(n) && n >= 1000);
      const maxCode = codes.length > 0 ? Math.max(...codes) : 1000;
      printer.shortCode = (maxCode + 1).toString();
    }
    const { id, ...data } = printer;
    const docRef = await addDoc(collection(db, COLLECTIONS.PRINTERS), cleanData(data));
    return docRef.id;
  },

  updatePrinter: async (printer: Printer) => {
    if (!printer.id) return;
    await updateDoc(doc(db, COLLECTIONS.PRINTERS, printer.id), cleanData(printer));
  },

  deletePrinter: async (printerId: string) => {
    await deleteDoc(doc(db, COLLECTIONS.PRINTERS, printerId));
  },

  findPrinterByShortCode: async (code: string): Promise<Printer | null> => {
    const q = query(collection(db, COLLECTIONS.PRINTERS), where('shortCode', '==', code.trim()));
    const snapshot = await getDocs(q);
    if (snapshot.empty) return null;
    return { id: snapshot.docs[0].id, ...snapshot.docs[0].data() as any } as Printer;
  },

  fixMissingShortCodes: async () => {
    const printers = await StorageService.getPrinters();
    const batch = writeBatch(db);
    let nextCode = 1001;
    for (const p of printers) {
      if (!p.shortCode || parseInt(p.shortCode) < 1000) {
        batch.update(doc(db, COLLECTIONS.PRINTERS, p.id), { shortCode: nextCode.toString() });
        nextCode++;
      }
    }
    await batch.commit();
    return printers.length;
  },

  // --- NOTES ---
  getNotes: async (): Promise<Note[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.NOTES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Note));
    } catch (e) { return []; }
  },

  addNote: async (note: Note) => {
    const { id, ...data } = note;
    const docRef = await addDoc(collection(db, COLLECTIONS.NOTES), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: note.user,
      action: 'NOT_EKLENDI',
      details: `"${note.title}" başlıklı yeni bir not oluşturuldu.`
    });
    return docRef.id;
  },

  updateNote: async (note: Note) => {
    if (!note.id) return;
    const { id, ...data } = note;
    await updateDoc(doc(db, COLLECTIONS.NOTES, id), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: note.user,
      action: 'NOT_GUNCELLEME',
      details: `"${note.title}" başlıklı not üzerinde değişiklik yapıldı.`
    });
  },

  deleteNote: async (id: string, user: string, title: string) => {
    await deleteDoc(doc(db, COLLECTIONS.NOTES, id));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'NOT_SILINDI',
      details: `"${title}" başlıklı not kalıcı olarak silindi.`
    });
  },

  // --- ACTIVITIES ---
  getActivities: async (): Promise<ActivityLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.ACTIVITIES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ActivityLog));
    } catch (e) { return []; }
  },

  addActivity: async (activity: ActivityLog) => {
    const { id, ...data } = activity;
    await addDoc(collection(db, COLLECTIONS.ACTIVITIES), cleanData(data));
  },

  // --- STOCKS & LOGS ---
  getStocks: async (): Promise<TonerStock[]> => {
    const snapshot = await getDocs(collection(db, COLLECTIONS.STOCKS));
    return snapshot.docs.map(doc => ({ ...doc.data() as any } as TonerStock));
  },

  saveStock: async (stock: TonerStock) => {
    const q = query(collection(db, COLLECTIONS.STOCKS));
    const snapshot = await getDocs(q);
    const existing = snapshot.docs.find(d => (d.data() as TonerStock).modelName === stock.modelName);
    if (existing) await updateDoc(doc(db, COLLECTIONS.STOCKS, existing.id), { quantity: stock.quantity });
    else await addDoc(collection(db, COLLECTIONS.STOCKS), cleanData(stock));
  },

  getLogs: async (): Promise<StockLog[]> => {
    const q = query(collection(db, COLLECTIONS.LOGS), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as StockLog));
  },

  addLog: async (log: StockLog) => {
    const { id, ...data } = log;
    await addDoc(collection(db, COLLECTIONS.LOGS), cleanData(data));
  },

  // --- SERVICES ---
  getServiceRecords: async (): Promise<ServiceRecord[]> => {
    const q = query(collection(db, COLLECTIONS.SERVICES), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ServiceRecord));
  },

  addServiceRecord: async (record: ServiceRecord, user: string) => {
    const { id, ...data } = record;
    const docRef = await addDoc(collection(db, COLLECTIONS.SERVICES), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'SERVIS_KAYDI_EKLENDI',
      details: `${record.printerName} cihazı için yeni servis kaydı açıldı.`
    });
    return docRef.id;
  },

  updateServiceRecord: async (record: ServiceRecord, user: string) => {
    if (!record.id) return;
    const { id, ...data } = record;
    await updateDoc(doc(db, COLLECTIONS.SERVICES, id), cleanData({ ...data, lastModifiedBy: user }));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'SERVIS_KAYDI_GUNCELLEME',
      details: `${record.printerName} servis kaydı güncellendi. Durum: ${record.status}`
    });
  },

  deleteServiceRecord: async (id: string, user: string, printerName: string) => {
    await deleteDoc(doc(db, COLLECTIONS.SERVICES, id));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'SERVIS_KAYDI_SILINDI',
      details: `${printerName} cihazına ait bir servis kaydı silindi.`
    });
  },

  // --- COUNTERS ---
  getCounterLogs: async (): Promise<CounterLog[]> => {
    const q = query(collection(db, COLLECTIONS.COUNTERS), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as CounterLog));
  },

  addCounterLog: async (log: CounterLog, updateMaster: boolean = true) => {
    const { id, ...data } = log;
    await addDoc(collection(db, COLLECTIONS.COUNTERS), cleanData(data));
    if (updateMaster) {
      await updateDoc(doc(db, COLLECTIONS.PRINTERS, log.printerId), { 
        lastCounter: log.currentCounter,
        lastCounterBW: log.currentBW,
        lastCounterColor: log.currentColor
      });
    }
  },

  getConfig: async (): Promise<SystemConfig> => {
    const docSnap = await getDoc(doc(db, COLLECTIONS.CONFIG, 'main_config'));
    return docSnap.exists() ? { ...INITIAL_CONFIG, ...docSnap.data() as SystemConfig } : INITIAL_CONFIG;
  },

  saveConfig: async (config: SystemConfig) => {
    await setDoc(doc(db, COLLECTIONS.CONFIG, 'main_config'), cleanData(config));
  },

  fetchPrinterCounterSimulated: async (printer: Printer) => {
    await new Promise(r => setTimeout(r, 1000));
    const inc = Math.floor(Math.random() * 50) + 10;
    const bwInc = Math.floor(inc * 0.7);
    const colorInc = inc - bwInc;
    return { 
      total: printer.lastCounter + inc, 
      bw: (printer.lastCounterBW || 0) + bwInc,
      color: printer.isColor ? (printer.lastCounterColor || 0) + colorInc : 0
    };
  }
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Trash2, Calendar, TrendingUp, CheckCircle2, AlertCircle, Upload } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewImage, setViewImage] = useState<string | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    // Form State
    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    useEffect(() => { loadData(); }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            setInvoices(data.sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                // Yıla göre de sırala (Yıl aynı ise aya göre)
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            }));
        } catch (error) {
            console.error("Faturalar yüklenirken hata:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                createdAt: formData.createdAt || new Date().toISOString()
            });
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            alert("Kaydedilirken bir hata oluştu.");
        }
    };

    const handleDelete = async (id: string, month: string, year: number) => {
        if (!id) {
            alert("Hata: Kayıt ID'si bulunamadı.");
            return;
        }

        const isConfirmed = window.confirm(`${month} ${year} faturasını silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`);

        if (isConfirmed) {
            try {
                setLoading(true);
                await StorageService.deleteMonthlyInvoice(id);
                await loadData();
            } catch (error) {
                console.error("Silme hatası:", error);
                alert("Fatura silinemedi. Lütfen internet bağlantınızı kontrol edin.");
                setLoading(false);
            }
        }
    };

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header Panel */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">2025 yılı kiralama faturalarını ve sayaç dökümlerini buradan takip edin.</p>
                </div>
                <button onClick={() => { setFormData({ ...formData, id: '', imageUrl: '', month: months[new Date().getMonth()] }); setIsModalOpen(true); }} className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase">
                    <Plus size={24} /> YENİ FATURA EKLE
                </button>
            </div>

            {/* Invoices List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col h-full relative">
                        <div className="relative h-48 overflow-hidden bg-zinc-100 dark:bg-zinc-900">
                            {inv.imageUrl ? (
                                <img src={inv.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Fatura" />
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300">
                                    <FileText size={48} />
                                    <span className="text-[10px] font-black mt-2">GÖRSEL YOK</span>
                                </div>
                            )}
                            <div className="absolute top-4 left-4 bg-zinc-900/80 backdrop-blur-md text-white px-4 py-2 rounded-2xl font-black text-xs uppercase tracking-widest">
                                {inv.month} {inv.year}
                            </div>
                            <div className="absolute top-4 right-4 flex gap-2 z-20">
                                {inv.imageUrl && (
                                    <button onClick={(e) => { e.stopPropagation(); setViewImage(inv.imageUrl!); }} className="p-2 bg-emerald-500 text-white rounded-xl shadow-lg hover:scale-110 active:scale-90 transition-all"><Eye size={18}/></button>
                                )}
                                <button 
                                    onClick={(e) => { e.stopPropagation(); handleDelete(inv.id, inv.month, inv.year); }} 
                                    className="p-2 bg-red-600 text-white rounded-xl shadow-lg hover:scale-110 active:scale-90 transition-all"
                                >
                                    <Trash2 size={18}/>
                                </button>
                            </div>
                        </div>
                        <div className="p-8 flex-1 flex flex-col">
                            <div className="grid grid-cols-2 gap-4 mb-8">
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest flex items-center gap-1.5"><TrendingUp size={12}/> EURO KURU</p>
                                    <p className="text-xl font-black text-zinc-900 dark:text-white font-mono">{inv.euroRate.toLocaleString()} ₺</p>
                                </div>
                                <div className="space-y-1 text-right">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">ÖDENEN TUTAR</p>
                                    <p className="text-xl font-black text-emerald-600 font-mono">{inv.totalTL.toLocaleString()} ₺</p>
                                </div>
                            </div>

                            <div className="mt-auto pt-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-between items-center">
                                <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${inv.status === 'PAID' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                    {inv.status === 'PAID' ? 'ÖDENDİ' : 'ÖDEME BEKLİYOR'}
                                </span>
                                <div className="flex items-center gap-1 text-[10px] text-zinc-400 font-bold uppercase">
                                    <Calendar size={12}/> {new Date(inv.createdAt).toLocaleDateString('tr-TR')}
                                </div>
                            </div>
                        </div>
                    </div>
                ))}

                {!loading && invoices.length === 0 && (
                    <div className="col-span-full py-32 bg-zinc-50 dark:bg-zinc-900/50 rounded-[4rem] border-4 border-dashed border-zinc-200 dark:border-zinc-800 flex flex-col items-center justify-center text-zinc-400 gap-6">
                        <div className="p-8 bg-white dark:bg-zinc-800 rounded-full shadow-2xl opacity-50"><AlertCircle size={64} /></div>
                        <p className="font-black text-2xl uppercase tracking-tighter text-center">Henüz hiçbir fatura kaydı bulunmuyor.</p>
                        <button onClick={() => setIsModalOpen(true)} className="text-emerald-500 font-black text-sm underline decoration-2 underline-offset-8 uppercase tracking-widest hover:text-emerald-400 transition-colors">İLK FATURAYI ŞİMDİ EKLE</button>
                    </div>
                )}
            </div>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[200] flex items-center justify-center p-6 animate-in fade-in duration-500">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-xl shadow-2xl overflow-hidden border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
                        <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                            <h3 className="font-black text-3xl text-zinc-900 dark:text-white tracking-tighter uppercase">FATURA KAYDET</h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-4 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all"><X size={32}/></button>
                        </div>
                        <form onSubmit={handleSave} className="p-10 space-y-8 overflow-y-auto custom-scrollbar">
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">AY</label>
                                    <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-bold outline-none focus:border-emerald-500" value={formData.month} onChange={e => setFormData({...formData, month: e.target.value})}>
                                        {months.map(m => <option key={m} value={m}>{m}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">YIL</label>
                                    <input required type="number" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} />
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">EURO KURU (TL)</label>
                                    <input required type="number" step="0.01" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold" value={formData.euroRate} onChange={e => setFormData({...formData, euroRate: parseFloat(e.target.value)})} />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">TOPLAM ÖDENEN (TL)</label>
                                    <input required type="number" step="0.01" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold" value={formData.totalTL} onChange={e => setFormData({...formData, totalTL: parseFloat(e.target.value)})} />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">ÖDEME DURUMU</label>
                                <div className="grid grid-cols-2 gap-4">
                                    <button type="button" onClick={() => setFormData({...formData, status: 'PAID'})} className={`py-4 rounded-2xl font-black text-[10px] tracking-widest uppercase transition-all ${formData.status === 'PAID' ? 'bg-emerald-600 text-white shadow-lg' : 'bg-zinc-100 dark:bg-zinc-800 text-zinc-500'}`}>ÖDENDİ</button>
                                    <button type="button" onClick={() => setFormData({...formData, status: 'PENDING'})} className={`py-4 rounded-2xl font-black text-[10px] tracking-widest uppercase transition-all ${formData.status === 'PENDING' ? 'bg-orange-600 text-white shadow-lg' : 'bg-zinc-100 dark:bg-zinc-800 text-zinc-500'}`}>ÖDEME BEKLİYOR</button>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">FATURA / SAYAÇ DÖKÜMÜ GÖRSELİ</label>
                                <div className="grid grid-cols-1 gap-4">
                                    <label className="flex flex-col items-center justify-center p-10 border-4 border-dashed border-zinc-100 dark:border-zinc-800 rounded-[2.5rem] bg-zinc-50 dark:bg-zinc-900 cursor-pointer hover:border-emerald-500 transition-all group">
                                        <Camera size={48} className="text-zinc-300 group-hover:text-emerald-500 mb-4" />
                                        <span className="text-[10px] font-black text-zinc-400 uppercase group-hover:text-emerald-500">RESMİ ÇEK VEYA YÜKLE</span>
                                        <input type="file" accept="image/*" onChange={handleImageChange} className="hidden" />
                                    </label>
                                    {formData.imageUrl && (
                                        <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl">
                                            <img src={formData.imageUrl} className="w-full h-auto" />
                                            <button type="button" onClick={() => setFormData({...formData, imageUrl: ''})} className="absolute top-4 right-4 p-3 bg-red-600 text-white rounded-2xl shadow-xl"><X size={20}/></button>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <button type="submit" className="w-full py-8 bg-emerald-600 text-white rounded-[2.5rem] font-black shadow-2xl shadow-emerald-500/30 transition-all flex items-center justify-center gap-4 uppercase tracking-[0.2em]">
                                <Save size={24}/> ARŞİVE KAYDET
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Fullscreen View */}
            {viewImage && (
                <div className="fixed inset-0 z-[300] bg-black/95 flex flex-col items-center justify-center p-10 animate-in fade-in" onClick={() => setViewImage(null)}>
                    <button className="absolute top-10 right-10 p-4 bg-white/10 text-white rounded-full"><X size={32}/></button>
                    <img src={viewImage} className="max-w-full max-h-full object-contain rounded-[2rem] shadow-2xl" />
                </div>
            )}
        </div>
    );
};

import { db } from './firebase';
import { collection, getDocs, addDoc, updateDoc, deleteDoc, doc, setDoc, query, orderBy, getDoc, where, writeBatch } from 'firebase/firestore';
import { Printer, TonerStock, StockLog, SystemConfig, ServiceRecord, User, CounterLog, Note, ActivityLog, MonthlyInvoice, InvoiceRecord } from '../types';

const COLLECTIONS = {
  PRINTERS: 'printers',
  STOCKS: 'stocks',
  LOGS: 'logs',
  CONFIG: 'config',
  SERVICES: 'services',
  USERS: 'users',
  COUNTERS: 'counters',
  NOTES: 'notes',
  ACTIVITIES: 'activities',
  MONTHLY_INVOICES: 'monthly_invoices',
  INVOICES: 'invoices'
};

const INITIAL_CONFIG: SystemConfig = {
  brands: ['Canon', 'HP', 'Kyocera', 'Xerox', 'Epson'],
  models: ['MF416dw', 'iF1643', 'LBP 251DW', '3325i', 'L3210', 'L1210', 'P2035', 'LBP 6030'],
  suppliers: ['Anahtar Bilgisayar', 'Enes Bilişim', 'Kendi Malımız'],
  tonerModels: ['1643', '505', '259x'],
  whatsappNumber: '',
  brandImages: {},
  modelImages: {}
};

const cleanData = (data: any) => {
  const newObj = { ...data };
  Object.keys(newObj).forEach(key => {
    if (newObj[key] === undefined) delete newObj[key];
  });
  return newObj;
};

export const StorageService = {
  // --- INVOICES (Detailed Records for Cost Analysis) ---
  getInvoices: async (): Promise<InvoiceRecord[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.INVOICES));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as InvoiceRecord));
    } catch (e) { return []; }
  },

  addInvoice: async (invoice: InvoiceRecord) => {
    const { id, ...data } = invoice;
    return await addDoc(collection(db, COLLECTIONS.INVOICES), cleanData(data));
  },

  updateInvoice: async (invoice: InvoiceRecord) => {
    if (!invoice.id) return;
    const { id, ...data } = invoice;
    await updateDoc(doc(db, COLLECTIONS.INVOICES, id), cleanData(data));
  },

  // --- MONTHLY INVOICES (Simple Archive with Images) ---
  getMonthlyInvoices: async (): Promise<MonthlyInvoice[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.MONTHLY_INVOICES));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as MonthlyInvoice));
    } catch (e) { 
        console.error("Firestore getMonthlyInvoices error:", e);
        return []; 
    }
  },

  saveMonthlyInvoice: async (invoice: MonthlyInvoice) => {
    const { id, ...data } = invoice;
    if (id) {
      await updateDoc(doc(db, COLLECTIONS.MONTHLY_INVOICES, id), cleanData(data));
    } else {
      await addDoc(collection(db, COLLECTIONS.MONTHLY_INVOICES), cleanData(data));
    }
  },

  deleteMonthlyInvoice: async (id: string) => {
    if (!id) throw new Error("ID required for deletion");
    const docRef = doc(db, COLLECTIONS.MONTHLY_INVOICES, id);
    await deleteDoc(docRef);
  },

  // --- AUTH ---
  getUsers: async (): Promise<User[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.USERS));
      return snapshot.docs.map(doc => ({ ...doc.data() as any } as User));
    } catch (error) { return []; }
  },

  login: async (username: string, password: string): Promise<User | null> => {
    const users = await StorageService.getUsers();
    const user = users.find(u => u.username.toLowerCase() === username.toLowerCase() && u.password === password);
    if (user) {
      const { password, ...safeUser } = user;
      return safeUser as User;
    }
    return null;
  },

  // --- PRINTERS ---
  getPrinters: async (): Promise<Printer[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.PRINTERS));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Printer));
    } catch (e) { return []; }
  },

  addPrinter: async (printer: Printer) => {
    const printers = await StorageService.getPrinters();
    if (!printer.shortCode) {
      const codes = printers.map(p => parseInt(p.shortCode || '1000')).filter(n => !isNaN(n) && n >= 1000);
      const maxCode = codes.length > 0 ? Math.max(...codes) : 1000;
      printer.shortCode = (maxCode + 1).toString();
    }
    const { id, ...data } = printer;
    const docRef = await addDoc(collection(db, COLLECTIONS.PRINTERS), cleanData(data));
    return docRef.id;
  },

  updatePrinter: async (printer: Printer) => {
    if (!printer.id) return;
    await updateDoc(doc(db, COLLECTIONS.PRINTERS, printer.id), cleanData(printer));
  },

  deletePrinter: async (printerId: string) => {
    await deleteDoc(doc(db, COLLECTIONS.PRINTERS, printerId));
  },

  findPrinterByShortCode: async (code: string): Promise<Printer | null> => {
    const q = query(collection(db, COLLECTIONS.PRINTERS), where('shortCode', '==', code.trim()));
    const snapshot = await getDocs(q);
    if (snapshot.empty) return null;
    return { id: snapshot.docs[0].id, ...snapshot.docs[0].data() as any } as Printer;
  },

  fixMissingShortCodes: async () => {
    const printers = await StorageService.getPrinters();
    const batch = writeBatch(db);
    let nextCode = 1001;
    for (const p of printers) {
      if (!p.shortCode || parseInt(p.shortCode) < 1000) {
        batch.update(doc(db, COLLECTIONS.PRINTERS, p.id), { shortCode: nextCode.toString() });
        nextCode++;
      }
    }
    await batch.commit();
    return printers.length;
  },

  // --- NOTES ---
  getNotes: async (): Promise<Note[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.NOTES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Note));
    } catch (e) { return []; }
  },

  addNote: async (note: Note) => {
    const { id, ...data } = note;
    const docRef = await addDoc(collection(db, COLLECTIONS.NOTES), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: note.user,
      action: 'NOT_EKLENDI',
      details: `"${note.title}" başlıklı yeni bir not oluşturuldu.`
    });
    return docRef.id;
  },

  updateNote: async (note: Note) => {
    if (!note.id) return;
    const { id, ...data } = note;
    await updateDoc(doc(db, COLLECTIONS.NOTES, id), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: note.user,
      action: 'NOT_GUNCELLEME',
      details: `"${note.title}" başlıklı not üzerinde değişiklik yapıldı.`
    });
  },

  deleteNote: async (id: string, user: string, title: string) => {
    await deleteDoc(doc(db, COLLECTIONS.NOTES, id));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'NOT_SILINDI',
      details: `"${title}" başlıklı not kalıcı olarak silindi.`
    });
  },

  // --- ACTIVITIES ---
  getActivities: async (): Promise<ActivityLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.ACTIVITIES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ActivityLog));
    } catch (e) { return []; }
  },

  addActivity: async (activity: ActivityLog) => {
    const { id, ...data } = activity;
    await addDoc(collection(db, COLLECTIONS.ACTIVITIES), cleanData(data));
  },

  // --- STOCKS & LOGS ---
  getStocks: async (): Promise<TonerStock[]> => {
    const snapshot = await getDocs(collection(db, COLLECTIONS.STOCKS));
    return snapshot.docs.map(doc => ({ ...doc.data() as any } as TonerStock));
  },

  saveStock: async (stock: TonerStock) => {
    const q = query(collection(db, COLLECTIONS.STOCKS));
    const snapshot = await getDocs(q);
    const existing = snapshot.docs.find(d => (d.data() as TonerStock).modelName === stock.modelName);
    if (existing) await updateDoc(doc(db, COLLECTIONS.STOCKS, existing.id), { quantity: stock.quantity });
    else await addDoc(collection(db, COLLECTIONS.STOCKS), cleanData(stock));
  },

  getLogs: async (): Promise<StockLog[]> => {
    const q = query(collection(db, COLLECTIONS.LOGS), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as StockLog));
  },

  addLog: async (log: StockLog) => {
    const { id, ...data } = log;
    await addDoc(collection(db, COLLECTIONS.LOGS), cleanData(data));
  },

  // --- SERVICES ---
  getServiceRecords: async (): Promise<ServiceRecord[]> => {
    const q = query(collection(db, COLLECTIONS.SERVICES), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ServiceRecord));
  },

  addServiceRecord: async (record: ServiceRecord, user: string) => {
    const { id, ...data } = record;
    const docRef = await addDoc(collection(db, COLLECTIONS.SERVICES), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'SERVIS_KAYDI_EKLENDI',
      details: `${record.printerName} cihazı için yeni servis kaydı açıldı.`
    });
    return docRef.id;
  },

  updateServiceRecord: async (record: ServiceRecord, user: string) => {
    if (!record.id) return;
    const { id, ...data } = record;
    await updateDoc(doc(db, COLLECTIONS.SERVICES, id), cleanData({ ...data, lastModifiedBy: user }));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'SERVIS_KAYDI_GUNCELLEME',
      details: `${record.printerName} servis kaydı güncellendi. Durum: ${record.status}`
    });
  },

  deleteServiceRecord: async (id: string, user: string, printerName: string) => {
    await deleteDoc(doc(db, COLLECTIONS.SERVICES, id));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'SERVIS_KAYDI_SILINDI',
      details: `${printerName} cihazına ait bir servis kaydı silindi.`
    });
  },

  // --- COUNTERS ---
  getCounterLogs: async (): Promise<CounterLog[]> => {
    const q = query(collection(db, COLLECTIONS.COUNTERS), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as CounterLog));
  },

  addCounterLog: async (log: CounterLog, updateMaster: boolean = true) => {
    const { id, ...data } = log;
    await addDoc(collection(db, COLLECTIONS.COUNTERS), cleanData(data));
    if (updateMaster) {
      await updateDoc(doc(db, COLLECTIONS.PRINTERS, log.printerId), { 
        lastCounter: log.currentCounter,
        lastCounterBW: log.currentBW,
        lastCounterColor: log.currentColor
      });
    }
  },

  getConfig: async (): Promise<SystemConfig> => {
    const docSnap = await getDoc(doc(db, COLLECTIONS.CONFIG, 'main_config'));
    return docSnap.exists() ? { ...INITIAL_CONFIG, ...docSnap.data() as SystemConfig } : INITIAL_CONFIG;
  },

  saveConfig: async (config: SystemConfig) => {
    await setDoc(doc(db, COLLECTIONS.CONFIG, 'main_config'), cleanData(config));
  },

  fetchPrinterCounterSimulated: async (printer: Printer) => {
    await new Promise(r => setTimeout(r, 1000));
    const inc = Math.floor(Math.random() * 50) + 10;
    const bwInc = Math.floor(inc * 0.7);
    const colorInc = inc - bwInc;
    return { 
      total: printer.lastCounter + inc, 
      bw: (printer.lastCounterBW || 0) + bwInc,
      color: printer.isColor ? (printer.lastCounterColor || 0) + colorInc : 0
    };
  }
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Calendar, TrendingUp, AlertCircle } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewImage, setViewImage] = useState<string | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    // Form State
    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    // ESC Key Support
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setIsModalOpen(false);
                setViewImage(null);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    useEffect(() => { loadData(); }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            setInvoices(data.sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            }));
        } catch (error) {
            console.error("Faturalar yüklenirken hata:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                createdAt: formData.createdAt || new Date().toISOString()
            });
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            alert("Kaydedilirken bir hata oluştu.");
        }
    };

    const handleDelete = async (id: string, month: string, year: number) => {
        if (!id) {
            alert("Hata: Kayıt ID'si bulunamadı.");
            return;
        }

        const isConfirmed = window.confirm(`${month} ${year} faturasını silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`);

        if (isConfirmed) {
            try {
                await StorageService.deleteMonthlyInvoice(id);
                await loadData();
            } catch (error) {
                console.error("Silme hatası:", error);
                alert("Fatura silinemedi.");
            }
        }
    };

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header Panel */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">2025 yılı faturalarını ve sayaç dökümlerini yönetin.</p>
                </div>
                <button onClick={() => { setFormData({ ...formData, id: '', imageUrl: '', month: months[new Date().getMonth()] }); setIsModalOpen(true); }} className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase">
                    <Plus size={24} /> YENİ FATURA EKLE
                </button>
            </div>

            {/* Invoices List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col h-full relative">
                        {/* Clickable Image Container */}
                        <div 
                            className="relative h-56 overflow-hidden bg-zinc-100 dark:bg-zinc-900 cursor-pointer"
                            onClick={() => inv.imageUrl && setViewImage(inv.imageUrl)}
                        >
                            {inv.imageUrl ? (
                                <>
                                    <img src={inv.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Fatura" />
                                    <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                        <div className="bg-white/20 backdrop-blur-md p-3 rounded-full text-white">
                                            <Eye size={24} />
                                        </div>
                                    </div>
