                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300">
                                    <FileText size={48} />
                                    <span className="text-[10px] font-black mt-2 uppercase tracking-widest">GÖRSEL YOK</span>
                                </div>
