                                    {inv.status === 'PAID' ? 'ÖDENDİ' : 'ÖDEME BEKLİYOR'}
                                </span>
                                <div className="flex items-center gap-1 text-[10px] text-zinc-400 font-bold uppercase tracking-widest">
                                    <Calendar size={12}/> {new Date(inv.createdAt).toLocaleDateString('tr-TR')}
