                                    <button type="button" onClick={() => setFormData({...formData, status: 'PENDING'})} className={`py-4 rounded-2xl font-black text-[10px] tracking-widest uppercase transition-all ${formData.status === 'PENDING' ? 'bg-orange-600 text-white shadow-lg' : 'bg-zinc-100 dark:bg-zinc-800 text-zinc-500'}`}>ÖDEME BEKLİYOR</button>
