        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    // Clean up Blob URLs to prevent memory leaks
    useEffect(() => {
        return () => {
            if (viewFileUrl && viewFileUrl.startsWith('blob:')) {
                URL.revokeObjectURL(viewFileUrl);
            }
        };
    }, [viewFileUrl]);

