        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    useEffect(() => { loadData(); }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            setInvoices(data.sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            }));
        } catch (error) {
            console.error("Faturalar yüklenirken hata:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                createdAt: formData.createdAt || new Date().toISOString()
            });
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            alert("Kaydedilirken bir hata oluştu.");
        }
    };

    const openViewer = (dataUrl: string) => {
        if (dataUrl.startsWith('data:application/pdf')) {
            // Convert base64 PDF to Blob for better browser compatibility
            const base64Data = dataUrl.split(',')[1];
            const byteCharacters = atob(base64Data);
            const byteNumbers = new Array(byteCharacters.length);
            for (let i = 0; i < byteCharacters.length; i++) {
                byteNumbers[i] = byteCharacters.charCodeAt(i);
            }
            const byteArray = new Uint8Array(byteNumbers);
            const blob = new Blob([byteArray], { type: 'application/pdf' });
            const url = URL.createObjectURL(blob);
            setViewFileUrl(url);
            setIsPdfView(true);
        } else {
            setViewFileUrl(dataUrl);
            setIsPdfView(false);
        }
    };

    const closeViewer = () => {
        if (viewFileUrl && viewFileUrl.startsWith('blob:')) {
            URL.revokeObjectURL(viewFileUrl);
        }
        setViewFileUrl(null);
        setIsPdfView(false);
    };

    const handleDelete = async (e: React.MouseEvent, id: string, month: string, year: number) => {
        e.preventDefault();
        e.stopPropagation();

        if (!id) {
            alert("Hata: Kayıt ID'si geçersiz.");
            return;
        }

        const isConfirmed = window.confirm(`DİKKAT: ${month} ${year} dönemine ait faturayı SİLMEK istediğinize emin misiniz? Bu işlem geri alınamaz.`);

        if (isConfirmed) {
            try {
                // UI'da hemen kaldır (Optimistic UI)
                setInvoices(prev => prev.filter(inv => inv.id !== id));
                await StorageService.deleteMonthlyInvoice(id);
                console.log("Fatura başarıyla silindi:", id);
            } catch (error) {
                console.error("Silme hatası:", error);
                alert("Fatura silinirken hata oluştu. Veri yenileniyor...");
                loadData(); // Hata durumunda listeyi tekrar çek
            }
        }
    };

    const isPdf = (dataUrl?: string) => dataUrl?.startsWith('data:application/pdf');

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header Panel */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Kiralama faturaları ve sayaç dökümlerini yönetin.</p>
                </div>
                <button onClick={() => { setFormData({ ...formData, id: '', imageUrl: '', month: months[new Date().getMonth()] }); setIsModalOpen(true); }} className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase">
                    <Plus size={24} /> YENİ FATURA EKLE
                </button>
            </div>

            {/* Invoices List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col h-full relative">
                        {/* Clickable Image/PDF Container */}
                        <div 
                            className="relative h-56 overflow-hidden bg-zinc-100 dark:bg-zinc-900 cursor-pointer"
                            onClick={() => inv.imageUrl && openViewer(inv.imageUrl)}
                        >
                            {inv.imageUrl ? (
                                isPdf(inv.imageUrl) ? (
                                    <div className="w-full h-full flex flex-col items-center justify-center bg-zinc-50 dark:bg-zinc-900 group-hover:bg-emerald-50 dark:group-hover:bg-emerald-950/20 transition-colors">
                                        <FileDigit size={64} className="text-red-500" />
                                        <span className="text-[10px] font-black mt-3 text-zinc-500 tracking-[0.2em] uppercase">PDF DÖKÜMANI</span>
                                    </div>
                                ) : (
                                    <>
                                        <img src={inv.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Fatura" />
                                        <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                            <div className="bg-white/20 backdrop-blur-md p-3 rounded-full text-white">
                                                <Eye size={24} />
                                            </div>
                                        </div>
                                    </>
                                )
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300">
                                    <FileText size={48} />
                                    <span className="text-[10px] font-black mt-2 uppercase tracking-widest">DOSYA YOK</span>
                                </div>
                            )}

                            <div className="absolute top-4 left-4 bg-zinc-900/80 backdrop-blur-md text-white px-4 py-2 rounded-2xl font-black text-xs uppercase tracking-widest">
                                {inv.month} {inv.year}
                            </div>
                        </div>

                        <div className="p-8 flex-1 flex flex-col">
                            <div className="grid grid-cols-2 gap-4 mb-8">
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest flex items-center gap-1.5"><TrendingUp size={12}/> EURO KURU</p>
                                    <p className="text-xl font-black text-zinc-900 dark:text-white font-mono">{inv.euroRate.toLocaleString()} ₺</p>
                                </div>
                                <div className="space-y-1 text-right">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">ÖDENEN TUTAR</p>
                                    <p className="text-xl font-black text-emerald-600 font-mono">{inv.totalTL.toLocaleString()} ₺</p>
                                </div>
                            </div>

                            <div className="mt-auto pt-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-between items-center">
                                <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${inv.status === 'PAID' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                    {inv.status === 'PAID' ? 'ÖDENDİ' : 'ÖDEME BEKLE'}
                                </span>
                                <button 
                                    onClick={(e) => handleDelete(e, inv.id, inv.month, inv.year)} 
                                    className="flex items-center gap-2 px-6 py-2 bg-red-600 hover:bg-red-700 text-white rounded-xl shadow-lg font-black text-[10px] tracking-widest uppercase transition-all active:scale-95"
                                >
                                    <Trash2 size={14}/> SİL
                                </button>
                            </div>
                        </div>
                    </div>
                ))}

                {!loading && invoices.length === 0 && (
                    <div className="col-span-full py-32 bg-zinc-50 dark:bg-zinc-900/50 rounded-[4rem] border-4 border-dashed border-zinc-200 dark:border-zinc-800 flex flex-col items-center justify-center text-zinc-400 gap-6">
                        <div className="p-8 bg-white dark:bg-zinc-800 rounded-full shadow-2xl opacity-50"><AlertCircle size={64} /></div>
                        <p className="font-black text-2xl uppercase tracking-tighter text-center">Henüz hiçbir fatura kaydı bulunmuyor.</p>
                        <button onClick={() => setIsModalOpen(true)} className="text-emerald-500 font-black text-sm underline decoration-2 underline-offset-8 uppercase tracking-widest hover:text-emerald-400 transition-colors">İLK FATURAYI ŞİMDİ EKLE</button>
                    </div>
                )}
            </div>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[200] flex items-center justify-center p-6 animate-in fade-in duration-500">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-xl shadow-2xl overflow-hidden border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
                        <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                            <h3 className="font-black text-3xl text-zinc-900 dark:text-white tracking-tighter uppercase">FATURA KAYDET</h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-4 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all"><X size={32}/></button>
                        </div>
                        <form onSubmit={handleSave} className="p-10 space-y-8 overflow-y-auto custom-scrollbar">
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">AY</label>
                                    <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-bold outline-none focus:border-emerald-500" value={formData.month} onChange={e => setFormData({...formData, month: e.target.value})}>
                                        {months.map(m => <option key={m} value={m}>{m}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">YIL</label>
                                    <input required type="number" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} />
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">EURO KURU (TL)</label>
                                    <input required type="number" step="0.01" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold" value={formData.euroRate} onChange={e => setFormData({...formData, euroRate: parseFloat(e.target.value)})} />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">TOPLAM ÖDENEN (TL)</label>
                                    <input required type="number" step="0.01" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold" value={formData.totalTL} onChange={e => setFormData({...formData, totalTL: parseFloat(e.target.value)})} />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">ÖDEME DURUMU</label>
                                <div className="grid grid-cols-2 gap-4">
                                    <button type="button" onClick={() => setFormData({...formData, status: 'PAID'})} className={`py-4 rounded-2xl font-black text-[10px] tracking-widest uppercase transition-all ${formData.status === 'PAID' ? 'bg-emerald-600 text-white shadow-lg' : 'bg-zinc-100 dark:bg-zinc-800 text-zinc-500'}`}>ÖDENDİ</button>
                                    <button type="button" onClick={() => setFormData({...formData, status: 'PENDING'})} className={`py-4 rounded-2xl font-black text-[10px] tracking-widest uppercase transition-all ${formData.status === 'PENDING' ? 'bg-orange-600 text-white shadow-lg' : 'bg-zinc-100 dark:bg-zinc-800 text-zinc-500'}`}>ÖDEME BEKLEYOR</button>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">FATURA / SAYAÇ DÖKÜMÜ (PDF VEYA RESİM)</label>
                                <div className="grid grid-cols-1 gap-4">
                                    <label className="flex flex-col items-center justify-center p-10 border-4 border-dashed border-zinc-100 dark:border-zinc-800 rounded-[2.5rem] bg-zinc-50 dark:bg-zinc-900 cursor-pointer hover:border-emerald-500 transition-all group">
                                        <Camera size={48} className="text-zinc-300 group-hover:text-emerald-500 mb-4" />
                                        <span className="text-[10px] font-black text-zinc-400 uppercase group-hover:text-emerald-500 text-center">RESİM ÇEK VEYA PDF YÜKLE</span>
                                        <input type="file" accept="image/*,application/pdf" onChange={handleFileChange} className="hidden" />
                                    </label>
                                    {formData.imageUrl && (
                                        <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl bg-zinc-100 dark:bg-zinc-900 p-4 border border-zinc-200 dark:border-zinc-800">
                                            {isPdf(formData.imageUrl) ? (
                                                <div className="flex flex-col items-center py-6">
                                                    <FileDigit size={48} className="text-red-500 mb-2" />
                                                    <span className="text-[10px] font-black text-zinc-500">PDF DOSYASI HAZIR</span>
                                                </div>
                                            ) : (
                                                <img src={formData.imageUrl} className="w-full h-auto max-h-64 object-contain" alt="Preview" />
                                            )}
                                            <button type="button" onClick={() => setFormData({...formData, imageUrl: ''})} className="absolute top-4 right-4 p-3 bg-red-600 text-white rounded-2xl shadow-xl hover:scale-110 active:scale-90 transition-all"><X size={20}/></button>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <button type="submit" className="w-full py-8 bg-emerald-600 text-white rounded-[2.5rem] font-black shadow-2xl shadow-emerald-500/30 transition-all flex items-center justify-center gap-4 uppercase tracking-[0.2em]">
                                <Save size={24}/> ARŞİVE KAYDET
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Fullscreen Viewer */}
            {viewFileUrl && (
                <div className="fixed inset-0 z-[300] bg-black/95 flex flex-col items-center justify-center p-4 md:p-10 animate-in fade-in" onClick={closeViewer}>
                    <button className="absolute top-6 right-6 md:top-10 md:right-10 p-4 bg-white/10 hover:bg-white/20 text-white rounded-full transition-all z-[310]"><X size={32}/></button>

                    <div className="w-full h-full max-w-6xl max-h-[85vh] flex items-center justify-center" onClick={(e) => e.stopPropagation()}>
                        {isPdfView ? (
                            <iframe 
                                src={viewFileUrl} 
                                className="w-full h-full rounded-[2rem] border-none bg-white" 
                                title="Fatura PDF"
                            />
                        ) : (
                            <img src={viewFileUrl} className="max-w-full max-h-full object-contain rounded-[2rem] shadow-2xl" alt="Fatura Tam Ekran" />
                        )}
                    </div>

                    <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mt-6">Kapatmak için ESC'ye basın veya dışarıya dokunun</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Calendar, TrendingUp, AlertCircle, FileDigit, Trash2, Loader2 } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewFileUrl, setViewFileUrl] = useState<string | null>(null);
    const [isPdfView, setIsPdfView] = useState(false);
    const [deletingId, setDeletingId] = useState<string | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    // Form State
    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    // ESC Tuşu ile Kapatma Desteği
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setIsModalOpen(false);
                closeViewer();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [viewFileUrl, isModalOpen]);

    useEffect(() => { loadData(); }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            setInvoices(data.sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            }));
        } catch (error) {
            console.error("Veri yükleme hatası:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                createdAt: formData.createdAt || new Date().toISOString()
            });
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            alert("Kaydedilirken hata oluştu.");
        }
    };

    const openViewer = (dataUrl: string) => {
        if (dataUrl.startsWith('data:application/pdf')) {
            try {
                const base64Data = dataUrl.split(',')[1];
                const byteCharacters = atob(base64Data);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++) {
                    byteNumbers[i] = byteCharacters.charCodeAt(i);
                }
                const byteArray = new Uint8Array(byteNumbers);
                const blob = new Blob([byteArray], { type: 'application/pdf' });
                const url = URL.createObjectURL(blob);
                setViewFileUrl(url);
                setIsPdfView(true);
            } catch (e) {
                console.error("PDF Dönüştürme Hatası:", e);
                alert("PDF dosyası işlenemedi.");
            }
        } else {
            setViewFileUrl(dataUrl);
            setIsPdfView(false);
        }
    };

    const closeViewer = () => {
        if (viewFileUrl && viewFileUrl.startsWith('blob:')) {
            URL.revokeObjectURL(viewFileUrl);
        }
        setViewFileUrl(null);
        setIsPdfView(false);
    };

    const handleDelete = async (id: string, month: string, year: number) => {
        if (!id) {
            alert("Hata: Doküman ID'si eksik. Sayfayı yenileyin.");
            return;
        }

        const confirmText = `DİKKAT: ${month} ${year} dönemine ait bu faturayı tamamen SİLMEK istediğinize emin misiniz?\n\nBu işlem geri alınamaz!`;
        if (window.confirm(confirmText)) {
            setDeletingId(id);
            try {
                await StorageService.deleteMonthlyInvoice(id);
                setInvoices(prev => prev.filter(inv => inv.id !== id));
                console.log("Başarıyla silindi:", id);
            } catch (error) {
                console.error("Silme işlemi başarısız:", error);
                alert("Silme işlemi sırasında bir hata oluştu. Lütfen tekrar deneyin.");
                loadData();
            } finally {
                setDeletingId(null);
            }
        }
    };

    const isPdf = (dataUrl?: string) => dataUrl?.startsWith('data:application/pdf');

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3.5rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Mobil uyumlu fatura ve sayaç döküm yönetim paneli.</p>
                </div>
                <button 
                    onClick={() => { setFormData({ id: '', month: months[new Date().getMonth()], year: currentYear, euroRate: 0, totalTL: 0, imageUrl: '', status: 'PENDING', createdAt: '' }); setIsModalOpen(true); }} 
                    className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase"
                >
                    <Plus size={24} /> YENİ FATURA EKLE
                </button>
            </div>

            {/* List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col h-full">
                        {/* Dosya Önizleme Alanı */}
                        <div 
                            className="relative h-60 overflow-hidden bg-zinc-100 dark:bg-zinc-900 cursor-pointer"
                            onClick={() => inv.imageUrl && openViewer(inv.imageUrl)}
                        >
                            {inv.imageUrl ? (
                                isPdf(inv.imageUrl) ? (
                                    <div className="w-full h-full flex flex-col items-center justify-center bg-zinc-50 dark:bg-zinc-900 group-hover:bg-emerald-50 transition-colors">
                                        <FileDigit size={64} className="text-red-500" />
                                        <span className="text-[10px] font-black mt-3 text-zinc-500 tracking-[0.2em] uppercase">PDF DÖKÜMANI</span>
                                    </div>
                                ) : (
                                    <>
