                                        {inv.status === 'PAID' ? 'ÖDENDİ' : 'ÖDEME BEKLE'}
                                    </span>
                                    <div className="text-[10px] text-zinc-400 font-bold uppercase flex items-center gap-1.5"><Calendar size={12}/> {new Date(inv.createdAt).toLocaleDateString('tr-TR')}</div>
