                        </div>
                    </div>
                ))}
            </div>

            {/* Modal - Fatura Kayıt */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[200] flex items-center justify-center p-4 md:p-6 animate-in fade-in duration-500">
