                    <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mt-6">Kapatmak için ESC'ye basın veya dışarıya dokunun</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Calendar, TrendingUp, AlertCircle, FileDigit, Trash2, Loader2, FileCheck } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewFileUrl, setViewFileUrl] = useState<string | null>(null);
    const [isPdfView, setIsPdfView] = useState(false);
    const [processingId, setProcessingId] = useState<string | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            // ID'si olmayan bozuk verileri filtrele ve tarihe göre sırala
            const validData = data.filter(d => d.id).sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            });
            setInvoices(validData);
            console.log("Yüklenen Fatura Sayısı:", validData.length);
        } catch (error) {
            console.error("Yükleme hatası:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                alert("Dosya boyutu çok büyük (Max 5MB)");
                return;
            }
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setProcessingId('saving');
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                createdAt: new Date().toISOString()
            });
            setIsModalOpen(false);
            await loadData();
            alert("Başarıyla kaydedildi.");
        } catch (error) {
            alert("Kaydetme sırasında bir hata oluştu.");
        } finally {
            setProcessingId(null);
        }
    };

    const openViewer = (dataUrl: string) => {
        if (dataUrl.startsWith('data:application/pdf')) {
            try {
                // Base64 -> Blob URL (Chrome ve Mobil için en güvenli yol)
                const base64Parts = dataUrl.split(',');
                const byteCharacters = atob(base64Parts[1]);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++) {
                    byteNumbers[i] = byteCharacters.charCodeAt(i);
                }
                const byteArray = new Uint8Array(byteNumbers);
                const blob = new Blob([byteArray], { type: 'application/pdf' });
                const blobUrl = URL.createObjectURL(blob);

                setViewFileUrl(blobUrl);
                setIsPdfView(true);
            } catch (err) {
                console.error("PDF Açma Hatası:", err);
                alert("PDF görüntülenemedi. Dosya bozuk olabilir.");
            }
        } else {
            setViewFileUrl(dataUrl);
            setIsPdfView(false);
        }
    };

    const closeViewer = () => {
        if (viewFileUrl && viewFileUrl.startsWith('blob:')) {
            URL.revokeObjectURL(viewFileUrl);
        }
        setViewFileUrl(null);
        setIsPdfView(false);
    };

    const handleDelete = async (inv: MonthlyInvoice) => {
        if (!inv.id) {
            alert("Hata: Kayıt ID'si bulunamadı. Lütfen sayfayı yenileyin.");
            return;
        }

        const confirmMessage = `🛑 DİKKAT!\n\n${inv.month} ${inv.year} dönemine ait bu faturayı KALICI olarak silmek istediğinize emin misiniz?`;

        if (window.confirm(confirmMessage)) {
            setProcessingId(inv.id);
            try {
                // UI'dan hemen kaldır
                setInvoices(prev => prev.filter(item => item.id !== inv.id));

                // Arka planda sil
                await StorageService.deleteMonthlyInvoice(inv.id);
                console.log("Kayıt başarıyla silindi:", inv.id);
            } catch (error) {
                console.error("Silme hatası:", error);
                alert("Silme işlemi başarısız oldu. Veriler tekrar yükleniyor.");
                await loadData(); // Hata durumunda listeyi tazele
            } finally {
                setProcessingId(null);
            }
        }
    };

    const isPdf = (dataUrl?: string) => dataUrl?.startsWith('data:application/pdf');

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-32">
            {/* Üst Panel */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10 text-center md:text-left">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center justify-center md:justify-start gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Fatura ve sayaç dökümlerini (PDF/JPG) güvenle yönetin.</p>
                </div>
                <button 
                    onClick={() => { setFormData({ id: '', month: months[new Date().getMonth()], year: currentYear, euroRate: 0, totalTL: 0, imageUrl: '', status: 'PENDING', createdAt: '' }); setIsModalOpen(true); }} 
                    className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase"
                >
                    <Plus size={24} /> YENİ KAYIT EKLE
                </button>
            </div>

            {/* Liste */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col relative">

                        {/* Dosya Önizleme */}
                        <div 
                            className="relative h-64 overflow-hidden bg-zinc-100 dark:bg-zinc-900 cursor-pointer"
                            onClick={() => inv.imageUrl && openViewer(inv.imageUrl)}
                        >
                            {inv.imageUrl ? (
                                isPdf(inv.imageUrl) ? (
                                    <div className="w-full h-full flex flex-col items-center justify-center bg-zinc-50 dark:bg-zinc-900 transition-colors group-hover:bg-emerald-50 dark:group-hover:bg-emerald-950/20">
                                        <FileDigit size={72} className="text-red-500" />
                                        <span className="text-[10px] font-black mt-4 text-zinc-500 tracking-[0.3em] uppercase">PDF DÖKÜMANI</span>
                                        <Eye size={20} className="mt-4 text-emerald-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                                    </div>
                                ) : (
                                    <>
                                        <img src={inv.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Fatura" />
                                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                            <div className="bg-white/20 backdrop-blur-md p-4 rounded-full text-white">
                                                <Eye size={32} />
                                            </div>
                                        </div>
                                    </>
                                )
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300">
                                    <FileText size={48} />
                                    <span className="text-[10px] font-black mt-2 uppercase tracking-widest">DOSYA YOK</span>
                                </div>
                            )}

                            <div className="absolute top-6 left-6 bg-zinc-900/90 backdrop-blur-md text-white px-5 py-2 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl">
                                {inv.month} {inv.year}
                            </div>
                        </div>

                        {/* Bilgiler */}
                        <div className="p-8 flex-1 flex flex-col">
                            <div className="grid grid-cols-2 gap-4 mb-8">
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest flex items-center gap-1.5"><TrendingUp size={12}/> EURO KURU</p>
                                    <p className="text-xl font-black text-zinc-900 dark:text-white font-mono">{inv.euroRate.toLocaleString()} ₺</p>
                                </div>
                                <div className="space-y-1 text-right">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">ÖDEME TUTARI</p>
                                    <p className="text-xl font-black text-emerald-600 font-mono">{inv.totalTL.toLocaleString()} ₺</p>
                                </div>
                            </div>

                            <div className="mt-auto space-y-4">
                                <div className="flex justify-between items-center border-t border-zinc-100 dark:border-zinc-900 pt-6">
                                    <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${inv.status === 'PAID' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                        {inv.status === 'PAID' ? 'ÖDENDİ' : 'BEKLEMEDE'}
                                    </span>
                                    <div className="text-[10px] text-zinc-400 font-bold uppercase flex items-center gap-1.5"><Calendar size={12}/> {new Date(inv.createdAt).toLocaleDateString('tr-TR')}</div>
                                </div>

                                {/* KESİN SİLME BUTONU - Geniş ve İzole */}
                                <button 
                                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleDelete(inv); }} 
                                    disabled={processingId === inv.id}
                                    className="w-full py-4 mt-2 bg-red-600 hover:bg-red-700 disabled:bg-zinc-300 text-white rounded-[1.5rem] shadow-xl font-black text-[11px] tracking-[0.2em] uppercase transition-all active:scale-95 flex items-center justify-center gap-2"
                                >
                                    {processingId === inv.id ? <Loader2 size={18} className="animate-spin"/> : <Trash2 size={18} />}
                                    BU KAYDI SİSTEMDEN SİL
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Yeni Kayıt Modalı */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[200] flex items-center justify-center p-4 md:p-6 animate-in fade-in duration-500">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-xl shadow-2xl overflow-hidden border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
                        <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                            <h3 className="font-black text-3xl text-zinc-900 dark:text-white tracking-tighter uppercase font-mono">FATURA KAYDET</h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-4 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all"><X size={32}/></button>
                        </div>
                        <form onSubmit={handleSave} className="p-10 space-y-8 overflow-y-auto custom-scrollbar">
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">DÖNEM AYI</label>
                                    <select required className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-bold text-zinc-900 dark:text-white" value={formData.month} onChange={e => setFormData({...formData, month: e.target.value})}>
                                        {months.map(m => <option key={m} value={m}>{m}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">YIL</label>
                                    <input required type="number" className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-bold text-zinc-900 dark:text-white" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} />
