                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">KUR (TL)</label>
                                    <input required type="number" step="0.01" className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold text-zinc-900 dark:text-white" value={formData.euroRate} onChange={e => setFormData({...formData, euroRate: parseFloat(e.target.value)})} />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">TOPLAM ÖDENEN (TL)</label>
                                    <input required type="number" step="0.01" className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold text-zinc-900 dark:text-white" value={formData.totalTL} onChange={e => setFormData({...formData, totalTL: parseFloat(e.target.value)})} />
                                </div>
                            </div>

                            <div className="space-y-4">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">DOSYA EKLE (PDF VEYA RESİM)</label>
                                <div className="grid grid-cols-1 gap-4">
                                    <label className="flex flex-col items-center justify-center p-10 border-4 border-dashed border-zinc-100 dark:border-zinc-800 rounded-[2.5rem] bg-zinc-50 dark:bg-zinc-900 cursor-pointer hover:border-emerald-500 transition-all group">
                                        <Camera size={48} className="text-zinc-300 group-hover:text-emerald-500 mb-4" />
                                        <span className="text-[10px] font-black text-zinc-400 uppercase group-hover:text-emerald-500 text-center">DOSYAYI BURAYA SÜRÜKLE VEYA SEÇ</span>
                                        <input type="file" accept="image/*,application/pdf" onChange={handleFileChange} className="hidden" />
                                    </label>
                                    {formData.imageUrl && (
                                        <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl bg-zinc-100 dark:bg-zinc-900 p-4 border-2 border-emerald-500">
                                            {isPdf(formData.imageUrl) ? (
                                                <div className="flex flex-col items-center py-8">
                                                    <FileCheck size={64} className="text-emerald-500 mb-2" />
                                                    <span className="text-xs font-black text-zinc-900 dark:text-white uppercase tracking-widest">PDF DOSYASI HAZIR</span>
                                                </div>
                                            ) : (
                                                <img src={formData.imageUrl} className="w-full h-auto max-h-64 object-contain" alt="Preview" />
                                            )}
                                            <button type="button" onClick={() => setFormData({...formData, imageUrl: ''})} className="absolute top-4 right-4 p-3 bg-red-600 text-white rounded-2xl shadow-xl"><X size={20}/></button>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <button 
                                type="submit" 
                                disabled={processingId === 'saving'}
                                className="w-full py-8 bg-emerald-600 text-white rounded-[2.5rem] font-black shadow-2xl shadow-emerald-500/30 transition-all flex items-center justify-center gap-4 uppercase tracking-[0.2em] active:scale-95 disabled:opacity-50"
                            >
                                {processingId === 'saving' ? <Loader2 size={24} className="animate-spin" /> : <Save size={24}/>} 
                                VERİLERİ ARŞİVE İŞLE
