import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Calendar, TrendingUp, AlertCircle, FileDigit, Trash2, Loader2, FileCheck, AlertTriangle } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewFileUrl, setViewFileUrl] = useState<string | null>(null);
    const [isPdfView, setIsPdfView] = useState(false);
    const [processingId, setProcessingId] = useState<string | null>(null);

    // Silme Onay State'i
    const [confirmDeleteInv, setConfirmDeleteInv] = useState<MonthlyInvoice | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            // ID'si olmayan veya bozuk verileri temizle
            const validData = data.filter(d => d.id).sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            });
            setInvoices(validData);
        } catch (error) {
            console.error("Yükleme hatası:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.size > 10 * 1024 * 1024) { // 10MB limit
                alert("Dosya çok büyük.");
                return;
            }
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setProcessingId('saving');
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                createdAt: new Date().toISOString()
            });
            setIsModalOpen(false);
            await loadData();
        } catch (error) {
            alert("Kaydetme hatası.");
        } finally {
            setProcessingId(null);
        }
    };

    const openViewer = (dataUrl: string) => {
        if (dataUrl.startsWith('data:application/pdf')) {
            try {
                const base64Parts = dataUrl.split(',');
                const byteCharacters = atob(base64Parts[1]);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++) {
                    byteNumbers[i] = byteCharacters.charCodeAt(i);
                }
                const byteArray = new Uint8Array(byteNumbers);
                const blob = new Blob([byteArray], { type: 'application/pdf' });
                const blobUrl = URL.createObjectURL(blob);
                setViewFileUrl(blobUrl);
                setIsPdfView(true);
            } catch (err) {
                alert("PDF açılamadı.");
            }
        } else {
            setViewFileUrl(dataUrl);
            setIsPdfView(false);
        }
    };

    const closeViewer = () => {
        if (viewFileUrl && viewFileUrl.startsWith('blob:')) {
            URL.revokeObjectURL(viewFileUrl);
        }
        setViewFileUrl(null);
        setIsPdfView(false);
    };

    const executeDelete = async () => {
        if (!confirmDeleteInv || !confirmDeleteInv.id) return;

        const idToDelete = confirmDeleteInv.id;
        setProcessingId(idToDelete);
        setConfirmDeleteInv(null);

        try {
            // UI'dan anında sil (Hız hissi için)
            setInvoices(prev => prev.filter(inv => inv.id !== idToDelete));

            // Veritabanından sil
            await StorageService.deleteMonthlyInvoice(idToDelete);
            console.log("Başarıyla silindi.");
        } catch (error) {
            console.error("Silme hatası:", error);
            alert("Silme işlemi başarısız. Veri geri getiriliyor.");
            await loadData(); // Hata varsa listeyi geri yükle
        } finally {
            setProcessingId(null);
        }
    };

    const isPdf = (dataUrl?: string) => dataUrl?.startsWith('data:application/pdf');

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura verileri taranıyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-32">
            {/* Header */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10 text-center md:text-left">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center justify-center md:justify-start gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Sayaç dökümleri ve kira faturaları dijital arşivi.</p>
                </div>
                <button 
                    onClick={() => { setFormData({ id: '', month: months[new Date().getMonth()], year: currentYear, euroRate: 0, totalTL: 0, imageUrl: '', status: 'PENDING', createdAt: '' }); setIsModalOpen(true); }} 
                    className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase"
                >
                    <Plus size={24} /> YENİ FATURA EKLE
                </button>
            </div>

            {/* Fatura Kartları */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col relative">

                        <div 
                            className="relative h-64 overflow-hidden bg-zinc-100 dark:bg-zinc-900 cursor-pointer"
                            onClick={() => inv.imageUrl && openViewer(inv.imageUrl)}
                        >
                            {inv.imageUrl ? (
                                isPdf(inv.imageUrl) ? (
                                    <div className="w-full h-full flex flex-col items-center justify-center bg-zinc-50 dark:bg-zinc-900">
                                        <FileDigit size={72} className="text-red-500" />
                                        <span className="text-[10px] font-black mt-4 text-zinc-500 tracking-[0.3em] uppercase">PDF FORMATI</span>
                                    </div>
                                ) : (
                                    <img src={inv.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Fatura" />
                                )
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300"><FileText size={48} /></div>
                            )}
                            <div className="absolute top-6 left-6 bg-zinc-900/90 backdrop-blur-md text-white px-5 py-2 rounded-2xl font-black text-xs uppercase tracking-widest">{inv.month} {inv.year}</div>
                        </div>

                        <div className="p-8 flex-1 flex flex-col">
                            <div className="grid grid-cols-2 gap-4 mb-8">
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">EURO KURU</p>
                                    <p className="text-xl font-black text-zinc-900 dark:text-white font-mono">{inv.euroRate.toLocaleString()} ₺</p>
                                </div>
                                <div className="space-y-1 text-right">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">TOPLAM TUTAR</p>
                                    <p className="text-xl font-black text-emerald-600 font-mono">{inv.totalTL.toLocaleString()} ₺</p>
                                </div>
                            </div>

                            <div className="mt-auto space-y-4 pt-6 border-t border-zinc-100 dark:border-zinc-900">
                                <div className="flex justify-between items-center">
                                    <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${inv.status === 'PAID' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                        {inv.status === 'PAID' ? 'ÖDENDİ' : 'BEKLİYOR'}
                                    </span>
                                    <span className="text-[10px] text-zinc-400 font-black uppercase"><Calendar size={12} className="inline mr-1"/> {new Date(inv.createdAt).toLocaleDateString('tr-TR')}</span>
                                </div>

                                {/* SİLME TETİKLEYİCİ - confirmDeleteInv state'ini kullanır */}
                                <button 
                                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); setConfirmDeleteInv(inv); }} 
                                    className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-[1.5rem] shadow-xl font-black text-[11px] tracking-[0.2em] uppercase transition-all active:scale-95 flex items-center justify-center gap-2"
                                >
                                    <Trash2 size={16} /> KAYDI SİSTEMDEN SİL
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* SİLME ONAY MODALI - Window.confirm yerine uygulama içi çözüm */}
            {confirmDeleteInv && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[400] flex items-center justify-center p-6 animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-md p-12 text-center shadow-2xl border border-zinc-100 dark:border-zinc-900 space-y-8 animate-in zoom-in-95">
                        <div className="w-24 h-24 bg-red-100 dark:bg-red-950/30 text-red-600 rounded-full flex items-center justify-center mx-auto shadow-xl">
                            <AlertTriangle size={48} />
                        </div>
                        <div>
                            <h3 className="text-3xl font-black text-zinc-900 dark:text-white uppercase tracking-tighter">EMİN MİSİNİZ?</h3>
                            <p className="text-zinc-500 dark:text-zinc-400 mt-4 font-medium leading-relaxed">
                                <strong className="text-zinc-900 dark:text-white">{confirmDeleteInv.month} {confirmDeleteInv.year}</strong> dönemine ait bu fatura kaydı kalıcı olarak silinecektir.
                            </p>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <button onClick={() => setConfirmDeleteInv(null)} className="py-6 bg-zinc-100 dark:bg-zinc-900 text-zinc-500 dark:text-zinc-400 rounded-3xl font-black text-[11px] tracking-widest uppercase active:scale-95 transition-all">VAZGEÇ</button>
                            <button onClick={executeDelete} className="py-6 bg-red-600 text-white rounded-3xl font-black text-[11px] tracking-widest uppercase shadow-xl shadow-red-600/20 active:scale-95 transition-all">EVET, SİL</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Kayıt Modalı */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[200] flex items-center justify-center p-4 md:p-6 animate-in fade-in">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-xl shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
                        <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center">
                            <h3 className="font-black text-3xl text-zinc-900 dark:text-white uppercase">FATURA EKLE</h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-4 bg-red-600 text-white rounded-3xl"><X size={32}/></button>
                        </div>
                        <form onSubmit={handleSave} className="p-10 space-y-8 overflow-y-auto">
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase">AY</label>
                                    <select className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.month} onChange={e => setFormData({...formData, month: e.target.value})}>
                                        {months.map(m => <option key={m} value={m}>{m}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase">YIL</label>
                                    <input type="number" className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase">KUR (TL)</label>
                                    <input type="number" step="0.01" className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.euroRate} onChange={e => setFormData({...formData, euroRate: parseFloat(e.target.value)})} />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase">TOPLAM (TL)</label>
                                    <input type="number" step="0.01" className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.totalTL} onChange={e => setFormData({...formData, totalTL: parseFloat(e.target.value)})} />
                                </div>
                            </div>
                            <div className="space-y-4">
                                <label className="text-[10px] font-black text-zinc-400 uppercase">DOSYA (PDF/JPG)</label>
                                <label className="flex flex-col items-center justify-center p-10 border-4 border-dashed border-zinc-100 dark:border-zinc-800 rounded-[2.5rem] cursor-pointer">
                                    <Camera size={48} className="text-zinc-300" />
                                    <input type="file" accept="image/*,application/pdf" onChange={handleFileChange} className="hidden" />
                                </label>
                                {formData.imageUrl && <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl text-center font-black uppercase text-[10px]">DOSYA HAZIR</div>}
                            </div>
                            <button type="submit" disabled={processingId === 'saving'} className="w-full py-8 bg-emerald-600 text-white rounded-[2.5rem] font-black">
                                {processingId === 'saving' ? <Loader2 className="animate-spin mx-auto" /> : 'KAYDET'}
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Viewer */}
            {viewFileUrl && (
                <div className="fixed inset-0 z-[500] bg-black/98 flex flex-col items-center justify-center p-4 animate-in fade-in" onClick={closeViewer}>
                    <button className="absolute top-10 right-10 p-4 bg-white/10 text-white rounded-full z-[510]"><X size={32}/></button>
                    <div className="w-full h-full flex items-center justify-center" onClick={e => e.stopPropagation()}>
                        {isPdfView ? (
                            <iframe src={viewFileUrl} className="w-full h-full rounded-[2rem] bg-white border-none" />
                        ) : (
                            <img src={viewFileUrl} className="max-w-full max-h-full object-contain rounded-[2rem]" alt="Fatura" />
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Calendar, TrendingUp, AlertCircle, FileDigit, Trash2, Loader2, AlertTriangle } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewFileUrl, setViewFileUrl] = useState<string | null>(null);
    const [isPdfView, setIsPdfView] = useState(false);
    const [processingId, setProcessingId] = useState<string | null>(null);
    const [confirmDeleteInv, setConfirmDeleteInv] = useState<MonthlyInvoice | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    // ESC TUŞU İLE KAPATMA DESTEĞİ
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setIsModalOpen(false);
                setConfirmDeleteInv(null);
                closeViewer();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [viewFileUrl, isModalOpen, confirmDeleteInv]);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            const validData = data.filter(d => d.id).sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            });
            setInvoices(validData);
        } catch (error) {
            console.error("Veri yükleme hatası:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setProcessingId('saving');
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                createdAt: new Date().toISOString()
            });
            setIsModalOpen(false);
            await loadData();
        } catch (error) {
            alert("Kaydedilirken hata oluştu.");
        } finally {
            setProcessingId(null);
        }
    };

    const openViewer = (dataUrl: string) => {
        if (dataUrl.startsWith('data:application/pdf')) {
            try {
                const base64Parts = dataUrl.split(',');
                const byteCharacters = atob(base64Parts[1]);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++) {
                    byteNumbers[i] = byteCharacters.charCodeAt(i);
                }
                const byteArray = new Uint8Array(byteNumbers);
                const blob = new Blob([byteArray], { type: 'application/pdf' });
                const url = URL.createObjectURL(blob);
                setViewFileUrl(url);
                setIsPdfView(true);
            } catch (e) {
                alert("PDF dosyası işlenemedi.");
            }
        } else {
            setViewFileUrl(dataUrl);
            setIsPdfView(false);
        }
    };

    const closeViewer = () => {
        if (viewFileUrl && viewFileUrl.startsWith('blob:')) {
            URL.revokeObjectURL(viewFileUrl);
        }
        setViewFileUrl(null);
        setIsPdfView(false);
    };

    const executeDelete = async () => {
        if (!confirmDeleteInv || !confirmDeleteInv.id) return;
        const idToDelete = confirmDeleteInv.id;
        setProcessingId(idToDelete);
        setConfirmDeleteInv(null);
        try {
            await StorageService.deleteMonthlyInvoice(idToDelete);
            setInvoices(prev => prev.filter(inv => inv.id !== idToDelete));
        } catch (error) {
            alert("Silme işlemi başarısız. Lütfen tekrar deneyin.");
            await loadData();
        } finally {
            setProcessingId(null);
        }
    };

    const isPdf = (dataUrl?: string) => dataUrl?.startsWith('data:application/pdf');

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-32">
            {/* Header */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3.5rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
