                                <strong className="text-zinc-900 dark:text-white">{confirmDeleteInv.month} {confirmDeleteInv.year}</strong> dönemine ait bu fatura kaydı kalıcı olarak silinecektir.
                            </p>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <button onClick={() => setConfirmDeleteInv(null)} className="py-6 bg-zinc-100 dark:bg-zinc-900 text-zinc-500 dark:text-zinc-400 rounded-3xl font-black text-[11px] tracking-widest uppercase active:scale-95 transition-all">VAZGEÇ</button>
                            <button onClick={executeDelete} className="py-6 bg-red-600 text-white rounded-3xl font-black text-[11px] tracking-widest uppercase shadow-xl active:scale-95 transition-all">EVET, SİL</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Tam Ekran Görüntüleyici */}
            {viewFileUrl && (
                <div className="fixed inset-0 z-[500] bg-black/98 flex flex-col items-center justify-center p-2 md:p-10 animate-in fade-in" onClick={closeViewer}>
                    <button className="absolute top-10 right-10 p-4 bg-white/10 hover:bg-white/20 text-white rounded-full z-[510]"><X size={32}/></button>
                    <div className="w-full h-full flex items-center justify-center" onClick={(e) => e.stopPropagation()}>
                        {isPdfView ? (
                            <iframe src={viewFileUrl} className="w-full h-full rounded-[2rem] bg-white border-none shadow-2xl" title="PDF Viewer" />
                        ) : (
                            <img src={viewFileUrl} className="max-w-full max-h-full object-contain rounded-[2rem] shadow-2xl select-none" alt="Fatura Tam Ekran" />
                        )}
                    </div>
                    <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mt-8">Kapatmak için ESC'ye basın veya dışarıya dokunun</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Calendar, TrendingUp, AlertCircle, FileDigit, Trash2, Loader2, AlertTriangle, ZoomIn, ZoomOut, Maximize2 } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewFileUrl, setViewFileUrl] = useState<string | null>(null);
    const [isPdfView, setIsPdfView] = useState(false);
    const [isZoomed, setIsZoomed] = useState(false);
    const [processingId, setProcessingId] = useState<string | null>(null);
    const [confirmDeleteInv, setConfirmDeleteInv] = useState<MonthlyInvoice | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    const [inputEuroRate, setInputEuroRate] = useState('');
    const [inputTotalTL, setInputTotalTL] = useState('');

    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    // ESC VE KLAVYE KONTROLLERİ
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                if (viewFileUrl) {
                    closeViewer();
                } else if (isModalOpen) {
                    setIsModalOpen(false);
                } else if (confirmDeleteInv) {
                    setConfirmDeleteInv(null);
                }
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [viewFileUrl, isModalOpen, confirmDeleteInv]);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            const validData = data.filter(d => d.id).sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            });
            setInvoices(validData);
        } catch (error) {
            console.error("Veri yükleme hatası:", error);
        } finally {
            setLoading(false);
        }
    };

    const parseLocaleNumber = (val: string): number => {
        if (!val) return 0;
        let cleanVal = val.replace(/\s/g, '');
        if (cleanVal.includes(',') && cleanVal.includes('.')) {
            cleanVal = cleanVal.replace(/\./g, '').replace(',', '.');
        } else if (cleanVal.includes(',')) {
            cleanVal = cleanVal.replace(',', '.');
        }
        const parsed = parseFloat(cleanVal);
        return isNaN(parsed) ? 0 : parsed;
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setProcessingId('saving');
        const finalEuroRate = parseLocaleNumber(inputEuroRate);
        const finalTotalTL = parseLocaleNumber(inputTotalTL);
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                euroRate: finalEuroRate,
                totalTL: finalTotalTL,
                createdAt: new Date().toISOString()
            });
            setIsModalOpen(false);
            await loadData();
        } catch (error) {
            alert("Kaydedilirken hata oluştu.");
        } finally {
            setProcessingId(null);
        }
    };

    const openViewer = (dataUrl: string) => {
        setIsZoomed(false);
        if (dataUrl.startsWith('data:application/pdf')) {
            try {
                const base64Parts = dataUrl.split(',');
                const byteCharacters = atob(base64Parts[1]);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++) {
                    byteNumbers[i] = byteCharacters.charCodeAt(i);
                }
                const byteArray = new Uint8Array(byteNumbers);
                const blob = new Blob([byteArray], { type: 'application/pdf' });
                const url = URL.createObjectURL(blob);
                setViewFileUrl(url);
                setIsPdfView(true);
            } catch (e) {
                alert("PDF dosyası işlenemedi.");
            }
        } else {
            setViewFileUrl(dataUrl);
            setIsPdfView(false);
        }
    };

    const closeViewer = () => {
        if (viewFileUrl && viewFileUrl.startsWith('blob:')) {
            URL.revokeObjectURL(viewFileUrl);
        }
        setViewFileUrl(null);
        setIsPdfView(false);
        setIsZoomed(false);
    };

    const executeDelete = async () => {
        if (!confirmDeleteInv || !confirmDeleteInv.id) return;
        const idToDelete = confirmDeleteInv.id;
        setProcessingId(idToDelete);
        setConfirmDeleteInv(null);
        try {
            await StorageService.deleteMonthlyInvoice(idToDelete);
            setInvoices(prev => prev.filter(inv => inv.id !== idToDelete));
        } catch (error) {
            alert("Silme işlemi başarısız.");
            await loadData();
        } finally {
            setProcessingId(null);
        }
    };

    const formatCurrency = (val: number) => {
        return val.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    };

    const isPdf = (dataUrl?: string) => dataUrl?.startsWith('data:application/pdf');

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-32">
            {/* Header */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3.5rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10 text-center md:text-left">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center justify-center md:justify-start gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Fatura ve sayaç dökümlerini tam ekran görüntüleyin.</p>
                </div>
                <button 
                    onClick={() => { 
                        setFormData({ id: '', month: months[new Date().getMonth()], year: currentYear, euroRate: 0, totalTL: 0, imageUrl: '', status: 'PENDING', createdAt: '' }); 
                        setInputEuroRate('');
                        setInputTotalTL('');
                        setIsModalOpen(true); 
                    }} 
                    className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase"
                >
                    <Plus size={24} /> YENİ FATURA EKLE
                </button>
            </div>

            {/* List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col h-full">
                        <div 
                            className="relative h-64 overflow-hidden bg-zinc-100 dark:bg-zinc-900 cursor-pointer"
                            onClick={() => inv.imageUrl && openViewer(inv.imageUrl)}
                        >
                            {inv.imageUrl ? (
                                isPdf(inv.imageUrl) ? (
                                    <div className="w-full h-full flex flex-col items-center justify-center bg-zinc-50 dark:bg-zinc-900 group-hover:bg-emerald-50 transition-colors">
                                        <FileDigit size={64} className="text-red-500" />
                                        <span className="text-[10px] font-black mt-3 text-zinc-500 tracking-widest uppercase">PDF DÖKÜMANI</span>
                                    </div>
                                ) : (
                                    <>
                                        <img src={inv.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Fatura" />
                                        <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                            <div className="bg-white/20 backdrop-blur-md p-4 rounded-full text-white"><Eye size={32} /></div>
                                        </div>
                                    </>
                                )
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300"><FileText size={48} /></div>
                            )}
                            <div className="absolute top-4 left-4 bg-zinc-900/80 backdrop-blur-md text-white px-4 py-2 rounded-2xl font-black text-xs uppercase tracking-widest">{inv.month} {inv.year}</div>
                        </div>

                        <div className="p-8 flex-1 flex flex-col">
                            <div className="grid grid-cols-2 gap-4 mb-8">
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">EURO KURU</p>
                                    <p className="text-xl font-black text-zinc-900 dark:text-white font-mono">{formatCurrency(inv.euroRate)} ₺</p>
                                </div>
                                <div className="space-y-1 text-right">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">TOPLAM TUTAR</p>
                                    <p className="text-xl font-black text-emerald-600 font-mono">{formatCurrency(inv.totalTL)} ₺</p>
                                </div>
                            </div>

                            <div className="mt-auto pt-6 border-t border-zinc-100 dark:border-zinc-900 flex flex-col gap-4">
                                <div className="flex justify-between items-center">
                                    <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${inv.status === 'PAID' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                        {inv.status === 'PAID' ? 'ÖDENDİ' : 'ÖDEME BEKLE'}
                                    </span>
                                    <div className="text-[10px] text-zinc-400 font-bold uppercase"><Calendar size={12} className="inline mr-1"/> {new Date(inv.createdAt).toLocaleDateString('tr-TR')}</div>
                                </div>

                                <button 
                                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); setConfirmDeleteInv(inv); }} 
                                    disabled={processingId === inv.id}
                                    className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-[1.5rem] shadow-lg font-black text-[11px] tracking-[0.2em] uppercase transition-all active:scale-95 flex items-center justify-center gap-2"
                                >
                                    {processingId === inv.id ? <Loader2 size={16} className="animate-spin"/> : <Trash2 size={16} />}
                                    SİSTEMDEN SİL
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Kayıt Modalı */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[200] flex items-center justify-center p-4 md:p-6 animate-in fade-in duration-500">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-xl shadow-2xl overflow-hidden border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
                        <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                            <h3 className="font-black text-3xl text-zinc-900 dark:text-white tracking-tighter uppercase">FATURA KAYDET</h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-4 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all"><X size={32}/></button>
                        </div>
                        <form onSubmit={handleSave} className="p-10 space-y-8 overflow-y-auto custom-scrollbar">
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">AY</label>
                                    <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.month} onChange={e => setFormData({...formData, month: e.target.value})}>
                                        {months.map(m => <option key={m} value={m}>{m}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">YIL</label>
                                    <input required type="number" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">KUR (TL)</label>
                                    <input 
                                        required 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="0,00"
                                        className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold" 
                                        value={inputEuroRate} 
                                        onChange={e => setInputEuroRate(e.target.value)} 
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">TOPLAM (TL)</label>
                                    <input 
                                        required 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="0,00"
                                        className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold" 
                                        value={inputTotalTL} 
                                        onChange={e => setInputTotalTL(e.target.value)} 
                                    />
                                </div>
                            </div>
                            <div className="space-y-4">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">DOSYA EKLE</label>
                                <label className="flex flex-col items-center justify-center p-10 border-4 border-dashed border-zinc-100 dark:border-zinc-800 rounded-[2.5rem] bg-zinc-50 dark:bg-zinc-900 cursor-pointer hover:border-emerald-500 transition-all group">
                                    <Camera size={48} className="text-zinc-300 group-hover:text-emerald-500 mb-4" />
                                    <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">RESİM VEYA PDF SEÇ</span>
                                    <input type="file" accept="image/*,application/pdf" onChange={handleFileChange} className="hidden" />
                                </label>
                                {formData.imageUrl && <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl text-center font-black uppercase text-[10px]">DOSYA HAZIR</div>}
                            </div>
                            <button type="submit" disabled={processingId === 'saving'} className="w-full py-8 bg-emerald-600 text-white rounded-[2.5rem] font-black shadow-2xl flex items-center justify-center gap-4 uppercase tracking-widest">
                                {processingId === 'saving' ? <Loader2 size={24} className="animate-spin" /> : <Save size={24}/>} KAYDET
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Silme Onay Modalı */}
            {confirmDeleteInv && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[400] flex items-center justify-center p-6 animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-md p-12 text-center shadow-2xl border border-zinc-100 dark:border-zinc-900 space-y-8 animate-in zoom-in-95">
                        <div className="w-24 h-24 bg-red-100 dark:bg-red-950/30 text-red-600 rounded-full flex items-center justify-center mx-auto shadow-xl"><AlertTriangle size={48} /></div>
                        <div>
                            <h3 className="text-3xl font-black text-zinc-900 dark:text-white uppercase tracking-tighter">EMİN MİSİNİZ?</h3>
                            <p className="text-zinc-500 dark:text-zinc-400 mt-4 font-medium leading-relaxed">
                                <strong className="text-zinc-900 dark:text-white">{confirmDeleteInv.month} {confirmDeleteInv.year}</strong> dönemine ait bu fatura kaydı kalıcı olarak silinecektir.
                            </p>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <button onClick={() => setConfirmDeleteInv(null)} className="py-6 bg-zinc-100 dark:bg-zinc-900 text-zinc-500 dark:text-zinc-400 rounded-3xl font-black text-[11px] tracking-widest uppercase active:scale-95 transition-all">VAZGEÇ</button>
                            <button onClick={executeDelete} className="py-6 bg-red-600 text-white rounded-3xl font-black text-[11px] tracking-widest uppercase shadow-xl active:scale-95 transition-all">EVET, SİL</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Tam Ekran Görüntüleyici (Akıllı Zoom Motoru) */}
            {viewFileUrl && (
                <div className="fixed inset-0 z-[500] bg-black/98 flex flex-col items-center justify-start animate-in fade-in">
                    {/* Üst Bar Kontrolleri */}
                    <div className="w-full bg-zinc-900/80 backdrop-blur-md p-6 flex justify-between items-center border-b border-white/5 z-[510]">
                        <div className="flex flex-col">
                            <h3 className="text-white font-black text-sm uppercase tracking-widest">FATURA ÖNİZLEME</h3>
                            <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">Kapatmak için ESC veya Kapat butonuna basın</p>
                        </div>
                        <div className="flex items-center gap-4">
                            {!isPdfView && (
                                <button 
                                    onClick={(e) => { e.stopPropagation(); setIsZoomed(!isZoomed); }}
                                    className="p-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl flex items-center gap-3 font-black text-[10px] tracking-widest uppercase transition-all"
                                >
                                    {isZoomed ? <ZoomOut size={20} /> : <ZoomIn size={20} />}
                                    {isZoomed ? 'EKRANA SIĞDIR' : 'TAM BOYUT (YAKINLAŞ)'}
                                </button>
                            )}
                            <button 
                                onClick={closeViewer} 
                                className="p-4 bg-red-600 hover:bg-red-500 text-white rounded-2xl shadow-xl shadow-red-600/20 active:scale-90 transition-all"
                            >
                                <X size={24} strokeWidth={3} />
                            </button>
                        </div>
                    </div>

                    {/* İçerik Alanı */}
                    <div 
                        className={`w-full h-full flex items-start justify-center overflow-auto p-2 md:p-10 custom-scrollbar ${isZoomed ? 'cursor-zoom-out' : 'cursor-zoom-in'}`}
                        onClick={() => !isPdfView && setIsZoomed(!isZoomed)}
                    >
                        <div className={`relative flex items-center justify-center min-h-full ${isZoomed ? 'w-fit' : 'w-full'}`} onClick={(e) => e.stopPropagation()}>
                            {isPdfView ? (
                                <iframe src={viewFileUrl} className="w-[90vw] h-[80vh] rounded-[2rem] bg-white border-none shadow-2xl" title="PDF Viewer" />
                            ) : (
                                <img 
                                    src={viewFileUrl} 
                                    className={`rounded-[2rem] shadow-2xl select-none transition-all duration-300 ${isZoomed ? 'max-w-none w-[150%] md:w-[200%] h-auto' : 'max-w-full max-h-full object-contain'}`} 
                                    alt="Fatura Tam Ekran" 
                                />
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { MonthlyInvoice } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Banknote, FileText, Plus, Camera, X, Save, Eye, Calendar, TrendingUp, AlertCircle, FileDigit, Trash2, Loader2, AlertTriangle, ZoomIn, ZoomOut, Maximize2, Minimize2 } from 'lucide-react';

export const Invoices: React.FC = () => {
    const [invoices, setInvoices] = useState<MonthlyInvoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [viewFileUrl, setViewFileUrl] = useState<string | null>(null);
    const [isPdfView, setIsPdfView] = useState(false);
    const [zoomLevel, setZoomLevel] = useState(1); // 1: Fit, 2: 2x, 3: Actual Size
    const [processingId, setProcessingId] = useState<string | null>(null);
    const [confirmDeleteInv, setConfirmDeleteInv] = useState<MonthlyInvoice | null>(null);

    const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
    const currentYear = 2025;

    const [inputEuroRate, setInputEuroRate] = useState('');
    const [inputTotalTL, setInputTotalTL] = useState('');

    const [formData, setFormData] = useState<MonthlyInvoice>({
        id: '',
        month: months[new Date().getMonth()],
        year: currentYear,
        euroRate: 0,
        totalTL: 0,
        imageUrl: '',
        status: 'PENDING',
        createdAt: ''
    });

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                if (viewFileUrl) closeViewer();
                else if (isModalOpen) setIsModalOpen(false);
                else if (confirmDeleteInv) setConfirmDeleteInv(null);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [viewFileUrl, isModalOpen, confirmDeleteInv]);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await StorageService.getMonthlyInvoices();
            const validData = data.filter(d => d.id).sort((a, b) => {
                const m1 = months.indexOf(a.month);
                const m2 = months.indexOf(b.month);
                if (a.year !== b.year) return b.year - a.year;
                return m2 - m1;
            });
            setInvoices(validData);
        } catch (error) {
            console.error("Veri yükleme hatası:", error);
        } finally {
            setLoading(false);
        }
    };

    const parseLocaleNumber = (val: string): number => {
        if (!val) return 0;
        let cleanVal = val.replace(/\s/g, '');
        if (cleanVal.includes(',') && cleanVal.includes('.')) {
            cleanVal = cleanVal.replace(/\./g, '').replace(',', '.');
        } else if (cleanVal.includes(',')) {
            cleanVal = cleanVal.replace(',', '.');
        }
        const parsed = parseFloat(cleanVal);
        return isNaN(parsed) ? 0 : parsed;
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setProcessingId('saving');
        const finalEuroRate = parseLocaleNumber(inputEuroRate);
        const finalTotalTL = parseLocaleNumber(inputTotalTL);
        try {
            await StorageService.saveMonthlyInvoice({
                ...formData,
                euroRate: finalEuroRate,
                totalTL: finalTotalTL,
                createdAt: new Date().toISOString()
            });
            setIsModalOpen(false);
            await loadData();
        } catch (error) {
            alert("Kaydedilirken hata oluştu.");
        } finally {
            setProcessingId(null);
        }
    };

    const openViewer = (dataUrl: string) => {
        setZoomLevel(1);
        if (dataUrl.startsWith('data:application/pdf')) {
            try {
                const base64Parts = dataUrl.split(',');
                const byteCharacters = atob(base64Parts[1]);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++) {
                    byteNumbers[i] = byteCharacters.charCodeAt(i);
                }
                const byteArray = new Uint8Array(byteNumbers);
                const blob = new Blob([byteArray], { type: 'application/pdf' });
                const url = URL.createObjectURL(blob);
                setViewFileUrl(url);
                setIsPdfView(true);
            } catch (e) {
                alert("PDF dosyası işlenemedi.");
            }
        } else {
            setViewFileUrl(dataUrl);
            setIsPdfView(false);
        }
    };

    const closeViewer = () => {
        if (viewFileUrl && viewFileUrl.startsWith('blob:')) {
            URL.revokeObjectURL(viewFileUrl);
        }
        setViewFileUrl(null);
        setIsPdfView(false);
        setZoomLevel(1);
    };

    const executeDelete = async () => {
        if (!confirmDeleteInv || !confirmDeleteInv.id) return;
        const idToDelete = confirmDeleteInv.id;
        setProcessingId(idToDelete);
        setConfirmDeleteInv(null);
        try {
            await StorageService.deleteMonthlyInvoice(idToDelete);
            setInvoices(prev => prev.filter(inv => inv.id !== idToDelete));
        } catch (error) {
            alert("Silme işlemi başarısız.");
            await loadData();
        } finally {
            setProcessingId(null);
        }
    };

    const formatCurrency = (val: number) => {
        return val.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    };

    const isPdf = (dataUrl?: string) => dataUrl?.startsWith('data:application/pdf');

    if (loading && invoices.length === 0) return <LoadingScreen message="Fatura arşivi yükleniyor..." />;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-32">
            {/* Header */}
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3.5rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
                <div className="relative z-10 text-center md:text-left">
                    <h2 className="text-4xl font-black text-zinc-900 dark:text-white flex items-center justify-center md:justify-start gap-4 tracking-tighter uppercase">
                        <Banknote size={48} className="text-emerald-500" /> Fatura Arşivi
                    </h2>
                    <p className="text-zinc-500 dark:text-zinc-400 mt-4 text-lg font-medium">Fatura ve sayaç dökümlerini tam ekran görüntüleyin.</p>
                </div>
                <button 
                    onClick={() => { 
                        setFormData({ id: '', month: months[new Date().getMonth()], year: currentYear, euroRate: 0, totalTL: 0, imageUrl: '', status: 'PENDING', createdAt: '' }); 
                        setInputEuroRate('');
                        setInputTotalTL('');
                        setIsModalOpen(true); 
                    }} 
                    className="relative z-10 bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black shadow-xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-3 text-sm tracking-widest uppercase"
                >
                    <Plus size={24} /> YENİ FATURA EKLE
                </button>
            </div>

            {/* List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {invoices.map(inv => (
                    <div key={inv.id} className="bg-white dark:bg-zinc-950 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 shadow-xl overflow-hidden group hover:border-emerald-500/30 transition-all flex flex-col h-full">
                        <div 
                            className="relative h-64 overflow-hidden bg-zinc-100 dark:bg-zinc-900 cursor-pointer"
                            onClick={() => inv.imageUrl && openViewer(inv.imageUrl)}
                        >
                            {inv.imageUrl ? (
                                isPdf(inv.imageUrl) ? (
                                    <div className="w-full h-full flex flex-col items-center justify-center bg-zinc-50 dark:bg-zinc-900 group-hover:bg-emerald-50 transition-colors">
                                        <FileDigit size={64} className="text-red-500" />
                                        <span className="text-[10px] font-black mt-3 text-zinc-500 tracking-widest uppercase">PDF DÖKÜMANI</span>
                                    </div>
                                ) : (
                                    <>
                                        <img src={inv.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Fatura" />
                                        <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                            <div className="bg-white/20 backdrop-blur-md p-4 rounded-full text-white"><Eye size={32} /></div>
                                        </div>
                                    </>
                                )
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300"><FileText size={48} /></div>
                            )}
                            <div className="absolute top-4 left-4 bg-zinc-900/80 backdrop-blur-md text-white px-4 py-2 rounded-2xl font-black text-xs uppercase tracking-widest">{inv.month} {inv.year}</div>
                        </div>

                        <div className="p-8 flex-1 flex flex-col">
                            <div className="grid grid-cols-2 gap-4 mb-8">
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">EURO KURU</p>
                                    <p className="text-xl font-black text-zinc-900 dark:text-white font-mono">{formatCurrency(inv.euroRate)} ₺</p>
                                </div>
                                <div className="space-y-1 text-right">
                                    <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">TOPLAM TUTAR</p>
                                    <p className="text-xl font-black text-emerald-600 font-mono">{formatCurrency(inv.totalTL)} ₺</p>
                                </div>
                            </div>

                            <div className="mt-auto pt-6 border-t border-zinc-100 dark:border-zinc-900 flex flex-col gap-4">
                                <div className="flex justify-between items-center">
                                    <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${inv.status === 'PAID' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                        {inv.status === 'PAID' ? 'ÖDENDİ' : 'ÖDEME BEKLE'}
                                    </span>
                                    <div className="text-[10px] text-zinc-400 font-bold uppercase"><Calendar size={12} className="inline mr-1"/> {new Date(inv.createdAt).toLocaleDateString('tr-TR')}</div>
                                </div>

                                <button 
                                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); setConfirmDeleteInv(inv); }} 
                                    disabled={processingId === inv.id}
                                    className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-[1.5rem] shadow-lg font-black text-[11px] tracking-[0.2em] uppercase transition-all active:scale-95 flex items-center justify-center gap-2"
                                >
                                    {processingId === inv.id ? <Loader2 size={16} className="animate-spin"/> : <Trash2 size={16} />}
                                    SİSTEMDEN SİL
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Kayıt Modalı */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[200] flex items-center justify-center p-4 md:p-6 animate-in fade-in duration-500">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-xl shadow-2xl overflow-hidden border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
                        <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                            <h3 className="font-black text-3xl text-zinc-900 dark:text-white tracking-tighter uppercase">FATURA KAYDET</h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-4 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all"><X size={32}/></button>
                        </div>
                        <form onSubmit={handleSave} className="p-10 space-y-8 overflow-y-auto custom-scrollbar">
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">AY</label>
                                    <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.month} onChange={e => setFormData({...formData, month: e.target.value})}>
                                        {months.map(m => <option key={m} value={m}>{m}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">YIL</label>
                                    <input required type="number" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">KUR (TL)</label>
                                    <input 
                                        required 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="0,00"
                                        className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold" 
                                        value={inputEuroRate} 
                                        onChange={e => setInputEuroRate(e.target.value)} 
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">TOPLAM (TL)</label>
                                    <input 
                                        required 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="0,00"
                                        className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 font-mono font-bold" 
                                        value={inputTotalTL} 
                                        onChange={e => setInputTotalTL(e.target.value)} 
                                    />
                                </div>
                            </div>
                            <div className="space-y-4">
                                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">DOSYA EKLE</label>
                                <label className="flex flex-col items-center justify-center p-10 border-4 border-dashed border-zinc-100 dark:border-zinc-800 rounded-[2.5rem] bg-zinc-50 dark:bg-zinc-900 cursor-pointer hover:border-emerald-500 transition-all group">
                                    <Camera size={48} className="text-zinc-300 group-hover:text-emerald-500 mb-4" />
                                    <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">RESİM VEYA PDF SEÇ</span>
                                    <input type="file" accept="image/*,application/pdf" onChange={handleFileChange} className="hidden" />
                                </label>
                                {formData.imageUrl && <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl text-center font-black uppercase text-[10px]">DOSYA HAZIR</div>}
                            </div>
                            <button type="submit" disabled={processingId === 'saving'} className="w-full py-8 bg-emerald-600 text-white rounded-[2.5rem] font-black shadow-2xl flex items-center justify-center gap-4 uppercase tracking-widest">
                                {processingId === 'saving' ? <Loader2 size={24} className="animate-spin" /> : <Save size={24}/>} KAYDET
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Silme Onay Modalı */}
            {confirmDeleteInv && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[400] flex items-center justify-center p-6 animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-md p-12 text-center shadow-2xl border border-zinc-100 dark:border-zinc-900 space-y-8 animate-in zoom-in-95">
                        <div className="w-24 h-24 bg-red-100 dark:bg-red-950/30 text-red-600 rounded-full flex items-center justify-center mx-auto shadow-xl"><AlertTriangle size={48} /></div>
                        <div>
                            <h3 className="text-3xl font-black text-zinc-900 dark:text-white uppercase tracking-tighter">EMİN MİSİNİZ?</h3>
                            <p className="text-zinc-500 dark:text-zinc-400 mt-4 font-medium leading-relaxed">
                                <strong className="text-zinc-900 dark:text-white">{confirmDeleteInv.month} {confirmDeleteInv.year}</strong> dönemine ait bu fatura kaydı kalıcı olarak silinecektir.
                            </p>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <button onClick={() => setConfirmDeleteInv(null)} className="py-6 bg-zinc-100 dark:bg-zinc-900 text-zinc-500 dark:text-zinc-400 rounded-3xl font-black text-[11px] tracking-widest uppercase active:scale-95 transition-all">VAZGEÇ</button>
                            <button onClick={executeDelete} className="py-6 bg-red-600 text-white rounded-3xl font-black text-[11px] tracking-widest uppercase shadow-xl active:scale-95 transition-all">EVET, SİL</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Tam Ekran Görüntüleyici (Ultra Zoom Engine) */}
            {viewFileUrl && (
                <div className="fixed inset-0 z-[500] bg-zinc-950/98 flex flex-col items-center justify-start animate-in fade-in duration-300">
                    {/* Üst Kontrol Barı */}
                    <div className="w-full bg-zinc-900/90 backdrop-blur-xl p-6 flex justify-between items-center border-b border-white/5 z-[510] shadow-2xl">
                        <div className="flex flex-col">
                            <h3 className="text-white font-black text-sm uppercase tracking-widest">FATURA DETAY İNCELEME</h3>
                            <div className="flex items-center gap-3 mt-1">
                                <span className="bg-emerald-500 w-2 h-2 rounded-full animate-pulse"></span>
                                <p className="text-zinc-400 text-[9px] font-bold uppercase tracking-widest">
                                    {zoomLevel === 1 ? 'EKRANA SIĞDIRILDI' : zoomLevel === 2 ? '%200 YAKINLAŞTIRILDI' : 'ORİJİNAL BOYUT (%300)'}
                                </p>
                            </div>
                        </div>

                        <div className="flex items-center gap-3">
                            {!isPdfView && (
                                <div className="flex bg-black/40 p-1 rounded-2xl border border-white/5 mr-4">
                                    <button 
                                        onClick={() => setZoomLevel(1)} 
                                        className={`p-3 rounded-xl transition-all ${zoomLevel === 1 ? 'bg-emerald-600 text-white shadow-lg' : 'text-zinc-500 hover:text-white'}`}
                                        title="Sığdır"
                                    >
                                        <Minimize2 size={20} />
                                    </button>
                                    <button 
                                        onClick={() => setZoomLevel(2)} 
                                        className={`p-3 rounded-xl transition-all ${zoomLevel === 2 ? 'bg-emerald-600 text-white shadow-lg' : 'text-zinc-500 hover:text-white'}`}
                                        title="2x Zoom"
                                    >
                                        <ZoomIn size={20} />
                                    </button>
                                    <button 
                                        onClick={() => setZoomLevel(3)} 
                                        className={`p-3 rounded-xl transition-all ${zoomLevel === 3 ? 'bg-emerald-600 text-white shadow-lg' : 'text-zinc-500 hover:text-white'}`}
                                        title="Gerçek Boyut"
                                    >
                                        <Maximize2 size={20} />
                                    </button>
                                </div>
                            )}
                            <button 
                                onClick={closeViewer} 
                                className="p-4 bg-red-600 hover:bg-red-500 text-white rounded-2xl shadow-xl shadow-red-600/30 active:scale-90 transition-all"
                            >
                                <X size={24} strokeWidth={3} />
                            </button>
                        </div>
                    </div>

                    {/* Ana Görüntüleme Alanı */}
                    <div className="w-full h-full overflow-auto custom-scrollbar flex items-start justify-center bg-black/40" onClick={closeViewer}>
                        <div 
                            className={`transition-all duration-300 ease-out flex items-center justify-center min-h-full p-4 md:p-10 ${
                                zoomLevel === 1 ? 'w-full h-full' : zoomLevel === 2 ? 'w-[150%] md:w-[200%]' : 'w-[250%] md:w-[350%]'
                            }`}
                            onClick={(e) => e.stopPropagation()}
                        >
                            {isPdfView ? (
                                <iframe 
                                    src={viewFileUrl} 
                                    className="w-[95vw] h-[85vh] rounded-[2rem] bg-white border-none shadow-[0_0_100px_rgba(0,0,0,0.5)]" 
                                    title="Fatura PDF" 
                                />
                            ) : (
                                <img 
                                    src={viewFileUrl} 
                                    className={`rounded-2xl shadow-[0_0_100px_rgba(0,0,0,0.5)] select-none transition-all duration-300 ${
                                        zoomLevel === 1 ? 'max-w-full max-h-[80vh] object-contain' : 'w-full h-auto max-w-none'
                                    }`} 
                                    alt="Fatura Görseli" 
                                />
                            )}
                        </div>
                    </div>

                    {/* Alt Bilgi */}
                    <div className="w-full p-4 bg-zinc-900/50 backdrop-blur-sm text-center border-t border-white/5">
                        <p className="text-zinc-500 text-[9px] font-black uppercase tracking-[0.4em]">
                            Kaydırmak için sürükleyin • Kapatmak için ESC basın
                        </p>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, QrCode, Download, RefreshCw, Calendar, Calculator, Wrench, Droplet, Globe, Activity, ChevronRight, TrendingUp, Clock, User as UserIcon, FileText, Settings, AlertCircle, Info } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, PrinterStatus, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);

  // Sağ Panel Detay State
  const [selectedPrinter, setSelectedPrinter] = useState<PrinterType | null>(null);
  const [printerServices, setPrinterServices] = useState<ServiceRecord[]>([]);
  const [printerCounters, setPrinterCounters] = useState<CounterLog[]>([]);

  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '',
    model: '',
    serialNumber: '',
    shortCode: '',
    location: '',
    floor: '',
    lastCounter: 0,
    connectionType: 'USB',
    ipAddress: '',
    status: 'ACTIVE'
  });

  useEffect(() => { loadData(); }, []);

  // URL'den gelen bir ID varsa (Scan'den gelince) direkt detayı aç
  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const p = printers.find(x => x.id === targetPrinterId);
      if (p) handleOpenDetail(p);
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  useEffect(() => {
    const handlePopState = () => {
      setIsFormModalOpen(false);
      setSelectedPrinter(null);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([StorageService.getPrinters(), StorageService.getConfig()]);
    setPrinters(p);
    setConfig(c);
    setLoading(false);
  };

  const handleOpenDetail = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'detail' }, '');
    setSelectedPrinter(printer);

    // Cihaza özel kayıtları çek
    const [services, counters] = await Promise.all([
      StorageService.getServiceRecords(),
      StorageService.getCounterLogs()
    ]);

    setPrinterServices(services.filter(s => s.printerId === printer.id));
    setPrinterCounters(counters.filter(c => c.printerId === printer.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };

  const openFormModal = (e: React.MouseEvent, printer?: PrinterType) => {
    e.stopPropagation();
    window.history.pushState({ modal: 'form' }, '');
    if (printer) {
      setEditingPrinter(printer); 
      setFormData({ ...printer });
    } else {
      setEditingPrinter(null);
      setFormData({ brand: config.brands[0] || '', model: config.models[0] || '', status: 'ACTIVE', connectionType: 'USB' });
    }
    setIsFormModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingPrinter?.id) {
       await StorageService.updatePrinter({ ...editingPrinter, ...formData } as PrinterType);
    } else {
       await StorageService.addPrinter({ id: '', lastTonerDate: new Date().toISOString(), ...formData as PrinterType });
    }
    window.history.back();
    loadData();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]';
      case 'MAINTENANCE': return 'bg-orange-500 shadow-[0_0_15px_rgba(249,115,22,0.5)]';
      case 'BROKEN': return 'bg-red-500 shadow-[0_0_15_rgba(239,68,68,0.5)]';
      case 'SPARE': return 'bg-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.5)]';
      default: return 'bg-zinc-500';
    }
  };

  const filteredPrinters = printers.filter(p => {
    const s = searchTerm.toLocaleLowerCase('tr-TR');
    return (p.model.toLocaleLowerCase('tr-TR').includes(s) || p.location.toLocaleLowerCase('tr-TR').includes(s) || p.shortCode?.includes(s) || p.serialNumber.toLowerCase().includes(s));
  });

  return (
    <div className="space-y-8 pb-32">
      {/* Header Panel */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 bg-white dark:bg-zinc-950 p-10 rounded-[3.5rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 overflow-hidden relative group transition-all">
        <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-3xl -ml-32 -mt-32"></div>
        <div className="relative z-10">
          <h2 className="text-4xl font-black text-zinc-900 dark:text-white tracking-tighter uppercase">CİHAZ HAVUZU</h2>
          <p className="text-sm font-bold text-zinc-400 mt-2 uppercase tracking-widest">{printers.length} Kayıtlı Cihaz Analizi</p>
        </div>
        <div className="flex gap-4 w-full sm:w-auto relative z-10">
            <button onClick={loadData} className="p-5 bg-zinc-100 dark:bg-zinc-900 rounded-3xl text-zinc-500 dark:text-zinc-400 hover:text-emerald-500 transition-all active:scale-90"><RefreshCw size={28}/></button>
            <button onClick={(e) => openFormModal(e)} className="flex-1 sm:flex-none bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-3xl flex items-center justify-center gap-3 font-black shadow-xl shadow-emerald-500/20 transition-all active:scale-95 uppercase text-xs tracking-widest"><Plus size={24} /> YENİ CİHAZ</button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative group">
        <div className="absolute inset-y-0 left-0 pl-8 flex items-center pointer-events-none text-zinc-400 group-focus-within:text-emerald-500 transition-colors"><Search size={28} /></div>
        <input type="text" placeholder="Model, Hızlı Kod veya Lokasyon ara..." className="w-full pl-20 pr-10 py-8 rounded-[2.5rem] border-2 border-transparent bg-white dark:bg-zinc-950 text-zinc-900 dark:text-white shadow-xl focus:border-emerald-500 outline-none transition-all font-black text-xl placeholder:text-zinc-400" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredPrinters.map(printer => (
          <div 
            key={printer.id} 
            onClick={() => handleOpenDetail(printer)}
            className="group rounded-[3rem] shadow-lg hover:shadow-2xl border border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950 overflow-hidden transition-all duration-500 flex flex-col relative hover:-translate-y-2 cursor-pointer"
          >
            <div className={`absolute top-8 left-8 w-4 h-4 rounded-full ${getStatusBadge(printer.status)} z-20 border-4 border-white dark:border-zinc-950`}></div>

            {/* Connection Badge */}
            <div className="absolute top-8 right-8 z-20 flex gap-2">
                {printer.connectionType === 'Network' ? (
                    <span className="bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 border border-emerald-100 dark:border-emerald-900/50">
                        <Wifi size={12} /> {printer.ipAddress}
                    </span>
                ) : (
                    <span className="bg-zinc-50 dark:bg-zinc-900/40 text-zinc-500 px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 border border-zinc-100 dark:border-zinc-800">
                        <Usb size={12} /> USB
                    </span>
                )}
            </div>

            <div className="p-10 flex-1">
              <div className="flex flex-col gap-6">
                  <div className="space-y-1">
                       <div className="flex items-center gap-2 text-zinc-400 dark:text-zinc-500 font-black text-[10px] uppercase tracking-widest"><MapPin size={14} className="text-emerald-500" /> {printer.location}</div>
                  </div>
                  <div>
                      <h3 className="text-3xl font-black text-zinc-900 dark:text-white leading-tight tracking-tighter group-hover:text-emerald-500 transition-colors uppercase">{printer.brand} {printer.model}</h3>
                      <div className="flex items-center gap-3 mt-4">
                        <span className="text-xs font-black text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/40 px-4 py-2 rounded-2xl border border-emerald-100 dark:border-emerald-900/50 tracking-widest">#{printer.shortCode}</span>
                        <span className="text-[10px] font-mono font-bold text-zinc-400 uppercase tracking-widest">SN: {printer.serialNumber}</span>
                      </div>
                  </div>
              </div>

              <div className="mt-10 pt-8 border-t border-zinc-50 dark:border-zinc-900 flex justify-between items-center">
                  <div className="flex flex-col">
                      <span className="text-[10px] text-zinc-400 font-black uppercase tracking-widest mb-1">GÜNCEL SAYAC</span>
                      <span className="text-3xl font-mono font-black text-zinc-900 dark:text-white">{printer.lastCounter.toLocaleString()}</span>
                  </div>
                  <div className="bg-zinc-50 dark:bg-zinc-900 p-4 rounded-3xl text-zinc-400 group-hover:text-emerald-500 group-hover:scale-110 transition-all">
                      <ChevronRight size={32} strokeWidth={3} />
                  </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* SAĞ PANEL DETAY DRAWER */}
      {selectedPrinter && (
          <div className="fixed inset-0 z-[300] flex justify-end">
              <div className="absolute inset-0 bg-black/80 backdrop-blur-md animate-in fade-in duration-500" onClick={() => window.history.back()}></div>
              <div className="relative w-full max-w-2xl bg-white dark:bg-zinc-950 h-full shadow-2xl border-l border-zinc-100 dark:border-zinc-900 animate-in slide-in-from-right duration-500 flex flex-col overflow-hidden">

                  {/* Drawer Header */}
                  <div className="p-10 border-b border-zinc-50 dark:border-zinc-900 bg-zinc-50/50 dark:bg-zinc-900/50 flex justify-between items-center">
                      <div className="flex items-center gap-5">
                          <div className={`w-5 h-5 rounded-full ${getStatusBadge(selectedPrinter.status)} shadow-lg`}></div>
                          <div>
                              <h3 className="text-3xl font-black text-zinc-900 dark:text-white tracking-tighter uppercase">{selectedPrinter.brand} {selectedPrinter.model}</h3>
                              <p className="text-[10px] text-zinc-400 font-black uppercase tracking-widest mt-1">CİHAZ ANALİZ VE KAYIT DEFTERİ</p>
                          </div>
                      </div>
                      <button onClick={() => window.history.back()} className="p-5 bg-red-600 text-white rounded-[1.5rem] shadow-xl hover:rotate-90 transition-all active:scale-90"><X size={28} strokeWidth={3}/></button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-10 space-y-12 custom-scrollbar">

                      {/* Cihaz Bilgi Kartı ve QR */}
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                          <div className="bg-zinc-50 dark:bg-zinc-900 p-8 rounded-[2.5rem] border border-zinc-100 dark:border-zinc-800 space-y-6">
                              <div className="space-y-4">
                                  <div className="flex items-center gap-3 text-emerald-500 font-black text-xs uppercase tracking-widest"><Hash size={16}/> HIZLI KOD: #{selectedPrinter.shortCode}</div>
                                  <div className="flex items-center gap-3 text-zinc-500 font-bold text-xs uppercase tracking-widest"><Info size={16}/> SERİ: {selectedPrinter.serialNumber}</div>
                                  <div className="flex items-center gap-3 text-zinc-500 font-bold text-xs uppercase tracking-widest"><MapPin size={16}/> LOKASYON: {selectedPrinter.location}</div>
                                  <div className="flex items-center gap-3 text-zinc-500 font-bold text-xs uppercase tracking-widest"><Globe size={16}/> BAĞLANTI: {selectedPrinter.connectionType} {selectedPrinter.ipAddress ? `(${selectedPrinter.ipAddress})` : ''}</div>
                              </div>
                              <button onClick={(e) => openFormModal(e, selectedPrinter)} className="w-full py-4 bg-zinc-900 dark:bg-white text-white dark:text-black rounded-2xl font-black text-[10px] tracking-widest uppercase shadow-xl transition-all active:scale-95 flex items-center justify-center gap-2">
                                  <Edit2 size={14}/> CİHAZ BİLGİLERİNİ DÜZENLE
                              </button>
                          </div>
                          <div className="bg-white dark:bg-zinc-900 p-8 rounded-[2.5rem] border border-zinc-100 dark:border-zinc-800 flex flex-col items-center justify-center text-center">
                              <img 
                                src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(window.location.origin + '?pid=' + selectedPrinter.id)}`} 
                                className="w-32 h-32 mb-4 p-2 bg-white rounded-2xl shadow-lg" 
                                alt="QR" 
                              />
                              <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">CİHAZ QR KODU</p>
                              <p className="text-[8px] text-zinc-300 mt-2">Hızlı erişim için etiketi taratın</p>
                          </div>
                      </div>

                      {/* Toner Durumu */}
                      <div className="bg-emerald-50 dark:bg-emerald-950/20 p-10 rounded-[3rem] border border-emerald-100 dark:border-emerald-900/50">
                          <h4 className="text-emerald-900 dark:text-emerald-400 font-black text-lg mb-6 uppercase flex items-center gap-3"><Droplet size={24}/> TONER DURUM ANALİZİ</h4>
                          <div className="grid grid-cols-2 gap-8">
                              <div>
                                  <p className="text-[10px] font-black text-emerald-600/50 uppercase tracking-widest">SON DEĞİŞİM TARİHİ</p>
                                  <p className="text-2xl font-black text-emerald-900 dark:text-emerald-100 mt-2">{new Date(selectedPrinter.lastTonerDate).toLocaleDateString('tr-TR')}</p>
                              </div>
                              <div>
                                  <p className="text-[10px] font-black text-emerald-600/50 uppercase tracking-widest">UYUMLU TONER</p>
                                  <p className="text-2xl font-black text-emerald-900 dark:text-emerald-100 mt-2">{selectedPrinter.compatibleToner || 'Tanımlanmamış'}</p>
                              </div>
                          </div>
                      </div>

                      {/* Endeks Geçmişi */}
                      <div className="space-y-6">
                          <h4 className="font-black text-zinc-900 dark:text-white uppercase tracking-widest text-sm flex items-center gap-3"><TrendingUp size={20} className="text-blue-500" /> SAYAC (ENDEKS) GEÇMİŞİ</h4>
                          <div className="bg-zinc-50 dark:bg-zinc-900 rounded-[2.5rem] border border-zinc-100 dark:border-zinc-800 overflow-hidden">
                              {printerCounters.length > 0 ? (
                                  <div className="divide-y divide-zinc-100 dark:divide-zinc-800">
                                      {printerCounters.slice(0, 5).map(log => (
                                          <div key={log.id} className="p-6 flex justify-between items-center hover:bg-zinc-100 dark:hover:bg-zinc-800/50 transition-colors">
                                              <div>
                                                  <p className="font-black text-sm text-zinc-800 dark:text-zinc-200">{log.currentCounter.toLocaleString()}</p>
                                                  <p className="text-[10px] text-zinc-400 font-bold">{new Date(log.date).toLocaleDateString('tr-TR')}</p>
                                              </div>
                                              <div className="text-right">
                                                  <p className="text-xs font-black text-emerald-600">+{log.usage.toLocaleString()}</p>
                                                  <p className="text-[9px] text-zinc-400 font-bold uppercase">{log.recordedBy.split('(')[0]}</p>
                                              </div>
                                          </div>
                                      ))}
                                  </div>
                              ) : (
                                  <div className="p-10 text-center text-zinc-400 font-bold text-xs uppercase tracking-widest">Endeks kaydı bulunamadı.</div>
                              )}
                          </div>
                      </div>

                      {/* Teknik Servis Kayıtları */}
                      <div className="space-y-6">
                          <h4 className="font-black text-zinc-900 dark:text-white uppercase tracking-widest text-sm flex items-center gap-3"><Wrench size={20} className="text-orange-500" /> TEKNİK KAYITLAR (SERVİS)</h4>
                          <div className="space-y-4">
                              {printerServices.length > 0 ? (
                                  printerServices.map(service => (
                                      <div key={service.id} className="bg-white dark:bg-zinc-900 p-8 rounded-[2.5rem] border border-zinc-100 dark:border-zinc-800 shadow-lg space-y-4">
                                          <div className="flex justify-between items-start">
                                              <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest ${service.status === 'COMPLETED' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                                  {service.status === 'COMPLETED' ? 'TAMAMLANDI' : 'BEKLİYOR'}
                                              </span>
                                              <span className="text-[10px] font-bold text-zinc-400">{new Date(service.date).toLocaleDateString('tr-TR')}</span>
                                          </div>
                                          <div>
                                              <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-1">ARIZA / İŞLEM</p>
                                              <p className="text-sm font-black text-zinc-800 dark:text-zinc-200">{service.issue}</p>
                                              <p className="text-xs text-zinc-500 dark:text-zinc-400 mt-2 leading-relaxed">{service.actionTaken}</p>
                                          </div>
                                          <div className="pt-4 border-t border-zinc-50 dark:border-zinc-800 flex justify-between items-center">
                                              <p className="text-[10px] font-black text-orange-600 uppercase tracking-widest">MALİYET: {service.cost.toLocaleString()} ₺</p>
                                              <p className="text-[9px] text-zinc-400 font-bold uppercase">{service.provider}</p>
                                          </div>
                                      </div>
                                  ))
                              ) : (
                                  <div className="p-20 bg-zinc-50 dark:bg-zinc-900/50 rounded-[3rem] text-center border-4 border-dashed border-zinc-100 dark:border-zinc-800">
                                      <p className="text-zinc-400 font-black text-xs uppercase tracking-widest">Servis kaydı bulunmuyor.</p>
                                  </div>
                              )}
                          </div>
                      </div>

                  </div>

                  {/* Drawer Footer Actions */}
                  <div className="p-10 border-t border-zinc-50 dark:border-zinc-900 bg-zinc-50/50 dark:bg-zinc-900/50 grid grid-cols-2 gap-4">
                      <button onClick={() => window.history.back()} className="py-6 bg-zinc-200 dark:bg-zinc-800 text-zinc-500 dark:text-zinc-400 rounded-3xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">PANELİ KAPAT</button>
                      <button onClick={async () => { if(confirm('Bu cihazı sistemden kalıcı olarak silmek istediğinize emin misiniz?')) { await StorageService.deletePrinter(selectedPrinter.id); window.history.back(); loadData(); } }} className="py-6 bg-red-600 text-white rounded-3xl font-black text-xs uppercase tracking-widest shadow-xl shadow-red-600/20 active:scale-95 transition-all flex items-center justify-center gap-2">
                          <Trash2 size={18}/> CİHAZI SİL
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Kayıt Modalı */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[400] flex items-center justify-center p-6 animate-in fade-in duration-500">
          <div className="bg-white dark:bg-zinc-950 rounded-[4rem] w-full max-w-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-500 border border-zinc-100 dark:border-zinc-900 flex flex-col max-h-[90vh]">
            <div className="p-10 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
              <h3 className="font-black text-3xl text-zinc-900 dark:text-white tracking-tighter uppercase">{editingPrinter ? 'CİHAZ GÜNCELLE' : 'YENİ CİHAZ EKLE'}</h3>
              <button onClick={() => window.history.back()} className="p-4 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all"><X size={32} strokeWidth={3} /></button>
            </div>
            <form onSubmit={handleSave} className="p-10 space-y-6 overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Marka</label>
                  <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})}>
                    {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Model</label>
                  <select required className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})}>
                    {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Seri Numarası</label>
                  <input required type="text" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Lokasyon</label>
                  <input required type="text" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Hızlı Kod (#)</label>
                    <input type="text" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.shortCode} onChange={e => setFormData({...formData, shortCode: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Bağlantı Tipi</label>
                    <select className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.connectionType} onChange={e => setFormData({...formData, connectionType: e.target.value as any})}>
                      <option value="USB">USB</option>
                      <option value="Network">Network (IP)</option>
                    </select>
                  </div>
              </div>

              {formData.connectionType === 'Network' && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">IP Adresi</label>
                    <input type="text" className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" placeholder="Örn: 192.168.1.100" value={formData.ipAddress} onChange={e => setFormData({...formData, ipAddress: e.target.value})} />
                  </div>
              )}

              <div className="space-y-2">
                <label className="text-[10px] font-black text-zinc-400 uppercase tracking-widest ml-2">Cihaz Durumu</label>
                <select className="w-full p-4 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white font-bold outline-none focus:border-emerald-500" value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as PrinterStatus})}>
                  <option value="ACTIVE">Aktif</option>
                  <option value="MAINTENANCE">Serviste</option>
                  <option value="BROKEN">Arızalı</option>
                  <option value="SPARE">Yedek</option>
                  <option value="SCRAPPED">Hurda</option>
                </select>
              </div>

              <button type="submit" className="w-full py-6 bg-emerald-600 text-white rounded-[2rem] font-black shadow-xl transition-all active:scale-95 uppercase tracking-widest">KAYDET VE SİSTEME İŞLE</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, QrCode, Download, RefreshCw, Calendar, Calculator, Wrench, Droplet, Globe, Activity, ChevronRight, TrendingUp, Clock, User as UserIcon, FileText, Settings, AlertCircle, Info, SortAsc, SortDesc, TrendingDown, MoreVertical } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, PrinterStatus, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState<'AZ' | 'ZA'>('AZ');
  const [loading, setLoading] = useState(true);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);

  // Sağ Panel Detay State
  const [selectedPrinter, setSelectedPrinter] = useState<PrinterType | null>(null);
  const [printerServices, setPrinterServices] = useState<ServiceRecord[]>([]);
  const [printerCounters, setPrinterCounters] = useState<CounterLog[]>([]);
  const [printerTonerLogs, setPrinterTonerLogs] = useState<StockLog[]>([]);

  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '',
    model: '',
    serialNumber: '',
    shortCode: '',
    location: '',
    floor: '',
    lastCounter: 0,
    connectionType: 'USB',
    ipAddress: '',
    status: 'ACTIVE'
  });

  useEffect(() => { loadData(); }, []);

  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const p = printers.find(x => x.id === targetPrinterId);
      if (p) handleOpenDetail(p);
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  useEffect(() => {
    const handlePopState = () => {
      setIsFormModalOpen(false);
      setSelectedPrinter(null);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([StorageService.getPrinters(), StorageService.getConfig()]);
    setPrinters(p);
    setConfig(c);
    setLoading(false);
  };

  const handleOpenDetail = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'detail' }, '');
    setSelectedPrinter(printer);

    // Cihaza özel kayıtları çek
    const [services, counters, logs] = await Promise.all([
      StorageService.getServiceRecords(),
      StorageService.getCounterLogs(),
      StorageService.getLogs()
    ]);

    setPrinterServices(services.filter(s => s.printerId === printer.id));
    setPrinterCounters(counters.filter(c => c.printerId === printer.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    setPrinterTonerLogs(logs.filter(l => l.printerId === printer.id && l.type === 'OUT'));
  };

  const openFormModal = (e: React.MouseEvent, printer?: PrinterType) => {
    e.stopPropagation();
    window.history.pushState({ modal: 'form' }, '');
    if (printer) {
      setEditingPrinter(printer); 
      setFormData({ ...printer });
    } else {
      setEditingPrinter(null);
      setFormData({ brand: config.brands[0] || '', model: config.models[0] || '', status: 'ACTIVE', connectionType: 'USB' });
    }
    setIsFormModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingPrinter?.id) {
       await StorageService.updatePrinter({ ...editingPrinter, ...formData } as PrinterType);
    } else {
       await StorageService.addPrinter({ id: '', lastTonerDate: new Date().toISOString(), ...formData as PrinterType });
    }
    window.history.back();
    loadData();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.4)]';
      case 'MAINTENANCE': return 'bg-orange-500';
      case 'BROKEN': return 'bg-red-500';
      default: return 'bg-zinc-500';
    }
  };

  const filteredPrinters = printers.filter(p => {
    const s = searchTerm.toLocaleLowerCase('tr-TR');
    return (
        p.model.toLocaleLowerCase('tr-TR').includes(s) || 
        p.location.toLocaleLowerCase('tr-TR').includes(s) || 
        p.shortCode?.includes(s) || 
        p.serialNumber.toLowerCase().includes(s)
    );
  }).sort((a, b) => {
    const nameA = a.location.toLocaleLowerCase('tr-TR');
    const nameB = b.location.toLocaleLowerCase('tr-TR');
    if (sortBy === 'AZ') return nameA.localeCompare(nameB);
    return nameB.localeCompare(nameA);
  });

  const getModelImage = (model: string) => {
    return config.modelImages?.[model] || null;
  };

  const calculateTotalCost = (services: ServiceRecord[]) => {
      return services.reduce((acc, curr) => acc + (curr.cost || 0), 0);
  };

  return (
    <div className="space-y-8 pb-32">
      {/* Header Panel */}
      <div className="bg-zinc-900/40 p-10 rounded-[3rem] border border-zinc-800 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden shadow-2xl">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-6">
            <div className="p-5 bg-emerald-500/10 text-emerald-500 rounded-3xl"><PrinterIcon size={40} /></div>
            <div className="text-center md:text-left">
                <h2 className="text-4xl font-black text-white tracking-tighter uppercase">CİHAZ HAVUZU</h2>
                <p className="text-xs font-bold text-zinc-500 mt-1 uppercase tracking-widest">{printers.length} Kayıtlı Cihaz Analizi</p>
            </div>
        </div>
        <div className="flex gap-4 relative z-10">
            <button onClick={() => setSortBy(sortBy === 'AZ' ? 'ZA' : 'AZ')} className="p-5 bg-zinc-800 text-zinc-400 rounded-3xl hover:text-emerald-500 transition-all flex items-center gap-2 font-black text-[10px] uppercase tracking-widest">
                {sortBy === 'AZ' ? <SortAsc size={24} /> : <SortDesc size={24} />} {sortBy === 'AZ' ? 'A-Z' : 'Z-A'}
            </button>
            <button onClick={(e) => openFormModal(e)} className="bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] flex items-center justify-center gap-3 font-black shadow-xl shadow-emerald-500/20 transition-all active:scale-95 uppercase text-xs tracking-widest">
                <Plus size={24} /> YENİ CİHAZ
            </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative group">
        <div className="absolute inset-y-0 left-0 pl-8 flex items-center pointer-events-none text-zinc-600 group-focus-within:text-emerald-500 transition-colors"><Search size={24} /></div>
        <input type="text" placeholder="Cihaz ara (Model, Lokasyon, Hızlı Kod...)" className="w-full pl-20 pr-10 py-7 rounded-[2.5rem] bg-zinc-900/60 border border-zinc-800 text-white shadow-xl focus:border-emerald-500 outline-none transition-all font-bold text-lg placeholder:text-zinc-600" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredPrinters.map(printer => (
          <div 
            key={printer.id} 
            onClick={() => handleOpenDetail(printer)}
            className="group rounded-[3.5rem] bg-[#0a0a0a] border border-zinc-900 p-1 transition-all duration-500 hover:border-emerald-500/40 hover:-translate-y-2 cursor-pointer shadow-2xl flex flex-col"
          >
            <div className="p-8 flex-1">
                {/* Card Top: Status & Location */}
                <div className="flex justify-between items-start mb-6">
                    <div className="flex items-start gap-4">
                        <div className={`mt-2 w-3 h-3 rounded-full ${getStatusBadge(printer.status)}`}></div>
                        <div>
                            <div className="flex items-center gap-2 text-emerald-500 font-black text-[10px] uppercase tracking-widest mb-1">
                                <MapPin size={12}/> {printer.location}
                            </div>
                            <div className="text-[9px] text-zinc-600 font-bold uppercase tracking-widest">{printer.floor || 'KONTROL EDİLMEDİ'}</div>
                        </div>
                    </div>
                    <button className="p-3 bg-zinc-900 rounded-2xl text-zinc-500 hover:text-white transition-all"><QrCode size={18}/></button>
                </div>

                {/* Card Center: Model & Image */}
                <div className="flex justify-between items-center gap-4 mb-10">
                    <div className="flex-1">
                        <h3 className="text-3xl font-black text-white leading-none tracking-tighter uppercase mb-4">{printer.brand} {printer.model}</h3>
                        <div className="flex flex-wrap gap-2">
                            <span className="bg-emerald-500/10 text-emerald-500 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-emerald-500/20">#{printer.shortCode}</span>
                            {printer.connectionType === 'Network' ? (
                                <span className="bg-blue-500/10 text-blue-400 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-blue-500/20 flex items-center gap-1.5"><Wifi size={12}/> {printer.ipAddress}</span>
                            ) : (
                                <span className="bg-zinc-800 text-zinc-500 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-zinc-700 flex items-center gap-1.5"><Usb size={12}/> USB</span>
                            )}
                        </div>
                    </div>
                    {getModelImage(printer.model) && (
                        <div className="w-24 h-24 bg-zinc-900/50 rounded-3xl p-3 border border-zinc-800 group-hover:scale-110 transition-transform duration-500">
                            <img src={getModelImage(printer.model)!} className="w-full h-full object-contain" alt={printer.model} />
                        </div>
                    )}
                </div>

                {/* Card Bottom: Counter */}
                <div className="pt-8 border-t border-zinc-900 flex justify-between items-end">
                    <div className="space-y-1">
                        <p className="text-[9px] font-black text-zinc-600 uppercase tracking-widest">GÜNCEL SAYAÇ</p>
                        <p className="text-3xl font-mono font-black text-white">{printer.lastCounter.toLocaleString('tr-TR')}</p>
                    </div>
                    <button className="bg-emerald-500/10 text-emerald-500 p-4 rounded-2xl group-hover:bg-emerald-500 group-hover:text-white transition-all duration-300">
                        <TrendingUp size={24} strokeWidth={2.5}/>
                    </button>
                </div>
            </div>

            {/* Hover Actions */}
            <div className="grid grid-cols-2 border-t border-zinc-900 bg-zinc-950 rounded-b-[3.5rem] overflow-hidden">
                <button onClick={(e) => openFormModal(e, printer)} className="py-6 font-black text-[10px] text-zinc-500 hover:text-white hover:bg-zinc-900 transition-all uppercase tracking-widest flex items-center justify-center gap-2"><Edit2 size={14}/> DÜZENLE</button>
                <button onClick={(e) => { e.stopPropagation(); if(confirm('Silsin mi?')) StorageService.deletePrinter(printer.id).then(() => loadData()); }} className="py-6 font-black text-[10px] text-zinc-700 hover:text-white hover:bg-red-600 transition-all uppercase tracking-widest flex items-center justify-center gap-2"><Trash2 size={14}/> SİL</button>
            </div>
          </div>
        ))}
      </div>

      {/* SAĞ PANEL DETAY DRAWER (Screenshot 2 Uyumu) */}
      {selectedPrinter && (
          <div className="fixed inset-0 z-[500] flex justify-end">
              <div className="absolute inset-0 bg-black/90 backdrop-blur-xl animate-in fade-in duration-500" onClick={() => window.history.back()}></div>
              <div className="relative w-full max-w-xl bg-black h-full shadow-2xl border-l border-zinc-900 animate-in slide-in-from-right duration-500 flex flex-col overflow-hidden">

                  {/* Header */}
                  <div className="p-10 flex justify-between items-center bg-zinc-950/50">
                      <div className="flex flex-col">
                          <div className="flex items-center gap-3 mb-2">
                             <span className="bg-emerald-500/10 text-emerald-500 px-3 py-1 rounded-lg text-[10px] font-black tracking-widest">#{selectedPrinter.shortCode}</span>
                             <span className="text-[10px] text-zinc-600 font-bold font-mono">{selectedPrinter.serialNumber}</span>
                          </div>
                          <h3 className="text-4xl font-black text-white tracking-tighter uppercase leading-none">{selectedPrinter.brand} {selectedPrinter.model}</h3>
                          <div className="flex gap-4 mt-6">
                              <span className="flex items-center gap-2 bg-emerald-600/10 text-emerald-400 px-4 py-2 rounded-2xl text-[10px] font-black uppercase border border-emerald-500/20"><MapPin size={12}/> {selectedPrinter.location} ({selectedPrinter.floor})</span>
                              <span className="flex items-center gap-2 bg-blue-600/10 text-blue-400 px-4 py-2 rounded-2xl text-[10px] font-black uppercase border border-blue-500/20"><Globe size={12}/> {selectedPrinter.ipAddress || 'USB'}</span>
                          </div>
                      </div>
                      <button onClick={() => window.history.back()} className="p-5 bg-zinc-900 text-white rounded-3xl hover:bg-zinc-800 transition-all"><X size={32}/></button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-10 space-y-12 custom-scrollbar">

                      {/* Üst 3'lü Analiz Kartları */}
                      <div className="grid grid-cols-3 gap-4">
                          <div className="bg-zinc-900/40 p-6 rounded-[2rem] border border-zinc-800 space-y-3">
                              <p className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">TOPLAM ENDEKS</p>
                              <p className="text-3xl font-black text-white font-mono leading-none">{selectedPrinter.lastCounter.toLocaleString('tr-TR')}</p>
                          </div>
                          <div className="bg-zinc-900/40 p-6 rounded-[2rem] border border-zinc-800 space-y-3">
                              <p className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">SİSTEM MALİYETİ</p>
                              <p className="text-3xl font-black text-emerald-500 font-mono leading-none">{calculateTotalCost(printerServices).toLocaleString('tr-TR')} ₺</p>
                          </div>
                          <div className="bg-zinc-900/40 p-6 rounded-[2rem] border border-zinc-800 space-y-3">
                              <p className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">TONER DEĞİŞİMİ</p>
                              <p className="text-3xl font-black text-orange-500 font-mono leading-none">{printerTonerLogs.length}</p>
                          </div>
                      </div>

                      {/* Toner Arşivi */}
                      <div className="space-y-6">
                          <h4 className="flex items-center gap-3 text-white font-black text-lg uppercase tracking-tighter">
                              <Droplet size={24} className="text-orange-500"/> TONER ARŞİVİ
                          </h4>
                          <div className="space-y-4">
                              {printerTonerLogs.length > 0 ? (
                                  printerTonerLogs.map(log => (
                                      <div key={log.id} className="bg-zinc-900/40 p-6 rounded-[2.5rem] border border-zinc-800 flex items-center justify-between">
                                          <div className="flex items-center gap-6">
                                              <div className="p-4 bg-orange-500/10 text-orange-500 rounded-2xl"><Droplet size={24}/></div>
                                              <div>
                                                  <p className="text-xl font-black text-white">{log.tonerModel}</p>
                                                  <div className="flex gap-4 mt-1">
                                                      <span className="text-[10px] text-zinc-500 font-bold uppercase flex items-center gap-1.5"><Calendar size={12}/> {new Date(log.date).toLocaleDateString('tr-TR')}</span>
                                                      <span className="text-[10px] text-zinc-500 font-bold uppercase flex items-center gap-1.5"><UserIcon size={12}/> {log.user.split(' ')[0]}</span>
                                                  </div>
                                              </div>
                                          </div>
                                          <span className="text-[9px] font-black text-zinc-400 bg-zinc-800 px-4 py-1.5 rounded-full tracking-widest uppercase">STOKTAN</span>
                                      </div>
                                  ))
                              ) : (
                                  <div className="p-10 border-2 border-dashed border-zinc-800 rounded-[2.5rem] text-center text-zinc-600 font-bold uppercase text-xs tracking-widest">Henüz toner kaydı bulunamadı.</div>
                              )}
                          </div>
                      </div>

                      {/* Teknik Kayıtlar */}
                      <div className="space-y-6">
                          <h4 className="flex items-center gap-3 text-white font-black text-lg uppercase tracking-tighter">
                              <Wrench size={24} className="text-blue-500"/> TEKNİK KAYITLAR
                          </h4>
                          {printerServices.length > 0 ? (
                              <div className="space-y-4">
                                  {printerServices.map(service => (
                                      <div key={service.id} className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-zinc-800 space-y-4">
                                          <div className="flex justify-between items-start">
                                              <p className="text-sm font-black text-white leading-relaxed">{service.issue}</p>
                                              <span className="text-[10px] font-bold text-zinc-600 uppercase">{new Date(service.date).toLocaleDateString('tr-TR')}</span>
                                          </div>
                                          <div className="p-4 bg-zinc-950/50 rounded-2xl text-xs text-zinc-400 leading-relaxed italic">{service.actionTaken}</div>
                                      </div>
                                  ))}
                              </div>
                          ) : (
                               <div className="bg-zinc-900/40 p-12 rounded-[2.5rem] border border-zinc-800 text-center text-zinc-500 font-bold text-xs uppercase tracking-widest">Cihaza ait servis kaydı yok.</div>
                          )}
                      </div>

                      {/* Endeks Analizi (Tablo Görünümü) */}
                      <div className="space-y-6">
                          <h4 className="flex items-center gap-3 text-white font-black text-lg uppercase tracking-tighter">
                              <Calculator size={24} className="text-emerald-500"/> ENDEKS ANALİZİ
                          </h4>
                          <div className="bg-zinc-900/40 rounded-[2.5rem] border border-zinc-800 overflow-hidden">
                              <table className="w-full text-left border-collapse">
                                  <thead className="bg-zinc-950/50 border-b border-zinc-800">
                                      <tr>
                                          <th className="p-6 text-[10px] font-black text-zinc-500 uppercase tracking-widest">TARİH</th>
                                          <th className="p-6 text-[10px] font-black text-zinc-500 uppercase tracking-widest text-center">SAYAÇ</th>
                                          <th className="p-6 text-[10px] font-black text-zinc-500 uppercase tracking-widest text-right">FARK</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-zinc-800">
                                      {printerCounters.slice(0, 10).map(log => (
                                          <tr key={log.id} className="hover:bg-zinc-800/20 transition-colors">
                                              <td className="p-6 text-xs text-zinc-400 font-bold">{new Date(log.date).toLocaleDateString('tr-TR')}</td>
                                              <td className="p-6 text-base text-white font-black font-mono text-center">{log.currentCounter.toLocaleString('tr-TR')}</td>
                                              <td className="p-6 text-base text-emerald-500 font-black font-mono text-right">+{log.usage.toLocaleString('tr-TR')}</td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      </div>

                  </div>

                  {/* Panel Footer */}
                  <div className="p-10 bg-zinc-950 border-t border-zinc-900 grid grid-cols-2 gap-4">
                      <button onClick={(e) => openFormModal(e, selectedPrinter)} className="py-6 bg-zinc-900 text-white rounded-[2rem] font-black uppercase text-xs tracking-widest transition-all active:scale-95">DÜZENLE</button>
                      <button onClick={() => window.history.back()} className="py-6 bg-white text-black rounded-[2rem] font-black uppercase text-xs tracking-widest transition-all active:scale-95">KAPAT</button>
                  </div>
              </div>
          </div>
      )}

      {/* Kayıt Modalı */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl z-[600] flex items-center justify-center p-6 animate-in fade-in duration-500">
          <div className="bg-zinc-950 rounded-[4rem] w-full max-w-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-500 border border-zinc-800 flex flex-col max-h-[90vh]">
            <div className="p-10 border-b border-zinc-900 flex justify-between items-center">
              <h3 className="font-black text-3xl text-white tracking-tighter uppercase">{editingPrinter ? 'CİHAZ GÜNCELLE' : 'YENİ CİHAZ EKLE'}</h3>
              <button onClick={() => window.history.back()} className="p-4 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all"><X size={32} strokeWidth={3} /></button>
            </div>
            <form onSubmit={handleSave} className="p-10 space-y-6 overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-2">Marka</label>
                  <select required className="w-full p-5 border border-zinc-800 rounded-3xl bg-zinc-900 text-white font-bold outline-none focus:border-emerald-500" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})}>
                    {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-2">Model</label>
                  <select required className="w-full p-5 border border-zinc-800 rounded-3xl bg-zinc-900 text-white font-bold outline-none focus:border-emerald-500" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})}>
                    {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-2">Seri Numarası</label>
                  <input required type="text" className="w-full p-5 border border-zinc-800 rounded-3xl bg-zinc-900 text-white font-bold outline-none focus:border-emerald-500" value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-2">Lokasyon</label>
                  <input required type="text" className="w-full p-5 border border-zinc-800 rounded-3xl bg-zinc-900 text-white font-bold outline-none focus:border-emerald-500" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-2">Kat / Bölüm</label>
                    <input type="text" className="w-full p-5 border border-zinc-800 rounded-3xl bg-zinc-900 text-white font-bold outline-none focus:border-emerald-500" placeholder="Örn: 2. Kat" value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-2">Bağlantı Tipi</label>
                    <select className="w-full p-5 border border-zinc-800 rounded-3xl bg-zinc-900 text-white font-bold outline-none focus:border-emerald-500" value={formData.connectionType} onChange={e => setFormData({...formData, connectionType: e.target.value as any})}>
                      <option value="USB">USB</option>
                      <option value="Network">Network (Ağ)</option>
                    </select>
                  </div>
              </div>

              <button type="submit" className="w-full py-8 bg-emerald-600 text-white rounded-[2.5rem] font-black shadow-xl transition-all active:scale-95 uppercase tracking-widest text-sm">SİSTEME KAYDET</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, MapPin, Hash, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, QrCode, Download, RefreshCw, Calendar, Calculator, Wrench, Droplet, Globe, Activity, ChevronRight, TrendingUp, Clock, User as UserIcon, FileText, Settings, AlertCircle, Info, SortAsc, SortDesc, TrendingDown, MoreVertical } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, PrinterStatus, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState<'AZ' | 'ZA'>('AZ');
  const [loading, setLoading] = useState(true);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);

  const [selectedPrinter, setSelectedPrinter] = useState<PrinterType | null>(null);
  const [printerServices, setPrinterServices] = useState<ServiceRecord[]>([]);
  const [printerCounters, setPrinterCounters] = useState<CounterLog[]>([]);
  const [printerTonerLogs, setPrinterTonerLogs] = useState<StockLog[]>([]);

  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '', model: '', serialNumber: '', shortCode: '', location: '', floor: '',
    lastCounter: 0, connectionType: 'USB', ipAddress: '', status: 'ACTIVE'
  });

  useEffect(() => { loadData(); }, []);

  // ESC TUŞU İLE GERİ DÖNME FONKSİYONU
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (isFormModalOpen || selectedPrinter) {
          window.history.back();
        }
      }
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isFormModalOpen, selectedPrinter]);

  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const p = printers.find(x => x.id === targetPrinterId);
      if (p) handleOpenDetail(p);
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  useEffect(() => {
    const handlePopState = () => {
      setIsFormModalOpen(false);
      setSelectedPrinter(null);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([StorageService.getPrinters(), StorageService.getConfig()]);
    setPrinters(p);
    setConfig(c);
    setLoading(false);
  };

  const handleOpenDetail = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'detail' }, '');
    setSelectedPrinter(printer);
    const [services, counters, logs] = await Promise.all([
      StorageService.getServiceRecords(),
      StorageService.getCounterLogs(),
      StorageService.getLogs()
    ]);
    setPrinterServices(services.filter(s => s.printerId === printer.id));
    setPrinterCounters(counters.filter(c => c.printerId === printer.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    setPrinterTonerLogs(logs.filter(l => l.printerId === printer.id && l.type === 'OUT'));
  };

  const openFormModal = (e: React.MouseEvent, printer?: PrinterType) => {
    e.stopPropagation();
    window.history.pushState({ modal: 'form' }, '');
    if (printer) {
      setEditingPrinter(printer); 
      setFormData({ ...printer });
    } else {
      setEditingPrinter(null);
      setFormData({ brand: config.brands[0] || '', model: config.models[0] || '', status: 'ACTIVE', connectionType: 'USB' });
    }
    setIsFormModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingPrinter?.id) {
       await StorageService.updatePrinter({ ...editingPrinter, ...formData } as PrinterType);
    } else {
       await StorageService.addPrinter({ id: '', lastTonerDate: new Date().toISOString(), ...formData as PrinterType });
    }
    window.history.back();
    loadData();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]';
      case 'MAINTENANCE': return 'bg-orange-500';
      case 'BROKEN': return 'bg-red-500';
      default: return 'bg-zinc-500';
    }
  };

  const filteredPrinters = printers.filter(p => {
    const s = searchTerm.toLocaleLowerCase('tr-TR');
    return (p.model.toLocaleLowerCase('tr-TR').includes(s) || p.location.toLocaleLowerCase('tr-TR').includes(s) || p.shortCode?.includes(s));
  }).sort((a, b) => {
    const nameA = a.location.toLocaleLowerCase('tr-TR');
    const nameB = b.location.toLocaleLowerCase('tr-TR');
    if (sortBy === 'AZ') return nameA.localeCompare(nameB);
    return nameB.localeCompare(nameA);
  });

  const getModelImage = (model: string) => config.modelImages?.[model] || null;
  const calculateTotalCost = (services: ServiceRecord[]) => services.reduce((acc, curr) => acc + (curr.cost || 0), 0);

  if (loading && printers.length === 0) return <LoadingScreen message="Antrasit ekosistem yükleniyor..." />;

  return (
    <div className="space-y-8 pb-32 anthracite-gradient min-h-full">
      {/* Premium Header */}
      <div className="bg-zinc-900/60 backdrop-blur-3xl p-10 rounded-[4rem] border border-white/5 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 left-0 w-96 h-96 bg-emerald-500/5 blur-[120px] -ml-48 -mt-48"></div>
        <div className="relative z-10 flex items-center gap-6">
            <div className="p-5 bg-emerald-500/10 text-emerald-500 rounded-3xl border border-emerald-500/20"><PrinterIcon size={40} strokeWidth={2.5}/></div>
            <div>
                <h2 className="text-4xl font-black text-white tracking-tighter uppercase leading-none">CİHAZ HAVUZU</h2>
                <p className="text-[10px] font-black text-emerald-500/60 mt-2 uppercase tracking-[0.4em]">{printers.length} Kayıtlı Aktif Ünite</p>
            </div>
        </div>
        <div className="flex gap-4 relative z-10 w-full md:w-auto">
            <button onClick={() => setSortBy(sortBy === 'AZ' ? 'ZA' : 'AZ')} className="flex-1 md:flex-none p-5 bg-white/5 hover:bg-white/10 text-zinc-400 rounded-[2rem] border border-white/5 transition-all flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest">
                {sortBy === 'AZ' ? <SortAsc size={24} /> : <SortDesc size={24} />} {sortBy === 'AZ' ? 'A-Z' : 'Z-A'}
            </button>
            <button onClick={(e) => openFormModal(e)} className="flex-[2] md:flex-none bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] flex items-center justify-center gap-3 font-black shadow-2xl shadow-emerald-600/20 transition-all active:scale-95 uppercase text-xs tracking-[0.2em]">
                <Plus size={24} /> YENİ CİHAZ
            </button>
        </div>
      </div>

      {/* Search Bar - Modern Style */}
      <div className="relative group mx-4 md:mx-0">
        <div className="absolute inset-y-0 left-8 flex items-center pointer-events-none text-zinc-600 group-focus-within:text-emerald-500 transition-colors"><Search size={28} /></div>
        <input type="text" placeholder="Hangi cihazı arıyorsunuz?" className="w-full pl-24 pr-10 py-8 rounded-[3rem] bg-zinc-900/40 backdrop-blur-md border border-white/5 text-white shadow-2xl focus:border-emerald-500/50 outline-none transition-all font-black text-xl placeholder:text-zinc-700" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      </div>

      {/* Grid - Antrasit Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 px-4 md:px-0">
        {filteredPrinters.map(printer => (
          <div 
            key={printer.id} 
            onClick={() => handleOpenDetail(printer)}
            className="group rounded-[4rem] bg-[#121214] border border-white/5 p-1 transition-all duration-700 hover:border-emerald-500/30 hover:-translate-y-3 cursor-pointer shadow-[0_30px_60px_-12px_rgba(0,0,0,0.5)] flex flex-col relative"
          >
            <div className="p-10 flex-1">
                <div className="flex justify-between items-start mb-8">
                    <div className="flex items-start gap-4">
                        <div className={`mt-2 w-3.5 h-3.5 rounded-full ${getStatusBadge(printer.status)} border-2 border-white/10`}></div>
                        <div>
                            <div className="flex items-center gap-2 text-emerald-500 font-black text-[11px] uppercase tracking-[0.3em] mb-1">
                                <MapPin size={14}/> {printer.location}
                            </div>
                            <div className="text-[9px] text-zinc-600 font-black uppercase tracking-widest">{printer.floor || 'BÖLÜM BELİRTİLMEDİ'}</div>
                        </div>
                    </div>
                    <button className="p-4 bg-white/5 rounded-2xl text-zinc-600 hover:text-emerald-500 transition-all"><QrCode size={20}/></button>
                </div>

                <div className="flex justify-between items-center gap-6 mb-12">
                    <div className="flex-1">
                        <h3 className="text-3xl font-black text-white leading-none tracking-tighter uppercase mb-6 group-hover:text-emerald-500 transition-colors">{printer.brand} {printer.model}</h3>
                        <div className="flex flex-wrap gap-3">
                            <span className="bg-emerald-500/10 text-emerald-500 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-emerald-500/20 shadow-lg shadow-emerald-500/5">#{printer.shortCode}</span>
                            {printer.connectionType === 'Network' ? (
                                <span className="bg-blue-500/10 text-blue-400 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-blue-500/20 flex items-center gap-2"><Wifi size={14}/> {printer.ipAddress}</span>
                            ) : (
                                <span className="bg-zinc-800/50 text-zinc-500 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-white/5 flex items-center gap-2"><Usb size={14}/> USB</span>
                            )}
                        </div>
                    </div>
                    {getModelImage(printer.model) && (
                        <div className="w-28 h-28 bg-zinc-800/30 rounded-[2.5rem] p-4 border border-white/5 group-hover:scale-110 transition-transform duration-700 shadow-2xl flex items-center justify-center">
                            <img src={getModelImage(printer.model)!} className="w-full h-full object-contain filter drop-shadow-2xl" alt={printer.model} />
                        </div>
                    )}
                </div>

                <div className="pt-8 border-t border-white/5 flex justify-between items-end">
                    <div className="space-y-1">
                        <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.4em]">GÜNCEL SAYAÇ</p>
                        <p className="text-4xl font-mono font-black text-white leading-none">{printer.lastCounter.toLocaleString('tr-TR')}</p>
                    </div>
                    <button className="bg-emerald-500/10 text-emerald-500 p-5 rounded-[1.5rem] group-hover:bg-emerald-600 group-hover:text-white transition-all duration-500 shadow-xl shadow-emerald-500/10">
                        <TrendingUp size={28} strokeWidth={3}/>
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-2 border-t border-white/5 bg-zinc-950/40 rounded-b-[4rem] overflow-hidden backdrop-blur-md">
                <button onClick={(e) => openFormModal(e, printer)} className="py-7 font-black text-[11px] text-zinc-600 hover:text-white hover:bg-emerald-600/10 transition-all uppercase tracking-[0.3em] flex items-center justify-center gap-3"><Edit2 size={16}/> DÜZENLE</button>
                <button onClick={(e) => { e.stopPropagation(); if(confirm('Silsin mi?')) StorageService.deletePrinter(printer.id).then(() => loadData()); }} className="py-7 font-black text-[11px] text-zinc-800 hover:text-white hover:bg-red-600 transition-all uppercase tracking-[0.3em] flex items-center justify-center gap-3 border-l border-white/5"><Trash2 size={16}/> SİL</button>
            </div>
          </div>
        ))}
      </div>

      {/* ANALİZ DRAWER - ANTRASİT REVİZYON */}
      {selectedPrinter && (
          <div className="fixed inset-0 z-[500] flex justify-end">
              <div className="absolute inset-0 bg-black/95 backdrop-blur-xl animate-in fade-in duration-500" onClick={() => window.history.back()}></div>
              <div className="relative w-full max-w-2xl bg-[#09090b] h-full shadow-[0_0_100px_rgba(0,0,0,1)] border-l border-white/5 animate-in slide-in-from-right duration-700 flex flex-col overflow-hidden">

                  {/* Header */}
                  <div className="p-12 flex justify-between items-center bg-zinc-950/50 border-b border-white/5">
                      <div className="flex flex-col">
                          <div className="flex items-center gap-4 mb-3">
                             <span className="bg-emerald-500/10 text-emerald-500 px-4 py-1.5 rounded-xl text-[11px] font-black tracking-[0.3em] border border-emerald-500/20 uppercase">#{selectedPrinter.shortCode}</span>
                             <span className="text-[11px] text-zinc-600 font-black font-mono tracking-widest">{selectedPrinter.serialNumber}</span>
                          </div>
                          <h3 className="text-5xl font-black text-white tracking-tighter uppercase leading-none">{selectedPrinter.brand} {selectedPrinter.model}</h3>
                      </div>
                      <button onClick={() => window.history.back()} className="p-6 bg-zinc-900 text-white rounded-[2rem] hover:bg-red-600 transition-all shadow-2xl active:scale-90"><X size={36} strokeWidth={3}/></button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-12 space-y-16 custom-scrollbar">
                      {/* Üst 3'lü Analiz Kartları */}
                      <div className="grid grid-cols-3 gap-6">
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">TOPLAM ENDEKS</p>
                              <p className="text-4xl font-black text-white font-mono leading-none">{selectedPrinter.lastCounter.toLocaleString('tr-TR')}</p>
                          </div>
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">SİSTEM MALİYETİ</p>
                              <p className="text-4xl font-black text-emerald-500 font-mono leading-none">{calculateTotalCost(printerServices).toLocaleString('tr-TR')} ₺</p>
                          </div>
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">TONER DEĞİŞİMİ</p>
                              <p className="text-4xl font-black text-orange-500 font-mono leading-none">{printerTonerLogs.length}</p>
                          </div>
                      </div>

                      {/* Toner Arşivi */}
                      <div className="space-y-8">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter">
                              <Droplet size={28} className="text-orange-500"/> TONER ARŞİVİ
                          </h4>
                          <div className="space-y-4">
                              {printerTonerLogs.length > 0 ? (
                                  printerTonerLogs.map(log => (
                                      <div key={log.id} className="bg-zinc-900/40 p-8 rounded-[3rem] border border-white/5 flex items-center justify-between group/row hover:bg-white/5 transition-all">
                                          <div className="flex items-center gap-8">
                                              <div className="p-5 bg-orange-500/10 text-orange-500 rounded-2xl border border-orange-500/20"><Droplet size={28}/></div>
                                              <div>
                                                  <p className="text-2xl font-black text-white uppercase">{log.tonerModel}</p>
                                                  <div className="flex gap-6 mt-2">
                                                      <span className="text-[10px] text-zinc-600 font-black uppercase flex items-center gap-2"><Calendar size={14}/> {new Date(log.date).toLocaleDateString('tr-TR')}</span>
                                                      <span className="text-[10px] text-zinc-600 font-black uppercase flex items-center gap-2"><UserIcon size={14}/> {log.user.split(' ')[0]}</span>
                                                  </div>
                                              </div>
                                          </div>
                                          <span className="text-[10px] font-black text-zinc-500 bg-zinc-800 px-5 py-2 rounded-full tracking-[0.2em] uppercase">STOKTAN</span>
                                      </div>
                                  ))
                              ) : (
                                  <div className="p-16 border-2 border-dashed border-white/5 rounded-[3rem] text-center text-zinc-700 font-black uppercase text-xs tracking-widest">Henüz kayıt yok.</div>
                              )}
                          </div>
                      </div>

                      {/* Teknik Kayıtlar */}
                      <div className="space-y-8">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter">
                              <Wrench size={28} className="text-blue-500"/> TEKNİK KAYITLAR
                          </h4>
                          {printerServices.length > 0 ? (
                              <div className="space-y-6">
                                  {printerServices.map(service => (
                                      <div key={service.id} className="bg-zinc-900/40 p-10 rounded-[3rem] border border-white/5 space-y-6 shadow-2xl">
                                          <div className="flex justify-between items-start">
                                              <p className="text-lg font-black text-white leading-relaxed">{service.issue}</p>
                                              <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">{new Date(service.date).toLocaleDateString('tr-TR')}</span>
                                          </div>
                                          <div className="p-6 bg-zinc-950 rounded-2xl text-xs text-zinc-500 leading-relaxed font-bold border border-white/5 italic">"{service.actionTaken}"</div>
                                      </div>
                                  ))}
                              </div>
                          ) : (
                               <div className="bg-zinc-900/40 p-16 rounded-[3rem] border border-white/5 text-center text-zinc-700 font-black text-xs uppercase tracking-widest">Servis kaydı yok.</div>
                          )}
                      </div>

                      {/* Endeks Analizi */}
                      <div className="space-y-8 pb-10">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter">
                              <Calculator size={28} className="text-emerald-500"/> ENDEKS ANALİZİ
                          </h4>
                          <div className="bg-zinc-900/20 rounded-[3rem] border border-white/5 overflow-hidden shadow-2xl">
                              <table className="w-full text-left border-collapse">
                                  <thead className="bg-zinc-950/80 border-b border-white/5">
                                      <tr>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em]">TARİH</th>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] text-center">SAYAÇ</th>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] text-right">FARK</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-white/5">
                                      {printerCounters.slice(0, 10).map(log => (
                                          <tr key={log.id} className="hover:bg-white/5 transition-colors">
                                              <td className="p-8 text-xs text-zinc-500 font-black uppercase tracking-widest">{new Date(log.date).toLocaleDateString('tr-TR')}</td>
                                              <td className="p-8 text-xl text-white font-black font-mono text-center">{log.currentCounter.toLocaleString('tr-TR')}</td>
                                              <td className="p-8 text-xl text-emerald-500 font-black font-mono text-right">+{log.usage.toLocaleString('tr-TR')}</td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      </div>
                  </div>

                  {/* Panel Footer */}
                  <div className="p-12 bg-zinc-950 border-t border-white/5 grid grid-cols-2 gap-6">
                      <button onClick={(e) => openFormModal(e, selectedPrinter)} className="py-8 bg-zinc-900 hover:bg-zinc-800 text-white rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] transition-all active:scale-95 border border-white/5">CİHAZI DÜZENLE</button>
                      <button onClick={() => window.history.back()} className="py-8 bg-white text-black rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] transition-all active:scale-95 shadow-2xl">PANELİ KAPAT</button>
                  </div>
              </div>
          </div>
      )}

      {/* Form Modal - Antrasit Tasarım */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/98 backdrop-blur-3xl z-[600] flex items-center justify-center p-6 animate-in fade-in duration-500">
          <div className="bg-[#09090b] rounded-[4rem] w-full max-w-2xl shadow-[0_40px_100px_rgba(0,0,0,1)] overflow-hidden animate-in zoom-in-95 duration-500 border border-white/5 flex flex-col max-h-[90vh]">
            <div className="p-10 border-b border-white/5 flex justify-between items-center bg-zinc-950/50">
              <h3 className="font-black text-4xl text-white tracking-tighter uppercase leading-none">{editingPrinter ? 'CİHAZ GÜNCELLE' : 'YENİ ÜNİTE EKLE'}</h3>
              <button onClick={() => window.history.back()} className="p-5 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all active:scale-90"><X size={32} strokeWidth={3} /></button>
            </div>
            <form onSubmit={handleSave} className="p-12 space-y-8 overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">MARKA</label>
                  <select required className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})}>
                    {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                  </select>
                </div>
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">MODEL</label>
                  <select required className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})}>
                    {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">SERİ NUMARASI</label>
                  <input required type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} />
                </div>
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">LOKASYON</label>
                  <input required type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">KAT / BÖLÜM</label>
                    <input type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" placeholder="2. KAT" value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">BAĞLANTI</label>
                    <select className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.connectionType} onChange={e => setFormData({...formData, connectionType: e.target.value as any})}>
                      <option value="USB">USB</option>
                      <option value="Network">NETWORK (IP)</option>
                    </select>
                  </div>
              </div>

              <button type="submit" className="w-full py-8 bg-emerald-600 hover:bg-emerald-500 text-white rounded-[2.5rem] font-black shadow-2xl transition-all active:scale-95 uppercase tracking-[0.4em] text-sm">ÜNİTEYİ SİSTEME KAYDET</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Search, MapPin, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, QrCode, RefreshCw, Calendar, Calculator, Wrench, Droplet, Globe, TrendingUp, User as UserIcon, SortAsc, SortDesc, Filter, Layers, LayoutGrid } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState<'AZ' | 'ZA'>('AZ');
  const [loading, setLoading] = useState(true);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);

  // Filtreleme State'leri
  const [selectedFloor, setSelectedFloor] = useState<string | null>(null);
  const [selectedModel, setSelectedModel] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);

  const [selectedPrinter, setSelectedPrinter] = useState<PrinterType | null>(null);
  const [printerServices, setPrinterServices] = useState<ServiceRecord[]>([]);
  const [printerCounters, setPrinterCounters] = useState<CounterLog[]>([]);
  const [printerTonerLogs, setPrinterTonerLogs] = useState<StockLog[]>([]);

  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '', model: '', serialNumber: '', shortCode: '', location: '', floor: '',
    lastCounter: 0, connectionType: 'USB', ipAddress: '', status: 'ACTIVE'
  });

  useEffect(() => { loadData(); }, []);

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (isFormModalOpen || selectedPrinter) {
          window.history.back();
        }
      }
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isFormModalOpen, selectedPrinter]);

  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const p = printers.find(x => x.id === targetPrinterId);
      if (p) handleOpenDetail(p);
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  useEffect(() => {
    const handlePopState = () => {
      setIsFormModalOpen(false);
      setSelectedPrinter(null);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([StorageService.getPrinters(), StorageService.getConfig()]);
    setPrinters(p);
    setConfig(c);
    setLoading(false);
  };

  // Dinamik filtre seçeneklerini hesapla
  const floorOptions = useMemo(() => {
    const floors = printers.map(p => p.floor).filter(Boolean);
    return Array.from(new Set(floors)).sort();
  }, [printers]);

  const modelOptions = useMemo(() => {
    const models = printers.map(p => p.model).filter(Boolean);
    return Array.from(new Set(models)).sort();
  }, [printers]);

  const handleOpenDetail = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'detail' }, '');
    setSelectedPrinter(printer);
    const [services, counters, logs] = await Promise.all([
      StorageService.getServiceRecords(),
      StorageService.getCounterLogs(),
      StorageService.getLogs()
    ]);
    setPrinterServices(services.filter(s => s.printerId === printer.id));
    setPrinterCounters(counters.filter(c => c.printerId === printer.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    setPrinterTonerLogs(logs.filter(l => l.printerId === printer.id && l.type === 'OUT'));
  };

  const openFormModal = (e: React.MouseEvent, printer?: PrinterType) => {
    e.stopPropagation();
    window.history.pushState({ modal: 'form' }, '');
    if (printer) {
      setEditingPrinter(printer); 
      setFormData({ ...printer });
    } else {
      setEditingPrinter(null);
      setFormData({ brand: config.brands[0] || '', model: config.models[0] || '', status: 'ACTIVE', connectionType: 'USB' });
    }
    setIsFormModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingPrinter?.id) {
       await StorageService.updatePrinter({ ...editingPrinter, ...formData } as PrinterType);
    } else {
       await StorageService.addPrinter({ id: '', lastTonerDate: new Date().toISOString(), ...formData as PrinterType });
    }
    window.history.back();
    loadData();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]';
      case 'MAINTENANCE': return 'bg-orange-500';
      case 'BROKEN': return 'bg-red-500';
      default: return 'bg-zinc-500';
    }
  };

  const filteredPrinters = printers.filter(p => {
    const s = searchTerm.toLocaleLowerCase('tr-TR');
    const matchesSearch = (
        p.model.toLocaleLowerCase('tr-TR').includes(s) || 
        p.location.toLocaleLowerCase('tr-TR').includes(s) || 
        p.shortCode?.includes(s) ||
        p.serialNumber.toLowerCase().includes(s)
    );
    const matchesFloor = !selectedFloor || p.floor === selectedFloor;
    const matchesModel = !selectedModel || p.model === selectedModel;

    return matchesSearch && matchesFloor && matchesModel;
  }).sort((a, b) => {
    const nameA = a.location.toLocaleLowerCase('tr-TR');
    const nameB = b.location.toLocaleLowerCase('tr-TR');
    if (sortBy === 'AZ') return nameA.localeCompare(nameB);
    return nameB.localeCompare(nameA);
  });

  const getModelImage = (model: string) => config.modelImages?.[model] || null;
  const calculateTotalCost = (services: ServiceRecord[]) => services.reduce((acc, curr) => acc + (curr.cost || 0), 0);

  if (loading && printers.length === 0) return <LoadingScreen message="Antrasit ekosistem yükleniyor..." />;

  return (
    <div className="space-y-8 pb-32 anthracite-gradient min-h-full">
      {/* Premium Header */}
      <div className="bg-zinc-900/60 backdrop-blur-3xl p-10 rounded-[4rem] border border-white/5 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 left-0 w-96 h-96 bg-emerald-500/5 blur-[120px] -ml-48 -mt-48"></div>
        <div className="relative z-10 flex items-center gap-6">
            <div className="p-5 bg-emerald-500/10 text-emerald-500 rounded-3xl border border-emerald-500/20 shadow-inner"><PrinterIcon size={40} strokeWidth={2.5}/></div>
            <div>
                <h2 className="text-4xl font-black text-white tracking-tighter uppercase leading-none">CİHAZ HAVUZU</h2>
                <p className="text-[10px] font-black text-emerald-500/60 mt-2 uppercase tracking-[0.4em]">{filteredPrinters.length} Eşleşen Ünite</p>
            </div>
        </div>
        <div className="flex gap-4 relative z-10 w-full md:w-auto">
            <button onClick={() => setShowFilters(!showFilters)} className={`flex-1 md:flex-none p-5 rounded-[2rem] border border-white/5 transition-all flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest ${showFilters || selectedFloor || selectedModel ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30 shadow-lg shadow-emerald-500/10' : 'bg-white/5 text-zinc-400 hover:bg-white/10'}`}>
                <Filter size={24} /> FİLTRELE
            </button>
            <button onClick={() => setSortBy(sortBy === 'AZ' ? 'ZA' : 'AZ')} className="flex-1 md:flex-none p-5 bg-white/5 hover:bg-white/10 text-zinc-400 rounded-[2rem] border border-white/5 transition-all flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest">
                {sortBy === 'AZ' ? <SortAsc size={24} /> : <SortDesc size={24} />} {sortBy === 'AZ' ? 'A-Z' : 'Z-A'}
            </button>
            <button onClick={(e) => openFormModal(e)} className="hidden md:flex bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] items-center justify-center gap-3 font-black shadow-2xl shadow-emerald-600/20 transition-all active:scale-95 uppercase text-xs tracking-[0.2em]">
                <Plus size={24} /> YENİ CİHAZ
            </button>
        </div>
      </div>

      {/* Gelişmiş Arama ve Filtreler */}
      <div className="space-y-6 mx-4 md:mx-0">
        <div className="relative group">
            <div className="absolute inset-y-0 left-8 flex items-center pointer-events-none text-zinc-600 group-focus-within:text-emerald-500 transition-colors"><Search size={28} /></div>
            <input 
                type="text" 
                placeholder="Model, Lokasyon veya Hızlı Kod ara..." 
                className="w-full pl-24 pr-10 py-8 rounded-[3rem] bg-zinc-900/40 backdrop-blur-md border border-white/5 text-white shadow-2xl focus:border-emerald-500/50 outline-none transition-all font-black text-xl placeholder:text-zinc-700" 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(e.target.value)} 
            />
            {(searchTerm || selectedFloor || selectedModel) && (
                <button 
                    onClick={() => { setSearchTerm(''); setSelectedFloor(null); setSelectedModel(null); }}
                    className="absolute inset-y-0 right-8 flex items-center text-zinc-600 hover:text-red-500 transition-colors"
                >
                    <X size={24} />
                </button>
            )}
        </div>

        {/* Filtre Panel (Dinamik Chips) */}
        {(showFilters || selectedFloor || selectedModel) && (
            <div className="animate-in slide-in-from-top-4 duration-500 space-y-4">
                <div className="bg-zinc-900/40 backdrop-blur-sm p-6 rounded-[2.5rem] border border-white/5 space-y-6">
                    {/* Kat Filtresi */}
                    <div>
                        <div className="flex items-center gap-3 text-zinc-500 mb-4 px-2">
                            <MapPin size={14} className="text-emerald-500" />
                            <span className="text-[10px] font-black uppercase tracking-widest">KAT SEÇİMİ</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            <button 
                                onClick={() => setSelectedFloor(null)}
                                className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${!selectedFloor ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white/5 text-zinc-500 hover:text-white'}`}
                            >
                                TÜMÜ
                            </button>
                            {floorOptions.map(floor => (
                                <button 
                                    key={floor}
                                    onClick={() => setSelectedFloor(selectedFloor === floor ? null : floor)}
                                    className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedFloor === floor ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white/5 text-zinc-500 hover:text-white'}`}
                                >
                                    {floor}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Model Filtresi */}
                    <div>
                        <div className="flex items-center gap-3 text-zinc-500 mb-4 px-2">
                            <LayoutGrid size={14} className="text-blue-500" />
                            <span className="text-[10px] font-black uppercase tracking-widest">MODEL SEÇİMİ</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            <button 
                                onClick={() => setSelectedModel(null)}
                                className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${!selectedModel ? 'bg-blue-600 text-white shadow-lg' : 'bg-white/5 text-zinc-500 hover:text-white'}`}
                            >
                                TÜMÜ
                            </button>
                            {modelOptions.map(model => (
                                <button 
                                    key={model}
                                    onClick={() => setSelectedModel(selectedModel === model ? null : model)}
                                    className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedModel === model ? 'bg-blue-600 text-white shadow-lg' : 'bg-white/5 text-zinc-500 hover:text-white'}`}
                                >
                                    {model}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Grid - Antrasit Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 px-4 md:px-0">
        {filteredPrinters.map(printer => (
          <div 
            key={printer.id} 
            onClick={() => handleOpenDetail(printer)}
            className="group rounded-[4rem] bg-[#121214] border border-white/5 p-1 transition-all duration-700 hover:border-emerald-500/30 hover:-translate-y-3 cursor-pointer shadow-[0_30px_60px_-12px_rgba(0,0,0,0.5)] flex flex-col relative"
          >
            <div className="p-10 flex-1">
                <div className="flex justify-between items-start mb-8">
                    <div className="flex items-start gap-4">
                        <div className={`mt-2 w-3.5 h-3.5 rounded-full ${getStatusBadge(printer.status)} border-2 border-white/10`}></div>
                        <div>
                            <div className="flex items-center gap-2 text-emerald-500 font-black text-[11px] uppercase tracking-[0.3em] mb-1">
                                <MapPin size={14}/> {printer.location}
                            </div>
                            <div className="text-[9px] text-zinc-600 font-black uppercase tracking-widest">{printer.floor || 'BÖLÜM BELİRTİLMEDİ'}</div>
                        </div>
                    </div>
                    <button className="p-4 bg-white/5 rounded-2xl text-zinc-600 hover:text-emerald-500 transition-all"><QrCode size={20}/></button>
                </div>

                <div className="flex justify-between items-center gap-6 mb-12">
                    <div className="flex-1">
                        <h3 className="text-3xl font-black text-white leading-none tracking-tighter uppercase mb-6 group-hover:text-emerald-500 transition-colors">{printer.brand} {printer.model}</h3>
                        <div className="flex flex-wrap gap-3">
                            <span className="bg-emerald-500/10 text-emerald-500 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-emerald-500/20 shadow-lg shadow-emerald-500/5">#{printer.shortCode}</span>
                            {printer.connectionType === 'Network' ? (
                                <span className="bg-blue-500/10 text-blue-400 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-blue-500/20 flex items-center gap-2"><Wifi size={14}/> {printer.ipAddress}</span>
                            ) : (
                                <span className="bg-zinc-800/50 text-zinc-500 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-white/5 flex items-center gap-2"><Usb size={14}/> USB</span>
                            )}
                        </div>
                    </div>
                    {getModelImage(printer.model) && (
                        <div className="w-28 h-28 bg-zinc-800/30 rounded-[2.5rem] p-4 border border-white/5 group-hover:scale-110 transition-transform duration-700 shadow-2xl flex items-center justify-center">
                            <img src={getModelImage(printer.model)!} className="w-full h-full object-contain filter drop-shadow-2xl" alt={printer.model} />
                        </div>
                    )}
                </div>

                <div className="pt-8 border-t border-white/5 flex justify-between items-end">
                    <div className="space-y-1">
                        <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.4em]">GÜNCEL SAYAÇ</p>
                        <p className="text-4xl font-mono font-black text-white leading-none">{printer.lastCounter.toLocaleString('tr-TR')}</p>
                    </div>
                    <button className="bg-emerald-500/10 text-emerald-500 p-5 rounded-[1.5rem] group-hover:bg-emerald-600 group-hover:text-white transition-all duration-500 shadow-xl shadow-emerald-500/10">
                        <TrendingUp size={28} strokeWidth={3}/>
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-2 border-t border-white/5 bg-zinc-950/40 rounded-b-[4rem] overflow-hidden backdrop-blur-md">
                <button onClick={(e) => openFormModal(e, printer)} className="py-7 font-black text-[11px] text-zinc-600 hover:text-white hover:bg-emerald-600/10 transition-all uppercase tracking-[0.3em] flex items-center justify-center gap-3"><Edit2 size={16}/> DÜZENLE</button>
                <button onClick={(e) => { e.stopPropagation(); if(confirm('Silsin mi?')) StorageService.deletePrinter(printer.id).then(() => loadData()); }} className="py-7 font-black text-[11px] text-zinc-800 hover:text-white hover:bg-red-600 transition-all uppercase tracking-[0.3em] flex items-center justify-center gap-3 border-l border-white/5"><Trash2 size={16}/> SİL</button>
            </div>
          </div>
        ))}

        {filteredPrinters.length === 0 && (
            <div className="col-span-full py-32 flex flex-col items-center justify-center text-zinc-700 gap-6">
                <div className="p-8 bg-zinc-900 rounded-full shadow-inner opacity-40"><Search size={64}/></div>
                <p className="font-black text-2xl uppercase tracking-widest text-zinc-600">Arama sonucu bulunamadı</p>
                <button onClick={() => { setSearchTerm(''); setSelectedFloor(null); setSelectedModel(null); }} className="text-emerald-500 font-bold uppercase tracking-widest text-xs border-b border-emerald-500/20 pb-1">FİLTRELERİ TEMİZLE</button>
            </div>
        )}
      </div>

      {/* ANALİZ DRAWER */}
      {selectedPrinter && (
          <div className="fixed inset-0 z-[500] flex justify-end">
              <div className="absolute inset-0 bg-black/95 backdrop-blur-xl animate-in fade-in duration-500" onClick={() => window.history.back()}></div>
              <div className="relative w-full max-w-2xl bg-[#09090b] h-full shadow-[0_0_100px_rgba(0,0,0,1)] border-l border-white/5 animate-in slide-in-from-right duration-700 flex flex-col overflow-hidden">

                  {/* Header */}
                  <div className="p-12 flex justify-between items-center bg-zinc-950/50 border-b border-white/5">
                      <div className="flex flex-col">
                          <div className="flex items-center gap-4 mb-3">
                             <span className="bg-emerald-500/10 text-emerald-500 px-4 py-1.5 rounded-xl text-[11px] font-black tracking-[0.3em] border border-emerald-500/20 uppercase">#{selectedPrinter.shortCode}</span>
                             <span className="text-[11px] text-zinc-600 font-black font-mono tracking-widest">{selectedPrinter.serialNumber}</span>
                          </div>
                          <h3 className="text-5xl font-black text-white tracking-tighter uppercase leading-none">{selectedPrinter.brand} {selectedPrinter.model}</h3>
                      </div>
                      <button onClick={() => window.history.back()} className="p-6 bg-zinc-900 text-white rounded-[2rem] hover:bg-red-600 transition-all shadow-2xl active:scale-90"><X size={36} strokeWidth={3}/></button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-12 space-y-16 custom-scrollbar">
                      {/* Üst 3'lü Analiz Kartları */}
                      <div className="grid grid-cols-3 gap-6">
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">TOPLAM ENDEKS</p>
                              <p className="text-4xl font-black text-white font-mono leading-none">{selectedPrinter.lastCounter.toLocaleString('tr-TR')}</p>
                          </div>
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">SİSTEM MALİYETİ</p>
                              <p className="text-4xl font-black text-emerald-500 font-mono leading-none">{calculateTotalCost(printerServices).toLocaleString('tr-TR')} ₺</p>
                          </div>
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">TONER DEĞİŞİMİ</p>
                              <p className="text-4xl font-black text-orange-500 font-mono leading-none">{printerTonerLogs.length}</p>
                          </div>
                      </div>

                      {/* Toner Arşivi */}
                      <div className="space-y-8">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter">
                              <Droplet size={28} className="text-orange-500"/> TONER ARŞİVİ
                          </h4>
                          <div className="space-y-4">
                              {printerTonerLogs.length > 0 ? (
                                  printerTonerLogs.map(log => (
                                      <div key={log.id} className="bg-zinc-900/40 p-8 rounded-[3rem] border border-white/5 flex items-center justify-between group/row hover:bg-white/5 transition-all">
                                          <div className="flex items-center gap-8">
                                              <div className="p-5 bg-orange-500/10 text-orange-500 rounded-2xl border border-orange-500/20"><Droplet size={28}/></div>
                                              <div>
                                                  <p className="text-2xl font-black text-white uppercase">{log.tonerModel}</p>
                                                  <div className="flex gap-6 mt-2">
                                                      <span className="text-[10px] text-zinc-600 font-black uppercase flex items-center gap-2"><Calendar size={14}/> {new Date(log.date).toLocaleDateString('tr-TR')}</span>
                                                      <span className="text-[10px] text-zinc-600 font-black uppercase flex items-center gap-2"><UserIcon size={14}/> {log.user.split(' ')[0]}</span>
                                                  </div>
                                              </div>
                                          </div>
                                          <span className="text-[10px] font-black text-zinc-500 bg-zinc-800 px-5 py-2 rounded-full tracking-[0.2em] uppercase">STOKTAN</span>
                                      </div>
                                  ))
                              ) : (
                                  <div className="p-16 border-2 border-dashed border-white/5 rounded-[3rem] text-center text-zinc-700 font-black uppercase text-xs tracking-widest">Henüz kayıt yok.</div>
                              )}
                          </div>
                      </div>

                      {/* Teknik Kayıtlar */}
                      <div className="space-y-8">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter">
                              <Wrench size={28} className="text-blue-500"/> TEKNİK KAYITLAR
                          </h4>
                          {printerServices.length > 0 ? (
                              <div className="space-y-6">
                                  {printerServices.map(service => (
                                      <div key={service.id} className="bg-zinc-900/40 p-10 rounded-[3rem] border border-white/5 space-y-6 shadow-2xl">
                                          <div className="flex justify-between items-start">
                                              <p className="text-lg font-black text-white leading-relaxed">{service.issue}</p>
                                              <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">{new Date(service.date).toLocaleDateString('tr-TR')}</span>
                                          </div>
                                          <div className="p-6 bg-zinc-950 rounded-2xl text-xs text-zinc-500 leading-relaxed font-bold border border-white/5 italic">"{service.actionTaken}"</div>
                                      </div>
                                  ))}
                              </div>
                          ) : (
                               <div className="bg-zinc-900/40 p-16 rounded-[3rem] border border-white/5 text-center text-zinc-700 font-black text-xs uppercase tracking-widest">Servis kaydı yok.</div>
                          )}
                      </div>

                      {/* Endeks Analizi */}
                      <div className="space-y-8 pb-10">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter">
                              <Calculator size={28} className="text-emerald-500"/> ENDEKS ANALİZİ
                          </h4>
                          <div className="bg-zinc-900/20 rounded-[3rem] border border-white/5 overflow-hidden shadow-2xl">
                              <table className="w-full text-left border-collapse">
                                  <thead className="bg-zinc-950/80 border-b border-white/5">
                                      <tr>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em]">TARİH</th>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] text-center">SAYAÇ</th>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] text-right">FARK</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-white/5">
                                      {printerCounters.slice(0, 10).map(log => (
                                          <tr key={log.id} className="hover:bg-white/5 transition-colors">
                                              <td className="p-8 text-xs text-zinc-500 font-black uppercase tracking-widest">{new Date(log.date).toLocaleDateString('tr-TR')}</td>
                                              <td className="p-8 text-xl text-white font-black font-mono text-center">{log.currentCounter.toLocaleString('tr-TR')}</td>
                                              <td className="p-8 text-xl text-emerald-500 font-black font-mono text-right">+{log.usage.toLocaleString('tr-TR')}</td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      </div>
                  </div>

                  {/* Panel Footer */}
                  <div className="p-12 bg-zinc-950 border-t border-white/5 grid grid-cols-2 gap-6">
                      <button onClick={(e) => openFormModal(e, selectedPrinter)} className="py-8 bg-zinc-900 hover:bg-zinc-800 text-white rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] transition-all active:scale-95 border border-white/5">CİHAZI DÜZENLE</button>
                      <button onClick={() => window.history.back()} className="py-8 bg-white text-black rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] transition-all active:scale-95 shadow-2xl">PANELİ KAPAT</button>
                  </div>
              </div>
          </div>
      )}

      {/* Form Modal */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/98 backdrop-blur-3xl z-[600] flex items-center justify-center p-6 animate-in fade-in duration-500">
          <div className="bg-[#09090b] rounded-[4rem] w-full max-w-2xl shadow-[0_40px_100px_rgba(0,0,0,1)] overflow-hidden animate-in zoom-in-95 duration-500 border border-white/5 flex flex-col max-h-[90vh]">
            <div className="p-10 border-b border-white/5 flex justify-between items-center bg-zinc-950/50">
              <h3 className="font-black text-4xl text-white tracking-tighter uppercase leading-none">{editingPrinter ? 'CİHAZ GÜNCELLE' : 'YENİ ÜNİTE EKLE'}</h3>
              <button onClick={() => window.history.back()} className="p-5 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all active:scale-90"><X size={32} strokeWidth={3} /></button>
            </div>
            <form onSubmit={handleSave} className="p-12 space-y-8 overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">MARKA</label>
                  <select required className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})}>
                    {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                  </select>
                </div>
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">MODEL</label>
                  <select required className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})}>
                    {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">SERİ NUMARASI</label>
                  <input required type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} />
                </div>
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">LOKASYON</label>
                  <input required type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">KAT / BÖLÜM</label>
                    <input type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" placeholder="2. KAT" value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">BAĞLANTI</label>
                    <select className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.connectionType} onChange={e => setFormData({...formData, connectionType: e.target.value as any})}>
                      <option value="USB">USB</option>
                      <option value="Network">NETWORK (IP)</option>
                    </select>
                  </div>
              </div>

              <button type="submit" className="w-full py-8 bg-emerald-600 hover:bg-emerald-500 text-white rounded-[2.5rem] font-black shadow-2xl transition-all active:scale-95 uppercase tracking-[0.4em] text-sm">ÜNİTEYİ SİSTEME KAYDET</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Search, MapPin, Printer as PrinterIcon, Edit2, X, Wifi, Usb, Trash2, QrCode, RefreshCw, Calendar, Calculator, Wrench, Droplet, Globe, TrendingUp, User as UserIcon, SortAsc, SortDesc, Filter, Layers, LayoutGrid, Type } from 'lucide-react';
import { Printer as PrinterType, SystemConfig, StockLog, ServiceRecord, CounterLog } from '../types';
import { StorageService } from '../services/storage';
import { LoadingScreen } from './LoadingScreen';

interface PrinterListProps {
  onSelectPrinter?: (printer: PrinterType) => void;
  targetPrinterId?: string | null;
  clearTarget?: () => void;
}

export const PrinterList: React.FC<PrinterListProps> = ({ targetPrinterId, clearTarget }) => {
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {} });
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState<'AZ' | 'ZA'>('AZ');
  const [loading, setLoading] = useState(true);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState<PrinterType | null>(null);

  // Filtreleme State'leri
  const [selectedFloor, setSelectedFloor] = useState<string | null>(null);
  const [selectedModel, setSelectedModel] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);

  const [selectedPrinter, setSelectedPrinter] = useState<PrinterType | null>(null);
  const [printerServices, setPrinterServices] = useState<ServiceRecord[]>([]);
  const [printerCounters, setPrinterCounters] = useState<CounterLog[]>([]);
  const [printerTonerLogs, setPrinterTonerLogs] = useState<StockLog[]>([]);

  // Form State
  const [formData, setFormData] = useState<Partial<PrinterType>>({
    brand: '', model: '', serialNumber: '', shortCode: '', location: '', floor: '',
    lastCounter: 0, connectionType: 'USB', ipAddress: '', status: 'ACTIVE'
  });

  // Manuel Giriş State'leri
  const [isCustomBrand, setIsCustomBrand] = useState(false);
  const [isCustomModel, setIsCustomModel] = useState(false);
  const [customBrand, setCustomBrand] = useState('');
  const [customModel, setCustomModel] = useState('');

  useEffect(() => { loadData(); }, []);

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (isFormModalOpen || selectedPrinter) {
          window.history.back();
        }
      }
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isFormModalOpen, selectedPrinter]);

  useEffect(() => {
    if (targetPrinterId && printers.length > 0) {
      const p = printers.find(x => x.id === targetPrinterId);
      if (p) handleOpenDetail(p);
      if (clearTarget) clearTarget();
    }
  }, [targetPrinterId, printers]);

  useEffect(() => {
    const handlePopState = () => {
      setIsFormModalOpen(false);
      setSelectedPrinter(null);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [p, c] = await Promise.all([StorageService.getPrinters(), StorageService.getConfig()]);
    setPrinters(p);
    setConfig(c);
    setLoading(false);
  };

  // Dinamik filtre seçeneklerini hesapla
  const floorOptions = useMemo(() => {
    const floors = printers.map(p => p.floor).filter(Boolean);
    return Array.from(new Set(floors)).sort();
  }, [printers]);

  const modelOptions = useMemo(() => {
    const models = printers.map(p => p.model).filter(Boolean);
    return Array.from(new Set(models)).sort();
  }, [printers]);

  const handleOpenDetail = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'detail' }, '');
    setSelectedPrinter(printer);
    const [services, counters, logs] = await Promise.all([
      StorageService.getServiceRecords(),
      StorageService.getCounterLogs(),
      StorageService.getLogs()
    ]);
    setPrinterServices(services.filter(s => s.printerId === printer.id));
    setPrinterCounters(counters.filter(c => c.printerId === printer.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    setPrinterTonerLogs(logs.filter(l => l.printerId === printer.id && l.type === 'OUT'));
  };

  const openFormModal = (e: React.MouseEvent, printer?: PrinterType) => {
    e.stopPropagation();
    window.history.pushState({ modal: 'form' }, '');

    if (printer) {
      setEditingPrinter(printer); 
      setFormData({ ...printer });

      // Marka listede var mı?
      const brandInConfig = config.brands.includes(printer.brand);
      setIsCustomBrand(!brandInConfig);
      setCustomBrand(brandInConfig ? '' : printer.brand);

      // Model listede var mı?
      const modelInConfig = config.models.includes(printer.model);
      setIsCustomModel(!modelInConfig);
      setCustomModel(modelInConfig ? '' : printer.model);
    } else {
      setEditingPrinter(null);
      setFormData({ brand: config.brands[0] || '', model: config.models[0] || '', status: 'ACTIVE', connectionType: 'USB' });
      setIsCustomBrand(false);
      setIsCustomModel(false);
      setCustomBrand('');
      setCustomModel('');
    }
    setIsFormModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();

    const finalBrand = isCustomBrand ? customBrand.trim() : formData.brand;
    const finalModel = isCustomModel ? customModel.trim() : formData.model;

    if (!finalBrand || !finalModel) {
      alert("Lütfen marka ve model bilgilerini eksiksiz giriniz.");
      return;
    }

    const payload = { 
      ...formData, 
      brand: finalBrand, 
      model: finalModel 
    } as PrinterType;

    if (editingPrinter?.id) {
       await StorageService.updatePrinter(payload);
    } else {
       await StorageService.addPrinter({ ...payload, id: '', lastTonerDate: new Date().toISOString() });
    }

    window.history.back();
    loadData();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]';
      case 'MAINTENANCE': return 'bg-orange-500';
      case 'BROKEN': return 'bg-red-500';
      default: return 'bg-zinc-500';
    }
  };

  const filteredPrinters = printers.filter(p => {
    const s = searchTerm.toLocaleLowerCase('tr-TR');
    const matchesSearch = (
        p.model.toLocaleLowerCase('tr-TR').includes(s) || 
        p.location.toLocaleLowerCase('tr-TR').includes(s) || 
        p.shortCode?.includes(s) ||
        p.serialNumber.toLowerCase().includes(s)
    );
    const matchesFloor = !selectedFloor || p.floor === selectedFloor;
    const matchesModel = !selectedModel || p.model === selectedModel;

    return matchesSearch && matchesFloor && matchesModel;
  }).sort((a, b) => {
    const nameA = a.location.toLocaleLowerCase('tr-TR');
    const nameB = b.location.toLocaleLowerCase('tr-TR');
    if (sortBy === 'AZ') return nameA.localeCompare(nameB);
    return nameB.localeCompare(nameA);
  });

  const getModelImage = (model: string) => config.modelImages?.[model] || null;
  const calculateTotalCost = (services: ServiceRecord[]) => services.reduce((acc, curr) => acc + (curr.cost || 0), 0);

  if (loading && printers.length === 0) return <LoadingScreen message="Antrasit ekosistem yükleniyor..." />;

  return (
    <div className="space-y-8 pb-32 anthracite-gradient min-h-full">
      {/* Premium Header */}
      <div className="bg-zinc-900/60 backdrop-blur-3xl p-10 rounded-[4rem] border border-white/5 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 left-0 w-96 h-96 bg-emerald-500/5 blur-[120px] -ml-48 -mt-48"></div>
        <div className="relative z-10 flex items-center gap-6">
            <div className="p-5 bg-emerald-500/10 text-emerald-500 rounded-3xl border border-emerald-500/20 shadow-inner"><PrinterIcon size={40} strokeWidth={2.5}/></div>
            <div>
                <h2 className="text-4xl font-black text-white tracking-tighter uppercase leading-none">CİHAZ HAVUZU</h2>
                <p className="text-[10px] font-black text-emerald-500/60 mt-2 uppercase tracking-[0.4em]">{filteredPrinters.length} Eşleşen Ünite</p>
            </div>
        </div>
        <div className="flex gap-4 relative z-10 w-full md:w-auto">
            <button onClick={() => setShowFilters(!showFilters)} className={`flex-1 md:flex-none p-5 rounded-[2rem] border border-white/5 transition-all flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest ${showFilters || selectedFloor || selectedModel ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30 shadow-lg shadow-emerald-500/10' : 'bg-white/5 text-zinc-400 hover:bg-white/10'}`}>
                <Filter size={24} /> FİLTRELE
            </button>
            <button onClick={() => setSortBy(sortBy === 'AZ' ? 'ZA' : 'AZ')} className="flex-1 md:flex-none p-5 bg-white/5 hover:bg-white/10 text-zinc-400 rounded-[2rem] border border-white/5 transition-all flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest">
