  const modelOptions = useMemo(() => {
    const models = printers.map(p => p.model).filter(Boolean);
    return Array.from(new Set(models)).sort();
  }, [printers]);

  const handleOpenDetail = async (printer: PrinterType) => {
    window.history.pushState({ modal: 'detail' }, '');
    setSelectedPrinter(printer);
    const [services, counters, logs] = await Promise.all([
      StorageService.getServiceRecords(),
      StorageService.getCounterLogs(),
      StorageService.getLogs()
    ]);
    setPrinterServices(services.filter(s => s.printerId === printer.id));
    setPrinterCounters(counters.filter(c => c.printerId === printer.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    setPrinterTonerLogs(logs.filter(l => l.printerId === printer.id && l.type === 'OUT'));
  };

  const openFormModal = (e: React.MouseEvent, printer?: PrinterType) => {
    e.stopPropagation();
    window.history.pushState({ modal: 'form' }, '');

    if (printer) {
      setEditingPrinter(printer); 
      setFormData({ ...printer });

      const brandInConfig = config.brands.includes(printer.brand);
      setIsCustomBrand(!brandInConfig);
      setCustomBrand(brandInConfig ? '' : printer.brand);

      const modelInConfig = config.models.includes(printer.model);
      setIsCustomModel(!modelInConfig);
      setCustomModel(modelInConfig ? '' : printer.model);
    } else {
      setEditingPrinter(null);
      setFormData({ brand: config.brands[0] || '', model: config.models[0] || '', status: 'ACTIVE', connectionType: 'USB' });
      setIsCustomBrand(false);
      setIsCustomModel(false);
      setCustomBrand('');
      setCustomModel('');
    }
    setIsFormModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalBrand = isCustomBrand ? customBrand.trim() : formData.brand;
    const finalModel = isCustomModel ? customModel.trim() : formData.model;

    if (!finalBrand || !finalModel) {
      alert("Lütfen marka ve model bilgilerini eksiksiz giriniz.");
      return;
    }

    const payload = { 
      ...formData, 
      brand: finalBrand, 
      model: finalModel 
    } as PrinterType;

    if (editingPrinter?.id) {
       await StorageService.updatePrinter(payload);
    } else {
       await StorageService.addPrinter({ ...payload, id: '', lastTonerDate: new Date().toISOString() });
    }
    window.history.back();
    loadData();
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]';
      case 'MAINTENANCE': return 'bg-orange-500';
      case 'BROKEN': return 'bg-red-500';
      default: return 'bg-zinc-500';
    }
  };

  const getServiceStatusStyles = (status: string) => {
    switch(status) {
        case 'SCRAPPED': return 'bg-orange-100 text-orange-900';
        case 'COMPLETED': return 'bg-emerald-100 text-emerald-900';
        case 'PENDING': return 'bg-yellow-100 text-yellow-900';
        default: return 'bg-zinc-200 text-zinc-900';
    }
  };

  const filteredPrinters = printers.filter(p => {
    const s = searchTerm.toLocaleLowerCase('tr-TR');
    const matchesSearch = (
        p.model.toLocaleLowerCase('tr-TR').includes(s) || 
        p.location.toLocaleLowerCase('tr-TR').includes(s) || 
        p.shortCode?.includes(s) ||
        p.serialNumber.toLowerCase().includes(s)
    );
    const matchesFloor = !selectedFloor || p.floor === selectedFloor;
    const matchesModel = !selectedModel || p.model === selectedModel;

    return matchesSearch && matchesFloor && matchesModel;
  }).sort((a, b) => {
    const nameA = a.location.toLocaleLowerCase('tr-TR');
    const nameB = b.location.toLocaleLowerCase('tr-TR');
    if (sortBy === 'AZ') return nameA.localeCompare(nameB);
    return nameB.localeCompare(nameA);
  });

  const getModelImage = (model: string) => config.modelImages?.[model] || null;
  const calculateTotalCost = (services: ServiceRecord[]) => services.reduce((acc, curr) => acc + (curr.cost || 0), 0);

  if (loading && printers.length === 0) return <LoadingScreen message="Antrasit ekosistem yükleniyor..." />;

  return (
    <div className="space-y-8 pb-32 anthracite-gradient min-h-full">
      {/* Premium Header */}
      <div className="bg-zinc-900/60 backdrop-blur-3xl p-10 rounded-[4rem] border border-white/5 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 left-0 w-96 h-96 bg-emerald-500/5 blur-[120px] -ml-48 -mt-48"></div>
        <div className="relative z-10 flex items-center gap-6">
            <div className="p-5 bg-emerald-500/10 text-emerald-500 rounded-3xl border border-emerald-500/20 shadow-inner"><PrinterIcon size={40} strokeWidth={2.5}/></div>
            <div>
                <h2 className="text-4xl font-black text-white tracking-tighter uppercase leading-none">CİHAZ HAVUZU</h2>
                <p className="text-[10px] font-black text-emerald-500/60 mt-2 uppercase tracking-[0.4em]">{filteredPrinters.length} Eşleşen Ünite</p>
            </div>
        </div>
        <div className="flex gap-4 relative z-10 w-full md:w-auto">
            <button onClick={() => setShowFilters(!showFilters)} className={`flex-1 md:flex-none p-5 rounded-[2rem] border border-white/5 transition-all flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest ${showFilters || selectedFloor || selectedModel ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30 shadow-lg shadow-emerald-500/10' : 'bg-white/5 text-zinc-400 hover:bg-white/10'}`}>
                <Filter size={24} /> FİLTRELE
            </button>
            <button onClick={() => setSortBy(sortBy === 'AZ' ? 'ZA' : 'AZ')} className="flex-1 md:flex-none p-5 bg-white/5 hover:bg-white/10 text-zinc-400 rounded-[2rem] border border-white/5 transition-all flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest">
                {sortBy === 'AZ' ? <SortAsc size={24} /> : <SortDesc size={24} />} {sortBy === 'AZ' ? 'A-Z' : 'Z-A'}
            </button>
            <button onClick={(e) => openFormModal(e)} className="hidden md:flex bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] items-center justify-center gap-3 font-black shadow-2xl shadow-emerald-600/20 transition-all active:scale-95 uppercase text-xs tracking-[0.2em]">
                <Plus size={24} /> YENİ CİHAZ
            </button>
        </div>
      </div>

      {/* Gelişmiş Arama */}
      <div className="space-y-6 mx-4 md:mx-0">
        <div className="relative group">
            <div className="absolute inset-y-0 left-8 flex items-center pointer-events-none text-zinc-600 group-focus-within:text-emerald-500 transition-colors"><Search size={28} /></div>
            <input 
                type="text" 
                placeholder="Model, Lokasyon veya Hızlı Kod ara..." 
                className="w-full pl-24 pr-10 py-8 rounded-[3rem] bg-zinc-900/40 backdrop-blur-md border border-white/5 text-white shadow-2xl focus:border-emerald-500/50 outline-none transition-all font-black text-xl placeholder:text-zinc-700" 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(e.target.value)} 
            />
            {(searchTerm || selectedFloor || selectedModel) && (
                <button 
                    onClick={() => { setSearchTerm(''); setSelectedFloor(null); setSelectedModel(null); }}
                    className="absolute inset-y-0 right-8 flex items-center text-zinc-600 hover:text-red-500 transition-colors"
                >
                    <X size={24} />
                </button>
            )}
        </div>

        {/* Filtre Panel */}
        {(showFilters || selectedFloor || selectedModel) && (
            <div className="animate-in slide-in-from-top-4 duration-500 space-y-4">
                <div className="bg-zinc-900/40 backdrop-blur-sm p-6 rounded-[2.5rem] border border-white/5 space-y-6">
                    <div>
                        <div className="flex items-center gap-3 text-zinc-500 mb-4 px-2">
                            <MapPin size={14} className="text-emerald-500" />
                            <span className="text-[10px] font-black uppercase tracking-widest">KAT SEÇİMİ</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            <button onClick={() => setSelectedFloor(null)} className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${!selectedFloor ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white/5 text-zinc-500 hover:text-white'}`}>TÜMÜ</button>
                            {floorOptions.map(floor => (
                                <button key={floor} onClick={() => setSelectedFloor(selectedFloor === floor ? null : floor)} className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedFloor === floor ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white/5 text-zinc-500 hover:text-white'}`}>{floor}</button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <div className="flex items-center gap-3 text-zinc-500 mb-4 px-2">
                            <LayoutGrid size={14} className="text-blue-500" />
                            <span className="text-[10px] font-black uppercase tracking-widest">MODEL SEÇİMİ</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            <button onClick={() => setSelectedModel(null)} className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${!selectedModel ? 'bg-blue-600 text-white shadow-lg' : 'bg-white/5 text-zinc-500 hover:text-white'}`}>TÜMÜ</button>
                            {modelOptions.map(model => (
                                <button key={model} onClick={() => setSelectedModel(selectedModel === model ? null : model)} className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedModel === model ? 'bg-blue-600 text-white shadow-lg' : 'bg-white/5 text-zinc-500 hover:text-white'}`}>{model}</button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Grid - Antrasit Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 px-4 md:px-0">
        {filteredPrinters.map(printer => (
          <div key={printer.id} onClick={() => handleOpenDetail(printer)} className="group rounded-[4rem] bg-[#121214] border border-white/5 p-1 transition-all duration-700 hover:border-emerald-500/30 hover:-translate-y-3 cursor-pointer shadow-[0_30px_60px_-12px_rgba(0,0,0,0.5)] flex flex-col relative">
            <div className="p-10 flex-1">
                <div className="flex justify-between items-start mb-8">
                    <div className="flex items-start gap-4">
                        <div className={`mt-2 w-3.5 h-3.5 rounded-full ${getStatusBadge(printer.status)} border-2 border-white/10`}></div>
                        <div>
                            <div className="flex items-center gap-2 text-emerald-500 font-black text-[11px] uppercase tracking-[0.3em] mb-1"><MapPin size={14}/> {printer.location}</div>
                            <div className="text-[9px] text-zinc-600 font-black uppercase tracking-widest">{printer.floor || 'BÖLÜM BELİRTİLMEDİ'}</div>
                        </div>
                    </div>
                    <button className="p-4 bg-white/5 rounded-2xl text-zinc-600 hover:text-emerald-500 transition-all"><QrCode size={20}/></button>
                </div>
                <div className="flex justify-between items-center gap-6 mb-12">
                    <div className="flex-1">
                        <h3 className="text-3xl font-black text-white leading-none tracking-tighter uppercase mb-6 group-hover:text-emerald-500 transition-colors">{printer.brand} {printer.model}</h3>
                        <div className="flex flex-wrap gap-3">
                            <span className="bg-emerald-500/10 text-emerald-500 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-emerald-500/20 shadow-lg shadow-emerald-500/5">#{printer.shortCode}</span>
                            {printer.connectionType === 'Network' ? (
                                <span className="bg-blue-500/10 text-blue-400 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-blue-500/20 flex items-center gap-2"><Wifi size={14}/> {printer.ipAddress}</span>
                            ) : (
                                <span className="bg-zinc-800/50 text-zinc-500 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-white/5 flex items-center gap-2"><Usb size={14}/> USB</span>
                            )}
                        </div>
                    </div>
                    {getModelImage(printer.model) && (
                        <div className="w-28 h-28 bg-zinc-800/30 rounded-[2.5rem] p-4 border border-white/5 group-hover:scale-110 transition-transform duration-700 shadow-2xl flex items-center justify-center">
                            <img src={getModelImage(printer.model)!} className="w-full h-full object-contain filter drop-shadow-2xl" alt={printer.model} />
                        </div>
                    )}
                </div>
                <div className="pt-8 border-t border-white/5 flex justify-between items-end">
                    <div className="space-y-1">
                        <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.4em]">GÜNCEL SAYAÇ</p>
                        <p className="text-4xl font-mono font-black text-white leading-none">{printer.lastCounter.toLocaleString('tr-TR')}</p>
                    </div>
                    <button className="bg-emerald-500/10 text-emerald-500 p-5 rounded-[1.5rem] group-hover:bg-emerald-600 group-hover:text-white transition-all duration-500 shadow-xl shadow-emerald-500/10"><TrendingUp size={28} strokeWidth={3}/></button>
                </div>
            </div>
            <div className="grid grid-cols-2 border-t border-white/5 bg-zinc-950/40 rounded-b-[4rem] overflow-hidden backdrop-blur-md">
                <button onClick={(e) => openFormModal(e, printer)} className="py-7 font-black text-[11px] text-zinc-600 hover:text-white hover:bg-emerald-600/10 transition-all uppercase tracking-[0.3em] flex items-center justify-center gap-3"><Edit2 size={16}/> DÜZENLE</button>
                <button onClick={(e) => { e.stopPropagation(); if(confirm('Silsin mi?')) StorageService.deletePrinter(printer.id).then(() => loadData()); }} className="py-7 font-black text-[11px] text-zinc-800 hover:text-white hover:bg-red-600 transition-all uppercase tracking-[0.3em] flex items-center justify-center gap-3 border-l border-white/5"><Trash2 size={16}/> SİL</button>
            </div>
          </div>
        ))}
      </div>

      {/* ANALİZ DRAWER (COMMAND CENTER) */}
      {selectedPrinter && (
          <div className="fixed inset-0 z-[500] flex justify-end">
              <div className="absolute inset-0 bg-black/95 backdrop-blur-xl animate-in fade-in duration-500" onClick={() => window.history.back()}></div>
              <div className="relative w-full max-w-2xl bg-[#09090b] h-full shadow-[0_0_100px_rgba(0,0,0,1)] border-l border-white/5 animate-in slide-in-from-right duration-700 flex flex-col overflow-hidden">

                  {/* Panel Header */}
                  <div className="p-10 flex flex-col bg-zinc-950/50 border-b border-white/5 relative">
                      {/* Close Button Top Right */}
                      <button onClick={() => window.history.back()} className="absolute top-8 right-8 p-5 bg-zinc-900 text-white rounded-[1.5rem] hover:bg-red-600 transition-all shadow-2xl active:scale-90 z-20">
                        <X size={32} strokeWidth={3}/>
                      </button>

                      <div className="flex flex-col md:flex-row gap-8 items-start mb-8">
                          {/* YENİ: DİNAMİK QR KOD VE HIZLI KOD ALANI */}
                          <div className="flex flex-col items-center gap-3 p-4 bg-white rounded-[2rem] shadow-2xl shadow-emerald-500/10 border border-zinc-800 shrink-0">
                              <img 
                                src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(window.location.origin + window.location.pathname + '?pid=' + selectedPrinter.id)}`} 
                                className="w-32 h-32 object-contain" 
                                alt="QR"
                              />
                              <div className="bg-zinc-950 text-emerald-500 px-4 py-1.5 rounded-xl font-black text-sm tracking-tighter">#{selectedPrinter.shortCode}</div>
                          </div>

                          <div className="flex-1 pt-2">
                              <div className="flex items-center gap-3 mb-4">
                                 <span className="bg-emerald-500/10 text-emerald-500 px-4 py-1.5 rounded-xl text-[10px] font-black tracking-[0.3em] border border-emerald-500/20 uppercase flex items-center gap-2">
                                     <Zap size={12} /> CİHAZ PASAPORTU
                                 </span>
                                 <div className={`w-3 h-3 rounded-full ${getStatusBadge(selectedPrinter.status)} animate-pulse shadow-lg`}></div>
                              </div>
                              <h3 className="text-4xl md:text-5xl font-black text-white tracking-tighter uppercase leading-none">{selectedPrinter.brand} {selectedPrinter.model}</h3>
                              <div className="mt-4 flex flex-wrap gap-4">
                                  <div className="flex flex-col">
                                      <p className="text-[9px] font-black text-zinc-600 uppercase tracking-widest">LOKASYON</p>
                                      <p className="text-sm font-bold text-zinc-300">{selectedPrinter.location}</p>
                                  </div>
                                  <div className="w-px h-8 bg-white/5 mx-2 self-center"></div>
                                  <div className="flex flex-col">
                                      <p className="text-[9px] font-black text-zinc-600 uppercase tracking-widest">SERİ NO</p>
                                      <p className="text-sm font-bold text-zinc-300 font-mono">{selectedPrinter.serialNumber}</p>
                                  </div>
                                  {selectedPrinter.ipAddress && (
                                      <>
                                          <div className="w-px h-8 bg-white/5 mx-2 self-center"></div>
                                          <div className="flex flex-col">
                                              <p className="text-[9px] font-black text-zinc-600 uppercase tracking-widest">IP ADRESİ</p>
                                              <p className="text-sm font-bold text-blue-400 font-mono">{selectedPrinter.ipAddress}</p>
                                          </div>
                                      </>
                                  )}
                              </div>
                          </div>
                      </div>
                  </div>

                  <div className="flex-1 overflow-y-auto p-12 space-y-16 custom-scrollbar">
                      {/* Üst Analiz Kartları */}
                      <div className="grid grid-cols-3 gap-6">
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">TOPLAM ENDEKS</p>
                              <p className="text-4xl font-black text-white font-mono leading-none">{selectedPrinter.lastCounter.toLocaleString('tr-TR')}</p>
                          </div>
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">SİSTEM MALİYETİ</p>
                              <p className="text-4xl font-black text-emerald-500 font-mono leading-none">{calculateTotalCost(printerServices).toLocaleString('tr-TR')} ₺</p>
                          </div>
                          <div className="bg-zinc-900/40 p-8 rounded-[2.5rem] border border-white/5 space-y-4 shadow-xl">
                              <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.3em]">TONER DEĞİŞİMİ</p>
                              <p className="text-4xl font-black text-orange-500 font-mono leading-none">{printerTonerLogs.length}</p>
                          </div>
                      </div>

                      {/* TONER ARŞİVİ */}
                      <div className="space-y-8">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter"><Droplet size={28} className="text-orange-500"/> TONER ARŞİVİ</h4>
                          {printerTonerLogs.length > 0 ? (
                              <div className="space-y-4">
                                  {printerTonerLogs.map(log => (
                                      <div key={log.id} className="bg-zinc-900/40 p-8 rounded-[3rem] border border-white/5 flex items-center justify-between group/row hover:bg-white/5 transition-all">
                                          <div className="flex items-center gap-8">
                                              <div className="p-5 bg-orange-500/10 text-orange-500 rounded-2xl border border-orange-500/20"><Droplet size={28}/></div>
                                              <div>
                                                  <p className="text-2xl font-black text-white uppercase">{log.tonerModel}</p>
                                                  <div className="flex gap-6 mt-2">
                                                      <span className="text-[10px] text-zinc-600 font-black uppercase flex items-center gap-2"><Calendar size={14}/> {new Date(log.date).toLocaleDateString('tr-TR')}</span>
                                                      <span className="text-[10px] text-zinc-600 font-black uppercase flex items-center gap-2"><UserIcon size={14}/> {log.user.split(' ')[0]}</span>
                                                  </div>
                                              </div>
                                          </div>
                                          <span className="text-[9px] font-black text-zinc-500 bg-zinc-800 px-4 py-1.5 rounded-full tracking-widest uppercase">OTOMATİK STOK</span>
                                      </div>
                                  ))}
                              </div>
                          ) : <p className="text-zinc-700 text-center font-black uppercase tracking-widest text-xs">Toner kaydı bulunamadı.</p>}
                      </div>

                      {/* TEKNİK KAYITLAR */}
                      <div className="space-y-10">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter">
                            <Wrench size={28} className="text-blue-500"/> TEKNİK KAYITLAR
                          </h4>
                          {printerServices.length > 0 ? (
                              <div className="space-y-6">
                                  {printerServices.map(service => (
                                      <div key={service.id} className="relative bg-[#1a1b1e] rounded-[2rem] overflow-hidden border border-white/5 shadow-2xl flex flex-col">
                                          <div className="absolute left-0 top-0 bottom-0 w-1.5 bg-blue-500"></div>
                                          <div className="p-8 space-y-8">
                                              <div className="flex justify-between items-center">
                                                  <div className={`px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.15em] ${getServiceStatusStyles(service.status)}`}>
                                                      {service.status === 'COMPLETED' ? 'COMPLETED' : service.status === 'SCRAPPED' ? 'SCRAPPED' : 'PENDING'}
                                                  </div>
                                                  <div className="flex items-center gap-2 text-zinc-500">
                                                      <Clock size={16} />
                                                      <span className="text-xs font-black tracking-widest">{new Date(service.date).toLocaleDateString('tr-TR')}</span>
                                                  </div>
                                              </div>
                                              <div className="space-y-3">
                                                  <h5 className="text-3xl font-black text-white uppercase tracking-tighter leading-none">{service.issue}</h5>
                                                  <p className="text-sm font-medium text-zinc-500 leading-relaxed">{service.actionTaken}</p>
                                              </div>
                                              <div className="h-px bg-white/5 w-full"></div>
                                              <div className="flex justify-between items-end">
                                                  <div className="space-y-1">
                                                      <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.2em]">SERVİS SAĞLAYICI</p>
                                                      <p className="text-sm font-black text-zinc-400 uppercase">{service.provider}</p>
                                                  </div>
                                                  <div className="text-3xl font-black text-blue-400 font-mono">
                                                      {service.cost.toLocaleString()} <span className="text-xl">₺</span>
                                                  </div>
                                              </div>
                                          </div>
                                      </div>
                                  ))}
                              </div>
                          ) : <p className="text-zinc-700 text-center font-black uppercase tracking-widest text-xs">Teknik kayıt bulunamadı.</p>}
                      </div>

                      {/* ENDEKS ANALİZİ */}
                      <div className="space-y-8 pb-10">
                          <h4 className="flex items-center gap-4 text-white font-black text-xl uppercase tracking-tighter"><Calculator size={28} className="text-emerald-500"/> ENDEKS ANALİZİ</h4>
                          <div className="bg-zinc-900/20 rounded-[3rem] border border-white/5 overflow-hidden shadow-2xl">
                              <table className="w-full text-left border-collapse">
                                  <thead className="bg-zinc-950/80 border-b border-white/5">
                                      <tr>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em]">TARİH</th>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] text-center">SAYAÇ</th>
                                          <th className="p-8 text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] text-right">FARK</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-white/5">
                                      {printerCounters.slice(0, 10).map(log => (
                                          <tr key={log.id} className="hover:bg-white/5 transition-colors group/row">
                                              <td className="p-8 text-xs text-zinc-500 font-black uppercase tracking-widest">{new Date(log.date).toLocaleDateString('tr-TR')}</td>
                                              <td className="p-8 text-xl text-white font-black font-mono text-center">{log.currentCounter.toLocaleString('tr-TR')}</td>
                                              <td className="p-8 text-xl text-emerald-500 font-black font-mono text-right group-hover/row:scale-110 transition-transform">+{log.usage.toLocaleString('tr-TR')}</td>
                                          </tr>
                                      ))}
                                      {printerCounters.length === 0 && (
                                          <tr><td colSpan={3} className="p-16 text-center text-zinc-800 font-black uppercase text-xs tracking-[0.4em]">Sayaç verisi bulunmuyor</td></tr>
                                      )}
                                  </tbody>
                              </table>
                          </div>
                      </div>
                  </div>

                  {/* Panel Footer */}
                  <div className="p-12 bg-zinc-950 border-t border-white/5 grid grid-cols-2 gap-6">
                      <button onClick={(e) => openFormModal(e, selectedPrinter)} className="py-8 bg-zinc-900 hover:bg-zinc-800 text-white rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] transition-all border border-white/5">CİHAZI DÜZENLE</button>
                      <button onClick={() => window.history.back()} className="py-8 bg-white text-black rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] transition-all shadow-2xl active:scale-95">PANELİ KAPAT</button>
                  </div>
              </div>
          </div>
      )}

      {/* Form Modal */}
      {isFormModalOpen && (
        <div className="fixed inset-0 bg-black/98 backdrop-blur-3xl z-[600] flex items-center justify-center p-6 animate-in fade-in duration-500">
          <div className="bg-[#09090b] rounded-[4rem] w-full max-w-2xl shadow-[0_40px_100px_rgba(0,0,0,1)] overflow-hidden animate-in zoom-in-95 duration-500 border border-white/5 flex flex-col max-h-[90vh]">
            <div className="p-10 border-b border-white/5 flex justify-between items-center bg-zinc-950/50">
              <h3 className="font-black text-4xl text-white tracking-tighter uppercase leading-none">{editingPrinter ? 'CİHAZ GÜNCELLE' : 'YENİ ÜNİTE EKLE'}</h3>
              <button onClick={() => window.history.back()} className="p-5 bg-red-600 text-white rounded-3xl shadow-xl hover:rotate-90 transition-all active:scale-90"><X size={32} strokeWidth={3} /></button>
            </div>

            <form onSubmit={handleSave} className="p-12 space-y-8 overflow-y-auto custom-scrollbar">
              <div className="space-y-4">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">MARKA</label>
                  {!isCustomBrand ? (
                      <select required className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.brand} onChange={e => { if(e.target.value === 'CUSTOM') setIsCustomBrand(true); else setFormData({...formData, brand: e.target.value}); }}>
                        {config.brands.map(b => <option key={b} value={b}>{b}</option>)}
                        <option value="CUSTOM" className="text-emerald-500">-- DİĞER (ELLE YAZ) --</option>
                      </select>
                  ) : (
                      <div className="relative">
                          <input autoFocus type="text" placeholder="Marka adını giriniz..." className="w-full p-6 border-2 border-emerald-500/30 rounded-3xl bg-zinc-900 text-white font-black outline-none shadow-lg shadow-emerald-500/5 transition-all" value={customBrand} onChange={e => setCustomBrand(e.target.value)} />
                          <button type="button" onClick={() => setIsCustomBrand(false)} className="absolute right-6 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-white font-black text-[10px] uppercase tracking-widest bg-zinc-800 px-4 py-2 rounded-xl border border-white/5">Listeye Dön</button>
                      </div>
                  )}
              </div>

              <div className="space-y-4">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">MODEL</label>
                  {!isCustomModel ? (
                      <select required className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.model} onChange={e => { if(e.target.value === 'CUSTOM') setIsCustomModel(true); else setFormData({...formData, model: e.target.value}); }}>
                        {config.models.map(m => <option key={m} value={m}>{m}</option>)}
                        <option value="CUSTOM" className="text-emerald-500">-- DİĞER (ELLE YAZ) --</option>
                      </select>
                  ) : (
                      <div className="relative">
                          <input autoFocus type="text" placeholder="Model adını giriniz..." className="w-full p-6 border-2 border-emerald-500/30 rounded-3xl bg-zinc-900 text-white font-black outline-none shadow-lg shadow-emerald-500/5 transition-all" value={customModel} onChange={e => setCustomModel(e.target.value)} />
                          <button type="button" onClick={() => setIsCustomModel(false)} className="absolute right-6 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-white font-black text-[10px] uppercase tracking-widest bg-zinc-800 px-4 py-2 rounded-xl border border-white/5">Listeye Dön</button>
                      </div>
                  )}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">SERİ NUMARASI</label>
                  <input required type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.serialNumber} onChange={e => setFormData({...formData, serialNumber: e.target.value})} />
                </div>
                <div className="space-y-3">
                  <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">LOKASYON</label>
                  <input required type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">KAT / BÖLÜM</label>
                    <input type="text" className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" placeholder="2. KAT" value={formData.floor} onChange={e => setFormData({...formData, floor: e.target.value})} />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.3em] ml-2">BAĞLANTI</label>
                    <select className="w-full p-6 border border-white/10 rounded-3xl bg-zinc-900 text-white font-black outline-none focus:border-emerald-500 transition-all" value={formData.connectionType} onChange={e => setFormData({...formData, connectionType: e.target.value as any})}>
                      <option value="USB">USB</option>
                      <option value="Network">NETWORK (IP)</option>
                    </select>
                  </div>
              </div>

              <button type="submit" className="w-full py-8 bg-emerald-600 hover:bg-emerald-500 text-white rounded-[2.5rem] font-black shadow-2xl transition-all active:scale-95 uppercase tracking-[0.4em] text-sm">ÜNİTEYİ SİSTEME KAYDET</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

