                                {editingInvoice ? 'GÜNCELLEMEYİ KAYDET' : 'FATURAYI KAYDET'}
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Silme Onay Modalı */}
            {confirmDeleteInv && (
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-[400] flex items-center justify-center p-6 animate-in fade-in duration-300">
