                                      <div className="flex justify-between items-center text-[8px] font-black text-zinc-600 mt-2">
                                          <span>SAAT: {new Date(log.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                          <span>TEKNİSYEN: {log.user}</span>
                                      </div>
                                  </div>
