                          </div>
                      </div>

                      <div className="space-y-6">
                          <h4 className="flex items-center gap-3 text-white font-black text-lg uppercase tracking-tighter"><Wrench size={24} className="text-emerald-500"/> SERVİS GEÇMİŞİ</h4>
