import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Printer as PrinterIcon, QrCode, Download, Save, Hash, FileText, Layers, RefreshCw, Wifi, Globe, Loader2, CheckCircle2, X } from 'lucide-react';

declare const html2canvas: any;
declare const jspdf: any;

export const QrManagement: React.FC = () => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedPrinters, setSelectedPrinters] = useState<string[]>([]);
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const data = await StorageService.getPrinters();
    setPrinters(data.sort((a, b) => (a.shortCode || '').localeCompare(b.shortCode || '')));
    setLoading(false);
  };

  const toggleSelect = (id: string) => {
    setSelectedPrinters(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const selectAll = () => {
    if (selectedPrinters.length === printers.length) setSelectedPrinters([]);
    else setSelectedPrinters(printers.map(p => p.id));
  };

  const generatePDF = async () => {
    if (selectedPrinters.length === 0) return;
    setGenerating(true);

    const printableArea = document.getElementById('printable-area');
    if (!printableArea) return;

    try {
      // 4x Çözünürlük ile yakala (Baskı kalitesi için)
      const canvas = await html2canvas(printableArea, {
        scale: 4,
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff',
        windowWidth: printableArea.scrollWidth,
        windowHeight: printableArea.scrollHeight
      });

      const imgData = canvas.toDataURL('image/jpeg', 1.0);
      const pdf = new jspdf.jsPDF('p', 'mm', 'a4');

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`toner_etiketleri_${new Date().getTime()}.pdf`);
    } catch (error) {
      console.error("PDF Hatası:", error);
      alert("PDF oluşturulurken bir hata oluştu.");
    } finally {
      setGenerating(false);
    }
  };

  if (loading) return <LoadingScreen message="Cihaz listesi hazırlanıyor..." />;

  const selectedPrintersData = printers.filter(p => selectedPrinters.includes(p.id));

  return (
    <div className="space-y-8 pb-32">
      {/* Üst Bilgi Paneli */}
      <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-500/10 text-blue-500 rounded-3xl border border-blue-500/20"><QrCode size={40} strokeWidth={2.5}/></div>
            <div>
                <h2 className="text-4xl font-black text-zinc-900 dark:text-white tracking-tighter uppercase leading-none">QR YÖNETİMİ</h2>
                <p className="text-zinc-500 dark:text-zinc-400 font-bold uppercase tracking-widest mt-3">Fiziksel Etiket ve Kimlik Oluşturucu</p>
            </div>
        </div>
        <div className="flex gap-4 w-full md:w-auto">
            <button onClick={selectAll} className="flex-1 md:flex-none px-8 py-5 rounded-2xl border border-zinc-100 dark:border-zinc-800 text-zinc-500 font-black text-xs uppercase tracking-widest hover:bg-zinc-50 dark:hover:bg-zinc-900 transition-all">
                {selectedPrinters.length === printers.length ? 'SEÇİMİ KALDIR' : 'TÜMÜNÜ SEÇ'}
            </button>
            <button 
                onClick={generatePDF} 
                disabled={selectedPrinters.length === 0 || generating}
                className="flex-1 md:flex-none bg-blue-600 hover:bg-blue-500 text-white px-10 py-5 rounded-2xl font-black shadow-xl shadow-blue-500/20 disabled:opacity-50 transition-all flex items-center justify-center gap-3 text-xs tracking-widest uppercase"
            >
                {generating ? <Loader2 className="animate-spin" size={20}/> : <Download size={20} />}
                PDF OLARAK İNDİR ({selectedPrinters.length})
            </button>
        </div>
      </div>

      {/* Grid Seçim Listesi */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
        {printers.map(printer => (
            <div 
                key={printer.id}
                onClick={() => toggleSelect(printer.id)}
                className={`p-6 rounded-[2rem] border transition-all cursor-pointer relative group flex flex-col justify-between h-48
                    ${selectedPrinters.includes(printer.id) 
                        ? 'bg-blue-600 border-blue-500 shadow-xl shadow-blue-500/20' 
                        : 'bg-white dark:bg-zinc-950 border-zinc-100 dark:border-zinc-900 hover:border-blue-500/50'}`}
            >
                <div className="flex justify-between items-start">
                    <div className={`p-2 rounded-xl ${selectedPrinters.includes(printer.id) ? 'bg-white/20 text-white' : 'bg-zinc-100 dark:bg-zinc-900 text-zinc-400'}`}>
                        <PrinterIcon size={20} />
                    </div>
                    {selectedPrinters.includes(printer.id) && <CheckCircle2 size={24} className="text-white" />}
                </div>
                <div>
                    <h3 className={`font-black text-lg uppercase tracking-tighter leading-none ${selectedPrinters.includes(printer.id) ? 'text-white' : 'text-zinc-900 dark:text-white'}`}>{printer.model}</h3>
                    <p className={`text-[10px] font-bold uppercase mt-2 tracking-widest ${selectedPrinters.includes(printer.id) ? 'text-blue-100' : 'text-zinc-500'}`}>{printer.location}</p>
                </div>
                <div className={`absolute bottom-6 right-6 font-mono font-black text-xl ${selectedPrinters.includes(printer.id) ? 'text-white/40' : 'text-zinc-100 dark:text-zinc-900'}`}>
                    #{printer.shortCode}
                </div>
            </div>
        ))}
      </div>

      {/* GİZLİ YAZDIRMA ALANI - PDF İÇİN ÖZEL STİLLER (FIXED LAYOUT) */}
      <div style={{ position: 'absolute', left: '-9999px', top: 0 }}>
        <div 
          id="printable-area" 
          style={{ 
            width: '210mm', 
            minHeight: '297mm', 
            padding: '12mm', 
            backgroundColor: 'white', 
            display: 'flex', 
            flexWrap: 'wrap', 
            alignContent: 'flex-start',
            gap: '8mm' // Etiketler arası dikey/yatay boşluk
          }}
        >
          {selectedPrintersData.map((printer) => (
            <div 
              key={printer.id} 
              style={{ 
                width: '60mm', 
                height: '80mm', 
                border: '0.5mm solid #e5e7eb', 
                borderRadius: '8mm', 
                backgroundColor: 'white', 
                overflow: 'hidden',
                position: 'relative',
                display: 'block',
                boxSizing: 'border-box'
              }}
            >
              {/* Header: Brand & Model (Sabit Yükseklik) */}
              <div style={{ height: '18mm', width: '100%', padding: '4mm 2mm', textAlign: 'center', borderBottom: '0.1mm solid #f3f4f6' }}>
                  <div style={{ fontSize: '12pt', fontWeight: '900', color: '#111827', textTransform: 'uppercase', lineHeight: '1.2', marginBottom: '1mm' }}>
                      {printer.brand} {printer.model}
                  </div>
                  <div style={{ backgroundColor: '#111827', color: 'white', fontSize: '8pt', fontWeight: '700', borderRadius: '4mm', padding: '1mm 3mm', display: 'inline-block', textTransform: 'uppercase' }}>
                      {printer.location}
                  </div>
              </div>

              {/* QR Container (Orta Alan) */}
              <div style={{ height: '42mm', width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '2mm' }}>
                  <img 
                    src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(window.location.origin + window.location.pathname + '?sc=' + printer.shortCode)}`} 
                    style={{ width: '35mm', height: '35mm', objectFit: 'contain' }}
                    alt="QR"
                  />
              </div>

              {/* Footer: IP & ShortCode (Sabit Alt Alan) */}
              <div style={{ height: '20mm', width: '100%', padding: '0 4mm', position: 'relative' }}>
                  {/* IP Kutusu */}
                  <div style={{ 
                      display: 'inline-flex', 
                      alignItems: 'center', 
                      gap: '1.5mm', 
                      backgroundColor: '#eff6ff', 
                      border: '0.2mm solid #bfdbfe', 
