import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Printer as PrinterIcon, QrCode, Download, Image as ImageIcon, CheckCircle2, Loader2, X, Filter } from 'lucide-react';

declare const html2canvas: any;
declare const jspdf: any;

export const QrManagement: React.FC = () => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedPrinters, setSelectedPrinters] = useState<string[]>([]);
  const [generating, setGenerating] = useState<null | 'pdf' | 'jpeg'>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const data = await StorageService.getPrinters();
    setPrinters(data.sort((a, b) => (a.shortCode || '').localeCompare(b.shortCode || '')));
    setLoading(false);
  };

  const toggleSelect = (id: string) => {
    setSelectedPrinters(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const selectAll = () => {
    if (selectedPrinters.length === printers.length) setSelectedPrinters([]);
    else setSelectedPrinters(printers.map(p => p.id));
  };

  const captureCanvas = async () => {
    const printableArea = document.getElementById('printable-area');
    if (!printableArea) return null;

    return await html2canvas(printableArea, {
      scale: 3, // 300 DPI kalitesi
      useCORS: true,
      logging: false,
      backgroundColor: '#ffffff',
      allowTaint: true
    });
  };

  const handleDownload = async (type: 'pdf' | 'jpeg') => {
    if (selectedPrinters.length === 0) return;
    setGenerating(type);

    try {
      const canvas = await captureCanvas();
      if (!canvas) return;

      if (type === 'jpeg') {
        const imgData = canvas.toDataURL('image/jpeg', 0.9);
        const link = document.createElement('a');
        link.href = imgData;
        link.download = `toner_etiketleri_${new Date().getTime()}.jpg`;
        link.click();
      } else {
        const imgData = canvas.toDataURL('image/jpeg', 1.0);
        const pdf = new jspdf.jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
        pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
        pdf.save(`toner_etiketleri_${new Date().getTime()}.pdf`);
      }
    } catch (error) {
      console.error("İndirme Hatası:", error);
      alert("İşlem sırasında bir hata oluştu.");
    } finally {
      setGenerating(null);
    }
  };

  if (loading) return <LoadingScreen message="Cihaz listesi hazırlanıyor..." />;

  const selectedPrintersData = printers.filter(p => selectedPrinters.includes(p.id));

  return (
    <div className="space-y-8 pb-32">
      {/* Üst Bilgi Paneli */}
      <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-500/10 text-blue-500 rounded-3xl border border-blue-500/20"><QrCode size={40} strokeWidth={2.5}/></div>
            <div>
                <h2 className="text-4xl font-black text-zinc-900 dark:text-white tracking-tighter uppercase leading-none">ETİKET MERKEZİ</h2>
                <p className="text-zinc-500 dark:text-zinc-400 font-bold uppercase tracking-widest mt-3">PDF ve Görsel Çıktı Oluşturucu</p>
            </div>
        </div>
        <div className="flex flex-wrap gap-3 w-full md:w-auto justify-center">
            <button onClick={selectAll} className="px-6 py-4 rounded-2xl border border-zinc-100 dark:border-zinc-800 text-zinc-500 font-black text-[10px] uppercase tracking-widest hover:bg-zinc-50 dark:hover:bg-zinc-900 transition-all">
                {selectedPrinters.length === printers.length ? 'TEMİZLE' : 'TÜMÜNÜ SEÇ'}
            </button>
            <button 
                onClick={() => handleDownload('jpeg')} 
                disabled={selectedPrinters.length === 0 || !!generating}
                className="bg-zinc-900 hover:bg-zinc-800 text-white px-8 py-4 rounded-2xl font-black shadow-xl disabled:opacity-50 transition-all flex items-center gap-3 text-[10px] tracking-widest uppercase"
            >
                {generating === 'jpeg' ? <Loader2 className="animate-spin" size={18}/> : <ImageIcon size={18} />}
                GÖRSEL (JPG)
            </button>
            <button 
                onClick={() => handleDownload('pdf')} 
                disabled={selectedPrinters.length === 0 || !!generating}
                className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-4 rounded-2xl font-black shadow-xl shadow-blue-500/20 disabled:opacity-50 transition-all flex items-center gap-3 text-[10px] tracking-widest uppercase"
            >
                {generating === 'pdf' ? <Loader2 className="animate-spin" size={18}/> : <Download size={18} />}
                BELGE (PDF)
            </button>
        </div>
      </div>

      {/* Grid Seçim Listesi */}
