            >
                <div className="flex justify-between items-start">
                    <div className={`p-2 rounded-xl ${selectedPrinters.includes(printer.id) ? 'bg-white/20 text-white' : 'bg-zinc-100 dark:bg-zinc-900 text-zinc-400'}`}>
                        <PrinterIcon size={20} />
                    </div>
                    {selectedPrinters.includes(printer.id) && <CheckCircle2 size={24} className="text-white animate-in zoom-in" />}
                </div>
                <div>
                    <h3 className={`font-black text-lg uppercase tracking-tighter leading-none truncate pr-10 ${selectedPrinters.includes(printer.id) ? 'text-white' : 'text-zinc-900 dark:text-white'}`}>{printer.model}</h3>
                    <p className={`text-[10px] font-bold uppercase mt-2 tracking-widest truncate ${selectedPrinters.includes(printer.id) ? 'text-blue-100' : 'text-zinc-500'}`}>{printer.location}</p>
                </div>
                <div className={`absolute bottom-6 right-6 font-mono font-black text-xl ${selectedPrinters.includes(printer.id) ? 'text-white/40' : 'text-zinc-100 dark:text-zinc-900'}`}>
                    #{printer.shortCode}
                </div>
            </div>
        ))}
      </div>

      {/* GİZLİ YAZDIRMA ALANI - ÇAKIŞMALARI ÖNLEMEK İÇİN ABSOLUTE LAYOUT */}
      <div style={{ position: 'absolute', left: '-9999px', top: 0 }}>
