            >
              {/* HEADER (Sabit 20mm) */}
              <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '22mm', padding: '4mm 2mm', textAlign: 'center', borderBottom: '0.2mm solid #f1f5f9' }}>
                  <div style={{ fontSize: '11pt', fontWeight: '900', color: '#0f172a', textTransform: 'uppercase', lineHeight: '1.1', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', marginBottom: '2mm' }}>
