  const getQrUrl = (sc: string) => {
      // Eğer kullanıcı Ayarlar'da bir URL belirtmişse onu kullan, yoksa mevcut pencerenin adresini kullan.
      // ÖNEMLİ: DNS hatası almamak için Ayarlar > Uygulama Genel URL Adresi kısmına 
      // Vercel linkinizi (https://...vercel.app) girmeniz gerekir.
      const baseUrl = config?.appUrl || window.location.origin + window.location.pathname;
      const cleanBase = baseUrl.replace(/\/$/, ""); // Sondaki eğik çizgiyi kaldır
      return `${cleanBase}?sc=${sc}`;
  };

  const handleDownload = async (type: 'pdf' | 'jpeg') => {
    if (selectedPrinters.length === 0) return;

    // DNS Hatası riskini önlemek için uyarı
    if (!config?.appUrl) {
        if (!confirm("UYARI: Ayarlar sayfasında 'Uygulama Genel URL Adresi' tanımlanmamış. QR kodlar sadece bu bilgisayarda çalışabilir, telefonda 'DNS Hatası' verebilir. Devam edilsin mi?")) {
            return;
        }
    }

    setGenerating(type);
    const selectedData = printers.filter(p => selectedPrinters.includes(p.id));
    const pages = chunkArray(selectedData, 12); 

    try {
      const pdf = type === 'pdf' ? new jspdf.jsPDF('p', 'mm', 'a4') : null;

      for (let i = 0; i < pages.length; i++) {
        const pageId = `page-${i}`;
        const pageElement = document.getElementById(pageId);

        if (pageElement) {
          const canvas = await html2canvas(pageElement, {
            scale: 4,
            useCORS: true,
            logging: false,
            backgroundColor: '#ffffff'
          });

          const imgData = canvas.toDataURL('image/jpeg', 1.0);

          if (type === 'pdf') {
            if (i > 0) pdf.addPage();
            pdf.addImage(imgData, 'JPEG', 0, 0, 210, 297);
          } else {
            const link = document.createElement('a');
            link.href = imgData;
            link.download = `toner_etiket_sayfa_${i + 1}.jpg`;
            link.click();
          }
        }
      }

      if (type === 'pdf') {
        pdf.save(`toner_etiketleri_${new Date().getTime()}.pdf`);
      }
    } catch (error) {
      console.error("Hata:", error);
      alert("İşlem sırasında bir hata oluştu.");
    } finally {
      setGenerating(null);
    }
  };

  if (loading) return <LoadingScreen message="Cihaz listesi hazırlanıyor..." />;

  const printerPages = chunkArray(printers.filter(p => selectedPrinters.includes(p.id)), 12);

  return (
    <div className="space-y-8 pb-32">
      {/* Uyarı Paneli (URL Tanımlı Değilse) */}
      {!config?.appUrl && (
          <div className="bg-amber-500/10 border border-amber-500/30 p-6 rounded-[2rem] flex items-center gap-4 text-amber-600 dark:text-amber-400">
              <AlertTriangle size={32} />
              <div className="flex-1">
                  <p className="font-black text-sm uppercase tracking-tighter leading-none">DNS HATASI UYARISI</p>
                  <p className="text-xs font-bold mt-1 opacity-80">Telefonda 'Siteye Ulaşılamıyor' hatası almamak için 'Ayarlar' sayfasından uygulamanın internet adresini kaydetmelisiniz.</p>
              </div>
          </div>
      )}

      {/* Üst Kontrol Paneli */}
      <div className="bg-white dark:bg-zinc-950 p-8 rounded-[2.5rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-500/10 text-blue-500 rounded-3xl border border-blue-500/20"><QrCode size={40} strokeWidth={2.5}/></div>
            <div>
                <h2 className="text-3xl font-black text-zinc-900 dark:text-white tracking-tighter uppercase leading-none">ETİKET YÖNETİMİ</h2>
                <p className="text-zinc-500 dark:text-zinc-400 font-bold uppercase tracking-widest mt-2 text-[10px]">Netleştirilmiş 45mm QR Kod Etiketleri</p>
            </div>
        </div>
        <div className="flex flex-wrap gap-3 w-full md:w-auto justify-center">
            <button onClick={selectAll} className="px-6 py-4 rounded-2xl border border-zinc-100 dark:border-zinc-800 text-zinc-500 font-black text-[10px] uppercase tracking-widest hover:bg-zinc-50 dark:hover:bg-zinc-900">
                {selectedPrinters.length === printers.length ? 'TEMİZLE' : 'HEPSİNİ SEÇ'}
            </button>
            <button onClick={() => handleDownload('jpeg')} disabled={selectedPrinters.length === 0 || !!generating} className="bg-zinc-900 text-white px-8 py-4 rounded-2xl font-black shadow-xl disabled:opacity-50 transition-all flex items-center gap-3 text-[10px] tracking-widest uppercase">
                {generating === 'jpeg' ? <Loader2 className="animate-spin" size={18}/> : <ImageIcon size={18} />} JPG
            </button>
            <button onClick={() => handleDownload('pdf')} disabled={selectedPrinters.length === 0 || !!generating} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl shadow-blue-500/20 disabled:opacity-50 transition-all flex items-center gap-3 text-[10px] tracking-widest uppercase">
                {generating === 'pdf' ? <Loader2 className="animate-spin" size={18}/> : <Download size={18} />} PDF
            </button>
        </div>
      </div>

      {/* Seçim Grid Listesi */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
        {printers.map(printer => (
            <div key={printer.id} onClick={() => toggleSelect(printer.id)} className={`p-6 rounded-[2.5rem] border transition-all cursor-pointer relative group flex flex-col justify-between h-44 ${selectedPrinters.includes(printer.id) ? 'bg-blue-600 border-blue-500 shadow-xl' : 'bg-white dark:bg-zinc-950 border-zinc-100 dark:border-zinc-900'}`}>
                <div className="flex justify-between items-start">
                    <div className={`p-2 rounded-xl ${selectedPrinters.includes(printer.id) ? 'bg-white/20 text-white' : 'bg-zinc-100 dark:bg-zinc-900 text-zinc-400'}`}>
                        <PrinterIcon size={18} />
                    </div>
                    {selectedPrinters.includes(printer.id) && <CheckCircle2 size={24} className="text-white" />}
                </div>
                <div>
                    <h3 className={`font-black text-sm uppercase tracking-tighter truncate ${selectedPrinters.includes(printer.id) ? 'text-white' : 'text-zinc-900 dark:text-white'}`}>{printer.model}</h3>
                    <p className={`text-[9px] font-bold uppercase mt-1 tracking-widest ${selectedPrinters.includes(printer.id) ? 'text-blue-100' : 'text-zinc-500'}`}>{printer.location}</p>
                </div>
                <div className={`absolute bottom-4 right-6 font-mono font-black text-lg ${selectedPrinters.includes(printer.id) ? 'text-white/40' : 'text-zinc-100 dark:text-zinc-900'}`}>#{printer.shortCode}</div>
            </div>
        ))}
      </div>

      {/* GİZLİ SAYFALAMA ALANI (PDF İÇİN HER SAYFA AYRI RENDER EDİLİR) */}
      <div style={{ position: 'absolute', left: '-9999px', top: 0 }}>
        {printerPages.map((pagePrinters, pageIdx) => (
          <div key={pageIdx} id={`page-${pageIdx}`} style={{ width: '210mm', height: '297mm', padding: '10mm', backgroundColor: 'white', display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gridTemplateRows: 'repeat(4, 1fr)', gap: '4mm', boxSizing: 'border-box' }}>
            {pagePrinters.map((printer) => (
              <div key={printer.id} style={{ width: '63mm', height: '90mm', border: '0.4mm solid #e2e8f0', borderRadius: '10mm', backgroundColor: 'white', position: 'relative', overflow: 'hidden', boxSizing: 'border-box' }}>
                {/* HEADER (20mm) */}
                <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '20mm', textAlign: 'center', padding: '4mm 2mm' }}>
                    <div style={{ fontSize: '10pt', fontWeight: '900', color: '#1e293b', textTransform: 'uppercase', lineHeight: '1.2', marginBottom: '1.5mm' }}>{printer.brand} {printer.model}</div>
                    <div style={{ backgroundColor: '#0f172a', color: 'white', fontSize: '7.5pt', fontWeight: '800', borderRadius: '4mm', padding: '1.5mm 4mm', display: 'inline-block', textTransform: 'uppercase' }}>{printer.location}</div>
                </div>
                {/* QR KOD (45mm) */}
                <div style={{ position: 'absolute', top: '22mm', left: 0, width: '100%', height: '48mm', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <img src={`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(getQrUrl(printer.shortCode || ''))}`} style={{ width: '45mm', height: '45mm' }} alt="QR" />
                </div>
                {/* FOOTER (20mm) */}
                <div style={{ position: 'absolute', bottom: 0, left: 0, width: '100%', height: '20mm', padding: '0 4mm' }}>
                    <div style={{ position: 'absolute', bottom: '5mm', left: '4mm', display: 'flex', alignItems: 'center', gap: '1.5mm', backgroundColor: '#f1f5f9', border: '0.1mm solid #e2e8f0', borderRadius: '2mm', padding: '2mm 4mm' }}>
                        <div style={{ width: '2mm', height: '2mm', borderRadius: '50%', backgroundColor: '#3b82f6' }}></div>
                        <span style={{ fontSize: '8pt', fontWeight: '900', color: '#1e293b', fontFamily: 'monospace' }}>{printer.connectionType === 'Network' ? (printer.ipAddress || 'AUTO IP') : 'USB'}</span>
                    </div>
                    <div style={{ position: 'absolute', bottom: '4mm', right: '4mm', fontSize: '20pt', fontWeight: '950', color: '#10b981', fontFamily: 'monospace', letterSpacing: '-1mm' }}>#{printer.shortCode}</div>
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { Camera, X, Zap, Hash, ArrowRight, Loader2, RefreshCw, AlertCircle, Maximize } from 'lucide-react';
import { StorageService } from '../services/storage';

export const QrScanner: React.FC = () => {
  const [scanResult, setScanResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [manualCode, setManualCode] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [isCameraReady, setIsCameraReady] = useState(false);
  const scannerRef = useRef<Html5Qrcode | null>(null);

  const startScanner = async () => {
    setError(null);
    setIsCameraReady(false);

    if (scannerRef.current && scannerRef.current.isScanning) {
        try { await scannerRef.current.stop(); } catch (e) {}
    }

    const html5QrCode = new Html5Qrcode("reader");
    scannerRef.current = html5QrCode;

    const config = { 
        fps: 30, 
        qrbox: (viewWidth: number, viewHeight: number) => {
            const minDim = Math.min(viewWidth, viewHeight);
            const boxSize = Math.floor(minDim * 0.7);
            return { width: boxSize, height: boxSize };
        },
        aspectRatio: 1.0,
        disableFlip: false
    };

    setTimeout(() => {
        html5QrCode.start(
          { facingMode: "environment" }, 
          config,
          (decodedText) => {
            setScanResult(decodedText);
            html5QrCode.stop().then(() => {
                 handleScanSuccess(decodedText);
            }).catch(err => console.error(err));
          },
          (errorMessage) => {}
        ).then(() => {
            setIsCameraReady(true);
        }).catch(err => {
            console.error("Camera error:", err);
            setError("Kamera başlatılamadı. APK izinlerini kontrol edin.");
        });
    }, 700);
  };

  useEffect(() => {
    startScanner();
    return () => {
       if (scannerRef.current && scannerRef.current.isScanning) {
           scannerRef.current.stop().catch(err => console.error(err));
       }
    };
  }, []);

  const handleScanSuccess = async (text: string) => {
      // 1. Durum: Tam URL okunduysa
      if (text.startsWith('http')) {
          try {
              const url = new URL(text);
              const sc = url.searchParams.get("sc");
              const pid = url.searchParams.get("pid");

              if (pid) {
                  window.location.href = `${window.location.origin}${window.location.pathname}?pid=${pid}`;
              } else if (sc) {
                  await handleManualSubmit(sc);
              } else {
                  setError("Okunan QR kodu sistemle uyumlu değil.");
              }
          } catch (e) {
              setError("Geçersiz URL formatı okundu.");
          }
      } 
      // 2. Durum: Sadece Hızlı Kod (4 haneli rakam) okunduysa
      else if (/^\d{4,5}$/.test(text)) {
          await handleManualSubmit(text);
      } 
      else {
          setError("QR içeriği anlaşılamadı. Lütfen sistem tarafından oluşturulan QR kodlarını kullanın.");
      }
  };

  const handleManualSubmit = async (codeToSearch?: string) => {
      const code = codeToSearch || manualCode;
      if (!code) return;
      setIsSearching(true);
      setError(null);
      try {
          const printer = await StorageService.findPrinterByShortCode(code);
          if (printer) {
              // Uygulamayı o yazıcının detayına yönlendir
              window.location.href = `${window.location.origin}${window.location.pathname}?pid=${printer.id}`;
          } else {
              setError(`Hızlı Kod (#${code}) ile eşleşen cihaz bulunamadı.`);
              setIsSearching(false);
          }
      } catch (e) {
          setError("Veritabanı sorgu hatası.");
          setIsSearching(false);
      }
  };

  return (
    <div className="flex flex-col h-full max-w-lg mx-auto animate-in fade-in duration-700 p-4">
      <div className="relative w-full bg-black aspect-square overflow-hidden rounded-[3rem] shadow-2xl border-4 border-zinc-900">
          <div id="reader" className="w-full h-full"></div>
          {!scanResult && isCameraReady && (
              <div className="absolute inset-0 pointer-events-none flex items-center justify-center z-20">
                  <div className="w-64 h-64 border-2 border-emerald-500/20 rounded-[2.5rem] relative">
                      <div className="absolute -top-1 -left-1 w-10 h-10 border-t-4 border-l-4 border-emerald-500 rounded-tl-xl"></div>
                      <div className="absolute -top-1 -right-1 w-10 h-10 border-t-4 border-r-4 border-emerald-500 rounded-tr-xl"></div>
                      <div className="absolute -bottom-1 -left-1 w-10 h-10 border-b-4 border-l-4 border-emerald-500 rounded-bl-xl"></div>
                      <div className="absolute -bottom-1 -right-1 w-10 h-10 border-b-4 border-r-4 border-emerald-500 rounded-br-xl"></div>
                      <div className="absolute top-0 left-0 w-full h-0.5 bg-emerald-500 shadow-[0_0_15px_#10b981] animate-scan"></div>
                  </div>
              </div>
          )}
          {!isCameraReady && !error && (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-zinc-950 text-emerald-500">
                  <Loader2 size={40} className="animate-spin mb-4 opacity-50" />
                  <p className="font-black text-[10px] uppercase tracking-widest">Kamera Aktifleşiyor...</p>
              </div>
          )}
          {error && (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-zinc-950 p-10 text-center z-30">
                  <AlertCircle size={40} className="text-red-500 mb-4" />
                  <p className="text-white text-xs font-bold mb-6">{error}</p>
                  <button onClick={startScanner} className="bg-emerald-600 text-white px-6 py-3 rounded-xl font-bold text-xs uppercase"><RefreshCw size={14} className="inline mr-2" /> Yeniden Dene</button>
              </div>
          )}
      </div>

      <div className="mt-8 space-y-6">
          <div className="flex flex-col items-center gap-4">
              <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">MANUEL KOD GİRİŞİ</span>
              <div className="flex w-full gap-2">
                  <div className="relative flex-1">
                      <Hash className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500" size={18} />
                      <input 
                        type="number" 
                        pattern="[0-9]*" 
                        inputMode="numeric" 
                        placeholder="Örn: 1022" 
                        className="w-full pl-12 pr-6 py-4 rounded-2xl bg-zinc-100 dark:bg-zinc-900 text-zinc-900 dark:text-white outline-none focus:ring-2 focus:ring-emerald-500 font-black text-xl" 
                        value={manualCode} 
                        onChange={(e) => setManualCode(e.target.value)} 
                        onKeyDown={(e) => e.key === 'Enter' && handleManualSubmit()} 
                      />
                  </div>
                  <button onClick={() => handleManualSubmit()} disabled={!manualCode || isSearching} className="bg-emerald-600 text-white px-6 rounded-2xl flex items-center justify-center">
                      {isSearching ? <Loader2 className="animate-spin" size={24}/> : <ArrowRight size={24} />}
                  </button>
              </div>
          </div>
      </div>
      <style>{`
          @keyframes scan { 0% { top: 0; } 100% { top: 100%; } }
          .animate-scan { animation: scan 2s linear infinite; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
import { Dashboard } from './components/Dashboard';
import { PrinterList } from './components/PrinterList';
import { StockManagement } from './components/StockManagement';
import { History } from './components/History';
import { Settings } from './components/Settings';
import { ServiceManagement } from './components/ServiceManagement';
import { QrManagement } from './components/QrManagement';
import { QrScanner } from './components/QrScanner';
import { Inventory } from './components/Inventory';
import { CounterManagement } from './components/CounterManagement';
import { Notes } from './components/Notes';
import { Invoices } from './components/Invoices';
import { User } from './types';
import { StorageService } from './services/storage';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [targetPrinterId, setTargetPrinterId] = useState<string | null>(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('app_user');
    if (savedUser) setUser(JSON.parse(savedUser));

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme === 'dark') setIsDarkMode(true);

    const resolveUrlParams = async () => {
      const params = new URLSearchParams(window.location.search);
      const pid = params.get('pid');
      const sc = params.get('sc');

      if (pid) {
        setTargetPrinterId(pid);
        // Parametreleri temizle (URL'yi sade tut)
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (sc) {
        const printer = await StorageService.findPrinterByShortCode(sc);
        if (printer) {
            setTargetPrinterId(printer.id);
            window.history.replaceState({}, document.title, window.location.pathname);
        }
      }
    };

    resolveUrlParams();
  }, []);

  // Kullanıcı giriş yaptıysa ve hedef bir yazıcı varsa direkt yönlendir
  useEffect(() => {
    if (user && targetPrinterId) {
        setActiveTab('printers');
    }
  }, [user, targetPrinterId]);

  const handleLogin = (user: User) => {
    localStorage.setItem('app_user', JSON.stringify(user));
    setUser(user);
    // targetPrinterId zaten state'de olduğu için yukarıdaki useEffect tetiklenip yönlendirme yapacaktır.
  };

  const handleLogout = () => {
    localStorage.removeItem('app_user');
    setUser(null);
    setActiveTab('dashboard');
    setTargetPrinterId(null);
    window.history.replaceState({}, '', window.location.pathname);
  };

  const toggleTheme = () => {
    const newMode = !isDarkMode;
    setIsDarkMode(newMode);
    localStorage.setItem('app_theme', newMode ? 'dark' : 'light');
  };

  if (!user) {
    return (
      <div className={isDarkMode ? 'dark' : ''}>
        <Login onLogin={handleLogin} isDarkMode={isDarkMode} toggleTheme={toggleTheme} />
      </div>
    );
  }

  return (
    <div className={isDarkMode ? 'dark' : ''}>
      <Layout 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={handleLogout} 
        user={user}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      >
        {activeTab === 'dashboard' && <Dashboard setActiveTab={setActiveTab} />}
        {activeTab === 'invoices' && <Invoices />}
        {activeTab === 'scan' && <QrScanner />}
        {activeTab === 'qr' && <QrManagement />}
        {activeTab === 'notes' && <Notes user={user} />}
        {activeTab === 'printers' && (
            <PrinterList 
                targetPrinterId={targetPrinterId} 
                clearTarget={() => setTargetPrinterId(null)} 
            />
        )}
        {activeTab === 'inventory' && <Inventory />} 
        {activeTab === 'counters' && <CounterManagement user={user} />}
        {activeTab === 'service' && <ServiceManagement user={user} />}
        {activeTab === 'stock' && <StockManagement user={user} />}
        {activeTab === 'history' && <History />}
        {activeTab === 'settings' && <Settings />}
      </Layout>
    </div>
  );
}

export default App;

