                {(editModal.type === 'brands' || editModal.type === 'models') && (
                     <input type="text" className="w-full p-3 border rounded-xl bg-slate-50 dark:bg-slate-700 text-xs" placeholder="Resim URL" value={editModal.newImage || ''} onChange={(e) => setEditModal({...editModal, newImage: e.target.value})} />
                )}
                <div className="flex gap-3"><button type="button" onClick={() => setEditModal(null)} className="flex-1 py-3 bg-slate-100 dark:bg-slate-700 rounded-xl">İptal</button><button type="submit" className="flex-1 py-3 bg-blue-600 text-white rounded-xl">Güncelle</button></div>
             </form>
          </div>
        </div>
      )}

      {deleteModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[80] flex items-center justify-center p-4">
           <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 text-center max-w-sm w-full">
              <div className="w-16 h-16 bg-red-100 dark:bg-red-900/30 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4"><Trash2 size={32} /></div>
              <p className="font-bold mb-2">"{deleteModal.val}" Silinsin mi?</p>
              <div className="grid grid-cols-2 gap-3 mt-6"><button onClick={() => setDeleteModal(null)} className="py-3 bg-slate-100 rounded-xl">Vazgeç</button><button onClick={handleDelete} className="py-3 bg-red-600 text-white rounded-xl">Evet, Sil</button></div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../services/storage';
import { Printer, SystemConfig } from '../types';
import { LoadingScreen } from './LoadingScreen';
import { Printer as PrinterIcon, QrCode, Download, Image as ImageIcon, CheckCircle2, Loader2, X, AlertTriangle, Settings } from 'lucide-react';

declare const html2canvas: any;
declare const jspdf: any;

export const QrManagement: React.FC = () => {
  const [printers, setPrinters] = useState<Printer[]>([]);
  const [config, setConfig] = useState<SystemConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedPrinters, setSelectedPrinters] = useState<string[]>([]);
  const [generating, setGenerating] = useState<null | 'pdf' | 'jpeg'>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [pData, cData] = await Promise.all([
        StorageService.getPrinters(),
        StorageService.getConfig()
    ]);
    setPrinters(pData.sort((a, b) => (a.shortCode || '').localeCompare(b.shortCode || '')));
    setConfig(cData);
    setLoading(false);
  };

  const toggleSelect = (id: string) => {
    setSelectedPrinters(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const selectAll = () => {
    if (selectedPrinters.length === printers.length) setSelectedPrinters([]);
    else setSelectedPrinters(printers.map(p => p.id));
  };

  const chunkArray = (array: any[], size: number) => {
    const chunked = [];
    for (let i = 0; i < array.length; i += size) {
      chunked.push(array.slice(i, i + size));
    }
    return chunked;
  };

  const getQrUrl = (sc: string) => {
      const baseUrl = config?.appUrl || window.location.origin + window.location.pathname;
      const cleanBase = baseUrl.replace(/\/$/, ""); 
      return `${cleanBase}?sc=${sc}`;
  };

  const handleDownload = async (type: 'pdf' | 'jpeg') => {
    if (selectedPrinters.length === 0) return;

    if (!config?.appUrl) {
        if (!confirm("UYARI: Ayarlar sayfasında 'Uygulama Genel URL Adresi' tanımlanmamış. QR kodlar sadece bu bilgisayarda çalışabilir, telefonda 'DNS Hatası' verebilir. Devam edilsin mi?")) {
            return;
        }
    }

    setGenerating(type);
    const selectedData = printers.filter(p => selectedPrinters.includes(p.id));
    const pages = chunkArray(selectedData, 12); 

    try {
      const pdf = type === 'pdf' ? new jspdf.jsPDF('p', 'mm', 'a4') : null;

      for (let i = 0; i < pages.length; i++) {
        const pageId = `page-${i}`;
        const pageElement = document.getElementById(pageId);

        if (pageElement) {
          const canvas = await html2canvas(pageElement, {
            scale: 3, // Performans ve kalite dengesi
            useCORS: true,
            logging: false,
            backgroundColor: '#ffffff',
            windowWidth: 794, // 210mm @ 96dpi
            windowHeight: 1123 // 297mm @ 96dpi
          });

          const imgData = canvas.toDataURL('image/jpeg', 0.95);

          if (type === 'pdf') {
            if (i > 0) pdf.addPage();
            pdf.addImage(imgData, 'JPEG', 0, 0, 210, 297);
          } else {
            const link = document.createElement('a');
            link.href = imgData;
            link.download = `toner_etiket_sayfa_${i + 1}.jpg`;
            link.click();
          }
        }
      }

      if (type === 'pdf') {
        pdf.save(`toner_etiketleri_${new Date().getTime()}.pdf`);
      }
    } catch (error) {
      console.error("Hata:", error);
      alert("İşlem sırasında bir hata oluştu.");
    } finally {
      setGenerating(null);
    }
  };

  if (loading) return <LoadingScreen message="Cihaz listesi hazırlanıyor..." />;

  const printerPages = chunkArray(printers.filter(p => selectedPrinters.includes(p.id)), 12);

  return (
    <div className="space-y-8 pb-32">
      {!config?.appUrl && (
          <div className="bg-amber-500/10 border border-amber-500/30 p-6 rounded-[2rem] flex items-center gap-4 text-amber-600 dark:text-amber-400">
              <AlertTriangle size={32} />
              <div className="flex-1">
                  <p className="font-black text-sm uppercase tracking-tighter leading-none">DNS HATASI UYARISI</p>
                  <p className="text-xs font-bold mt-1 opacity-80">Telefonda 'Siteye Ulaşılamıyor' hatası almamak için 'Ayarlar' sayfasından uygulamanın internet adresini kaydetmelisiniz.</p>
              </div>
          </div>
      )}

      <div className="bg-white dark:bg-zinc-950 p-8 rounded-[2.5rem] shadow-2xl border border-zinc-100 dark:border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-500/10 text-blue-500 rounded-3xl border border-blue-500/20"><QrCode size={40} strokeWidth={2.5}/></div>
            <div>
                <h2 className="text-3xl font-black text-zinc-900 dark:text-white tracking-tighter uppercase leading-none">ETİKET YÖNETİMİ</h2>
                <p className="text-zinc-500 dark:text-zinc-400 font-bold uppercase tracking-widest mt-2 text-[10px]">A4 SAYFA BAŞI 12 ETİKET (62x67mm)</p>
            </div>
        </div>
        <div className="flex flex-wrap gap-3 w-full md:w-auto justify-center">
            <button onClick={selectAll} className="px-6 py-4 rounded-2xl border border-zinc-100 dark:border-zinc-800 text-zinc-500 font-black text-[10px] uppercase tracking-widest hover:bg-zinc-50 dark:hover:bg-zinc-900">
                {selectedPrinters.length === printers.length ? 'TEMİZLE' : 'HEPSİNİ SEÇ'}
            </button>
            <button onClick={() => handleDownload('jpeg')} disabled={selectedPrinters.length === 0 || !!generating} className="bg-zinc-900 text-white px-8 py-4 rounded-2xl font-black shadow-xl disabled:opacity-50 transition-all flex items-center gap-3 text-[10px] tracking-widest uppercase">
                {generating === 'jpeg' ? <Loader2 className="animate-spin" size={18}/> : <ImageIcon size={18} />} JPG
            </button>
            <button onClick={() => handleDownload('pdf')} disabled={selectedPrinters.length === 0 || !!generating} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl shadow-blue-500/20 disabled:opacity-50 transition-all flex items-center gap-3 text-[10px] tracking-widest uppercase">
                {generating === 'pdf' ? <Loader2 className="animate-spin" size={18}/> : <Download size={18} />} PDF
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
        {printers.map(printer => (
            <div key={printer.id} onClick={() => toggleSelect(printer.id)} className={`p-6 rounded-[2.5rem] border transition-all cursor-pointer relative group flex flex-col justify-between h-44 ${selectedPrinters.includes(printer.id) ? 'bg-blue-600 border-blue-500 shadow-xl' : 'bg-white dark:bg-zinc-950 border-zinc-100 dark:border-zinc-900'}`}>
                <div className="flex justify-between items-start">
                    <div className={`p-2 rounded-xl ${selectedPrinters.includes(printer.id) ? 'bg-white/20 text-white' : 'bg-zinc-100 dark:bg-zinc-900 text-zinc-400'}`}>
                        <PrinterIcon size={18} />
                    </div>
                    {selectedPrinters.includes(printer.id) && <CheckCircle2 size={24} className="text-white" />}
                </div>
                <div>
                    <h3 className={`font-black text-sm uppercase tracking-tighter truncate ${selectedPrinters.includes(printer.id) ? 'text-white' : 'text-zinc-900 dark:text-white'}`}>{printer.model}</h3>
                    <p className={`text-[9px] font-bold uppercase mt-1 tracking-widest ${selectedPrinters.includes(printer.id) ? 'text-blue-100' : 'text-zinc-500'}`}>{printer.location}</p>
                </div>
                <div className={`absolute bottom-4 right-6 font-mono font-black text-lg ${selectedPrinters.includes(printer.id) ? 'text-white/40' : 'text-zinc-100 dark:text-zinc-900'}`}>#{printer.shortCode}</div>
            </div>
        ))}
      </div>

      {/* GİZLİ SAYFALAMA ALANI - A4 BOYUTLARI (210x297mm) */}
      <div style={{ position: 'absolute', left: '-9999px', top: 0 }}>
        {printerPages.map((pagePrinters, pageIdx) => (
          <div key={pageIdx} id={`page-${pageIdx}`} style={{ width: '210mm', height: '297mm', padding: '10mm', backgroundColor: 'white', display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gridTemplateRows: 'repeat(4, 1fr)', gap: '3mm', boxSizing: 'border-box' }}>
            {pagePrinters.map((printer) => (
              <div key={printer.id} style={{ width: '62mm', height: '67mm', border: '0.3mm solid #e2e8f0', borderRadius: '6mm', backgroundColor: 'white', position: 'relative', overflow: 'hidden', boxSizing: 'border-box' }}>
                {/* HEADER (15mm) */}
                <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '15mm', textAlign: 'center', padding: '2mm 1mm' }}>
                    <div style={{ fontSize: '8pt', fontWeight: '900', color: '#1e293b', textTransform: 'uppercase', lineHeight: '1.1', marginBottom: '1mm', whiteSpace: 'nowrap', overflow: 'hidden' }}>{printer.brand} {printer.model}</div>
                    <div style={{ backgroundColor: '#0f172a', color: 'white', fontSize: '6pt', fontWeight: '800', borderRadius: '2mm', padding: '1mm 3mm', display: 'inline-block', textTransform: 'uppercase' }}>{printer.location}</div>
                </div>
                {/* QR KOD (35mm) */}
                <div style={{ position: 'absolute', top: '16mm', left: 0, width: '100%', height: '35mm', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(getQrUrl(printer.shortCode || ''))}`} style={{ width: '33mm', height: '33mm' }} alt="QR" />
                </div>
                {/* FOOTER (15mm) */}
                <div style={{ position: 'absolute', bottom: 0, left: 0, width: '100%', height: '15mm', padding: '0 3mm' }}>
                    <div style={{ position: 'absolute', bottom: '3mm', left: '3mm', display: 'flex', alignItems: 'center', gap: '1mm', backgroundColor: '#f1f5f9', border: '0.1mm solid #e2e8f0', borderRadius: '1.5mm', padding: '1.5mm 3mm' }}>
                        <div style={{ width: '1.5mm', height: '1.5mm', borderRadius: '50%', backgroundColor: '#3b82f6' }}></div>
                        <span style={{ fontSize: '7pt', fontWeight: '900', color: '#1e293b', fontFamily: 'monospace' }}>{printer.connectionType === 'Network' ? (printer.ipAddress?.split('.').pop() || 'IP') : 'USB'}</span>
                    </div>
                    <div style={{ position: 'absolute', bottom: '2mm', right: '3mm', fontSize: '16pt', fontWeight: '950', color: '#10b981', fontFamily: 'monospace', letterSpacing: '-0.5mm' }}>#{printer.shortCode}</div>
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
};

import { db } from './firebase';
import { collection, getDocs, addDoc, updateDoc, deleteDoc, doc, setDoc, query, orderBy, getDoc, where, writeBatch } from 'firebase/firestore';
import { Printer, TonerStock, StockLog, SystemConfig, ServiceRecord, User, CounterLog, Note, ActivityLog, MonthlyInvoice, InvoiceRecord } from '../types';

const COLLECTIONS = {
  PRINTERS: 'printers',
  STOCKS: 'stocks',
  LOGS: 'logs',
  CONFIG: 'config',
  SERVICES: 'services',
  USERS: 'users',
  COUNTERS: 'counters',
  NOTES: 'notes',
  ACTIVITIES: 'activities',
  MONTHLY_INVOICES: 'monthly_invoices',
  INVOICES: 'invoices'
};

const INITIAL_CONFIG: SystemConfig = {
  brands: ['Canon', 'HP', 'Kyocera', 'Xerox', 'Epson'],
  models: ['MF416dw', 'iF1643', 'LBP 251DW', '3325i', 'L3210', 'L1210', 'P2035', 'LBP 6030'],
  suppliers: ['Anahtar Bilgisayar', 'Enes Bilişim', 'Kendi Malımız'],
  tonerModels: ['1643', '505', '259x'],
  whatsappNumber: '',
  appUrl: '',
  brandImages: {},
  modelImages: {}
};

const cleanData = (data: any) => {
  const newObj = { ...data };
  Object.keys(newObj).forEach(key => {
    if (newObj[key] === undefined || newObj[key] === null) delete newObj[key];
  });
  return newObj;
};

export const StorageService = {
  // --- INVOICES ---
  getInvoices: async (): Promise<InvoiceRecord[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.INVOICES));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as InvoiceRecord));
    } catch (e) { return []; }
  },

  addInvoice: async (invoice: InvoiceRecord) => {
    const { id, ...data } = invoice;
    return await addDoc(collection(db, COLLECTIONS.INVOICES), cleanData(data));
  },

  updateInvoice: async (invoice: InvoiceRecord) => {
    if (!invoice.id) return;
    const { id, ...data } = invoice;
    await updateDoc(doc(db, COLLECTIONS.INVOICES, id), cleanData(data));
  },

  // --- MONTHLY INVOICES ---
  getMonthlyInvoices: async (): Promise<MonthlyInvoice[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.MONTHLY_INVOICES));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as MonthlyInvoice));
    } catch (e) { return []; }
  },

  saveMonthlyInvoice: async (invoice: MonthlyInvoice) => {
    const { id, ...data } = invoice;
    if (id) {
      await updateDoc(doc(db, COLLECTIONS.MONTHLY_INVOICES, id), cleanData(data));
    } else {
      await addDoc(collection(db, COLLECTIONS.MONTHLY_INVOICES), cleanData(data));
    }
  },

  deleteMonthlyInvoice: async (id: string) => {
    if (!id) throw new Error("ID required");
    await deleteDoc(doc(db, COLLECTIONS.MONTHLY_INVOICES, id));
  },

  // --- AUTH ---
  getUsers: async (): Promise<User[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.USERS));
      return snapshot.docs.map(doc => ({ ...doc.data() as any } as User));
    } catch (error) { return []; }
  },

  login: async (username: string, password: string): Promise<User | null> => {
    const users = await StorageService.getUsers();
    const user = users.find(u => u.username.toLowerCase() === username.toLowerCase() && u.password === password);
    if (user) {
      const { password, ...safeUser } = user;
      return safeUser as User;
    }
    return null;
  },

  // --- PRINTERS ---
  getPrinters: async (): Promise<Printer[]> => {
    try {
      const snapshot = await getDocs(collection(db, COLLECTIONS.PRINTERS));
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Printer));
    } catch (e) { return []; }
  },

  addPrinter: async (printer: Printer) => {
    const printers = await StorageService.getPrinters();
    if (!printer.shortCode) {
      const codes = printers.map(p => parseInt(p.shortCode || '1000')).filter(n => !isNaN(n) && n >= 1000);
      const maxCode = codes.length > 0 ? Math.max(...codes) : 1000;
      printer.shortCode = (maxCode + 1).toString();
    }
    const { id, ...data } = printer;
    const docRef = await addDoc(collection(db, COLLECTIONS.PRINTERS), cleanData(data));
    return docRef.id;
  },

  updatePrinter: async (printer: Printer) => {
    if (!printer.id) return;
    await updateDoc(doc(db, COLLECTIONS.PRINTERS, printer.id), cleanData(printer));
  },

  deletePrinter: async (printerId: string) => {
    await deleteDoc(doc(db, COLLECTIONS.PRINTERS, printerId));
  },

  findPrinterByShortCode: async (code: string): Promise<Printer | null> => {
    const q = query(collection(db, COLLECTIONS.PRINTERS), where('shortCode', '==', code.trim()));
    const snapshot = await getDocs(q);
    if (snapshot.empty) return null;
    return { id: snapshot.docs[0].id, ...snapshot.docs[0].data() as any } as Printer;
  },

  fixMissingShortCodes: async () => {
    const printers = await StorageService.getPrinters();
    const batch = writeBatch(db);
    let nextCode = 1001;
    for (const p of printers) {
      if (!p.shortCode || parseInt(p.shortCode) < 1000) {
        batch.update(doc(db, COLLECTIONS.PRINTERS, p.id), { shortCode: nextCode.toString() });
        nextCode++;
      }
    }
    await batch.commit();
    return printers.length;
  },

  // --- NOTES ---
  getNotes: async (): Promise<Note[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.NOTES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Note));
    } catch (e) { return []; }
  },

  getNotesByPrinter: async (printerId: string): Promise<Note[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.NOTES), where('printerId', '==', printerId), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as Note));
    } catch (e) { return []; }
  },

  addNote: async (note: Note) => {
    const { id, ...data } = note;
    const docRef = await addDoc(collection(db, COLLECTIONS.NOTES), cleanData(data));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: note.user,
      action: 'NOT_EKLENDI',
      details: `"${note.title}" başlıklı yeni bir not oluşturuldu.`
    });
    return docRef.id;
  },

  updateNote: async (note: Note) => {
    if (!note.id) return;
    const { id, ...data } = note;
    await updateDoc(doc(db, COLLECTIONS.NOTES, id), cleanData(data));
  },

  deleteNote: async (id: string, user: string, title: string) => {
    await deleteDoc(doc(db, COLLECTIONS.NOTES, id));
    await StorageService.addActivity({
      id: '',
      date: new Date().toISOString(),
      user: user,
      action: 'NOT_SILINDI',
      details: `"${title}" başlıklı not silindi.`
    });
  },

  // --- ACTIVITIES ---
  getActivities: async (): Promise<ActivityLog[]> => {
    try {
      const q = query(collection(db, COLLECTIONS.ACTIVITIES), orderBy('date', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ActivityLog));
    } catch (e) { return []; }
  },

  addActivity: async (activity: ActivityLog) => {
    const { id, ...data } = activity;
    await addDoc(collection(db, COLLECTIONS.ACTIVITIES), cleanData(data));
  },

  // --- STOCKS & LOGS ---
  getStocks: async (): Promise<TonerStock[]> => {
    const snapshot = await getDocs(collection(db, COLLECTIONS.STOCKS));
    return snapshot.docs.map(doc => ({ ...doc.data() as any } as TonerStock));
  },

  saveStock: async (stock: TonerStock) => {
    const q = query(collection(db, COLLECTIONS.STOCKS));
    const snapshot = await getDocs(q);
    const existing = snapshot.docs.find(d => (d.data() as TonerStock).modelName === stock.modelName);
    if (existing) await updateDoc(doc(db, COLLECTIONS.STOCKS, existing.id), { quantity: stock.quantity });
    else await addDoc(collection(db, COLLECTIONS.STOCKS), cleanData(stock));
  },

  getLogs: async (): Promise<StockLog[]> => {
    const q = query(collection(db, COLLECTIONS.LOGS), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as StockLog));
  },

  addLog: async (log: StockLog) => {
    const { id, ...data } = log;
    await addDoc(collection(db, COLLECTIONS.LOGS), cleanData(data));
  },

  // --- SERVICES ---
  getServiceRecords: async (): Promise<ServiceRecord[]> => {
    const q = query(collection(db, COLLECTIONS.SERVICES), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as ServiceRecord));
  },

  addServiceRecord: async (record: ServiceRecord, user: string) => {
    const { id, ...data } = record;
    const docRef = await addDoc(collection(db, COLLECTIONS.SERVICES), cleanData(data));
    return docRef.id;
  },

  updateServiceRecord: async (record: ServiceRecord, user: string) => {
    if (!record.id) return;
    const { id, ...data } = record;
    await updateDoc(doc(db, COLLECTIONS.SERVICES, id), cleanData({ ...data, lastModifiedBy: user }));
  },

  deleteServiceRecord: async (id: string, user: string, printerName: string) => {
    await deleteDoc(doc(db, COLLECTIONS.SERVICES, id));
  },

  // --- COUNTERS ---
  getCounterLogs: async (): Promise<CounterLog[]> => {
    const q = query(collection(db, COLLECTIONS.COUNTERS), orderBy('date', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() as any } as CounterLog));
  },

  addCounterLog: async (log: CounterLog, updateMaster: boolean = true) => {
    const { id, ...data } = log;
    // Log kaydını ekle
    await addDoc(collection(db, COLLECTIONS.COUNTERS), cleanData(data));

    // Yazıcı ana verisini (Son Sayaç) güncelle
    if (updateMaster && log.printerId) {
      const updatePayload = {
        lastCounter: log.currentCounter,
        lastCounterBW: log.currentBW,
        lastCounterColor: log.currentColor
      };
      // undefined alanları temizle yoksa Firebase hata verir
      await updateDoc(doc(db, COLLECTIONS.PRINTERS, log.printerId), cleanData(updatePayload));
    }
  },

  // Implementation for simulation fetching counter data
  fetchPrinterCounterSimulated: async (printer: Printer) => {
    await new Promise(resolve => setTimeout(resolve, 800));
    const base = printer.lastCounter || 0;
    const increment = Math.floor(Math.random() * 500) + 50;
    const total = base + increment;

    if (printer.isColor) {
      const bwBase = printer.lastCounterBW || Math.floor(base * 0.7);
      const colorBase = printer.lastCounterColor || Math.floor(base * 0.3);
      const bwInc = Math.floor(increment * 0.8);
      const colorInc = increment - bwInc;
      return { total, bw: bwBase + bwInc, color: colorBase + colorInc };
    }

    return { total, bw: total, color: 0 };
  },

  getConfig: async (): Promise<SystemConfig> => {
    const docSnap = await getDoc(doc(db, COLLECTIONS.CONFIG, 'main_config'));
    return docSnap.exists() ? { ...INITIAL_CONFIG, ...docSnap.data() as SystemConfig } : INITIAL_CONFIG;
  },

  saveConfig: async (config: SystemConfig) => {
    await setDoc(doc(db, COLLECTIONS.CONFIG, 'main_config'), cleanData(config));
  }
};
